    $t26BomRe.exit, $t26BomRevName, $(if ($t26BomPrevSha) { $t26BomPrevSha.Substring(0, 16) } else { '(none)' }), $(if ($t26BomDiskSha) { $t26BomDiskSha.Substring(0, 16) } else { '(none)' }),
