$probeOutLines.Add('PROVIDER_CALLS=' + [string]($probeProv -match 'Get-LamConsoleConfirmAnnouncement'))
$probeOutLines.Add('PROVIDER_RAW_GATE=' + [string]($probeProv -match [regex]::Escape('$Context.gate')))
[System.IO.File]::WriteAllLines($ProbeOut, [string[]]$probeOutLines.ToArray())
'@
$t26N2Probe = Join-Path $sandbox 't26-n2-probe.ps1'
Write-Utf8 -Path $t26N2Probe -Text $t26N2ProbeSrc
$t26N2IntDir = Join-Path $sandbox 't26-n2-integrated'
New-Item -ItemType Directory -Path $t26N2IntDir -Force | Out-Null
$t26N2IntRead = Get-LamBaseBytes -Base $t26IntegratedSha -Path 'tools/lam/lam-console.ps1' -Pin '2d8110438945ab00e5f63887af1281e877236c9c3050722bf54f5d3b787cdbb6'
$t26N2IntSrc = [System.Text.Encoding]::UTF8.GetString($t26N2IntRead.bytes)
Write-Utf8 -Path (Join-Path $t26N2IntDir 'lam-console.ps1') -Text $t26N2IntSrc
function Invoke-T26N2Probe {
    param([string]$Lib)
    $po = Join-Path $sandbox ('t26-n2-out-' + [guid]::NewGuid().ToString('N').Substring(0, 8) + '.txt')
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $null = & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $t26N2Probe -ProbeLib $Lib -ProbeOut $po 2>&1 }
    finally { $ErrorActionPreference = $prevEap }
    $r = @{ line = ''; calls = ''; raw = '' }
    if (Test-Path -LiteralPath $po) {
        foreach ($pl in @([System.IO.File]::ReadAllLines($po))) {
            if ($pl.StartsWith('ANNOUNCE=')) { $r.line = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($pl.Substring(9))) }
            elseif ($pl.StartsWith('PROVIDER_CALLS=')) { $r.calls = $pl.Substring(15) }
            elseif ($pl.StartsWith('PROVIDER_RAW_GATE=')) { $r.raw = $pl.Substring(18) }
        }
        Remove-Item -LiteralPath $po -Force -ErrorAction SilentlyContinue
    }
    return [pscustomobject]$r
}
$t26N2Gate = 'dispatch-n2' + [char]27 + '[2J' + [char]0x3C + 'x' + [char]0xE9 + [char]13 + 'y'
$t26N2Root = 'C:\n2' + [char]7 + 'root'
$t26N2Expect = 'lam-console: about to authorize approve ' + (ConvertTo-T26Visible -Text $t26N2Gate) + ' in ' + (ConvertTo-T26Visible -Text $t26N2Root) + ' (preview digest abababababababab...).'
$t26N2 = Invoke-T26N2Probe -Lib $lamConsole
$t26N2Int = Invoke-T26N2Probe -Lib (Join-Path $t26N2IntDir 'lam-console.ps1')
$t26N2Printable = ($t26N2.line.Length -gt 0) -and ($t26N2.line -notmatch '[^\x20-\x7E]')
$t26N2Ok = ($t26N2.line -ceq $t26N2Expect) -and $t26N2Printable -and ($t26N2.calls -eq 'True') -and ($t26N2.raw -eq 'False')
$t26N2ControlSaw = ($t26N2Int.raw -eq 'True') -and ($t26N2Int.calls -eq 'False')
if (-not ($t26N2Ok -and $t26N2ControlSaw)) { $t26ok = $false }
if (-not $t26N2IntRead.ok) { $t26ok = $false }
$t26rows.Add('    RE-REVIEW CONTROL console (' + $t26IntegratedSha + ') read from ' + $t26N2IntRead.from + $(if ($t26N2IntRead.ok) { '' } else { ' -- NOT HELD' }))
$t26rows.Add(('    RE-REVIEW the announcement line renders the gate name: equals the rendering={0}, printable ASCII={1}, provider calls the renderer={2}, provider prints $Context.gate raw={3}; CONTROL integrated console prints it raw={4} : {5}' -f `
    ($t26N2.line -ceq $t26N2Expect), $t26N2Printable, $t26N2.calls, $t26N2.raw, $t26N2ControlSaw, ($t26N2Ok -and $t26N2ControlSaw)))

# --- RE-REVIEW: A FAILED RE-MINT RESTORES A BOM-CARRYING PRIOR BYTE FOR BYTE ------------------------
# reapprove's rollback compared and rewrote the prior as TEXT (ReadAllText, then a BOM-less WriteAllText),
# so a prior saved WITH a UTF-8 byte-order mark whose re-mint failed after the stamp write had begun came
# back WITHOUT its BOM while the tool printed "RESTORED ... original bytes". HOW THE STAMP WRITE IS MADE TO
# FAIL, MEASURED BEFORE IT WAS WRITTEN: this process opens the prior for READ with FileShare
# ReadWrite|Delete and takes a byte-range lock at offset 65536. The handle follows the file through the
# tool's rename (share-delete admits the move), and a lock is on the file, not the name. The stamp is made
# longer than 65536 bytes by a 70000-character -Reason, so the tool's WriteAllBytes to the .revoked-1 name
# OPENS AND TRUNCATES the file and then fails on the locked range -- the stamp write fails part-way, which
# is exactly the case the rollback's rewrite exists for. Every read the tool and the rollback make stays
# below 65536 (the prior is ~1.5 KB, read in 4 KB buffers), and the restore's rewrite is the prior's own
# length, so it does not touch the lock. (A deny-create ACL cannot drive this: measured on this host, a
# rename needs create-file rights on the directory too, so it blocks the move before the stamp.)
# THE BUILT TOOL must come back byte-identical (Get-FileHash equal to before) and say RESTORED. CONTROL:
# the same case against a copy of the integrated tool (its tools/lam/mission-gate.ps1, beside the
# current console and gate-class map) must be seen saying RESTORED over bytes that MOVED (the BOM gone);
# if it is not seen, this row could not see the defect and fails.
$t26N1IntDir = Join-Path $sandbox 't26-n1-integrated'
New-Item -ItemType Directory -Path $t26N1IntDir -Force | Out-Null
$t26N1IntRead = Get-LamBaseBytes -Base $t26IntegratedSha -Path 'tools/lam/mission-gate.ps1' -Pin 'd142d86fa6d0667fe1d1915dd2e25708184476f3e42cbb0a039640ee655d30af'
$t26N1IntSrc = [System.Text.Encoding]::UTF8.GetString($t26N1IntRead.bytes)
Write-Utf8 -Path (Join-Path $t26N1IntDir 'mission-gate.ps1') -Text $t26N1IntSrc
Copy-Item -LiteralPath (Join-Path $repoRoot 'tools\lam\lam-gate-class.ps1') -Destination (Join-Path $t26N1IntDir 'lam-gate-class.ps1') -Force
Copy-Item -LiteralPath $lamConsole -Destination (Join-Path $t26N1IntDir 'lam-console.ps1') -Force
$t26N1IntHasTextRollback = ($t26N1IntSrc -match [regex]::Escape('[System.IO.File]::WriteAllText($p, $priorText'))

function Invoke-T26N1Case {
    param([string]$Label, [string]$ConsoleLib)
    $root = Join-Path $env:TEMP ('lam-wp4-t26n1' + $Label + '-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
    New-Item -ItemType Directory -Path (Join-Path $root '.mission') -Force | Out-Null
    Write-Utf8 -Path (Join-Path $root 'bound.txt') -Text "t26 n1 bound bytes v1`n"
    $gate = Join-Path $root '.mission\gates\dispatch-t26n1.yaml'
    $r = [ordered]@{ mintExit = -1; bomOk = $false; notRevoked = $false; exit = -1; stage = ''; aside = $false; saidRestored = $false; notFully = $false
                     hashEqual = $false; afterBom = $false; beforeLen = 0; afterLen = 0; revLeft = -1; newGate = $false; out = '' }
    $savedLib = $script:lamConsole
    $script:lamConsole = $ConsoleLib
    try {
        $mint = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'dispatch'; Id = 't26n1'; Binds = 'bound.txt'; MissionRoot = $root }
        $r.mintExit = $mint.exit
        if (Test-Path -LiteralPath $gate) {
            # SAVED BY HAND WITH A BOM, NOT REVOKED: the operator's editor re-saves the same text with a mark.
            [System.IO.File]::WriteAllText($gate, [System.IO.File]::ReadAllText($gate), (New-Object System.Text.UTF8Encoding($true)))
            $head = [System.IO.File]::ReadAllBytes($gate)
            $r.bomOk = ($head.Length -ge 3) -and ($head[0] -eq 0xEF) -and ($head[1] -eq 0xBB) -and ($head[2] -eq 0xBF)
            $r.notRevoked = -not ([System.IO.File]::ReadAllText($gate) -match '(?m)^revoked_at:\s*\S')
            $r.beforeLen = $head.Length
            Write-Utf8 -Path (Join-Path $root 'bound.txt') -Text "t26 n1 bound bytes v2`n"
            $before = (Get-FileHash -Algorithm SHA256 -LiteralPath $gate).Hash
            $holder = New-Object System.IO.FileStream($gate, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read,
                          ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
            try {
                $holder.Lock(65536, 1)
                $re = Invoke-GateConsoleLauncher -Spec @{ Verb = 'reapprove'; Kind = 'dispatch'; Id = 't26n1'; Binds = 'bound.txt'; MissionRoot = $root
                                                          Reason = ('T-26 stamp forced to fail ' + ('x' * 70000)) }
            } finally {
                try { $holder.Unlock(65536, 1) } catch { }
                $holder.Dispose()
            }
            $r.exit = $re.exit; $r.stage = $re.stage; $r.out = $re.out
            $r.aside = ($re.out -match 'could not set the prior aside')
            $r.saidRestored = ($re.out -match 'RESTORED : the prior stands at its original name with its original bytes')
            $r.notFully = ($re.out -match 'NOT FULLY RESTORED')
            if (Test-Path -LiteralPath $gate) {
                $after = [System.IO.File]::ReadAllBytes($gate)
                $r.afterLen = $after.Length
                $r.afterBom = ($after.Length -ge 3) -and ($after[0] -eq 0xEF) -and ($after[1] -eq 0xBB) -and ($after[2] -eq 0xBF)
                $r.hashEqual = ((Get-FileHash -Algorithm SHA256 -LiteralPath $gate).Hash -eq $before)
            }
            $r.revLeft = @(Get-ChildItem -LiteralPath (Join-Path $root '.mission\gates') -Filter 'dispatch-t26n1.revoked-*.yaml' -ErrorAction SilentlyContinue).Count
        }
    } finally {
        $script:lamConsole = $savedLib
        Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue
    }
    return [pscustomobject]$r
}
$t26N1 = Invoke-T26N1Case -Label 'b' -ConsoleLib $lamConsole
$t26N1Int = Invoke-T26N1Case -Label 'i' -ConsoleLib (Join-Path $t26N1IntDir 'lam-console.ps1')
$t26N1Ok = ($t26N1.mintExit -eq 0) -and $t26N1.bomOk -and $t26N1.notRevoked -and ($t26N1.exit -eq 2) -and ($t26N1.stage -eq 'mint') -and
           $t26N1.aside -and $t26N1.saidRestored -and (-not $t26N1.notFully) -and $t26N1.hashEqual -and $t26N1.afterBom -and ($t26N1.revLeft -eq 0)
$t26N1ControlSaw = $t26N1IntHasTextRollback -and ($t26N1Int.mintExit -eq 0) -and $t26N1Int.bomOk -and $t26N1Int.notRevoked -and ($t26N1Int.exit -eq 2) -and
                   $t26N1Int.aside -and $t26N1Int.saidRestored -and (-not $t26N1Int.notFully) -and (-not $t26N1Int.hashEqual) -and (-not $t26N1Int.afterBom)
if (-not ($t26N1Ok -and $t26N1ControlSaw)) { $t26ok = $false }
if (-not $t26N1IntRead.ok) { $t26ok = $false }
$t26rows.Add('    RE-REVIEW CONTROL tool (' + $t26IntegratedSha + ') read from ' + $t26N1IntRead.from + $(if ($t26N1IntRead.ok) { '' } else { ' -- NOT HELD' }))
$t26rows.Add(('    RE-REVIEW reapprove over a BOM-carrying open prior, stamp write forced to fail by a byte-range lock: built exit {0} stage {1}, set-aside refusal={2}, says RESTORED={3}, NOT FULLY={4}, prior bytes {5}->{6} Get-FileHash equal={7} BOM kept={8}, .revoked-N left={9} : {10}' -f `
    $t26N1.exit, $t26N1.stage, $t26N1.aside, $t26N1.saidRestored, $t26N1.notFully, $t26N1.beforeLen, $t26N1.afterLen, $t26N1.hashEqual, $t26N1.afterBom, $t26N1.revLeft, $t26N1Ok))
$t26rows.Add(('      CONTROL the integrated tool ({0}, text rollback present={1}): exit {2}, says RESTORED={3}, NOT FULLY={4}, prior bytes {5}->{6} Get-FileHash equal={7} BOM kept={8} -- RESTORED printed over moved bytes, the defect seen={9}' -f `
    $t26IntegratedSha, $t26N1IntHasTextRollback, $t26N1Int.exit, $t26N1Int.saidRestored, $t26N1Int.notFully, $t26N1Int.beforeLen, $t26N1Int.afterLen, $t26N1Int.hashEqual, $t26N1Int.afterBom, $t26N1ControlSaw))
if (-not $t26N1Ok) { $t26rows.Add('      built output: ' + (($t26N1.out -split "`n" | Where-Object { $_ -match 'mission-gate:|RESTORED|  ' } | Select-Object -First 8) -join ' | ')) }

Remove-Item -LiteralPath $t26BuiltRoot -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $t26BaseRoot -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $t26ConRoot -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $t26D2Root -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $t26FailRoot -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $t26D1Base -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $t26CaRoot -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $t26BomRoot -Recurse -Force -ErrorAction SilentlyContinue

$t26detail = @"
    The documented refusal set from batch-4-proposals.md item 1, driven exactly. Every shape invokes
    a mutating verb WITHOUT the console's verified path and is refused; the base tool is
    the control that proves the corpus can see a mint (base has no -ConsoleToken: $t26BaseHasNoToken).
$($t26rows -join "`n")
    The console verified path, driven in the scrubbed hidden-console launcher where no session
    condition fires, is the ONLY shape that mints, and the artifact says injected-seam on its face; the
    same shape with the harness environment set is refused by the tool (both halves are required); with
    the injected provider failing, nothing is written and the failure is named. The REGRESSION rows
    are regression rows for the review's defects, and the RE-REVIEW rows for the re-review's
    observations (the BOM-restore and announcement rows each carry a control against the integrated $t26IntegratedSha tool or
    console that must be seen to exhibit the defect); none is an addition to the corpus. STAGE 2 (the gate
    directory ACL'd to a gate-owner principal) is the operator's own setup, documented in LAM-INSTALL,
    not built here.
"@
Check -Id 'T-26' -Title 'the operator corpus: every documented shape that invokes a mutating verb without the console verified path is refused (exit 3, CONSOLE-VERIFIED-PATH, nothing written), the base tool mints where it always did so the corpus is non-vacuous, the console verified path in the scrubbed launcher mints once (artifact bytes hash to the previewed digest, every byte rendered, binds re-derived, list open, injected-seam, one attestation line) and writes nothing when the credential fails, the same console shape with the harness environment set is refused naming HARNESS-SESSION, and the review regressions hold (relative -MissionRoot attests under the root and a lost line is reported; -ComposedAt malformed or out of window is refused; a BOM prior previews the bytes that land), and the re-review rows hold (a failed re-mint restores a BOM prior byte for byte and says RESTORED, where the integrated tool said RESTORED over moved bytes; the confirm announcement renders the gate name; the preview names the absolute mission root, gates directory and every write target)' `
      -Ok $t26ok -Detail $t26detail

# =================================================================================================
# T-27 -- THE EIGHTH KIND: halt-ruling, THE OPERATOR'S ANSWER TO ONE HALT
# =================================================================================================
# WHAT WAS FOUND. A HALT was answered when its own `**Status:**` line read ANSWERED, and the HALT
# file is agent-writable on every layer, so one Edit by the seat flipped the goal verdict. The cure
# moves the answer onto an operator act: a `halt-ruling` gate, minted through the console's verified
# path, binding the HALT file's bytes by sha256 and naming the HALT in `halt_id`. The goal evaluator's
# side of the cure is WP-3's C-3d; THIS member drives the tool's side -- that the kind mints only
# through the console, carries exactly the fields the evaluator reads, keeps the recorded-ruling
# lifecycle, and refuses the two ways an operator could mint a gate no reader will ever look at.
#
# EVERY MINT, REVOKE AND RE-MINT BELOW GOES THROUGH lam-console.ps1 IN THE SCRUBBED LAUNCHER (the
# shared block at the top of this file), and the refusal rows are refusals AT COMPOSE -- exit 2, stage
# compose, nothing written -- which is where the console meets a tool refusal before any credential is
# collected. The acceptance controls sit beside the refusals: a refusal member without them reports
# green on a tool that refuses every halt-ruling.
$t27ok = $true
$t27rows = New-Object System.Collections.Generic.List[string]
$t27Root = Join-Path $env:TEMP ('lam-wp4-t27-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
New-Item -ItemType Directory -Path (Join-Path $t27Root '.mission') -Force | Out-Null
$t27Gates = Join-Path $t27Root '.mission\gates'
$t27Rel1 = '.mission-runtime\halts\HALT-T27-01.md'
$t27Halt1 = Join-Path $t27Root $t27Rel1
Write-Utf8 -Path $t27Halt1 -Text "# HALT-T27-01`n`n**Status:** OPEN`n`nA question only the operator can settle.`n"
$t27Rel2 = '.mission-runtime\halts\HALT-T27-02.md'
Write-Utf8 -Path (Join-Path $t27Root $t27Rel2) -Text "# HALT-T27-02`n`n**Status:** OPEN`n"
$t27Rel3 = '.mission-runtime\halts\HALT-T27-03.md'
Write-Utf8 -Path (Join-Path $t27Root $t27Rel3) -Text "# HALT-T27-03`n`n**Status:** OPEN`n"
$t27RelLc = '.mission-runtime\halts\halt-t27-lc.md'
Write-Utf8 -Path (Join-Path $t27Root $t27RelLc) -Text "# halt-t27-lc`n`n**Status:** OPEN`n"
Write-Utf8 -Path (Join-Path $t27Root 'notes\RULING-T27.md') -Text "not a HALT`n"
Write-Utf8 -Path (Join-Path $t27Root 'bound.txt') -Text "t27 dispatch bound bytes`n"
$t27Gate1 = Join-Path $t27Gates 'halt-ruling-HALT-T27-01.yaml'

function Add-T27Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t27ok = $false }
    $script:t27rows.Add(('      {0,-86} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + $Said } else { '' })))
}
function Get-T27Field {
    param([string]$Text, [string]$Key)
    $fieldMatch = [regex]::Match([string]$Text, '(?m)^' + [regex]::Escape($Key) + ':[ \t]*(.*?)[ \t]*\r?$')
    if ($fieldMatch.Success) { return $fieldMatch.Groups[1].Value }
    return $null
}
function Get-T27ListLine {
    param([string]$Root, [string]$BaseName)
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $listOut = (& $gateTool list -MissionRoot $Root 2>&1 | Out-String) } finally { $ErrorActionPreference = $prevEap }
    $listLine = @(($listOut -split "`r?`n") | Where-Object { $_ -match ('^' + [regex]::Escape($BaseName) + '\s') })
    if ($listLine.Count -eq 1) { return $listLine[0] }
    return ''
}

# --- (1) THE MINT: every field the evaluator reads, and the recorded-ruling lifecycle -------------
# The ruling text carries a line break, a double quote and a backslash, because those are the three
# things that would split or end a YAML double-quoted scalar if they were written raw.
$t27RulingIn = 'Ruled: proceed with option B.' + "`n" + 'The "second" path, C:\x, is fine.'
$t27RulingLine = 'ruling: "Ruled: proceed with option B. The \"second\" path, C:\\x, is fine."'
$t27A = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'halt-ruling'; Id = 'HALT-T27-01'; Binds = $t27Rel1; MissionRoot = $t27Root; Ruling = $t27RulingIn }
$t27AText = if (Test-Path -LiteralPath $t27Gate1) { [System.IO.File]::ReadAllText($t27Gate1) } else { '' }
$t27Sha1 = (Get-FileHash -Algorithm SHA256 -LiteralPath $t27Halt1).Hash.ToLowerInvariant()
Add-T27Row 'approve through the console exits 0 at stage mint and writes halt-ruling-HALT-T27-01.yaml' `
    (($t27A.exit -eq 0) -and ($t27A.stage -eq 'mint') -and [bool]$t27AText) ("exit=$($t27A.exit) stage=$($t27A.stage)")
Add-T27Row 'kind: halt-ruling / gate_class: governance / halt_id: HALT-T27-01' `
    (((Get-T27Field $t27AText 'kind') -ceq 'halt-ruling') -and ((Get-T27Field $t27AText 'gate_class') -ceq 'governance') -and ((Get-T27Field $t27AText 'halt_id') -ceq 'HALT-T27-01')) ''
Add-T27Row 'binds_sha256 equals Get-FileHash of the HALT file' ((Get-T27Field $t27AText 'binds_sha256') -ceq $t27Sha1) ("expect $t27Sha1")
Add-T27Row 'permanence: until-revoked, NO expires_at, NO single_use, consumed_at: null' `
    (((Get-T27Field $t27AText 'permanence') -ceq 'until-revoked') -and ($t27AText -notmatch '(?m)^expires_at:') -and
     ($t27AText -notmatch '(?m)^single_use:') -and ((Get-T27Field $t27AText 'consumed_at') -ceq 'null')) ''
Add-T27Row 'operator_credential: injected-seam (the console seam authorized it, on its face)' ((Get-T27Field $t27AText 'operator_credential') -ceq 'injected-seam') ''
$t27RulingOnDisk = @(($t27AText -split "`r?`n") | Where-Object { $_ -match '^ruling:' })
Add-T27Row 'the -Ruling words land on ONE line, newline collapsed, quote and backslash escaped' `
    (($t27RulingOnDisk.Count -eq 1) -and ($t27RulingOnDisk[0] -ceq $t27RulingLine)) ("on disk: $(if ($t27RulingOnDisk.Count) { $t27RulingOnDisk -join ' | ' } else { '(no ruling line)' })")
$t27Note = if ($t27AText -match '(?m)^lifecycle_note:[ \t]*"(.*)"[ \t]*\r?$') { $Matches[1] } else { '' }
Add-T27Row 'lifecycle_note: answers ONE HALT, binds by sha256, an edit re-opens it, neither expires nor consumed' `
    ([bool]$t27Note -and ($t27Note -match 'ANSWERING ONE HALT') -and ($t27Note -match 'binds by sha256') -and ($t27Note -match 'binds field') -and
     ($t27Note -match 'reads OPEN again until the operator reapproves') -and ($t27Note -match 'neither expires nor is consumed') -and ($t27Note -match 'Revoke it to withdraw it')) ''
Add-T27Row 'the console PREVIEW showed the ruling line before the credential was collected' `
    ($t27A.preview -match [regex]::Escape('  | ' + $t27RulingLine + '<CR><LF>')) ''
$t27List1 = Get-T27ListLine -Root $t27Root -BaseName 'halt-ruling-HALT-T27-01'
Add-T27Row 'list reads it open governance' ($t27List1 -match '^halt-ruling-HALT-T27-01\s+open\s+governance\s') ("list: $t27List1")
Add-T27Row 'the class map carries the kind: Get-LamGateClassForKind halt-ruling -> governance' ((Get-LamGateClassForKind -Kind 'halt-ruling') -ceq 'governance') ''

# --- (2) THE ABSENCE OF -Ruling IS RECORDED, AND -ExpiresMinutes IS IGNORED --------------------------
$t27B = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'halt-ruling'; Id = 'HALT-T27-02'; Binds = $t27Rel2; MissionRoot = $t27Root; ExpiresMinutes = 5 }
$t27BGate = Join-Path $t27Gates 'halt-ruling-HALT-T27-02.yaml'
$t27BText = if (Test-Path -LiteralPath $t27BGate) { [System.IO.File]::ReadAllText($t27BGate) } else { '' }
Add-T27Row 'no -Ruling: the artifact records the absence verbatim, and -ExpiresMinutes 5 wrote no expires_at' `
    (($t27B.exit -eq 0) -and ((Get-T27Field $t27BText 'ruling') -ceq '"(NO RULING TEXT GIVEN -- -Ruling was not supplied)"') -and ($t27BText -notmatch '(?m)^expires_at:')) ("exit=$($t27B.exit) ruling=$(Get-T27Field $t27BText 'ruling')")

# --- (3) REFUSED: -Id IS NOT THE -Binds BaseName (a gate no reader looks for) ------------------------
$t27C = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'halt-ruling'; Id = 'HALT-T27-99'; Binds = $t27Rel1; MissionRoot = $t27Root; Ruling = 'wrong id' }
Add-T27Row 'REFUSED -Id HALT-T27-99 over HALT-T27-01.md: exit 2 at compose, names the rule, no artifact' `
    (($t27C.exit -eq 2) -and ($t27C.stage -eq 'compose') -and ($t27C.out -match "Id must be the bound HALT file's BaseName") -and
     (-not (Test-Path -LiteralPath (Join-Path $t27Gates 'halt-ruling-HALT-T27-99.yaml')))) ("exit=$($t27C.exit) stage=$($t27C.stage)")
# The id is compared CASE-SENSITIVELY, because the evaluator compares halt_id with -ceq: an id that
# differs only in case would mint a gate that never answers.
$t27D = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'halt-ruling'; Id = 'halt-t27-03'; Binds = $t27Rel3; MissionRoot = $t27Root }
Add-T27Row 'REFUSED -Id halt-t27-03 over HALT-T27-03.md (case differs): exit 2 at compose, no artifact' `
    (($t27D.exit -eq 2) -and ($t27D.stage -eq 'compose') -and (-not (Test-Path -LiteralPath (Join-Path $t27Gates 'halt-ruling-halt-t27-03.yaml')))) ("exit=$($t27D.exit) stage=$($t27D.stage)")

# --- (4) REFUSED: the bound leaf is not a HALT --------------------------------------------------------
$t27E = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'halt-ruling'; Id = 'RULING-T27'; Binds = 'notes\RULING-T27.md'; MissionRoot = $t27Root }
Add-T27Row 'REFUSED -Binds notes\RULING-T27.md (leaf does not begin HALT-): exit 2 at compose, no artifact' `
    (($t27E.exit -eq 2) -and ($t27E.stage -eq 'compose') -and ($t27E.out -match 'does not name one') -and
     (-not (Test-Path -LiteralPath (Join-Path $t27Gates 'halt-ruling-RULING-T27.yaml')))) ("exit=$($t27E.exit) stage=$($t27E.stage)")
# CONTROL: the prefix is matched as the SCANNER matches it -- case-insensitively -- so a HALT named
# halt-t27-lc.md, which the evaluator's -Filter 'HALT-*' does scan, is rulable.
$t27F = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'halt-ruling'; Id = 'halt-t27-lc'; Binds = $t27RelLc; MissionRoot = $t27Root }
$t27FGate = Join-Path $t27Gates 'halt-ruling-halt-t27-lc.yaml'
$t27FText = if (Test-Path -LiteralPath $t27FGate) { [System.IO.File]::ReadAllText($t27FGate) } else { '' }
Add-T27Row 'CONTROL a lower-case halt- leaf the scanner does scan mints (exit 0), halt_id halt-t27-lc' `
    (($t27F.exit -eq 0) -and ((Get-T27Field $t27FText 'halt_id') -ceq 'halt-t27-lc')) ("exit=$($t27F.exit)")

# --- (4b) REFUSED: AN -Id OUTSIDE ^HALT-[A-Za-z0-9][A-Za-z0-9._-]*$ (a review finding) ------------
# The review drove it: -Id "HALT-A B" over "HALT-A B.md" passed both checks above (the leaf begins HALT-, the
# id IS the BaseName), so the tool minted `halt_id: HALT-A B` -- which the evaluator's reader of that build
# could not match, so the operator's ruling answered nothing. The id is now held to the pattern at compose,
# BEFORE the BaseName comparison, so this exact act is refused naming the pattern. The lower-case control
# above still mints: the HALT- prefix is matched in any case, as the scan matches it.
$t27RelSp = '.mission-runtime\halts\HALT-A B.md'
Write-Utf8 -Path (Join-Path $t27Root $t27RelSp) -Text "# HALT-A B`n`n**Status:** OPEN`n"
$t27SpSpec = @{ Verb = 'approve'; Kind = 'halt-ruling'; Id = 'HALT-A B'; Binds = $t27RelSp; MissionRoot = $t27Root; Ruling = 'a ruling on a HALT whose name holds a space' }
$t27S = Invoke-GateConsoleLauncher -Spec $t27SpSpec
$t27Pattern = '^HALT-[A-Za-z0-9][A-Za-z0-9._-]*$'
Add-T27Row 'REFUSED -Id "HALT-A B" over HALT-A B.md (the BaseName, with a space): exit 2 at compose, names the pattern, no artifact' `
    (($t27S.exit -eq 2) -and ($t27S.stage -eq 'compose') -and ([string]$t27S.out).Contains($t27Pattern) -and
     (-not (Test-Path -LiteralPath (Join-Path $t27Gates 'halt-ruling-HALT-A B.yaml')))) ("exit=$($t27S.exit) stage=$($t27S.stage) pattern named=$(([string]$t27S.out).Contains($t27Pattern))")
# THE PLANTED REVERT: the SAME console act, in its own root, through a sandbox console standing beside the
# mission-gate.ps1 of the build the review read. It must MINT -- exit 0, a gate recording
# `halt_id: HALT-A B` -- or the refusal row above could not tell a cure from a tool that refuses everything.
$t27RvSha = '700e19e5-s05'
$t27RvDir = Join-Path $sandbox 't27-revert-base'
New-Item -ItemType Directory -Path $t27RvDir -Force | Out-Null
$t27RvRead = Get-LamBaseBytes -Base $t27RvSha -Path 'tools/lam/mission-gate.ps1' -Pin 'd8d8ffdc18d4aa12efd1269a0f218a3ffd50483fa54cc63099fc44e84f04f9d5'
$t27RvSrc = [System.Text.Encoding]::UTF8.GetString($t27RvRead.bytes)
$t27RvGitExit = if ($t27RvRead.ok) { 0 } else { 1 }
$t27RvReady = $false
if ($t27RvRead.ok) {
    Write-Utf8 -Path (Join-Path $t27RvDir 'mission-gate.ps1') -Text $t27RvSrc
    Copy-Item -LiteralPath $lamConsole -Destination (Join-Path $t27RvDir 'lam-console.ps1') -Force
    Copy-Item -LiteralPath (Join-Path $repoRoot 'tools\lam\lam-gate-class.ps1') -Destination (Join-Path $t27RvDir 'lam-gate-class.ps1') -Force
    $t27RvReady = ($t27RvSrc -match 'haltRulingBase') -and ($t27RvSrc -notmatch 'LamHaltRulingIdPattern')
}
$t27RvRoot = Join-Path $env:TEMP ('lam-wp4-t27r-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
New-Item -ItemType Directory -Path (Join-Path $t27RvRoot '.mission') -Force | Out-Null
Write-Utf8 -Path (Join-Path $t27RvRoot $t27RelSp) -Text "# HALT-A B`n`n**Status:** OPEN`n"
$t27RvSpec = @{ Verb = 'approve'; Kind = 'halt-ruling'; Id = 'HALT-A B'; Binds = $t27RelSp; MissionRoot = $t27RvRoot; Ruling = 'a ruling on a HALT whose name holds a space' }
$t27Rv = if ($t27RvReady) { Invoke-GateConsoleLauncher -Spec $t27RvSpec -ConsoleLib (Join-Path $t27RvDir 'lam-console.ps1') } else { [pscustomobject]@{ exit = -1; stage = '(not run)'; out = '' } }
$t27RvGate = Join-Path $t27RvRoot '.mission\gates\halt-ruling-HALT-A B.yaml'
$t27RvText = if (Test-Path -LiteralPath $t27RvGate) { [System.IO.File]::ReadAllText($t27RvGate) } else { '' }
Add-T27Row 'PLANTED REVERT: that SAME act through a console over the reviewed tool MINTS, recording halt_id: HALT-A B' `
    ($t27RvReady -and ($t27Rv.exit -eq 0) -and ($t27RvText -match '(?m)^halt_id: HALT-A B\r?$')) ("revert tool ready=$t27RvReady (read from $($t27RvRead.from)) exit=$($t27Rv.exit) stage=$($t27Rv.stage) gate written=$([bool]$t27RvText)")
Remove-Item -LiteralPath $t27RvRoot -Recurse -Force -ErrorAction SilentlyContinue

# --- (5) AND THE TOOL RUN DIRECTLY IS STILL REFUSED FOR THIS KIND (the verified path has no exception) --
$t27DirRoot = Join-Path $env:TEMP ('lam-wp4-t27d-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
Write-Utf8 -Path (Join-Path $t27DirRoot '.mission-runtime\halts\HALT-T27-D.md') -Text "# HALT-T27-D`n"
$prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
try {
    $t27DirOut = (& $gateTool approve -Kind halt-ruling -Id HALT-T27-D -Binds '.mission-runtime\halts\HALT-T27-D.md' -MissionRoot $t27DirRoot 2>&1 | Out-String)
    $t27DirExit = $LASTEXITCODE
} finally { $ErrorActionPreference = $prevEap }
Add-T27Row 'mission-gate.ps1 approve -Kind halt-ruling run directly: exit 3, CONSOLE-VERIFIED-PATH, no gates dir' `
    (($t27DirExit -eq 3) -and ($t27DirOut -match 'CONSOLE-VERIFIED-PATH') -and (-not (Test-Path -LiteralPath (Join-Path $t27DirRoot '.mission\gates')))) ("exit=$t27DirExit")

# --- (6) REVOKE THROUGH THE CONSOLE -------------------------------------------------------------------
$t27R = Invoke-GateConsoleLauncher -Spec @{ Verb = 'revoke'; Kind = 'halt-ruling'; Id = 'HALT-T27-01'; MissionRoot = $t27Root; Reason = 'T-27 revoke' }
$t27RText = if (Test-Path -LiteralPath $t27Gate1) { [System.IO.File]::ReadAllText($t27Gate1) } else { '' }
$t27ListR = Get-T27ListLine -Root $t27Root -BaseName 'halt-ruling-HALT-T27-01'
Add-T27Row 'revoke through the console: exit 0, revoked_at + revoked_reason appended, list reads REVOKED' `
    (($t27R.exit -eq 0) -and ($t27RText -match '(?m)^revoked_at:[ \t]*\d') -and ((Get-T27Field $t27RText 'revoked_reason') -ceq '"T-27 revoke"') -and
     ($t27ListR -match '^halt-ruling-HALT-T27-01\s+REVOKED\s+governance\s')) ("exit=$($t27R.exit) list: $t27ListR")

# --- (7) REAPPROVE THROUGH THE CONSOLE, OVER NEW HALT BYTES ------------------------------------------
# The HALT changed (a follow-up appended), so the old ruling no longer binds it; the operator re-rules
# over the SAME file in one act and the new gate binds the NEW bytes.
Write-Utf8 -Path $t27Halt1 -Text "# HALT-T27-01`n`n**Status:** OPEN`n`nA question only the operator can settle.`n`nFollow-up: one more fact for the operator.`n"
$t27Sha1b = (Get-FileHash -Algorithm SHA256 -LiteralPath $t27Halt1).Hash.ToLowerInvariant()
$t27P = Invoke-GateConsoleLauncher -Spec @{ Verb = 'reapprove'; Kind = 'halt-ruling'; Id = 'HALT-T27-01'; Binds = $t27Rel1; MissionRoot = $t27Root; Reason = 'T-27 the HALT gained a follow-up'; Ruling = 'Re-ruled over the follow-up.' }
$t27PText = if (Test-Path -LiteralPath $t27Gate1) { [System.IO.File]::ReadAllText($t27Gate1) } else { '' }
$t27ListP = Get-T27ListLine -Root $t27Root -BaseName 'halt-ruling-HALT-T27-01'
Add-T27Row 'reapprove through the console: exit 0, prior at .revoked-1, new gate binds the NEW sha, open' `
    (($t27P.exit -eq 0) -and (Test-Path -LiteralPath (Join-Path $t27Gates 'halt-ruling-HALT-T27-01.revoked-1.yaml')) -and
     ((Get-T27Field $t27PText 'binds_sha256') -ceq $t27Sha1b) -and ($t27Sha1b -cne $t27Sha1) -and ((Get-T27Field $t27PText 'halt_id') -ceq 'HALT-T27-01') -and
     ((Get-T27Field $t27PText 'ruling') -ceq '"Re-ruled over the follow-up."') -and ($t27ListP -match '^halt-ruling-HALT-T27-01\s+open\s+governance\s')) ("exit=$($t27P.exit) list: $t27ListP")

# --- (8) -Ruling IS IGNORED FOR EVERY OTHER KIND: no other kind's bytes change -----------------------
$t27G = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'dispatch'; Id = 't27-dispatch'; Binds = 'bound.txt'; MissionRoot = $t27Root; Ruling = 'must not appear' }
$t27GText = $(if (Test-Path -LiteralPath (Join-Path $t27Gates 'dispatch-t27-dispatch.yaml')) { [System.IO.File]::ReadAllText((Join-Path $t27Gates 'dispatch-t27-dispatch.yaml')) } else { '' })
