$t28LauncherSrc = @'
param(
    [Parameter(Mandatory = $true)][string]$T28Lib,
    [Parameter(Mandatory = $true)][string]$T28Provider,
    [Parameter(Mandatory = $true)][string]$T28Root,
    [Parameter(Mandatory = $true)][string]$T28GateId,
