$ErrorActionPreference = 'Continue'
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class T28Launch {
    [DllImport("kernel32.dll")] public static extern uint SetErrorMode(uint uMode);
    [DllImport("msvcrt.dll", CallingConvention = CallingConvention.Cdecl)] static extern IntPtr memset(IntPtr dest, int c, UIntPtr count);
    public static void NativeFault() { memset((IntPtr)8, 0x41, (UIntPtr)16); }
}
"@
[void][T28Launch]::SetErrorMode(0x0003)
foreach ($t28Scrub in @('CLAUDECODE','CLAUDE_CODE_SESSION_ID','CLAUDE_CODE_ENTRYPOINT','CLAUDE_PROJECT_DIR','LAM_DISPATCH')) {
