        'managed-throw' { $script:LamConsoleConfirmProvider = { param($Context) throw [System.AccessViolationException]::new('T-28 planted') } }
        'text-throw'    { $script:LamConsoleConfirmProvider = { param($Context) throw 'T-28 planted text' } }
        'success'       { $script:LamConsoleConfirmProvider = { param($Context) @{ ok = $true; reason = 'T-28 injected success'; credential = 'injected-seam' } } }
        'failure'       { $script:LamConsoleConfirmProvider = { param($Context) @{ ok = $false; reason = 'T-28 injected credential failure'; credential = 'injected-seam' } } }
        default         { throw ('T-28 launcher: unknown provider ' + $T28Provider) }
    }
    # NEVER THE DEFAULT PROVIDER: it raises the real credential prompt.
    if (([string]$script:LamConsoleConfirmProvider) -match 'PromptSecureDesktop') { throw 'T-28 launcher: the default provider is still installed; refusing to drive it' }
    $t28Raw = Invoke-LamConsoleGateAct -Quiet -Verb 'approve' -Kind 'dispatch' -Id $T28GateId -Binds 'bound.txt' -MissionRoot $T28Root
    $t28R = @(@($t28Raw) | Where-Object { $null -ne $_ -and ($_.PSObject.Properties.Name -contains 'stage') })[-1]
    $t28Obj = @{ exit = [int]$t28R.exit; stage = [string]$t28R.stage; minted = [bool]$t28R.minted; out = [string]$t28R.out; attested = [bool]$t28R.attested; error = '' }
} catch {
    $t28Obj = @{ exit = 98; stage = 'launcher-error'; minted = $false; out = ('T-28 LAUNCHER ERROR: ' + $_.Exception.Message); attested = $false
                 error = ([string]$_.Exception.GetType().FullName + ': ' + [string]$_.Exception.Message) }
}
[System.IO.File]::WriteAllText($T28Out, (ConvertTo-Json -InputObject $t28Obj -Depth 4), (New-Object System.Text.UTF8Encoding($false)))
exit 0
'@
Write-Utf8 -Path $t28Launcher -Text $t28LauncherSrc

function Invoke-T28Launcher {
    param([string]$Lib, [string]$Provider, [string]$Label)
    $fixture = Join-Path $env:TEMP ('lam-wp4-t28' + $Label + '-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
    New-Item -ItemType Directory -Path (Join-Path $fixture '.mission') -Force | Out-Null
    Write-Utf8 -Path (Join-Path $fixture 'bound.txt') -Text "t28 bound bytes`n"
    $gateId = 't28' + $Label
    $resultFile = Join-Path $t28Dir ('t28-result-' + $Label + '.json')
    if (Test-Path -LiteralPath $resultFile) { Remove-Item -LiteralPath $resultFile -Force }
    $argLine = ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -T28Lib "{1}" -T28Provider {2} -T28Root "{3}" -T28GateId {4} -T28Out "{5}"' -f $t28Launcher, $Lib, $Provider, $fixture, $gateId, $resultFile)
    $r = [ordered]@{ label = $Label; provider = $Provider; processExit = $null; timedOut = $false; json = $false; exit = -1; stage = '(none)'; minted = $false
                     out = ''; error = ''; artifacts = -1; gateFile = $false; elapsedMs = 0 }
    $t28Clock = [System.Diagnostics.Stopwatch]::StartNew()
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try {
        $proc = Start-Process -FilePath 'powershell.exe' -ArgumentList $argLine -WindowStyle Hidden -PassThru
        $null = $proc.Handle
        if (-not $proc.WaitForExit(180000)) {
            $r.timedOut = $true
            try { $proc.Kill() } catch { }
            [void]$proc.WaitForExit(10000)
        }
        $r.processExit = $proc.ExitCode
    } finally { $ErrorActionPreference = $prevEap }
    $r.elapsedMs = $t28Clock.ElapsedMilliseconds
    if (Test-Path -LiteralPath $resultFile) {
        $obj = $null
        try { $obj = ([System.IO.File]::ReadAllText($resultFile) | ConvertFrom-Json) } catch { $obj = $null }
        if ($null -ne $obj) {
            $r.json = $true; $r.exit = [int]$obj.exit; $r.stage = [string]$obj.stage; $r.minted = [bool]$obj.minted
            $r.out = [string]$obj.out; $r.error = [string]$obj.error
        }
        Remove-Item -LiteralPath $resultFile -Force -ErrorAction SilentlyContinue
    }
    $gates = Join-Path $fixture '.mission\gates'
    $r.artifacts = @(Get-ChildItem -LiteralPath $gates -File -Force -ErrorAction SilentlyContinue).Count
    $r.gateFile = Test-Path -LiteralPath (Join-Path $gates ('dispatch-' + $gateId + '.yaml'))
    Remove-Item -LiteralPath $fixture -Recurse -Force -ErrorAction SilentlyContinue
    return [pscustomobject]$r
}
function Format-T28Launch {
    param($R)
    return ('process exit {0}{1}, result JSON {2}, exit {3}, stage {4}, minted {5}, gate files {6}, {7} ms' -f `
        $R.processExit, $(if ($R.timedOut) { ' (TIMED OUT, killed)' } else { '' }), $R.json, $R.exit, $R.stage, $R.minted, $R.artifacts, $R.elapsedMs)
}
function Get-T28RefusalLine {
    param($R)
    $line = @(([string]$R.out -split "`r?`n") | Where-Object { $_ -match 'REFUSED|ERROR' } | Select-Object -First 1)
    if ($line.Count -eq 1) { return $line[0] }
    return '(no refusal line)'
}
function Test-T28Refused {
    param($R, [string]$TypeName)
    return ($R.json -and (-not $R.timedOut) -and ($R.exit -eq 3) -and ($R.stage -eq 'confirm') -and (-not $R.minted) -and
            ($R.artifacts -eq 0) -and (-not $R.gateFile) -and ([string]$R.out).Contains('the confirm provider raised ' + $TypeName))
}

