# --- THE ITEM 1 PROBES (rows f-h): children, SetErrorMode(0x0003) first, a hard timeout ----------------
$t28ReflectProbe = Join-Path $t28Dir 't28-reflect-probe.ps1'
$t28ReflectSrc = @'
param([Parameter(Mandatory = $true)][string]$T28Lib, [Parameter(Mandatory = $true)][string]$T28Out)
$ErrorActionPreference = 'Continue'
$t28Lines = New-Object System.Collections.Generic.List[string]
function Add-T28Reading {
    param([string]$Key, $Value)
    $t28Lines.Add($Key + '=' + [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes([string]$Value)))
}
function Get-T28MarshalAs {
    param($Parameter)
    $found = @($Parameter.GetCustomAttributes([System.Runtime.InteropServices.MarshalAsAttribute], $false))
    if ($found.Count -eq 1) { return [string]$found[0].Value }
    return ''
}
try {
    Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class T28Probe { [DllImport("kernel32.dll")] public static extern uint SetErrorMode(uint uMode); }
"@
    [void][T28Probe]::SetErrorMode(0x0003)
    . $T28Lib
    Initialize-LamConsoleCredType
    $t28Type = [LamConsoleCred]
    $t28Bf = [System.Reflection.BindingFlags]'Public,NonPublic,Static,DeclaredOnly'
    Add-T28Reading 'intPtrSize' ([IntPtr]::Size)
    $t28Ext = $t28Type.GetMethod('CredUIPromptForWindowsCredentials', $t28Bf)
    Add-T28Reading 'externFound' ($null -ne $t28Ext)
    $t28Dll = @($t28Ext.GetCustomAttributes([System.Runtime.InteropServices.DllImportAttribute], $false))
    if ($t28Dll.Count -eq 1) {
        Add-T28Reading 'dllValue' $t28Dll[0].Value
        Add-T28Reading 'entryPoint' $t28Dll[0].EntryPoint
        Add-T28Reading 'exactSpelling' $t28Dll[0].ExactSpelling
    }
    $t28Params = @($t28Ext.GetParameters())
    Add-T28Reading 'paramCount' $t28Params.Count
    foreach ($t28P in $t28Params) {
        Add-T28Reading ('p' + $t28P.Position + 'Type') $t28P.ParameterType.FullName
        Add-T28Reading ('p' + $t28P.Position + 'IsOut') $t28P.IsOut
        Add-T28Reading ('p' + $t28P.Position + 'MarshalAs') (Get-T28MarshalAs -Parameter $t28P)
    }
    Add-T28Reading 'returnType' $t28Ext.ReturnType.FullName
    if ($t28Params.Count -ge 1 -and $t28Params[0].ParameterType.IsByRef) {
        $t28Elem = $t28Params[0].ParameterType.GetElementType()
        Add-T28Reading 'p0ElemName' $t28Elem.Name
        Add-T28Reading 'p0ElemValueType' $t28Elem.IsValueType
        Add-T28Reading 'p0ElemNestedPrivate' $t28Elem.IsNestedPrivate
        Add-T28Reading 'p0ElemSequential' $t28Elem.IsLayoutSequential
        $t28Fields = @($t28Elem.GetFields([System.Reflection.BindingFlags]'Instance,Public,NonPublic') | Sort-Object { [int64][System.Runtime.InteropServices.Marshal]::OffsetOf([type]$t28Elem, $_.Name) })
        Add-T28Reading 'p0ElemFields' (($t28Fields | ForEach-Object { $_.FieldType.FullName }) -join ',')
        Add-T28Reading 'p0ElemSize' ([System.Runtime.InteropServices.Marshal]::SizeOf([type]$t28Elem))
        $t28Blittable = $false
        try {
            $t28Pin = [System.Runtime.InteropServices.GCHandle]::Alloc([Activator]::CreateInstance($t28Elem), [System.Runtime.InteropServices.GCHandleType]::Pinned)
            $t28Pin.Free()
            $t28Blittable = $true
        } catch { $t28Blittable = $false }
        Add-T28Reading 'p0ElemBlittable' $t28Blittable
    }
    $t28FlagsField = $t28Type.GetField('PromptFlags', $t28Bf)
    if ($null -ne $t28FlagsField) { Add-T28Reading 'promptFlags' ([string]$t28FlagsField.GetValue($null)) }
    $t28SizeProp = $t28Type.GetProperty('CredUiInfoSize', $t28Bf)
    if ($null -ne $t28SizeProp) { Add-T28Reading 'credUiInfoSize' ([string]$t28SizeProp.GetValue($null, $null)) }
    $t28Free = $t28Type.GetMethod('CoTaskMemFree', $t28Bf)
    if ($null -ne $t28Free) { Add-T28Reading 'coTaskMemFree' (@($t28Free.GetCustomAttributes([System.Runtime.InteropServices.DllImportAttribute], $false))[0].Value) }
    $t28Hpcse = [System.Runtime.ExceptionServices.HandleProcessCorruptedStateExceptionsAttribute]
    $t28Pwf = $t28Type.GetMethod('PromptWithFlags', $t28Bf)
    Add-T28Reading 'hpcsePromptWithFlags' (($null -ne $t28Pwf) -and (@($t28Pwf.GetCustomAttributes($t28Hpcse, $false)).Count -eq 1))
    $t28Vic = $t28Type.GetMethod('VerifyIsCurrentUser', $t28Bf)
    Add-T28Reading 'hpcseVerify' (($null -ne $t28Vic) -and (@($t28Vic.GetCustomAttributes($t28Hpcse, $false)).Count -eq 1))
    $t28Quota = $t28Type.GetNestedType('QUOTA_LIMITS', [System.Reflection.BindingFlags]'NonPublic')
    if ($null -ne $t28Quota) { Add-T28Reading 'quotaSize' ([System.Runtime.InteropServices.Marshal]::SizeOf([type]$t28Quota)) }
    # (h) A NULL BUFFER: dereferenced (packed.Length) before LsaConnectUntrusted in both helpers.
    $t28VerifyReason = ''
    try {
        $t28VerifyOk = [LamConsoleCred]::VerifyIsCurrentUser($null, [uint32]0, [ref]$t28VerifyReason)
        Add-T28Reading 'verifyThrew' $false
        Add-T28Reading 'verifyReturned' $t28VerifyOk
        Add-T28Reading 'verifyReason' $t28VerifyReason
    } catch {
        Add-T28Reading 'verifyThrew' $true
        Add-T28Reading 'verifyThrewType' ($_.Exception.GetType().FullName + ' / ' + $_.Exception.GetBaseException().GetType().FullName)
    }
    Add-T28Reading 'completed' $true
} catch {
    Add-T28Reading 'probeError' ($_.Exception.GetType().FullName + ': ' + $_.Exception.Message)
}
[System.IO.File]::WriteAllLines($T28Out, [string[]]$t28Lines.ToArray())
exit 0
'@
Write-Utf8 -Path $t28ReflectProbe -Text $t28ReflectSrc

$t28DriveProbe = Join-Path $t28Dir 't28-drive-probe.ps1'
$t28DriveSrc = @'
param([Parameter(Mandatory = $true)][string]$T28Lib, [Parameter(Mandatory = $true)][string]$T28Out,
      [Parameter(Mandatory = $true)][string]$T28Mark, [switch]$T28BaseExtern)
$ErrorActionPreference = 'Continue'
$t28Lines = New-Object System.Collections.Generic.List[string]
function Add-T28Reading {
    param([string]$Key, $Value)
    $t28Lines.Add($Key + '=' + [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes([string]$Value)))
}
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class T28Probe { [DllImport("kernel32.dll")] public static extern uint SetErrorMode(uint uMode); }
// The base extern's signature, so a delegate can be BOUND to that private extern and CALLED DIRECTLY.
// MethodInfo.Invoke wraps a corrupted-state exception in a TargetInvocationException, which surfaces as the
// .NET unhandled-managed-exception exit code (0xE0434352) rather than the raw access violation; a direct
// call through a delegate (the way PowerShell's own call site reaches a method) lets the raw AV terminate
// the process with 0xC0000005, which is what the base control asserts.
public delegate int T28CredExtern(IntPtr pUiInfo, int dwAuthError, ref uint pulAuthPackage, IntPtr pvIn, uint cbIn, out IntPtr ppOut, out uint cbOut, ref bool pfSave, uint dwFlags);
"@
[void][T28Probe]::SetErrorMode(0x0003)
try {
    . $T28Lib
    Initialize-LamConsoleCredType
    $t28Bf = [System.Reflection.BindingFlags]'NonPublic,Static,DeclaredOnly'
    # FLAGS 0x20 (CREDUIWIN_IN_CRED_ONLY) ONLY, NO INCOMING BUFFER -- NEVER 0x1000.
    $t28InCredOnly = [uint32]0x20
    $t28Returned = $null
    if ($T28BaseExtern) {
        # BASE CONTROL: bind a delegate to the base extern and call it DIRECTLY, so the raw AV crashes
        # the child with 0xC0000005 (MethodInfo.Invoke would wrap it to 0xE0434352 instead).
        $t28Ext = [LamConsoleCred].GetMethod('CredUIPromptForWindowsCredentials', $t28Bf)
        if (-not $t28Ext) { throw 'T-28 drive probe: the base extern is absent' }
        $t28Del = [Delegate]::CreateDelegate([T28CredExtern], $t28Ext)
        $t28Ap = [uint32]0; $t28Ob = [IntPtr]::Zero; $t28Os = [uint32]0; $t28Sv = $false
        if ($t28InCredOnly -ne 0x20) { throw 'T-28 drive probe: flags are not 0x20' }
        [System.IO.File]::WriteAllText($T28Mark, [string][DateTime]::UtcNow.Ticks)
        $t28Watch = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            $t28Returned = $t28Del.Invoke([IntPtr]::Zero, 0, [ref]$t28Ap, [IntPtr]::Zero, 0, [ref]$t28Ob, [ref]$t28Os, [ref]$t28Sv, $t28InCredOnly)
            Add-T28Reading 'threw' $false
        } catch {
            Add-T28Reading 'threw' $true
            Add-T28Reading 'threwType' ($_.Exception.GetBaseException().GetType().FullName)
        }
        Add-T28Reading 'elapsedMs' $t28Watch.ElapsedMilliseconds
        Add-T28Reading 'returned' $t28Returned
        Add-T28Reading 'rc' $t28Returned
    } else {
        # CURRENT CONSOLE: reflect-invoke the private PromptWithFlags(0x20, ...), which returns cleanly (no
        # fault), so MethodInfo.Invoke is fine and the byref out args carry rc, reason and the null buffer.
        $t28Method = [LamConsoleCred].GetMethod('PromptWithFlags', $t28Bf)
        if (-not $t28Method) { throw 'T-28 drive probe: PromptWithFlags is absent' }
        $t28Args = [object[]]@($t28InCredOnly, $null, [uint32]0, $null, [uint32]0)
        if ([uint32]$t28Args[0] -ne 0x20) { throw 'T-28 drive probe: flags are not 0x20' }
        [System.IO.File]::WriteAllText($T28Mark, [string][DateTime]::UtcNow.Ticks)
        $t28Watch = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            $t28Returned = $t28Method.Invoke($null, $t28Args)
            Add-T28Reading 'threw' $false
        } catch {
            Add-T28Reading 'threw' $true
            Add-T28Reading 'threwType' ($_.Exception.GetBaseException().GetType().FullName)
        }
        Add-T28Reading 'elapsedMs' $t28Watch.ElapsedMilliseconds
        Add-T28Reading 'returned' $t28Returned
        Add-T28Reading 'rc' $t28Args[4]
        Add-T28Reading 'reason' $t28Args[3]
        Add-T28Reading 'packedNull' ($null -eq $t28Args[1])
    }
    Add-T28Reading 'completed' $true
} catch {
    Add-T28Reading 'probeError' ($_.Exception.GetType().FullName + ': ' + $_.Exception.Message)
}
[System.IO.File]::WriteAllLines($T28Out, [string[]]$t28Lines.ToArray())
exit 0
'@
Write-Utf8 -Path $t28DriveProbe -Text $t28DriveSrc

if (-not ('T28Windows' -as [type])) {
    Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class T28Windows {
    delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
    [DllImport("user32.dll")] static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetClassName(IntPtr hWnd, StringBuilder lpClassName, int nMaxCount);
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
    // Every TOP-LEVEL window of the given class, as "hwnd:pid".
    public static string[] Find(string className) {
        List<string> found = new List<string>();
        EnumWindows(delegate (IntPtr hWnd, IntPtr lParam) {
            StringBuilder sb = new StringBuilder(256);
            GetClassName(hWnd, sb, sb.Capacity);
            if (string.Equals(sb.ToString(), className, StringComparison.Ordinal)) {
                uint pid;
                GetWindowThreadProcessId(hWnd, out pid);
                found.Add(hWnd.ToInt64().ToString() + ":" + pid.ToString());
            }
            return true;
        }, IntPtr.Zero);
        return found.ToArray();
    }
}
'@ -Language CSharp
}
$t28DialogClass = 'Credential Dialog Xaml Host'

function Read-T28Readings {
    param([string]$Path)
    $readings = @{}
    if (Test-Path -LiteralPath $Path) {
        foreach ($line in @([System.IO.File]::ReadAllLines($Path))) {
            $eq = $line.IndexOf('=')
            if ($eq -lt 1) { continue }
            $readings[$line.Substring(0, $eq)] = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($line.Substring($eq + 1)))
        }
    }
    return $readings
}

function Invoke-T28Probe {
    # A probe child, hidden, under a hard timeout. With -Watch, a WATCHDOG polls every top-level window of
    # class 'Credential Dialog Xaml Host' while the child runs: any window not present before the child started
    # FAILS the drive, the child is killed, and so is any CredentialUIBroker.exe whose start time is after the
    # call's own timestamp (written by the child just before the call) -- and no other process.
    param([string]$Script, [string]$Lib, [string]$Label, [int]$TimeoutMs, [switch]$Watch, [switch]$BaseExtern)
    $outFile = Join-Path $t28Dir ('t28-probe-' + $Label + '.txt')
    $markFile = Join-Path $t28Dir ('t28-probe-' + $Label + '.mark')
    foreach ($stale in @($outFile, $markFile)) { if (Test-Path -LiteralPath $stale) { Remove-Item -LiteralPath $stale -Force } }
    $argLine = ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -T28Lib "{1}" -T28Out "{2}"' -f $Script, $Lib, $outFile)
    if ($Watch) { $argLine += (' -T28Mark "{0}"' -f $markFile) }
    if ($BaseExtern) { $argLine += ' -T28BaseExtern' }
    $w = [ordered]@{ processExit = $null; timedOut = $false; windowSeen = $false; windows = ''; brokersKilled = ''; polls = 0; elapsedMs = 0; readings = @{} }
    $before = @{}
    if ($Watch) { foreach ($hw in @([T28Windows]::Find($t28DialogClass))) { $before[$hw] = $true } }
    $t28Clock = [System.Diagnostics.Stopwatch]::StartNew()
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try {
        $proc = Start-Process -FilePath 'powershell.exe' -ArgumentList $argLine -WindowStyle Hidden -PassThru
        $null = $proc.Handle
        $startedUtc = $proc.StartTime.ToUniversalTime()
        $newWindows = @()
        while ($true) {
            $exited = $proc.WaitForExit(40)
            if ($Watch) {
                $w.polls++
                $newWindows = @([T28Windows]::Find($t28DialogClass) | Where-Object { -not $before.ContainsKey($_) })
                if ($newWindows.Count -gt 0) { $w.windowSeen = $true; break }
            }
            if ($exited) { break }
            if ($t28Clock.ElapsedMilliseconds -gt $TimeoutMs) { $w.timedOut = $true; break }
        }
        if ($Watch -and (-not $w.windowSeen)) {
            $newWindows = @([T28Windows]::Find($t28DialogClass) | Where-Object { -not $before.ContainsKey($_) })
            if ($newWindows.Count -gt 0) { $w.windowSeen = $true }
        }
        if ($w.windowSeen -or $w.timedOut) {
            $w.windows = ($newWindows -join ',')
            if (-not $proc.HasExited) { try { $proc.Kill() } catch { }; [void]$proc.WaitForExit(10000) }
            if ($Watch) {
                $callUtc = $startedUtc
                if (Test-Path -LiteralPath $markFile) { try { $callUtc = [DateTime]::new([int64]([System.IO.File]::ReadAllText($markFile).Trim()), [DateTimeKind]::Utc) } catch { $callUtc = $startedUtc } }
                $killed = @()
                foreach ($broker in @(Get-Process -Name 'CredentialUIBroker' -ErrorAction SilentlyContinue)) {
                    $brokerStart = $null
                    try { $brokerStart = $broker.StartTime.ToUniversalTime() } catch { $brokerStart = $null }
                    if (($null -ne $brokerStart) -and ($brokerStart -ge $callUtc)) {
                        try { $broker.Kill(); $killed += [string]$broker.Id } catch { $killed += ([string]$broker.Id + '(kill failed)') }
                    }
                }
                $w.brokersKilled = ($killed -join ',')
            }
        }
        [void]$proc.WaitForExit(10000)
        $w.processExit = $proc.ExitCode
    } finally { $ErrorActionPreference = $prevEap }
    $w.elapsedMs = $t28Clock.ElapsedMilliseconds
    $w.readings = Read-T28Readings -Path $outFile
    foreach ($done in @($outFile, $markFile)) { Remove-Item -LiteralPath $done -Force -ErrorAction SilentlyContinue }
    return [pscustomobject]$w
}

# --- (f) ITEM 1's SIGNATURE, BY REFLECTION, COMPILE ONLY; BASE CONTROL: the base p0 is IntPtr ----
$t28F = Invoke-T28Probe -Script $t28ReflectProbe -Lib $lamConsole -Label 'f' -TimeoutMs 120000
$t28Fr = $t28F.readings
$t28Ip = 0
if ($t28Fr.ContainsKey('intPtrSize')) { $t28Ip = [int]$t28Fr['intPtrSize'] }
$t28CiExpect = 4 + ($t28Ip - 4) + 4 * $t28Ip
$t28FlagsNum = [int64]0
if ($t28Fr.ContainsKey('promptFlags') -and ($t28Fr['promptFlags'] -match '^\d+$')) { $t28FlagsNum = [int64]$t28Fr['promptFlags'] }
$t28FChecks = [ordered]@{
    'probe completed'                                         = ($t28Fr['completed'] -eq 'True') -and (-not $t28F.timedOut)
    'extern CredUIPromptForWindowsCredentials found'          = ($t28Fr['externFound'] -eq 'True')
    'DllImport credui.dll'                                    = ($t28Fr['dllValue'] -ceq 'credui.dll')
    'EntryPoint CredUIPromptForWindowsCredentialsW'           = ($t28Fr['entryPoint'] -ceq 'CredUIPromptForWindowsCredentialsW')
    'ExactSpelling'                                           = ($t28Fr['exactSpelling'] -eq 'True')
    '9 parameters'                                            = ($t28Fr['paramCount'] -eq '9')
    'p0 ByRef to private value type CREDUI_INFO (not out)'    = ($t28Fr['p0Type'] -like '*+CREDUI_INFO&') -and ($t28Fr['p0IsOut'] -eq 'False') -and ($t28Fr['p0ElemName'] -ceq 'CREDUI_INFO') -and
                                                                ($t28Fr['p0ElemValueType'] -eq 'True') -and ($t28Fr['p0ElemNestedPrivate'] -eq 'True')
    'CREDUI_INFO Sequential'                                  = ($t28Fr['p0ElemSequential'] -eq 'True')
    'CREDUI_INFO fields Int32,IntPtr,IntPtr,IntPtr,IntPtr'    = ($t28Fr['p0ElemFields'] -ceq 'System.Int32,System.IntPtr,System.IntPtr,System.IntPtr,System.IntPtr')
    'CREDUI_INFO blittable (pins)'                            = ($t28Fr['p0ElemBlittable'] -eq 'True')
    'SizeOf(CREDUI_INFO) = 4 + (IntPtr.Size - 4) + 4*IntPtr.Size' = ($t28Ip -gt 0) -and ($t28Fr['p0ElemSize'] -eq [string]$t28CiExpect)
    'p1 UInt32'                                               = ($t28Fr['p1Type'] -ceq 'System.UInt32')
    'p2 UInt32 ByRef (ref)'                                   = ($t28Fr['p2Type'] -ceq 'System.UInt32&') -and ($t28Fr['p2IsOut'] -eq 'False')
    'p3 IntPtr'                                               = ($t28Fr['p3Type'] -ceq 'System.IntPtr')
    'p4 UInt32'                                               = ($t28Fr['p4Type'] -ceq 'System.UInt32')
    'p5 IntPtr ByRef IsOut'                                   = ($t28Fr['p5Type'] -ceq 'System.IntPtr&') -and ($t28Fr['p5IsOut'] -eq 'True')
    'p6 UInt32 ByRef IsOut'                                   = ($t28Fr['p6Type'] -ceq 'System.UInt32&') -and ($t28Fr['p6IsOut'] -eq 'True')
    'p7 Boolean ByRef (ref) MarshalAs Bool'                   = ($t28Fr['p7Type'] -ceq 'System.Boolean&') -and ($t28Fr['p7IsOut'] -eq 'False') -and ($t28Fr['p7MarshalAs'] -ceq 'Bool')
    'p8 UInt32'                                               = ($t28Fr['p8Type'] -ceq 'System.UInt32')
    'returns UInt32'                                          = ($t28Fr['returnType'] -ceq 'System.UInt32')
    'PromptFlags 0x1000, neither 0x200 nor 0x1 set'           = ($t28FlagsNum -eq 0x1000) -and (($t28FlagsNum -band 0x200) -eq 0) -and (($t28FlagsNum -band 0x1) -eq 0)
    'CredUiInfoSize = SizeOf(CREDUI_INFO)'                    = ($t28Fr.ContainsKey('credUiInfoSize')) -and ($t28Fr['credUiInfoSize'] -eq $t28Fr['p0ElemSize'])
    'ole32 CoTaskMemFree extern'                              = ($t28Fr['coTaskMemFree'] -ceq 'ole32.dll')
    'PromptWithFlags carries HPCSE'                           = ($t28Fr['hpcsePromptWithFlags'] -eq 'True')
    'VerifyIsCurrentUser carries HPCSE'                       = ($t28Fr['hpcseVerify'] -eq 'True')
    'SizeOf(QUOTA_LIMITS) = 5 SIZE_T 8-aligned + 8'           = ($t28Ip -gt 0) -and ($t28Fr['quotaSize'] -eq [string]((8 * [math]::Ceiling((5 * $t28Ip) / 8)) + 8))
}
$t28FFailed = @($t28FChecks.Keys | Where-Object { -not $t28FChecks[$_] })
$t28Fb = if ($t28BaseReady) { Invoke-T28Probe -Script $t28ReflectProbe -Lib $t28BaseLib -Label 'fbase' -TimeoutMs 120000 } else { $null }
