$t28FOk = ($t28FFailed.Count -eq 0) -and $t28FbOk
if (-not $t28FOk) { $t28ok = $false }
$t28rows.Add(('    (f) ITEM 1 SIGNATURE BY REFLECTION (compile only; IntPtr.Size {0}): {1} of {2} readings hold{3}; p0 {4}, SizeOf(CREDUI_INFO) {5}, PromptFlags {6}, SizeOf(QUOTA_LIMITS) {7}' -f `
    $t28Ip, ($t28FChecks.Count - $t28FFailed.Count), $t28FChecks.Count, $(if ($t28FFailed.Count) { ' -- FAILED: ' + ($t28FFailed -join '; ') } else { '' }),
    $t28Fr['p0Type'], $t28Fr['p0ElemSize'], $t28Fr['promptFlags'], $t28Fr['quotaSize']))
if ($t28Fr.ContainsKey('probeError')) { $t28rows.Add('        probe error: ' + $t28Fr['probeError']) }
$t28rows.Add(('    (f) BASE CONTROL helper: extern p0 is {0}, where the SDK takes PCREDUI_INFOW and the base passed NULL -- the mismatch named : {1} ; row (f) : {2}' -f $t28FbP0, $t28FbOk, $t28FOk))

# --- (g) ITEM 1's NO-UI NATIVE DRIVE: PromptWithFlags(0x20) returns rc 87; BASE CONTROL crashes 0xC0000005 --
$t28G = Invoke-T28Probe -Script $t28DriveProbe -Lib $lamConsole -Label 'g' -TimeoutMs 30000 -Watch
$t28Gr = $t28G.readings
$t28GOkCur = ($t28Gr['completed'] -eq 'True') -and ($t28Gr['threw'] -eq 'False') -and ($t28Gr['returned'] -eq 'False') -and ($t28Gr['rc'] -eq '87') -and
