    $(if ($t28Gb) { $t28Gb.processExit } else { '(not run)' }), $(if ($t28Gb) { $t28Gb.readings.ContainsKey('completed') } else { '' }), $(if ($t28Gb) { $t28Gb.windowSeen } else { '' }),
    $(if ($t28Gb) { $t28Gb.timedOut } else { '' }), $(if ($t28Gb) { $t28Gb.brokersKilled } else { '' }), $t28GbOk, $t28GOk))

