# =================================================================================================
# T-29 -- THE OPERATOR'S CREDENTIAL PROBE: tools\lam\lam-console-probe.ps1
# =================================================================================================
# WHAT IT IS FOR. No agent session may raise the secure-desktop prompt (it lands on the operator's screen),
# so the operator drives it, before the second real console drive, through a probe that calls ONLY
# LamConsoleCred.PromptSecureDesktop and prints the packed buffer's LENGTH and the auth package, never the
# credential. This member measures the probe's contract without a prompt:
#   (a) its MAIN flow, run as a child with stdin redirected from an empty file, refuses before loading,
#       compiling or calling anything: exit 2, one REFUSED line, no LAMPROBE line;
#   (b) dot-sourced in a hidden-console child with $script:LamConsoleProbePrompt PLANTED to return a known
#       48-byte buffer, it exits 0 with the five lines in order, and NO rendering of that buffer -- hex,
#       dashed hex, base64, ASCII or decimal, whole or any window -- reaches the captured host output,
#       and every byte of the planted array is 0 afterwards (the finally zeroed it in place);
#   (c) a planted cancel is exit 1, rc=1223; (d) a planted native-fault report is exit 3 naming the type;
#   (e) statically, over its AST, it calls PromptSecureDesktop and Initialize-LamConsoleCredType and no LSA,
#       gate, attestation, file-writing or environment-setting call;
#   (f) its identity line's sha256 is Get-FileHash of lam-console.ps1 and its flags line reads 0x00001000.
#
# WHAT THIS MEMBER NEVER DOES. It never runs the probe's main flow with a real console, never calls
# PromptSecureDesktop, never passes CREDUIWIN_SECURE_PROMPT, makes no CredUI call and reaches no LSA call.
# The (b)-(d) children compile LamConsoleCred (compile only, as T-28's reflection probe does), call
# SetErrorMode(0x0003) first, run under a hard timeout, and REFUSE to drive the probe if the default prompt
# (the one that calls PromptSecureDesktop) is still installed after planting. They run in a hidden console
# with no stdin redirect because the probe's own console test would otherwise refuse before the seam.
$t29ok = $true
$t29rows = New-Object System.Collections.Generic.List[string]
$t29Dir = Join-Path $sandbox 't29'
New-Item -ItemType Directory -Path $t29Dir -Force | Out-Null
$t29Probe = Join-Path $repoRoot 'tools\lam\lam-console-probe.ps1'
$t29Present = Test-Path -LiteralPath $t29Probe -PathType Leaf
if (-not $t29Present) { $t29ok = $false }
$t29rows.Add(('    probe {0} present: {1}' -f $t29Probe, $t29Present))

# THE KNOWN BUFFER: 48 printable ASCII bytes chosen so every rendering is distinctive and none occurs in the
# probe's fixed text. Handed to the child as a file, so the canary has one definition in this file.
$t29Canary = [byte[]]@(0x6B,0x37,0x51,0x7A,0x23,0x57,0x6D,0x32,0x24,0x58,0x76,0x39,0x21,0x4A,0x70,0x34,
                       0x25,0x52,0x74,0x38,0x26,0x42,0x6E,0x33,0x2A,0x48,0x79,0x36,0x28,0x4C,0x64,0x31,
                       0x29,0x46,0x67,0x35,0x2B,0x43,0x73,0x30,0x3D,0x55,0x65,0x37,0x3F,0x54,0x61,0x32)
$t29CanaryFile = Join-Path $t29Dir 't29-canary.bin'
[System.IO.File]::WriteAllBytes($t29CanaryFile, $t29Canary)
$t29Fixed1 = 'lam-console-probe: PROBE ONLY -- calls LamConsoleCred.PromptSecureDesktop and nothing else: no compose, no token, no LsaLogonUser, no gate, no attestation line, nothing written.'
$t29Fixed4 = 'lam-console-probe: raising the SECURE-DESKTOP credential prompt now -- enter your own credential to test collection, or press Cancel.'
$t29IdRx = '^lam-console-probe: lam-console\.ps1 (.+) sha256 ([0-9a-f]{64}) \((\d+) bytes\)$'
$t29FlagsRx = '^lam-console-probe: process 64-bit (True|False); CREDUI_INFO marshalled size (\d+) bytes; dwFlags 0x([0-9A-F]{8})$'

# --- THE T-29 LAUNCHER (rows b-d) ---------------------------------------------------------------------
$t29Launcher = Join-Path $t29Dir 't29-launcher.ps1'
$t29LauncherSrc = @'
param(
    [Parameter(Mandatory = $true)][string]$T29Probe,
    [Parameter(Mandatory = $true)][string]$T29Case,
    [Parameter(Mandatory = $true)][string]$T29Canary,
    [Parameter(Mandatory = $true)][string]$T29Out
)
$ErrorActionPreference = 'Continue'
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class T29Launch { [DllImport("kernel32.dll")] public static extern uint SetErrorMode(uint uMode); }
"@
[void][T29Launch]::SetErrorMode(0x0003)
foreach ($t29Scrub in @('CLAUDECODE','CLAUDE_CODE_SESSION_ID','CLAUDE_CODE_ENTRYPOINT','CLAUDE_PROJECT_DIR','LAM_DISPATCH')) {
    [Environment]::SetEnvironmentVariable($t29Scrub, $null)
}
$t29Obj = [ordered]@{ completed = $false; error = ''; exit = -1; lines = @(); captured = @(); controlCaptured = $false; plantedCalls = -1
                      keptLength = -1; keptNonZero = -1; inputRedirected = [bool][Console]::IsInputRedirected; keyAvailableThrew = $false }
try { $null = [Console]::KeyAvailable } catch { $t29Obj.keyAvailableThrew = $true }
try {
    $script:T29Kept = [System.IO.File]::ReadAllBytes($T29Canary)
    $script:T29Calls = 0
    . $T29Probe
    switch ($T29Case) {
        'collected' { $script:LamConsoleProbePrompt = { $script:T29Calls++; return @{ collected = $true; packed = $script:T29Kept; authPackage = [uint32]7; reason = 'collected'; rc = [uint32]0 } } }
        'cancelled' { $script:LamConsoleProbePrompt = { $script:T29Calls++; return @{ collected = $false; packed = $null; authPackage = [uint32]0; reason = 'operator cancelled the secure-desktop prompt (rc 1223 ERROR_CANCELLED)'; rc = [uint32]1223 } } }
        'faulted'   { $script:LamConsoleProbePrompt = { $script:T29Calls++; return @{ collected = $false; packed = $null; authPackage = [uint32]0; reason = 'native exception System.AccessViolationException inside CredUIPromptForWindowsCredentials: Attempted to read or write protected memory. This is often an indication that other memory is corrupt.'; rc = [uint32]4294967295 } } }
        default     { throw ('T-29 launcher: unknown case ' + $T29Case) }
    }
    # NEVER THE DEFAULT PROMPT: it calls PromptSecureDesktop, which raises the real secure-desktop prompt.
    if (([string]$script:LamConsoleProbePrompt) -match 'PromptSecureDesktop') { throw 'T-29 launcher: the default prompt is still installed; refusing to drive it' }
    $t29Stream = @(& { Write-Host 'T-29 capture control: a Write-Host line before the probe'; Invoke-LamConsoleProbe } *>&1)
    $t29Result = $null
    $t29Host = New-Object System.Collections.Generic.List[string]
    foreach ($t29Item in $t29Stream) {
        if ($t29Item -is [System.Collections.IDictionary]) { if ($t29Item.Contains('exit')) { $t29Result = $t29Item } }
        else { $t29Host.Add([string]$t29Item) }
    }
    if ($null -eq $t29Result) { throw 'T-29 launcher: Invoke-LamConsoleProbe returned no result' }
    $t29Obj.exit = [int]$t29Result['exit']
    $t29Obj.lines = [string[]]@($t29Result['lines'])
    $t29Obj.captured = [string[]]$t29Host.ToArray()
    $t29Obj.controlCaptured = ($t29Host -contains 'T-29 capture control: a Write-Host line before the probe')
    $t29Obj.plantedCalls = [int]$script:T29Calls
    $t29Obj.keptLength = $script:T29Kept.Length
    $t29Obj.keptNonZero = @($script:T29Kept | Where-Object { $_ -ne 0 }).Count
    $t29Obj.completed = $true
} catch {
    $t29Obj.error = ([string]$_.Exception.GetType().FullName + ': ' + [string]$_.Exception.Message)
}
[System.IO.File]::WriteAllText($T29Out, (ConvertTo-Json -InputObject $t29Obj -Depth 4), (New-Object System.Text.UTF8Encoding($false)))
exit 0
'@
Write-Utf8 -Path $t29Launcher -Text $t29LauncherSrc

function Invoke-T29Child {
    # A hidden-console child (no stdin redirect), under a hard timeout, returning the launcher's readings.
    param([string]$Probe, [string]$Case)
    $resultFile = Join-Path $t29Dir ('t29-result-' + $Case + '.json')
    if (Test-Path -LiteralPath $resultFile) { Remove-Item -LiteralPath $resultFile -Force }
    $argLine = ('-NoProfile -ExecutionPolicy Bypass -File "{0}" -T29Probe "{1}" -T29Case {2} -T29Canary "{3}" -T29Out "{4}"' -f $t29Launcher, $Probe, $Case, $t29CanaryFile, $resultFile)
    $r = [ordered]@{ case = $Case; processExit = $null; timedOut = $false; json = $false; completed = $false; error = ''; exit = -1; lines = @(); captured = @()
                     controlCaptured = $false; plantedCalls = -1; keptLength = -1; keptNonZero = -1; inputRedirected = $null; keyAvailableThrew = $null; elapsedMs = 0 }
    $t29Clock = [System.Diagnostics.Stopwatch]::StartNew()
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try {
        $proc = Start-Process -FilePath 'powershell.exe' -ArgumentList $argLine -WindowStyle Hidden -PassThru
        $null = $proc.Handle
        if (-not $proc.WaitForExit(120000)) {
            $r.timedOut = $true
            try { $proc.Kill() } catch { }
            [void]$proc.WaitForExit(10000)
        }
        $r.processExit = $proc.ExitCode
    } finally { $ErrorActionPreference = $prevEap }
    $r.elapsedMs = $t29Clock.ElapsedMilliseconds
    if (Test-Path -LiteralPath $resultFile) {
        $obj = $null
        try { $obj = ([System.IO.File]::ReadAllText($resultFile) | ConvertFrom-Json) } catch { $obj = $null }
        if ($null -ne $obj) {
            $r.json = $true; $r.completed = [bool]$obj.completed; $r.error = [string]$obj.error; $r.exit = [int]$obj.exit
            $r.lines = [string[]]@($obj.lines); $r.captured = [string[]]@($obj.captured); $r.controlCaptured = [bool]$obj.controlCaptured
            $r.plantedCalls = [int]$obj.plantedCalls; $r.keptLength = [int]$obj.keptLength; $r.keptNonZero = [int]$obj.keptNonZero
            $r.inputRedirected = $obj.inputRedirected; $r.keyAvailableThrew = $obj.keyAvailableThrew
        }
        Remove-Item -LiteralPath $resultFile -Force -ErrorAction SilentlyContinue
    }
    return [pscustomobject]$r
}

function Invoke-T29Redirected {
    # The probe's MAIN flow as a hidden child with stdin redirected from an EMPTY file, 60 s hard kill.
    param([string]$Probe)
    $stdinFile = Join-Path $t29Dir 't29-a-stdin-empty.txt'
    $outFile = Join-Path $t29Dir 't29-a-stdout.txt'
    $errFile = Join-Path $t29Dir 't29-a-stderr.txt'
    [System.IO.File]::WriteAllBytes($stdinFile, [byte[]]@())
    foreach ($stale in @($outFile, $errFile)) { if (Test-Path -LiteralPath $stale) { Remove-Item -LiteralPath $stale -Force } }
    $argLine = ('-NoProfile -ExecutionPolicy Bypass -File "{0}"' -f $Probe)
    $w = [ordered]@{ processExit = $null; timedOut = $false; stdinBytes = ([System.IO.FileInfo]$stdinFile).Length; lines = @(); stderr = ''; elapsedMs = 0 }
    $t29Clock = [System.Diagnostics.Stopwatch]::StartNew()
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try {
        $proc = Start-Process -FilePath 'powershell.exe' -ArgumentList $argLine -WindowStyle Hidden -PassThru `
                              -RedirectStandardInput $stdinFile -RedirectStandardOutput $outFile -RedirectStandardError $errFile
        $null = $proc.Handle
        if (-not $proc.WaitForExit(60000)) {
            $w.timedOut = $true
            try { $proc.Kill() } catch { }
            [void]$proc.WaitForExit(10000)
        }
        $w.processExit = $proc.ExitCode
    } finally { $ErrorActionPreference = $prevEap }
    $w.elapsedMs = $t29Clock.ElapsedMilliseconds
    if (Test-Path -LiteralPath $outFile) { $w.lines = [string[]]@([System.IO.File]::ReadAllLines($outFile) | Where-Object { $_.Trim() -ne '' }) }
    if (Test-Path -LiteralPath $errFile) { $w.stderr = [System.IO.File]::ReadAllText($errFile).Trim() }
    foreach ($done in @($stdinFile, $outFile, $errFile)) { Remove-Item -LiteralPath $done -Force -ErrorAction SilentlyContinue }
    return [pscustomobject]$w
}

function Get-T29Renderings {
    # EVERY RENDERING ROW (b) SEARCHES FOR: the whole buffer as hex, dashed hex, base64 and ASCII, and EVERY
    # window of it -- each 8-byte window as hex, dashed hex, ASCII, and space- and LF-joined decimal, and each
    # 6-byte window as base64 (an unaligned base64 of part of the buffer is not a substring of the whole's).
    # Returns @{ kind; text; ci } where ci marks a case-insensitive (hex) match.
    param([byte[]]$Bytes)
    $found = New-Object System.Collections.Generic.List[object]
    $found.Add(@{ kind = 'hex whole'; text = ([BitConverter]::ToString($Bytes)).Replace('-', ''); ci = $true })
    $found.Add(@{ kind = 'dashed hex whole'; text = [BitConverter]::ToString($Bytes); ci = $true })
    $found.Add(@{ kind = 'base64 whole'; text = [Convert]::ToBase64String($Bytes); ci = $false })
    $found.Add(@{ kind = 'ascii whole'; text = [System.Text.Encoding]::ASCII.GetString($Bytes); ci = $false })
    for ($wi = 0; $wi -le ($Bytes.Length - 8); $wi++) {
        $win = New-Object byte[] 8
        [Array]::Copy($Bytes, $wi, $win, 0, 8)
        $found.Add(@{ kind = 'hex window'; text = ([BitConverter]::ToString($win)).Replace('-', ''); ci = $true })
        $found.Add(@{ kind = 'dashed hex window'; text = [BitConverter]::ToString($win); ci = $true })
        $found.Add(@{ kind = 'ascii window'; text = [System.Text.Encoding]::ASCII.GetString($win); ci = $false })
        $found.Add(@{ kind = 'decimal window (space)'; text = (@($win | ForEach-Object { [string]$_ }) -join ' '); ci = $false })
        $found.Add(@{ kind = 'decimal window (LF)'; text = (@($win | ForEach-Object { [string]$_ }) -join "`n"); ci = $false })
    }
    for ($wi = 0; $wi -le ($Bytes.Length - 6); $wi++) {
        $win = New-Object byte[] 6
        [Array]::Copy($Bytes, $wi, $win, 0, 6)
        $found.Add(@{ kind = 'base64 window'; text = [Convert]::ToBase64String($win); ci = $false })
    }
    return $found.ToArray()
}

function Find-T29Leaks {
    # Returns the kinds of every rendering found in the text (CRLF folded to LF first).
    param([string]$Text, [object[]]$Renderings)
    $flat = $Text -replace "`r`n", "`n"
    $hits = New-Object System.Collections.Generic.List[string]
    foreach ($rd in $Renderings) {
        $cmp = [System.StringComparison]::Ordinal
        if ($rd.ci) { $cmp = [System.StringComparison]::OrdinalIgnoreCase }
        if ($flat.IndexOf([string]$rd.text, $cmp) -ge 0) { $hits.Add([string]$rd.kind) }
    }
    return , $hits.ToArray()
}

function Test-T29InOrder {
    # Every expected line occurs in the captured host lines, in order.
    param([string[]]$Expected, [string[]]$Captured)
    $at = 0
    foreach ($ex in @($Expected)) {
        $hit = -1
        for ($ci = $at; $ci -lt @($Captured).Count; $ci++) { if ([string]::Equals($Captured[$ci], $ex, [System.StringComparison]::Ordinal)) { $hit = $ci; break } }
        if ($hit -lt 0) { return $false }
        $at = $hit + 1
    }
    return $true
}

# --- (a) THE MAIN FLOW REFUSES WITHOUT A CONSOLE ----------------------------------------------------------
$t29A = if ($t29Present) { Invoke-T29Redirected -Probe $t29Probe } else { $null }
$t29AOk = ($null -ne $t29A) -and (-not $t29A.timedOut) -and ($t29A.processExit -eq 2) -and (@($t29A.lines).Count -eq 1) -and
          ([string]@($t29A.lines)[0]).StartsWith('lam-console-probe: REFUSED before any prompt -- no interactive console', [System.StringComparison]::Ordinal) -and
          ([string]@($t29A.lines)[0]).EndsWith('.') -and (@(@($t29A.lines) | Where-Object { $_.StartsWith('LAMPROBE') }).Count -eq 0)
if (-not $t29AOk) { $t29ok = $false }
if ($t29A) {
    $t29rows.Add(('    (a) MAIN FLOW, stdin redirected from an empty file ({0} bytes), hidden, 60 s kill: process exit {1}{2}, {3} non-empty stdout line(s), LAMPROBE lines {4}, stderr {5} chars, {6} ms : {7}' -f `
        $t29A.stdinBytes, $t29A.processExit, $(if ($t29A.timedOut) { ' (TIMED OUT, killed)' } else { '' }), @($t29A.lines).Count,
        @(@($t29A.lines) | Where-Object { $_.StartsWith('LAMPROBE') }).Count, ([string]$t29A.stderr).Length, $t29A.elapsedMs, $t29AOk))
    foreach ($t29Line in @($t29A.lines)) { $t29rows.Add('        ' + $t29Line) }
} else {
    $t29rows.Add('    (a) not run: the probe is absent : False')
}

# --- (b) NEVER THE CREDENTIAL: a planted 48-byte buffer is collected, never rendered, and zeroed in place ---
$t29Renderings = Get-T29Renderings -Bytes $t29Canary
$t29B = if ($t29Present) { Invoke-T29Child -Probe $t29Probe -Case 'collected' } else { $null }
$t29BOk = $false
if ($t29B) {
    $t29BLines = [string[]]@($t29B.lines)
    $t29BExpect = 'LAMPROBE collected=true rc=0 packed_length=48 auth_package=7 reason=collected'
    $t29BShape = ($t29BLines.Count -eq 5) -and ($t29BLines[0] -ceq $t29Fixed1) -and ($t29BLines[1] -cmatch $t29IdRx) -and
                 ($t29BLines[2] -cmatch $t29FlagsRx) -and ($t29BLines[3] -ceq $t29Fixed4) -and ($t29BLines[4] -ceq $t29BExpect)
    $t29BCapture = $t29B.controlCaptured -and (Test-T29InOrder -Expected $t29BLines -Captured ([string[]]@($t29B.captured)))
    $t29BText = ((@($t29B.captured) + @($t29BLines)) -join "`n")
    $t29BLeaks = Find-T29Leaks -Text $t29BText -Renderings $t29Renderings
    $t29BZeroed = ($t29B.keptLength -eq 48) -and ($t29B.keptNonZero -eq 0)
    $t29BOk = $t29B.json -and $t29B.completed -and (-not $t29B.timedOut) -and ($t29B.exit -eq 0) -and ($t29B.plantedCalls -eq 1) -and
              $t29BShape -and $t29BCapture -and (@($t29BLeaks).Count -eq 0) -and $t29BZeroed
    $t29rows.Add(('    (b) PLANTED COLLECT (48-byte buffer, auth package 7), dot-sourced in a hidden console (stdin redirected {0}, KeyAvailable threw {1}): process exit {2}{3}, result JSON {4}, completed {5}, probe exit {6}, planted prompt called {7} time(s), {8} ms{9}' -f `
        $t29B.inputRedirected, $t29B.keyAvailableThrew, $t29B.processExit, $(if ($t29B.timedOut) { ' (TIMED OUT, killed)' } else { '' }), $t29B.json, $t29B.completed,
        $t29B.exit, $t29B.plantedCalls, $t29B.elapsedMs, $(if ($t29B.error) { ' -- launcher error: ' + $t29B.error } else { '' })))
    $t29rows.Add(('        five lines in order, fixed text and the LAMPROBE line exact: {0}' -f $t29BShape))
    $t29rows.Add(('        capture measured: the control Write-Host line captured {0}, and all {1} returned lines found in the {2} captured host lines in order: {3}' -f `
        $t29B.controlCaptured, $t29BLines.Count, @($t29B.captured).Count, $t29BCapture))
    $t29rows.Add(('        renderings searched: {0} (hex, dashed hex, base64, ASCII whole; every 8-byte window as hex, dashed hex, ASCII, decimal; every 6-byte window as base64) over {1} chars; found: {2}' -f `
        @($t29Renderings).Count, $t29BText.Length, $(if (@($t29BLeaks).Count) { ((@($t29BLeaks) | Sort-Object -Unique) -join ', ') + ' (' + @($t29BLeaks).Count + ' hits)' } else { 'none' })))
    $t29rows.Add(('        the planted array afterwards: length {0}, non-zero bytes {1} -- zeroed in place: {2}' -f $t29B.keptLength, $t29B.keptNonZero, $t29BZeroed))
    foreach ($t29Line in $t29BLines) { $t29rows.Add('        ' + $t29Line) }
    $t29rows.Add(('    (b) : {0}' -f $t29BOk))
} else {
    $t29rows.Add('    (b) not run: the probe is absent : False')
}
if (-not $t29BOk) { $t29ok = $false }

# --- (c) CANCELLED ------------------------------------------------------------------------------------
$t29C = if ($t29Present) { Invoke-T29Child -Probe $t29Probe -Case 'cancelled' } else { $null }
$t29COk = $false
if ($t29C) {
    $t29CLines = [string[]]@($t29C.lines)
    $t29CExpect = 'LAMPROBE collected=false rc=1223 packed_length=0 auth_package=0 reason=operator cancelled the secure-desktop prompt (rc 1223 ERROR_CANCELLED)'
    $t29COk = $t29C.json -and $t29C.completed -and (-not $t29C.timedOut) -and ($t29C.exit -eq 1) -and ($t29C.plantedCalls -eq 1) -and
              ($t29CLines.Count -eq 5) -and ($t29CLines[4] -ceq $t29CExpect)
    $t29rows.Add(('    (c) PLANTED CANCEL (rc 1223): process exit {0}, probe exit {1}, planted prompt called {2} time(s), {3} ms{4} : {5}' -f `
        $t29C.processExit, $t29C.exit, $t29C.plantedCalls, $t29C.elapsedMs, $(if ($t29C.error) { ' -- launcher error: ' + $t29C.error } else { '' }), $t29COk))
    if ($t29CLines.Count -ge 1) { $t29rows.Add('        ' + $t29CLines[-1]) }
} else {
    $t29rows.Add('    (c) not run: the probe is absent : False')
}
if (-not $t29COk) { $t29ok = $false }

# --- (d) A FAULT IS REPORTED, NOT CRASHED ------------------------------------------------------------
$t29D = if ($t29Present) { Invoke-T29Child -Probe $t29Probe -Case 'faulted' } else { $null }
$t29DOk = $false
if ($t29D) {
    $t29DLines = [string[]]@($t29D.lines)
    $t29DRx = '^LAMPROBE collected=false rc=4294967295 packed_length=0 auth_package=0 reason=native exception System\.AccessViolationException inside CredUIPromptForWindowsCredentials: '
    $t29DOk = $t29D.json -and $t29D.completed -and (-not $t29D.timedOut) -and ($t29D.exit -eq 3) -and ($t29D.plantedCalls -eq 1) -and
              ($t29DLines.Count -eq 5) -and ($t29DLines[4] -cmatch $t29DRx)
    $t29rows.Add(('    (d) PLANTED NATIVE-FAULT REPORT (rc 4294967295, System.AccessViolationException): process exit {0}, probe exit {1}, planted prompt called {2} time(s), {3} ms{4} : {5}' -f `
        $t29D.processExit, $t29D.exit, $t29D.plantedCalls, $t29D.elapsedMs, $(if ($t29D.error) { ' -- launcher error: ' + $t29D.error } else { '' }), $t29DOk))
    if ($t29DLines.Count -ge 1) { $t29rows.Add('        ' + $t29DLines[-1]) }
} else {
    $t29rows.Add('    (d) not run: the probe is absent : False')
}
if (-not $t29DOk) { $t29ok = $false }

# --- (e) CALLS ONLY THE PROMPT: the probe's AST, statically -----------------------------------------------
$t29EOk = $false
if ($t29Present) {
    $t29Tokens = $null
    $t29ParseErrors = $null
    $t29Ast = [System.Management.Automation.Language.Parser]::ParseFile($t29Probe, [ref]$t29Tokens, [ref]$t29ParseErrors)
    $t29CmdNames = @($t29Ast.FindAll({ param($t29Node) $t29Node -is [System.Management.Automation.Language.CommandAst] }, $true) | ForEach-Object {
        $t29Cn = $_.GetCommandName()
        if ($t29Cn) { $t29Cn } else { $_.CommandElements[0].Extent.Text }
    })
    $t29MethodNames = @($t29Ast.FindAll({ param($t29Node) $t29Node -is [System.Management.Automation.Language.InvokeMemberExpressionAst] }, $true) | ForEach-Object { $_.Member.Extent.Text })
    $t29EnvAssign = @($t29Ast.FindAll({ param($t29Node) ($t29Node -is [System.Management.Automation.Language.AssignmentStatementAst]) -and
        ($t29Node.Left -is [System.Management.Automation.Language.VariableExpressionAst]) -and ($t29Node.Left.VariablePath.DriveName -eq 'env') }, $true)).Count
    $t29FileRedirects = @($t29Ast.FindAll({ param($t29Node) $t29Node -is [System.Management.Automation.Language.FileRedirectionAst] }, $true)).Count
    $t29Invoked = @($t29CmdNames) + @($t29MethodNames)
    $t29HasPrompt = @($t29MethodNames | Where-Object { $_ -ceq 'PromptSecureDesktop' }).Count
    $t29HasInit = @($t29CmdNames | Where-Object { $_ -ceq 'Initialize-LamConsoleCredType' }).Count
    $t29Forbidden = @('VerifyIsCurrentUser', 'LsaLogonUser', 'Invoke-LamConsoleGateAct', 'Invoke-LamConsoleConfirm', 'Register-LamConsoleToken',
                      'Invoke-LamConsoleAttest', 'mission-gate', 'Set-Content', 'Add-Content', 'Out-File', 'New-Item', 'WriteAllText', 'WriteAllBytes',
                      'WriteAllLines', 'AppendAllText', 'SetEnvironmentVariable')
    $t29ForbiddenHits = @()
    foreach ($t29F in $t29Forbidden) {
        $t29FHits = @($t29Invoked | Where-Object { ([string]$_).IndexOf($t29F, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 })
        if ($t29FHits.Count -gt 0) { $t29ForbiddenHits += ($t29F + ' (' + (($t29FHits | Sort-Object -Unique) -join ', ') + ')') }
    }
    $t29EOk = (@($t29ParseErrors).Count -eq 0) -and ($t29HasPrompt -ge 1) -and ($t29HasInit -ge 1) -and ($t29ForbiddenHits.Count -eq 0) -and
              ($t29EnvAssign -eq 0) -and ($t29FileRedirects -eq 0)
    $t29rows.Add(('    (e) STATIC, over the probe''s AST: parse errors {0}; {1} command and {2} method invocations; PromptSecureDesktop invoked {3} time(s), Initialize-LamConsoleCredType {4} time(s); forbidden invocations found: {5}; $env: assignments {6}; file redirections {7} : {8}' -f `
        @($t29ParseErrors).Count, @($t29CmdNames).Count, @($t29MethodNames).Count, $t29HasPrompt, $t29HasInit,
        $(if ($t29ForbiddenHits.Count) { $t29ForbiddenHits -join '; ' } else { 'none of ' + $t29Forbidden.Count }), $t29EnvAssign, $t29FileRedirects, $t29EOk))
    $t29rows.Add('        commands: ' + ((@($t29CmdNames) | Sort-Object -Unique) -join ', '))
    $t29rows.Add('        methods:  ' + ((@($t29MethodNames) | Sort-Object -Unique) -join ', '))
} else {
    $t29rows.Add('    (e) not run: the probe is absent : False')
}
if (-not $t29EOk) { $t29ok = $false }

# --- (f) THE IDENTITY LINE AND THE FLAGS LINE, from row (b)'s capture ----------------------------------------
$t29FOk = $false
$t29LibHash = (Get-FileHash -LiteralPath $lamConsole -Algorithm SHA256).Hash.ToLowerInvariant()
$t29LibLength = ([System.IO.FileInfo]$lamConsole).Length
if ($t29B -and (@($t29B.lines).Count -ge 3)) {
    $t29IdM = [regex]::Match([string]@($t29B.lines)[1], $t29IdRx)
    $t29FlM = [regex]::Match([string]@($t29B.lines)[2], $t29FlagsRx)
    $t29IdOk = $t29IdM.Success -and [string]::Equals($t29IdM.Groups[1].Value, [System.IO.Path]::GetFullPath($lamConsole), [System.StringComparison]::OrdinalIgnoreCase) -and
               ($t29IdM.Groups[2].Value -ceq $t29LibHash) -and ($t29IdM.Groups[3].Value -eq [string]$t29LibLength)
    $t29Ptr = 0
    if ($t29FlM.Success) { $t29Ptr = $(if ($t29FlM.Groups[1].Value -ceq 'True') { 8 } else { 4 }) }
    $t29FlOk = $t29FlM.Success -and ($t29FlM.Groups[3].Value -ceq '00001000') -and ($t29FlM.Groups[2].Value -eq [string](4 + ($t29Ptr - 4) + 4 * $t29Ptr))
    $t29FOk = $t29IdOk -and $t29FlOk
    $t29rows.Add(('    (f) identity line: path {0}, sha256 {1}, {2} bytes; Get-FileHash of {3}: {4}, {5} bytes : {6}' -f `
        $t29IdM.Groups[1].Value, $t29IdM.Groups[2].Value, $t29IdM.Groups[3].Value, $lamConsole, $t29LibHash, $t29LibLength, $t29IdOk))
    $t29rows.Add(('    (f) flags line: 64-bit {0}, CREDUI_INFO {1} bytes (expect {2}), dwFlags 0x{3} (expect 0x00001000) : {4} ; row (f) : {5}' -f `
        $t29FlM.Groups[1].Value, $t29FlM.Groups[2].Value, (4 + ($t29Ptr - 4) + 4 * $t29Ptr), $t29FlM.Groups[3].Value, $t29FlOk, $t29FOk))
} else {
    $t29rows.Add('    (f) not measured: row (b) produced no identity or flags line : False')
}
if (-not $t29FOk) { $t29ok = $false }

$t29detail = @"
    The operator's credential probe drives the secure-desktop prompt WITHOUT MINTING: it calls only
    LamConsoleCred.PromptSecureDesktop and reports the packed buffer's length and auth package, never its bytes.
    No row here raises a prompt: (a) runs the main flow with stdin redirected, (b)-(d) plant the prompt seam in a
    hidden-console child that refuses to drive the default prompt, (e) is static.
$($t29rows -join "`n")
    NO SESSION HAS RAISED THE SECURE-DESKTOP PROMPT through the probe or the console; the operator's drives
    (LAM-INSTALL section 5.6.3) are owed and are recorded on LAM-ACCEPT amendment 44.
"@
Check -Id 'T-29' -Title 'the operator''s credential probe tools\lam\lam-console-probe.ps1: its main flow with stdin redirected refuses before any prompt (exit 2, one REFUSED line, no LAMPROBE line); dot-sourced with a planted prompt returning a 48-byte buffer it prints its five lines in order ending LAMPROBE collected=true rc=0 packed_length=48 auth_package=7 reason=collected, exits 0, lets no hex, base64, ASCII or decimal rendering of the buffer (whole or any window) reach the captured host output, and zeroes the array in place; a planted cancel exits 1 with rc=1223 and a planted native-fault report exits 3 naming System.AccessViolationException; its AST invokes PromptSecureDesktop and Initialize-LamConsoleCredType and no LSA, gate, attestation, file-writing or environment call; its identity line carries Get-FileHash of lam-console.ps1 and its flags line 0x00001000' `
      -Ok $t29ok -Detail $t29detail

# =================================================================================================
# T-30 -- THE ROUND-LABEL CAST IN THE THREE SPAWN-LEDGER
# READERS. A spawn ledger can carry `round` as a LABEL ('R-FX-1', 'R-FX-1-RECORD') and the integer
# in `round_number` -- on the SPAWN line only; its complete lines carry the label and no round_number. Three
# readers cast `round` to an integer and crashed on it: tools/mission-close-milestone.ps1's roster gate
# ([int]$_.round), and tools/lam/transcribe_validator_results.py's seq resolution and its attempt figure
# (int(...)). THE RULED CURE: the attempt is `round` when it is an integer (the reader's own cast,
# unchanged), else `round_number` when that is an integer, else a REFUSAL -- one line, at column 0,
# naming the seq and the values seen, never a traceback or a cast exception.
#
# WHY WP-4. No WP instrument owned a close-milestone check (the F-032 CLI guards are pytest's, under
# tools/tests/cli/); the ruling's dispatch names WP-4 for that case.
#
# EVERY FIXTURE IS A SCRATCH MISSION ROOT under this instrument's sandbox: the CLI and mission-lib.ps1 are
# COPIED into <root>\tools\, so Get-MissionRoot (the parent of the script's own directory) resolves to the
# scratch root and the gate reads nothing else. The real .mission/ and .mission-runtime/ are never named.
# The transcription tool is driven by its --root, in its default CHECK-ONLY mode (it writes nothing), and
# directly under the interpreter its wrapper would pick, so a PS 5.1 wrapper's stderr handling cannot
# decorate the column-0 STOP line this member reads.
# =================================================================================================
$t30Base  = Join-Path $sandbox 't30'
$t30Close = Join-Path $repoRoot 'tools\mission-close-milestone.ps1'
$t30Lib   = Join-Path $repoRoot 'tools\mission-lib.ps1'
$t30Py    = Join-Path $repoRoot 'tools\lam\transcribe_validator_results.py'
$t30rows  = New-Object System.Collections.Generic.List[string]
$t30ok    = $true
$t30Tip   = '3030303030303030303030303030303030303030'
$t30Crash = '(?i)Cannot convert|System\.Int32|InvalidCast|Traceback|At line:|ValueError|TypeError'

function Get-T30Sha {
    param([string]$Text)
    $bytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes($Text)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-', '').ToLowerInvariant() }
    finally { $sha.Dispose() }
}

function Get-T30ResultText {
    param([string]$Aid, [string]$Verdict, [string]$Extra = '')
    return ("verdict: $Verdict`nid: D-V-$Aid`nvalidates: $Aid`n$Extra" + "checks:`n  - check: the T-30 fixture check`n    verdict: $Verdict`nfindings: []`n")
}

function Add-T30Pair {
    # One spawn line and its complete line, paired by seq, in the shape the real ledger uses.
    param($Into, [int]$Seq, [string]$Aid, $Round, $SpawnRoundNumber, $CompleteRoundNumber, [string]$Sha, [string]$Verdict, [switch]$NoSpawn)
    $spawn = [ordered]@{ event = 'spawn'; seq = $Seq; kind = 'validator'; dispatch_id = "D-V-$Aid-$Seq"; validates = $Aid; round = $Round }
    if ($null -ne $SpawnRoundNumber) { $spawn['round_number'] = $SpawnRoundNumber }
    $complete = [ordered]@{ event = 'complete'; seq = $Seq; kind = 'validator'; role = 'qa-validator'; dispatch_id = "D-V-$Aid-$Seq"
        validates = $Aid; round = $Round; verdict = $Verdict; result_sha256 = $Sha
        result_path = "tests/lam/validator-$Aid.result.yaml"; tip_judged = $t30Tip }
    if ($null -ne $CompleteRoundNumber) { $complete['round_number'] = $CompleteRoundNumber }
    if (-not $NoSpawn) { [void]$Into.Add($spawn) }
    [void]$Into.Add($complete)
}

function New-T30MissionRoot {
    param([string]$Name, [string[]]$Roster, $Lines, [hashtable]$Results)
    $r = Join-Path $t30Base $Name
    foreach ($d in @('tools', '.mission\spec', '.mission\amendments', '.mission\ledger', 'tests\lam', '.mission-runtime\lam')) {
        New-Item -ItemType Directory -Path (Join-Path $r $d) -Force | Out-Null
    }
    Copy-Item -LiteralPath $t30Close -Destination (Join-Path $r 'tools\mission-close-milestone.ps1')
    Copy-Item -LiteralPath $t30Lib   -Destination (Join-Path $r 'tools\mission-lib.ps1')
    Write-Utf8 -Path (Join-Path $r '.mission\mission.yaml') -Text "id: T30-FIXTURE`nstate: Reworking`ncurrent_spec_version: v010`ncurrent_milestone: M-98`n"
    Write-Utf8 -Path (Join-Path $r '.mission\spec\current.txt') -Text "v010`n"
    $spec = "version: v010`nfeatures:`n  - id: F-930`n    status: pending`nmilestones:`n  - id: M-99`n    status: pending`n    features: [F-930]`n    contract_assertion_ids: [" + ($Roster -join ', ') + "]`ntrailer: end`n"
    Write-Utf8 -Path (Join-Path $r '.mission\spec\v010.yaml') -Text $spec
    Write-Utf8 -Path (Join-Path $r '.mission\amendments\AM-099-t30.yaml') -Text "id: AM-099`n"
    Write-Utf8 -Path (Join-Path $r '.mission\ledger\entries.jsonl') -Text ''
    Write-Utf8 -Path (Join-Path $r 'led.txt') -Text "T-30 fixture ledger content`n"
    foreach ($aid in $Results.Keys) {
        Write-Utf8 -Path (Join-Path $r "tests\lam\validator-$aid.result.yaml") -Text $Results[$aid]
    }
    $json = New-Object System.Collections.Generic.List[string]
    foreach ($ln in $Lines) { [void]$json.Add(($ln | ConvertTo-Json -Compress)) }
    Write-Utf8 -Path (Join-Path $r '.mission-runtime\lam\spawn-ledger.jsonl') -Text (($json.ToArray() -join "`n") + "`n")
    return $r
}

function Invoke-T30Gate {
    # -CliName: another copy of the CLI standing in the SAME <root>\tools (row (f6g) names the base blob's copy), so
    # Get-MissionRoot resolves to the same scratch root for both.
    param([string]$Root, [string]$CliName = 'mission-close-milestone.ps1')
    $cli = Join-Path $Root (Join-Path 'tools' $CliName)
    $led = Join-Path $Root 'led.txt'
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $raw = @(); $code = $null
    try {
        $raw = & powershell -NoProfile -ExecutionPolicy Bypass -File $cli -Milestone M-99 -AmendmentId AM-099 -LedgerContentFile $led -NoCommit -RosterGateOnly 2>&1
        $code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ Code = $code; Text = ((@($raw) | ForEach-Object { "$_" }) -join "`n") }
}

# the interpreter the transcription wrapper would pick: $env:MISSION_PYTHON, this tree's tools\.venv, the PRIMARY
# checkout's tools\.venv, then PATH. The primary checkout is the parent of git's common dir (git rev-parse
# --git-common-dir), so a reading in a linked worktree -- which has no venv of its own, since adding a worktree copies
# no untracked file -- picks the interpreter a reading at the primary checkout picks. At the primary checkout the two
# venv candidates are one path, tried once. WP-3 keeps its own copy of this order for seat.py; the two change together.
$t30PyExe = $null
$t30PyFrom = ''
$t30PrimaryRoot = ''
$t30PrimaryVenv = ''
$t30TreeVenv = Join-Path $repoRoot 'tools\.venv\Scripts\python.exe'
$t30Cd = ''
$prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
try { $t30Cd = (@(& git -C $repoRoot rev-parse --git-common-dir 2>$null) -join '').Trim() } catch { $t30Cd = '' } finally { $ErrorActionPreference = $prevEap }
if ($t30Cd) {
    if (-not [System.IO.Path]::IsPathRooted($t30Cd)) { $t30Cd = Join-Path $repoRoot $t30Cd }
    $t30PrimaryRoot = Split-Path -Parent ([System.IO.Path]::GetFullPath($t30Cd.Replace('/', '\')).TrimEnd('\'))
    $t30PrimaryVenv = Join-Path $t30PrimaryRoot 'tools\.venv\Scripts\python.exe'
    if ([string]::Equals([System.IO.Path]::GetFullPath($t30PrimaryVenv), [System.IO.Path]::GetFullPath($t30TreeVenv), [System.StringComparison]::OrdinalIgnoreCase)) { $t30PrimaryVenv = '' }
}
foreach ($t30PyCand in @(
        [pscustomobject]@{ from = 'MISSION_PYTHON'; path = [string]$env:MISSION_PYTHON },
        [pscustomobject]@{ from = "this tree's tools\.venv"; path = $t30TreeVenv },
        [pscustomobject]@{ from = "the primary checkout's tools\.venv"; path = $t30PrimaryVenv })) {
    if ($t30PyCand.path -and (Test-Path -LiteralPath $t30PyCand.path)) { $t30PyExe = $t30PyCand.path; $t30PyFrom = $t30PyCand.from; break }
}
if (-not $t30PyExe) { $t30OnPath = Get-Command python -ErrorAction SilentlyContinue; if ($t30OnPath) { $t30PyExe = $t30OnPath.Source; $t30PyFrom = 'python on the PATH' } }
Write-Host ""
Write-Host "python    : $(if ($t30PyExe) { $t30PyExe } else { '(none resolved)' })   (from: $(if ($t30PyFrom) { $t30PyFrom } else { 'nowhere' }); order: MISSION_PYTHON, this tree's tools\.venv, the primary checkout's tools\.venv, python on the PATH)"
Write-Host "            the primary checkout's candidate: $(if ($t30PrimaryVenv) { $t30PrimaryVenv + $(if (Test-Path -LiteralPath $t30PrimaryVenv) { '' } else { '   (absent)' }) } elseif ($t30PrimaryRoot) { '(the primary checkout is this tree: the same path as this tree''s)' } else { '(git named no common dir)' })"

function Invoke-T30Transcribe {
    param([string]$Root, [string]$Target)
    if (-not $t30PyExe) { return [pscustomobject]@{ Code = $null; Text = 'no Python interpreter resolved' } }
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $raw = @(); $code = $null
    try {
        $raw = & $t30PyExe $t30Py $Target --root $Root --arc T30 2>&1
        $code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ Code = $code; Text = ((@($raw) | ForEach-Object { "$_" }) -join "`n") }
}

function Get-T30Line {
    param([string]$Text, [string]$Pattern)
    $m = [regex]::Matches($Text, $Pattern, [System.Text.RegularExpressions.RegexOptions]::Multiline)
    return @($m | ForEach-Object { $_.Value.TrimEnd("`r") })
}

function Add-T30Row {
    # -Max: where the Reading is cut. The (f) and (g) rows pass a larger bound, so the line each one reads is on
    # the face whole.
    param([string]$Label, [bool]$Ok, [string]$Reading, [int]$Max = 600)
    if (-not $Ok) { $script:t30ok = $false }
    $one = ($Reading -replace '[\r\n]+', ' | ')
    if ($one.Length -gt $Max) { $one = $one.Substring(0, $Max) + ' ...' }
    $script:t30rows.Add(('    {0} : {1}' -f $Label, $Ok))
    $script:t30rows.Add('        ' + $one)
}

# --- the fixtures --------------------------------------------------------------------------------------------
# (a) THE LABELLED SHAPE: label `round` on both lines, integer round_number on the SPAWN line only.
$t30LinesA = New-Object System.Collections.ArrayList
$t30ResA = @{}
foreach ($t30Spec in @(@('A-901', 301, 'R-FX-1'), @('A-902', 302, 'R-FX-1-RECORD'))) {
    # A-901's result carries its own integer `round: 1`; the transcription tool
    # cross-checks it against the attempt, so it must read EQUAL to the round_number, not to the label.
    $t30Extra = if ($t30Spec[0] -eq 'A-901') { "round: 1`n" } else { '' }
    $t30ResA[$t30Spec[0]] = Get-T30ResultText -Aid $t30Spec[0] -Verdict 'PASS' -Extra $t30Extra
    Add-T30Pair -Into $t30LinesA -Seq $t30Spec[1] -Aid $t30Spec[0] -Round $t30Spec[2] -SpawnRoundNumber 1 -CompleteRoundNumber $null -Sha (Get-T30Sha $t30ResA[$t30Spec[0]]) -Verdict 'PASS'
}
$t30RootA = New-T30MissionRoot -Name 'a-label-spawn-rn' -Roster @('A-901', 'A-902') -Lines $t30LinesA -Results $t30ResA

# (a2) the integer on the COMPLETE line itself.
