$t30ResA2 = @{ 'A-903' = (Get-T30ResultText -Aid 'A-903' -Verdict 'PASS') }
Add-T30Pair -Into $t30LinesA2 -Seq 303 -Aid 'A-903' -Round 'R-FX-2' -SpawnRoundNumber $null -CompleteRoundNumber 2 -Sha (Get-T30Sha $t30ResA2['A-903']) -Verdict 'PASS'
$t30RootA2 = New-T30MissionRoot -Name 'a2-label-complete-rn' -Roster @('A-903') -Lines $t30LinesA2 -Results $t30ResA2

# (b) a label `round` and NO integer anywhere.
$t30LinesB = New-Object System.Collections.ArrayList
$t30ResB = @{ 'A-911' = (Get-T30ResultText -Aid 'A-911' -Verdict 'PASS') }
Add-T30Pair -Into $t30LinesB -Seq 311 -Aid 'A-911' -Round 'R-FX-1' -SpawnRoundNumber $null -CompleteRoundNumber $null -Sha (Get-T30Sha $t30ResB['A-911']) -Verdict 'PASS'
$t30RootB = New-T30MissionRoot -Name 'b-label-no-integer' -Roster @('A-911') -Lines $t30LinesB -Results $t30ResB

# (b2) a label `round` whose round_number is a STRING '1' -- not an integer, so refused (deny-side).
$t30LinesB2 = New-Object System.Collections.ArrayList
$t30ResB2 = @{ 'A-912' = (Get-T30ResultText -Aid 'A-912' -Verdict 'PASS') }
Add-T30Pair -Into $t30LinesB2 -Seq 312 -Aid 'A-912' -Round 'R-FX-1' -SpawnRoundNumber '1' -CompleteRoundNumber $null -Sha (Get-T30Sha $t30ResB2['A-912']) -Verdict 'PASS'
$t30RootB2 = New-T30MissionRoot -Name 'b2-label-string-rn' -Roster @('A-912') -Lines $t30LinesB2 -Results $t30ResB2

# (c) INTEGER rounds -- the shape earlier arcs wrote. Round 2 supersedes round 1.
$t30LinesC = New-Object System.Collections.ArrayList
$t30ResC = @{ 'A-921' = (Get-T30ResultText -Aid 'A-921' -Verdict 'PASS') }
$t30ShaC = Get-T30Sha $t30ResC['A-921']
Add-T30Pair -Into $t30LinesC -Seq 321 -Aid 'A-921' -Round 1 -SpawnRoundNumber $null -CompleteRoundNumber $null -Sha $t30ShaC -Verdict 'PASS'
Add-T30Pair -Into $t30LinesC -Seq 322 -Aid 'A-921' -Round 2 -SpawnRoundNumber $null -CompleteRoundNumber $null -Sha $t30ShaC -Verdict 'PASS'
$t30RootC = New-T30MissionRoot -Name 'c-integer-round' -Roster @('A-921') -Lines $t30LinesC -Results $t30ResC

# (c2) integer rounds, the CURRENT (round 2) result a fail: the refusal names round 2 and seq 332.
