$t30ResC2 = @{ 'A-922' = (Get-T30ResultText -Aid 'A-922' -Verdict 'REFUTED') }
$t30ShaC2 = Get-T30Sha $t30ResC2['A-922']
Add-T30Pair -Into $t30LinesC2 -Seq 331 -Aid 'A-922' -Round 1 -SpawnRoundNumber $null -CompleteRoundNumber $null -Sha $t30ShaC2 -Verdict 'REFUTED'
Add-T30Pair -Into $t30LinesC2 -Seq 332 -Aid 'A-922' -Round 2 -SpawnRoundNumber $null -CompleteRoundNumber $null -Sha $t30ShaC2 -Verdict 'REFUTED'
