$t30ShaC3 = Get-T30Sha $t30ResC3['A-923']
Add-T30Pair -Into $t30LinesC3 -Seq 341 -Aid 'A-923' -Round 2 -SpawnRoundNumber $null -CompleteRoundNumber $null -Sha $t30ShaC3 -Verdict 'PASS'
Add-T30Pair -Into $t30LinesC3 -Seq 342 -Aid 'A-923' -Round 2 -SpawnRoundNumber $null -CompleteRoundNumber $null -Sha $t30ShaC3 -Verdict 'PASS'
$t30RootC3 = New-T30MissionRoot -Name 'c3-integer-round-tie' -Roster @('A-923') -Lines $t30LinesC3 -Results $t30ResC3

# (d) VALIDATOR ROUND 1's cases. round_number is CROSS-CHECKED where both lines carry it, a non-integer one on
#     either line is refused rather than skipped, and a JSON-integer `round` the gate's [int] cannot hold is
#     refused as out of range -- it is an integer, so round_number is never consulted for it.
function New-T30OneCase {
    param([string]$Name, [string]$Aid, [int]$Seq, $Round, $SpawnRn, $CompleteRn, [switch]$NoSpawn)
    $lines = New-Object System.Collections.ArrayList
    $res = @{ $Aid = (Get-T30ResultText -Aid $Aid -Verdict 'PASS') }
    Add-T30Pair -Into $lines -Seq $Seq -Aid $Aid -Round $Round -SpawnRoundNumber $SpawnRn -CompleteRoundNumber $CompleteRn -Sha (Get-T30Sha $res[$Aid]) -Verdict 'PASS' -NoSpawn:$NoSpawn
    return (New-T30MissionRoot -Name $Name -Roster @($Aid) -Lines $lines -Results $res)
}
$t30RootD1 = New-T30OneCase -Name 'd1-rn-disagree' -Aid 'A-931' -Seq 351 -Round 'R-FX-1' -SpawnRn 1 -CompleteRn 2
$t30RootD2 = New-T30OneCase -Name 'd2-complete-rn-string' -Aid 'A-932' -Seq 352 -Round 'R-FX-1' -SpawnRn 1 -CompleteRn '7'
$t30RootD3 = New-T30OneCase -Name 'd3-round-out-of-range' -Aid 'A-933' -Seq 353 -Round ([long]3000000000) -SpawnRn 1 -CompleteRn $null
$t30RootD4 = New-T30OneCase -Name 'd4-no-spawn-line' -Aid 'A-934' -Seq 354 -Round 'R-FX-1' -SpawnRn $null -CompleteRn $null -NoSpawn

# (d5) a SUPERSEDED candidate whose attempt cannot be read refuses the assertion, as one with no `round` does.
$t30LinesD5 = New-Object System.Collections.ArrayList
$t30ResD5 = @{ 'A-935' = (Get-T30ResultText -Aid 'A-935' -Verdict 'PASS') }
$t30ShaD5 = Get-T30Sha $t30ResD5['A-935']
Add-T30Pair -Into $t30LinesD5 -Seq 361 -Aid 'A-935' -Round 'R-FX-1' -SpawnRoundNumber $null -CompleteRoundNumber $null -Sha $t30ShaD5 -Verdict 'PASS'
Add-T30Pair -Into $t30LinesD5 -Seq 362 -Aid 'A-935' -Round 2 -SpawnRoundNumber $null -CompleteRoundNumber $null -Sha $t30ShaD5 -Verdict 'PASS'
$t30RootD5 = New-T30MissionRoot -Name 'd5-superseded-unreadable' -Roster @('A-935') -Lines $t30LinesD5 -Results $t30ResD5

# (e) WP-D, D-3: an earlier revision's validator round 2 recorded, as a LOW finding, that this
#     member did not drive ORDERING BETWEEN SEVERAL CANDIDATES READ THROUGH round_number, and a round 1 LOW finding
#     left SEVERAL SPAWN LINES AT ONE SEQ untested. Rows (e1)-(e5) drive both shapes. Every candidate in
#     (e1)-(e3) binds a REFUTED result, so the gate's existing verdict refusal NAMES the round and the seq it
#     took as current and the tool prints the seq it resolved: which candidate won is read off the output,
#     not inferred from a PERMIT that would read the same whichever one was taken. (e1) and (e2) are the same
#     two candidates in the two ledger orders, so a reader that ordered by seq in either direction fails one.
function New-T30OrderCase {
    # $Cands holds one @(seq, round, spawn round_number) per candidate, in LEDGER order.
    param([string]$Name, [string]$Aid, [object[]]$Cands)
    $lines = New-Object System.Collections.ArrayList
    $res = @{ $Aid = (Get-T30ResultText -Aid $Aid -Verdict 'REFUTED') }
    $sha = Get-T30Sha $res[$Aid]
    foreach ($t30Cand in $Cands) {
        Add-T30Pair -Into $lines -Seq $t30Cand[0] -Aid $Aid -Round $t30Cand[1] -SpawnRoundNumber $t30Cand[2] -CompleteRoundNumber $null -Sha $sha -Verdict 'REFUTED'
    }
    return (New-T30MissionRoot -Name $Name -Roster @($Aid) -Lines $lines -Results $res)
}
$t30RootE1 = New-T30OrderCase -Name 'e1-rn-ascending' -Aid 'A-941' -Cands @(@(371, 'R-FX-1', 1), @(372, 'R-FX-2', 2))
$t30RootE2 = New-T30OrderCase -Name 'e2-rn-descending' -Aid 'A-942' -Cands @(@(381, 'R-FX-2', 2), @(382, 'R-FX-1', 1))
