function Get-T30BaseBlob {
    # One base file of the installed synthetic base $t30BaseLabel, by its path, written to $OutFile byte for byte;
    # returns the sha256 of those bytes, or a reason beginning 'UNREAD'. Get-LamBaseBytes: no history is read.
    param([string]$Path, [string]$Pin, [string]$OutFile)
    try {
        $read = Get-LamBaseBytes -Base $script:t30BaseLabel -Path $Path -Pin $Pin
        if (-not $read.ok) { return ('UNREAD: ' + $read.from) }
        $bytes = $read.bytes
        $dir = Split-Path -Parent $OutFile
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        [System.IO.File]::WriteAllBytes($OutFile, $bytes)
        $sha = [System.Security.Cryptography.SHA256]::Create()
        try { return ([BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-', '').ToLowerInvariant() }
        finally { $sha.Dispose() }
    } catch { return "UNREAD: $($_.Exception.Message)" }
}

function Invoke-T30Bound {
    # THE GOAL EVALUATOR'S READER, Test-LamLedgerBound, lifted by the parser from tools/lam/lam-verify-admission.ps1
    # (with Get-LamLedgerPath) as WP-2 R-54 lifts it, and asked whether $File is bound by a complete line of $Root's
    # spawn ledger. This package edits neither function.
    param([string]$Root, [string]$File)
    return (& {
        $t = $null; $e = $null
        $ast = [System.Management.Automation.Language.Parser]::ParseFile((Join-Path $repoRoot 'tools\lam\lam-verify-admission.ps1'), [ref]$t, [ref]$e)
        $want = @('Get-LamLedgerPath', 'Test-LamLedgerBound')
        $fns = @($ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] }, $true) | Where-Object { $want -ccontains $_.Name })
        if ($fns.Count -ne 2) { return [pscustomobject]@{ bound = $false; reason = "lifted $($fns.Count) of 2 functions" } }
        foreach ($fn in $fns) { . ([scriptblock]::Create($fn.Extent.Text)) }
        return (Test-LamLedgerBound -MissionRoot $Root -FilePath $File)
    })
}

$t30PassRx = '^\s*\[PASS\] roster closable: .*$'
function Test-T30SetAside {
    # The gate's ONE '[PASS] roster closable' line: with -Clause, whether it ENDS with exactly that set-aside clause;
    # without, whether it carries no set-aside clause at all.
    param([string]$Text, [string]$Clause = '')
    $pl = @(Get-T30Line -Text $Text -Pattern $t30PassRx)
    if ($pl.Count -ne 1) { return $false }
    if (-not $Clause) { return (-not $pl[0].Contains('SET ASIDE')) }
    return $pl[0].EndsWith($Clause)
}

