# (f6g) THE BASE CLI, read from the installed synthetic base and held to its sha256, driven beside the tree's CLI from the SAME
#       <root>\tools over seven ledgers that carry no null-result line: exit and output must be equal, byte for byte.
$t30gBaseName = 'mission-close-milestone-base.ps1'
$t30gBaseSha = Get-T30BaseBlob -Path $t30BaseCliBlob -Pin $t30BaseCliSha -OutFile (Join-Path $t30Base "base\$t30gBaseName")
$t30gSame = 0; $t30gDiffer = New-Object System.Collections.Generic.List[string]
$t30gCodes = New-Object System.Collections.Generic.List[string]
if ($t30gBaseSha -eq $t30BaseCliSha) {
    foreach ($t30R in @($t30RootA, $t30RootB, $t30RootC, $t30RootC2, $t30RootC3, $t30RootF11, $t30RootF13)) {
        Copy-Item -LiteralPath (Join-Path $t30Base "base\$t30gBaseName") -Destination (Join-Path $t30R "tools\$t30gBaseName") -Force
        $t30gTree = Invoke-T30Gate -Root $t30R
        $t30gBase = Invoke-T30Gate -Root $t30R -CliName $t30gBaseName
        Remove-Item -LiteralPath (Join-Path $t30R "tools\$t30gBaseName") -Force
        [void]$t30gCodes.Add("$(Split-Path -Leaf $t30R): exit $($t30gTree.Code) / base $($t30gBase.Code)")
        if (($t30gTree.Code -eq $t30gBase.Code) -and ($null -ne $t30gTree.Code) -and ($t30gTree.Text -ceq $t30gBase.Text) -and ($t30gTree.Text.Length -gt 0)) { $t30gSame++ }
        else { [void]$t30gDiffer.Add((Split-Path -Leaf $t30R)) }
    }
}
