# (f6) THE EXPLICIT id:seq PATH -- OUT OF SCOPE AND UNCHANGED. The tool before this cure, read from the
#      installed synthetic base and held to its sha256, driven beside the tree's tool over the SAME roots and the same explicit
#      targets, stdout and stderr captured APART: which stream's line reaches a merged pipe first is the pipe's, not
#      the tool's. Eight targets -- a bound seq and the null-result seq of (f1), the lower-round bound seq and the
#      null-result seq of (f2), and of (f4) the two seqs the bare path now resolves, A-596's superseded round-1 seq
#      and its null-result seq -- four of which exit 0 and four of which STOP.
function Invoke-T30TranscribeSplit {
    param([string]$Root, [string]$Target, [string]$Tool)
    if (-not $t30PyExe) { return [pscustomobject]@{ Code = $null; Out = ''; Err = 'no Python interpreter resolved' } }
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $t30PyExe
        $psi.Arguments = ('"{0}" {1} --root "{2}" --arc T30' -f $Tool, $Target, $Root)
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        $proc = [System.Diagnostics.Process]::Start($psi)
        $errTask = $proc.StandardError.ReadToEndAsync()
        $outText = $proc.StandardOutput.ReadToEnd()
        $proc.WaitForExit()
        return [pscustomobject]@{ Code = $proc.ExitCode; Out = $outText; Err = [string]$errTask.Result }
    } catch { return [pscustomobject]@{ Code = $null; Out = ''; Err = "not started: $($_.Exception.Message)" } }
}
$t30pBase = Join-Path $t30Base 'base\transcribe_validator_results.base.py'
$t30pBaseSha = Get-T30BaseBlob -Path $t30BasePyBlob -Pin $t30BasePySha -OutFile $t30pBase
$t30pSame = 0; $t30pZero = 0; $t30pStop = 0
$t30pFaces = New-Object System.Collections.Generic.List[string]
if ($t30pBaseSha -eq $t30BasePySha) {
    foreach ($t30X in @(
            @($t30RootF1, 'A-951:402'), @($t30RootF1, 'A-951:401'), @($t30RootF2, 'A-953:411'), @($t30RootF2, 'A-953:412'),
            @($t30RootF4, 'A-594:208'), @($t30RootF4, 'A-596:212'), @($t30RootF4, 'A-596:209'), @($t30RootF4, 'A-596:211'))) {
        $t30xTree = Invoke-T30TranscribeSplit -Root $t30X[0] -Target $t30X[1] -Tool $t30Py
        $t30xBase = Invoke-T30TranscribeSplit -Root $t30X[0] -Target $t30X[1] -Tool $t30pBase
        $t30xSame = ($null -ne $t30xTree.Code) -and ($t30xTree.Code -eq $t30xBase.Code) -and ($t30xTree.Out -ceq $t30xBase.Out) -and ($t30xTree.Err -ceq $t30xBase.Err) -and (($t30xTree.Out.Length + $t30xTree.Err.Length) -gt 0)
        if ($t30xSame) { $t30pSame++ }
        if ($t30xTree.Code -eq 0) { $t30pZero++ }
        if (($t30xTree.Code -eq 1) -and ($t30xTree.Err -match '(?m)^STOP: ')) { $t30pStop++ }
        [void]$t30pFaces.Add("$($t30X[1]): exit $($t30xTree.Code) / base $($t30xBase.Code), $(if ($t30xSame) { 'identical' } else { 'DIFFERS' })")
    }
}
