        @($t30RootF10b, 'A-966', "A-966: the complete line seq 474 binds no result and carries round '2', which is not a JSON integer", 'transcribe (f10b) bare A-966, a null-result line (seq 474) whose round is the STRING ''2'', beside the bound line at round 2 (seq 473): one column-0 STOP naming seq 474 and the value'))) {
    $t30p = Invoke-T30Transcribe -Root $t30F[0] -Target $t30F[1]
    $t30lines = @(Get-T30Line -Text $t30p.Text -Pattern '^STOP: .*$')
    $t30rowOk = ($t30p.Code -eq 1) -and ($t30lines.Count -eq 1) -and ($t30p.Text -notmatch 'EQUALITIES HELD') -and ($t30p.Text -notmatch $t30Crash)
    if ($t30rowOk) { $t30rowOk = $t30lines[0].Contains($t30F[2]) }
    Add-T30Row -Label $t30F[3] -Ok $t30rowOk -Reading ("exit $($t30p.Code); column-0 STOP lines $($t30lines.Count): " + $t30p.Text) -Max 1600
}

$t30p = Invoke-T30Transcribe -Root $t30RootG2 -Target 'A-968'
$t30lines = @(Get-T30Line -Text $t30p.Text -Pattern '^STOP: .*$')
$t30rowOk = ($t30p.Code -eq 1) -and ($t30lines.Count -eq 1) -and ($t30p.Text -notmatch 'EQUALITIES HELD') -and ($t30p.Text -notmatch $t30Crash)
if ($t30rowOk) { $t30rowOk = ($t30lines[0] -match '\b492\b') }
Add-T30Row -Label 'transcribe (g2) CONTROL A RESIDUAL, MEASURED: bare A-968 over the (g2) ledger: the tool borrows `validates` for seq 492 from its spawn line, so the null-result line stands at round 2 above the bound line and the tool STOPS naming seq 492 -- where the gate PERMITS' -Ok $t30rowOk -Reading ("exit $($t30p.Code); column-0 STOP lines $($t30lines.Count): " + $t30p.Text) -Max 1600

Check -Id 'T-30' -Title 'C4: a spawn ledger whose `round` is a LABEL and whose integer is `round_number` (on the spawn line or on the complete line) PASSES the close-milestone roster gate (-RosterGateOnly, scratch mission roots) and resolves in the transcription tool (a result file''s own integer `round` cross-checked against that integer); with neither an integer, both REFUSE with one column-0 reason line naming the seq and the values seen and no cast exception or traceback; integer rounds are unchanged (supersession, a failing current round, a tie); round_number is cross-checked where both lines carry it and a non-integer one is refused, a JSON-integer round beyond the gate''s [int] is refused as out of range, a label with no spawn line and a superseded unreadable candidate are refused; and (LAM-ACCEPT amendment 56) where several candidates are read through round_number, both readers take the highest round_number as current in either ledger order and over an integer round 1, refuse a round_number tie naming both seqs, and refuse a label whose seq carries two spawn lines, which pair none; and (widened to both readers: THE COMPLETE LINE''S READING) a complete line that binds no result -- its result_sha256 null or absent -- claims no round in either reader: beside a bound line at the same highest round the gate PERMITS and names and counts it on its [PASS] roster closable line, and the tool''s bare-id path resolves the bound seq and names it, an arc''s roster in its own shapes among them (seq 208 for A-594''s, seq 212 for A-596''s); a highest round held only by such lines still REFUSES in both, the refusal naming the round and the lines; two bound lines at the highest round still REFUSE as a tie, counted over the bound lines; an empty-string result_sha256 stays a claimant in both, a null-result line whose round cannot be read still refuses at the gate, and one whose round is not a JSON integer -- the number 2.5 above the bound round, the string ''2'' beside it -- is not set aside and REFUSES in both; where a line is set aside, a BOUND line whose round is not a JSON integer -- 1.5 beside a null-result line at round 2, -0.5 beside one at round 0 -- REFUSES in both rather than be cast onto the null-result line''s round; and, as controls, the goal evaluator''s unchanged Test-LamLedgerBound binds each result to its bound line, and the gate over seven ledgers with no such line, the tool''s bare-id path over seven and its explicit id:seq path over eight targets read byte-identical to the readers before this cure (read from the installed synthetic base base-700e19e5-s08); and, a residual measured, a null-result complete line with no `validates` of its own above the bound round is unseen by the gate, which PERMITS, while the tool STOPS' `
      -Ok $t30ok -Detail ("      THE $(@($t30rows | Where-Object { $_ -match ' : (True|False)$' }).Count) ROWS:`n" + ($t30rows -join "`n"))


# =================================================================================================
# T-31 -- origin_tip_at_mint: WHAT THE DECLARED ORIGIN HELD AT THE MOMENT OF APPROVAL
#         (operator ruling (i))
# =================================================================================================
# WHAT THE RULING ASKS FOR. "The mint records origin_tip_at_mint; earlier gates settle with
# consumed_origin_before 'not observed at mint'." So a push gate must carry, on its face, the tip the
# DECLARED origin was observed to hold at the moment the human approved -- read by ls-remote against
# the gate's OWN declared URL, never the remote NAME `origin` and never remote.origin.url, because
# the gate declares its own URL precisely so that a repointed remote cannot move the authorization.
#
# THE FIELD IS A RECORD, NOT A PRECONDITION. A failure to observe does NOT refuse the mint: a human is
# approving a publication and the observation is evidence about the world, not a check on the act. So
# there are THREE outcomes and all three mint. Two of them are RECORDED ABSENCES with distinct
# literals, following $script:LamNoReasonText and $script:LamNoRulingText: "we asked and the ref was
# not there" and "we could not ask at all" are DIFFERENT FACTS, and conflating them is exactly the
# conflation this toolchain refuses everywhere else. A missing line would be a third, worse thing --
# indistinguishable from an artifact minted before the field existed.
#
# FIXTURE HERMETICITY. Every origin below is a LOCAL BARE REPOSITORY; nothing here touches a network.
# The declared URLs are FORWARD-SLASHED (a backslashed scratch remote URL in git config once broke the
# whole repository), and the scratch root's own git dir is ASSERTED to resolve INSIDE the fixture
# BEFORE the first `git config` runs -- the 2026-09-13 rule, left behind by a fixture that skipped
# that assertion, fell through to the HOST repository's .git/config, and rewrote the real repo's
# identity and hooksPath.
$t31ok = $true
$t31rows = New-Object System.Collections.Generic.List[string]
function Add-T31Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t31ok = $false }
    $script:t31rows.Add(('      {0,-94} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + $Said } else { '' })))
}
function Get-T31Field {
    param([string]$Text, [string]$Key)
    $fieldMatch = [regex]::Match([string]$Text, '(?m)^' + [regex]::Escape($Key) + ':[ \t]*(.*?)[ \t]*\r?$')
    if ($fieldMatch.Success) { return $fieldMatch.Groups[1].Value }
    return $null
}
function Invoke-T31Git {
    # EVERY native git call in this member goes through here, with $ErrorActionPreference saved and
    # restored around it. Under 'Stop' any native exe writing to stderr is a fatal NativeCommandError
    # and 2>$null does not help -- the unreachable-origin row DELIBERATELY drives a git call that
    # writes to stderr, so a bare call here would abort the member rather than measure it.
    param([string[]]$GitArgs)
    # BOTH LOCALS ARE SEEDED BEFORE THE try. Under Set-StrictMode -Version Latest -- which this
    # file inherits from evidence-common.ps1 -- reading a variable the try never reached is a
    # terminating error, and the seeded code is NON-ZERO so a git that failed to launch reads as
    # a failure rather than inheriting a stale success from some earlier command.
    $gitOut = ''
    $gitCode = -1
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $gitOut = & git @GitArgs 2>&1
        $gitCode = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ out = ((@($gitOut) | ForEach-Object { [string]$_ }) -join "`n"); code = $gitCode }
}

# THE TWO RECORDED-ABSENCE LITERALS, SPELLED OUT HERE RATHER THAN READ FROM THE TOOL. Asserting them
# against $script:LamOriginTipRefAbsentText would pass against any string the tool happened to hold,
# including one that had drifted into conflating the two cases. The sibling settle verb and the
# amendment both quote these bytes, so this member is where they are pinned.
$t31AbsentText     = '(REF NOT PRESENT AT ORIGIN AT MINT -- the declared origin answered and holds no such ref)'
$t31UnobservedText = '(ORIGIN NOT OBSERVED AT MINT -- the declared origin could not be asked; this is NOT a claim that the ref is absent)'

$t31Base = Join-Path $env:TEMP ('lam-wp4-t31-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
$t31Root       = Join-Path $t31Base 'mission'
$t31OriginDir  = Join-Path $t31Base 'origin-declared.git'
$t31DecoyDir   = Join-Path $t31Base 'origin-decoy.git'
$t31EmptyDir   = Join-Path $t31Base 'origin-empty.git'
$t31GoneDir    = Join-Path $t31Base 'origin-gone.git'
$t31DecoyWork  = Join-Path $t31Base 'decoy-work'
$t31Gates      = Join-Path $t31Root '.mission\gates'
New-Item -ItemType Directory -Path (Join-Path $t31Root '.mission') -Force | Out-Null
Write-Utf8 -Path (Join-Path $t31Root 'bound.txt') -Text "t31 bound bytes`n"

# --- THE 2026-09-13 RULE: ASSERT THE FIXTURE'S OWN GIT DIR BEFORE ANY `git config` ------------------
$null = Invoke-T31Git -GitArgs @('init', '-q', $t31Root)
$t31GitDirRaw = (Invoke-T31Git -GitArgs @('-C', $t31Root, 'rev-parse', '--absolute-git-dir')).out.Trim()
$t31RootFull  = ''
try { $t31RootFull = (Resolve-Path -LiteralPath $t31Root).Path } catch { $t31RootFull = '' }
$t31GitDirInside = $false
if ($t31GitDirRaw -and $t31RootFull) {
    $t31GitDirNorm = ($t31GitDirRaw -replace '/', '\')
    $t31GitDirInside = $t31GitDirNorm.StartsWith(($t31RootFull.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase)
}
Add-T31Row 'FIXTURE the scratch root git dir resolves INSIDE the fixture, asserted BEFORE any git config' `
    $t31GitDirInside ("git dir: $t31GitDirRaw")

if (-not $t31GitDirInside) {
    # NOT a skip dressed as a pass. The fixture could not prove it owns the configuration it is about
    # to write, so it writes none and the member FAILS -- which is the only safe direction, because
    # the alternative is a `git config` that lands in whatever repository this process is standing in.
    Add-T31Row 'FIXTURE REFUSING to run: no git config was written and no row below was driven' $false ''
} else {
    $null = Invoke-T31Git -GitArgs @('-C', $t31Root, 'config', 'user.email', 't31@instrument.local')
    $null = Invoke-T31Git -GitArgs @('-C', $t31Root, 'config', 'user.name',  'T31 Instrument')
    $null = Invoke-T31Git -GitArgs @('-C', $t31Root, 'add', 'bound.txt')
    $null = Invoke-T31Git -GitArgs @('-C', $t31Root, 'commit', '-q', '-m', 't31 seed')
    $t31HeadSha = (Invoke-T31Git -GitArgs @('-C', $t31Root, 'rev-parse', 'HEAD')).out.Trim()
    # THE REF IS NAMED EXPLICITLY AND PUSHED BY REFSPEC, never inferred from whatever `git init` called
    # the local branch. A fixture helper may add a remote; it may not restyle the repository it holds.
    $t31Ref      = 'refs/heads/t31-published'
    $t31AbsentRef = 'refs/heads/t31-no-such-ref'

    # FORWARD SLASHES IN EVERY DECLARED URL.
    $t31OriginUrl = ($t31OriginDir -replace '\\', '/')
    $t31DecoyUrl  = ($t31DecoyDir  -replace '\\', '/')
    $t31EmptyUrl  = ($t31EmptyDir  -replace '\\', '/')
    $t31GoneUrl   = ($t31GoneDir   -replace '\\', '/')

    $null = Invoke-T31Git -GitArgs @('init', '-q', '--bare', $t31OriginDir)
    $null = Invoke-T31Git -GitArgs @('init', '-q', '--bare', $t31DecoyDir)
    $null = Invoke-T31Git -GitArgs @('init', '-q', '--bare', $t31EmptyDir)
    $null = Invoke-T31Git -GitArgs @('-C', $t31Root, 'push', '-q', $t31OriginUrl, ('HEAD:' + $t31Ref))
    $t31OriginSha = (Invoke-T31Git -GitArgs @('-C', $t31OriginDir, 'rev-parse', $t31Ref)).out.Trim()

    # A SECOND ORIGIN HOLDING A DIFFERENT SHA, so the declared-versus-configured row is not vacuous.
    New-Item -ItemType Directory -Path $t31DecoyWork -Force | Out-Null
    Write-Utf8 -Path (Join-Path $t31DecoyWork 'decoy.txt') -Text "t31 decoy bytes`n"
    $null = Invoke-T31Git -GitArgs @('init', '-q', $t31DecoyWork)
    $null = Invoke-T31Git -GitArgs @('-C', $t31DecoyWork, 'config', 'user.email', 't31decoy@instrument.local')
    $null = Invoke-T31Git -GitArgs @('-C', $t31DecoyWork, 'config', 'user.name',  'T31 Decoy')
    $null = Invoke-T31Git -GitArgs @('-C', $t31DecoyWork, 'add', 'decoy.txt')
    $null = Invoke-T31Git -GitArgs @('-C', $t31DecoyWork, 'commit', '-q', '-m', 't31 decoy')
    $null = Invoke-T31Git -GitArgs @('-C', $t31DecoyWork, 'push', '-q', $t31DecoyUrl, ('HEAD:' + $t31Ref))
    $t31DecoySha = (Invoke-T31Git -GitArgs @('-C', $t31DecoyDir, 'rev-parse', $t31Ref)).out.Trim()

    Add-T31Row 'FIXTURE two LOCAL BARE origins hold the same ref at DIFFERENT shas (no network anywhere)' `
        (($t31OriginSha -match '\A[0-9a-f]{40}\z') -and ($t31DecoySha -match '\A[0-9a-f]{40}\z') -and ($t31OriginSha -ne $t31DecoySha)) `
        ("declared $t31OriginSha / decoy $t31DecoySha")
    # BUILT INTO A VARIABLE, THEN COUNTED. `(pipeline).Count` is $null.Count when Where-Object
    # matches nothing, and StrictMode makes that a TERMINATING error that takes the whole member
    # with it -- measured on this member's own first RED run. The arity of the literal is asserted
    # too: an array literal in ARGUMENT position has silently yielded more elements than it looked
    # to have, so the count is checked rather than assumed.
    $t31AllUrls = @($t31OriginUrl, $t31DecoyUrl, $t31EmptyUrl, $t31GoneUrl)
    $t31BackslashUrls = @($t31AllUrls | Where-Object { $_ -match '\\' })
    Add-T31Row 'FIXTURE all 4 declared URLs are forward-slashed (a backslashed scratch remote once broke the repo)' `
        (($t31AllUrls.Count -eq 4) -and ($t31BackslashUrls.Count -eq 0)) `
        ("urls=$($t31AllUrls.Count) backslashed=$($t31BackslashUrls.Count)")
    Add-T31Row 'FIXTURE the unreachable origin path does NOT exist' (-not (Test-Path -LiteralPath $t31GoneDir)) ''
    Add-T31Row 'the two recorded-absence literals are DIFFERENT strings (unreachable is not absent)' `
        ($t31AbsentText -cne $t31UnobservedText) ''

    # --- (1) ORIGIN ANSWERED AND THE REF IS PRESENT -> THE 40-HEX SHA ------------------------------
    $t31A = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'push'; Id = 'T31A'; Binds = 'bound.txt'
                                                MissionRoot = $t31Root; OriginUrl = $t31OriginUrl; RemoteRef = $t31Ref; TipSha = $t31HeadSha }
    $t31AGate = Join-Path $t31Gates 'push-T31A.yaml'
    $t31AText = if (Test-Path -LiteralPath $t31AGate) { [System.IO.File]::ReadAllText($t31AGate) } else { '' }
    Add-T31Row '(1) a push mint against an origin holding a known sha exits 0 at stage mint' `
        (($t31A.exit -eq 0) -and ($t31A.stage -eq 'mint') -and [bool]$t31AText) ("exit=$($t31A.exit) stage=$($t31A.stage)")
    Add-T31Row '(1) origin_tip_at_mint ON THE ARTIFACT is exactly the sha the declared origin holds' `
        ((Get-T31Field $t31AText 'origin_tip_at_mint') -ceq $t31OriginSha) `
        ("on disk: $(Get-T31Field $t31AText 'origin_tip_at_mint')  expect: $t31OriginSha")
    # PART OF THE COMPOSED BYTES, so the operator SEES it before the credential is collected and the
    # act digest covers it. A field the preview does not show is not part of what the human approved.
    Add-T31Row '(1) the console PREVIEW rendered the field, byte for byte, before any credential' `
        ($t31A.preview -match [regex]::Escape('  | origin_tip_at_mint: ' + $t31OriginSha + '<CR><LF>')) ''
    Add-T31Row '(1) the artifact carries origin_url and remote_ref beside it (the amendment-20 triple)' `
        (((Get-T31Field $t31AText 'origin_url') -ceq $t31OriginUrl) -and ((Get-T31Field $t31AText 'remote_ref') -ceq $t31Ref)) ''
    # (5) THE PREVIEWED BYTES AND THE MINTED BYTES ARE THE SAME BYTES. Origin did not move between the
    # two independent ls-remote reads, so the act digest held and the mint wrote what the preview showed.
    $t31ADiskSha = if (Test-Path -LiteralPath $t31AGate) { (Get-FileHash -Algorithm SHA256 -LiteralPath $t31AGate).Hash.ToLowerInvariant() } else { '' }
    $t31APrevSha = ''
    $t31AWrites = @($t31A.writes)
    if ($t31AWrites.Count -eq 1) { $t31APrevSha = ([string]$t31AWrites[0].sha256).ToLowerInvariant() }
    Add-T31Row '(5) ONE previewed write, and the bytes on disk hash to the digest the preview declared' `
        (($t31AWrites.Count -eq 1) -and [bool]$t31ADiskSha -and ($t31ADiskSha -ceq $t31APrevSha)) `
        ("writes=$($t31AWrites.Count) preview=$t31APrevSha disk=$t31ADiskSha")

    # --- (2) ORIGIN ANSWERED AND THE REF IS ABSENT -> THE RECORDED ABSENCE, AND THE MINT STILL HAPPENS -
    $t31B = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'push'; Id = 'T31B'; Binds = 'bound.txt'
                                                MissionRoot = $t31Root; OriginUrl = $t31OriginUrl; RemoteRef = $t31AbsentRef; TipSha = $t31HeadSha }
    $t31BGate = Join-Path $t31Gates 'push-T31B.yaml'
    $t31BText = if (Test-Path -LiteralPath $t31BGate) { [System.IO.File]::ReadAllText($t31BGate) } else { '' }
    Add-T31Row '(2) ref ABSENT at a reachable origin: the mint is NOT refused (exit 0, stage mint)' `
        (($t31B.exit -eq 0) -and ($t31B.stage -eq 'mint') -and [bool]$t31BText) ("exit=$($t31B.exit) stage=$($t31B.stage)")
    Add-T31Row '(2) origin_tip_at_mint records the REF-ABSENT literal, verbatim' `
        ((Get-T31Field $t31BText 'origin_tip_at_mint') -ceq $t31AbsentText) `
        ("on disk: $(Get-T31Field $t31BText 'origin_tip_at_mint')")
    # CONTROL: a bare repository with NO refs at all is the same fact -- origin answered, the ref is
    # not there -- and must record the same literal, not the unreachable one.
    $t31E = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'push'; Id = 'T31E'; Binds = 'bound.txt'
                                                MissionRoot = $t31Root; OriginUrl = $t31EmptyUrl; RemoteRef = $t31Ref; TipSha = $t31HeadSha }
    $t31EGate = Join-Path $t31Gates 'push-T31E.yaml'
    $t31EText = if (Test-Path -LiteralPath $t31EGate) { [System.IO.File]::ReadAllText($t31EGate) } else { '' }
    Add-T31Row '(2) CONTROL an empty bare origin (answers, holds no refs) records the SAME absent literal' `
        (($t31E.exit -eq 0) -and ((Get-T31Field $t31EText 'origin_tip_at_mint') -ceq $t31AbsentText)) `
        ("on disk: $(Get-T31Field $t31EText 'origin_tip_at_mint')")

    # --- (3) ORIGIN COULD NOT BE ASKED AT ALL -> A DIFFERENT LITERAL, AND STILL NOT A REFUSAL --------
    $t31C = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'push'; Id = 'T31C'; Binds = 'bound.txt'
                                                MissionRoot = $t31Root; OriginUrl = $t31GoneUrl; RemoteRef = $t31Ref; TipSha = $t31HeadSha }
    $t31CGate = Join-Path $t31Gates 'push-T31C.yaml'
    $t31CText = if (Test-Path -LiteralPath $t31CGate) { [System.IO.File]::ReadAllText($t31CGate) } else { '' }
    Add-T31Row '(3) origin UNREACHABLE: the mint is NOT refused (exit 0, stage mint) -- a record, not a precondition' `
        (($t31C.exit -eq 0) -and ($t31C.stage -eq 'mint') -and [bool]$t31CText) ("exit=$($t31C.exit) stage=$($t31C.stage)")
    Add-T31Row '(3) origin_tip_at_mint records the UNREACHABLE literal, verbatim' `
        ((Get-T31Field $t31CText 'origin_tip_at_mint') -ceq $t31UnobservedText) `
        ("on disk: $(Get-T31Field $t31CText 'origin_tip_at_mint')")
    Add-T31Row '(3) the unreachable artifact does NOT carry the ref-absent literal (the conflation is refused)' `
        (((Get-T31Field $t31CText 'origin_tip_at_mint') -cne $t31AbsentText) -and ((Get-T31Field $t31BText 'origin_tip_at_mint') -cne $t31UnobservedText)) ''
    # A NON-ZERO git EXIT IS WHAT MAKES CASE 3 CASE 3. Both of this file's push-gate neighbours carry
    # recorded fail-open bugs from an unchecked git return code, so the member states the mechanism it
    # depends on rather than trusting it: this ls-remote really does exit non-zero and write to stderr.
    $t31Probe = Invoke-T31Git -GitArgs @('-C', $t31Root, 'ls-remote', $t31GoneUrl, $t31Ref)
    Add-T31Row '(3) MECHANISM ls-remote against the missing origin exits NON-ZERO (unchecked, it would fail open)' `
        ($t31Probe.code -ne 0) ("git exit $($t31Probe.code)")
    $t31Probe2 = Invoke-T31Git -GitArgs @('-C', $t31Root, 'ls-remote', $t31OriginUrl, $t31AbsentRef)
    Add-T31Row '(3) MECHANISM ls-remote for an absent ref exits ZERO with EMPTY output -- the two cases differ in git, not only in the tool' `
        (($t31Probe2.code -eq 0) -and (-not $t31Probe2.out.Trim())) ("git exit $($t31Probe2.code), output length $($t31Probe2.out.Trim().Length)")

    # --- (6) THE DECLARED URL WINS OVER remote.origin.url (the whole point) ------------
    # remote.origin.url is pointed at the DECOY, which holds the same ref at a different sha. A tool
    # that read the remote NAME instead of the declared URL would record the decoy's sha here -- which
    # is round 12's attack exactly, one field further on.
    $null = Invoke-T31Git -GitArgs @('-C', $t31Root, 'remote', 'add', 'origin', $t31DecoyUrl)
    $t31ConfiguredUrl = (Invoke-T31Git -GitArgs @('-C', $t31Root, 'config', '--get', 'remote.origin.url')).out.Trim()
    $t31D = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'push'; Id = 'T31D'; Binds = 'bound.txt'
                                                MissionRoot = $t31Root; OriginUrl = $t31OriginUrl; RemoteRef = $t31Ref; TipSha = $t31HeadSha }
    $t31DGate = Join-Path $t31Gates 'push-T31D.yaml'
    $t31DText = if (Test-Path -LiteralPath $t31DGate) { [System.IO.File]::ReadAllText($t31DGate) } else { '' }
    Add-T31Row '(6) with remote.origin.url pointed at a DECOY, the tip recorded is the DECLARED origin''s' `
        (($t31D.exit -eq 0) -and ((Get-T31Field $t31DText 'origin_tip_at_mint') -ceq $t31OriginSha) -and
         ((Get-T31Field $t31DText 'origin_tip_at_mint') -cne $t31DecoySha)) `
        ("configured=$t31ConfiguredUrl recorded=$(Get-T31Field $t31DText 'origin_tip_at_mint')")

    # --- (4) NO OTHER KIND'S BYTES MOVE -------------------------------------------------------------
    $t31F = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'dispatch'; Id = 't31f'; Binds = 'bound.txt'; MissionRoot = $t31Root }
    $t31FGate = Join-Path $t31Gates 'dispatch-t31f.yaml'
    $t31FText = if (Test-Path -LiteralPath $t31FGate) { [System.IO.File]::ReadAllText($t31FGate) } else { '' }
    # THE COUNT IS COMPUTED INTO A VARIABLE FIRST. Spelling it inline would need an escaped double
    # quote inside a double-quoted string, and `\"` ENDS a PS 5.1 string -- that exact line once
    # produced eight parse errors in mission-gate.ps1, which is a run-time failure, not a build one.
    $t31FOriginTipLines = @([regex]::Matches($t31FText, '(?m)^origin_tip')).Count
    Add-T31Row '(4) a non-push kind mints and gains NO origin_tip line of any sort -- the field is gated on -Kind push' `
        (($t31F.exit -eq 0) -and [bool]$t31FText -and ($t31FOriginTipLines -eq 0)) `
        ("dispatch origin_tip lines: $t31FOriginTipLines")

    # --- (7) THE FIELD SAYS ON ITS FACE WHAT IT IS, AND NAMES THE RESIDUAL IT CREATES ----------------
    # binds_resolved_note is the precedent: a field that no check in this file reads says so on the
    # artifact, so a later reader cannot mistake a record for a guarantee. The note must also make the
    # determinism residual legible -- compose and mint each read origin independently, so an origin
    # that MOVES between the preview and the confirm makes the two byte streams differ and the mint
    # refuses with `act digest mismatch`. That refusal is correct and fail-closed, but it is a NEW way
    # for a push mint to refuse and the operator has to be able to tell it from a genuine tamper.
    $t31Note = Get-T31Field $t31AText 'origin_tip_note'
    Add-T31Row '(7) origin_tip_note is present and says RECORD, not an input' `
        ([bool]$t31Note -and ($t31Note -match 'RECORD, not an input')) ("note: $t31Note")
    Add-T31Row '(7) the note names its one consumer (the settle verb / consumed_origin_before)' `
        ([bool]$t31Note -and ($t31Note -match 'consumed_origin_before')) ''
    Add-T31Row '(7) the note makes the determinism residual legible: re-read at mint, digest mismatch if origin moved' `
        ([bool]$t31Note -and ($t31Note -match 'act digest') -and ($t31Note -match 'moved')) ''
    Add-T31Row '(7) the note rode in the PREVIEW too (the operator saw the caveat with the value)' `
        ([bool]$t31Note -and ($t31A.preview -match [regex]::Escape('  | origin_tip_note: '))) ''
}

if (Test-Path -LiteralPath $t31Base) { Remove-Item -LiteralPath $t31Base -Recurse -Force -ErrorAction SilentlyContinue }

Check -Id 'T-31' -Title 'operator ruling (i): a push mint RECORDS origin_tip_at_mint -- the tip the DECLARED origin (ls-remote against the gate''s own -OriginUrl, never the remote name or remote.origin.url, proven against a decoy) was observed to hold at mint -- as part of the composed bytes, so the console preview shows it and the act digest covers it; observation FAILURE never refuses the mint, and the three outcomes stay distinguishable: the 40-hex sha, a verbatim REF-NOT-PRESENT literal (a reachable origin missing the ref, and an empty bare origin), and a verbatim ORIGIN-NOT-OBSERVED literal that is a different string (git itself separates the cases: exit 0 with empty output versus a non-zero exit); no other kind gains the field, the previewed bytes are the bytes on disk, and origin_tip_note declares the field a RECORD, names its settle-verb consumer and makes the compose-versus-mint determinism residual legible' `
      -Ok $t31ok -Detail ($t31rows -join "`n")

# =================================================================================================
# T-32 -- THE SETTLE VERB: THE ACTOR THAT PERFORMS A GATED ACT STAMPS ITS GATE
#         (operator ruling (i))
# =================================================================================================
# THE ROW. A push gate is stamped by the session that PERFORMS the push -- and a TERMINAL push has
# no such session. An arc's close gate was read four times across the arc's close, by a
# hook-bearing session that was present and active throughout, and read `consumed_at: null` every
# time. The row called that "early, not wrong" at S0; here it is STRUCTURALLY ABSENT.
#
# THE RULING'S CURE, QUOTED: "The actor that performs a gated act stamps its gate; the operator's
# console is the operator's stamping instrument. A console verb `settle -Kind push -Id <id>` reads
# the gate, observes the gate's own origin_url (never remote.origin.url) holding authorized_tip_sha
# at remote_ref, refuses otherwise or if consumed or revoked, and writes consumed_at /
# consumed_origin_tip / consumed_ref / consumed_origin_before / consumed_basis 'post-push witness by
# console'. ... expires_at binds the pre-push decider (authorization), not the settle (record of
# use)."
#
# SO EXPIRY IS DRIVEN AS AN ADMITTING ROW, NOT A REFUSING ONE, and that is the whole point of the
# ruling's named FIRST EXERCISE: the gate it reserves is EXPIRED. A member that only drove live
# gates would leave the one property the row exists for unmeasured.
#
# WHAT IS DELIBERATELY NOT DRIVEN HERE, SAID PLAINLY: THE REAL CREDENTIAL PATH. Every row below
# goes through the console's injected seam (`Provider = 'success' | 'failure'`), which is the path
# every existing console member in this file uses, and the artifacts it mints carry
# `operator_credential: injected-seam`. The acceptance record's own "WHAT IS OWED" section records that the
# operator's Cancel and OK probes on the REAL secure-desktop prompt are owed and unperformed, and
# its (G4) records that NO SESSION CAN OBTAIN `ERROR_CANCELLED` -- a posted WM_CLOSE did not dismiss
# that dialog, a UI Automation search found no Cancel button, and only killing the broker ended the
# call, returning rc 1726 and never 1223. The `failure`-provider row below is therefore a CONFIRM
# REFUSAL, not a cancelled credential prompt, and it is labelled as one.
#
# FIXTURE HERMETICITY, as T-31 established it: every origin is a LOCAL BARE REPOSITORY, no network
# is touched, declared URLs are FORWARD-SLASHED (a backslashed scratch remote URL in git config once
# broke the whole repository), and each scratch root's git dir is ASSERTED to resolve INSIDE the
# fixture BEFORE the first `git config` -- the 2026-09-13 rule, left behind by a fixture that
# skipped it, fell through to the HOST repository's .git/config and rewrote its identity and
# hooksPath.
$t32ok = $true
$t32rows = New-Object System.Collections.Generic.List[string]
function Add-T32Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t32ok = $false }
    $script:t32rows.Add(('      {0,-86} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + $Said } else { '' })))
}
function Get-T32Field {
    # ONE field read, column 0, Multiline. An INDENTED look-alike is not a top-level field, and the
    # gate artifacts this member mints carry no nested mappings -- but the reader is anchored anyway,
    # because the next artifact that does carry one must not silently satisfy a row here.
    param([string]$Text, [string]$Key)
    $m = [regex]::Match([string]$Text, '(?m)^' + [regex]::Escape($Key) + ':[ \t]*(.*?)[ \t]*\r?$')
    if ($m.Success) { return $m.Groups[1].Value }
    return $null
}
function Get-T32FieldCount {
    # HOW MANY TIMES the key appears at column 0. `exactly once` is a property this member asserts
    # directly: the settle appends, and an append that ran twice would leave an AUDIT ARTIFACT with
    # two consumed_at keys -- a missing record traded for an ambiguous one, which is the defect the
    # hook's own sentinel-replacement comment records.
    param([string]$Text, [string]$Key)
    return @([regex]::Matches([string]$Text, '(?m)^' + [regex]::Escape($Key) + ':')).Count
}
function Invoke-T32Git {
    # EVERY native git call goes through here with $ErrorActionPreference saved and restored. Under
    # 'Stop' any native exe writing to stderr is a fatal NativeCommandError and 2>$null does not
    # help. Both locals are seeded BEFORE the try -- StrictMode Latest is inherited from
    # evidence-common.ps1, so reading a variable the try never reached is terminating -- and $gitCode
    # is seeded NON-ZERO so a git that failed to launch cannot inherit a stale success.
    param([string[]]$GitArgs)
    $gitOut = ''
    $gitCode = -1
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $gitOut = & git @GitArgs 2>&1
        $gitCode = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ out = ((@($gitOut) | ForEach-Object { [string]$_ }) -join "`n"); code = $gitCode }
}

# THE FIVE FIELD NAMES AND THE TWO LITERALS, SPELLED OUT HERE RATHER THAN READ FROM THE TOOL.
# Asserting a tool's constant against itself passes for any string the tool happens to hold,
# including one that has drifted. The amendment quotes these same bytes.
$t32Basis      = 'post-push witness by console: the DECLARED origin observed holding the authorized sha'
$t32NoMintText = 'not observed at mint'
$t32Fields     = @('consumed_at', 'consumed_origin_tip', 'consumed_ref', 'consumed_origin_before', 'consumed_basis')

# THE WHOLE BODY RUNS INSIDE try/catch, AND THAT IS NOT DEFENSIVENESS FOR ITS OWN SAKE. This file
# inherits Set-StrictMode -Version Latest from evidence-common.ps1, under which an ordinary slip --
# reading .Count on something that is not a collection, touching a variable a branch never set --
# is TERMINATING. Uncaught, it kills the instrument mid-file: the summary line never prints, the
# exit code is not a failure COUNT, and every member after this one goes unmeasured. Driven here on
# this member's own first RED run, which aborted after T-31 and reported nothing at all. A member
# that cannot run must say so as a FAILING ROW naming its line, which is a measurement; an abort is
# the absence of one.
try {
$t32Base   = Join-Path $env:TEMP ('lam-wp4-t32-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
$t32Root   = Join-Path $t32Base 'mission'
$t32Origin = Join-Path $t32Base 'origin-declared.git'
$t32Gates  = Join-Path $t32Root '.mission\gates'
New-Item -ItemType Directory -Path (Join-Path $t32Root '.mission') -Force | Out-Null

# ---- the declared origin: a local bare repository carrying one commit on refs/heads/main --------
New-Item -ItemType Directory -Path $t32Origin -Force | Out-Null
$null = Invoke-T32Git -GitArgs @('init', '--bare', '--quiet', '--initial-branch=main', $t32Origin)
$t32Work = Join-Path $t32Base 'seed-work'
New-Item -ItemType Directory -Path $t32Work -Force | Out-Null
$null = Invoke-T32Git -GitArgs @('init', '--quiet', '--initial-branch=main', $t32Work)
# ASSERT THE GIT DIR BEFORE ANY `git config` (the 2026-09-13 rule).
$t32WorkGd = (Invoke-T32Git -GitArgs @('-C', $t32Work, 'rev-parse', '--absolute-git-dir')).out.Trim()
$t32WorkOk = $t32WorkGd.Replace('/', '\').StartsWith(([System.IO.Path]::GetFullPath($t32Work)), [StringComparison]::OrdinalIgnoreCase)
Add-T32Row -Label 'seed work tree: its git dir resolves INSIDE the fixture before any git config' -Ok $t32WorkOk -Said $t32WorkGd
if ($t32WorkOk) {
    $null = Invoke-T32Git -GitArgs @('-C', $t32Work, 'config', 'user.email', 't32@example.invalid')
    $null = Invoke-T32Git -GitArgs @('-C', $t32Work, 'config', 'user.name', 'T32')
    Write-Utf8 -Path (Join-Path $t32Work 'seed.txt') -Text "t32`n"
    $null = Invoke-T32Git -GitArgs @('-C', $t32Work, 'add', '--', 'seed.txt')
    $null = Invoke-T32Git -GitArgs @('-C', $t32Work, 'commit', '--quiet', '-m', 'seed')
    # FORWARD SLASHES in the pushed-to URL, for the reason in the header.
    $null = Invoke-T32Git -GitArgs @('-C', $t32Work, 'push', '--quiet', ($t32Origin -replace '\\', '/'), 'HEAD:refs/heads/main')
}
$t32OriginUrl = ($t32Origin -replace '\\', '/')
$t32Ls = Invoke-T32Git -GitArgs @('ls-remote', $t32OriginUrl, 'refs/heads/main')
$t32Tip = ''
$t32LsMatch = [regex]::Match($t32Ls.out, '(?m)^([0-9a-f]{40})\s')
if ($t32LsMatch.Success) { $t32Tip = $t32LsMatch.Groups[1].Value }
Add-T32Row -Label 'declared origin (local bare) advertises a 40-hex tip at refs/heads/main' -Ok ([bool]$t32Tip) -Said $t32Tip

# ---- the mission root whose gates the console will mint and settle ------------------------------
$null = Invoke-T32Git -GitArgs @('init', '--quiet', '--initial-branch=main', $t32Root)
$t32RootGd = (Invoke-T32Git -GitArgs @('-C', $t32Root, 'rev-parse', '--absolute-git-dir')).out.Trim()
$t32RootOk = $t32RootGd.Replace('/', '\').StartsWith(([System.IO.Path]::GetFullPath($t32Root)), [StringComparison]::OrdinalIgnoreCase)
Add-T32Row -Label 'mission root: its git dir resolves INSIDE the fixture before any git config' -Ok $t32RootOk -Said $t32RootGd
if ($t32RootOk) {
    $null = Invoke-T32Git -GitArgs @('-C', $t32Root, 'config', 'user.email', 't32@example.invalid')
    $null = Invoke-T32Git -GitArgs @('-C', $t32Root, 'config', 'user.name', 'T32')
    $null = Invoke-T32Git -GitArgs @('-C', $t32Root, 'remote', 'add', 'origin', $t32OriginUrl)
}
Write-Utf8 -Path (Join-Path $t32Root 'bound.txt') -Text "t32 bound`n"

function New-T32Gate {
    # MINT A REAL GATE, through the console's verified path, with the injected seam. It must be a
    # gate mission-gate.ps1 ACTUALLY WROTE: lam-gate-class.ps1's own header records that a
    # hand-rolled fixture gate which merely OMITS consumed_at takes a different branch and makes a
    # broken predicate look correct. Returns the artifact path.
    param([string]$Id, [string]$Tip, [string]$Url, [string]$Ref = 'refs/heads/main', [int]$Expires = 60)
    $spec = @{ Verb = 'approve'; Kind = 'push'; Id = $Id; Binds = 'bound.txt'; MissionRoot = $t32Root
               TipSha = $Tip; OriginUrl = $Url; RemoteRef = $Ref; ExpiresMinutes = "$Expires" }
    $r = Invoke-GateConsoleLauncher -Spec $spec
    return [pscustomobject]@{ result = $r; path = (Join-Path $t32Gates ("push-$Id.yaml")) }
}
function Invoke-T32Settle {
    param([string]$Id, [string]$Provider)
    $spec = @{ Verb = 'settle'; Kind = 'push'; Id = $Id; MissionRoot = $t32Root }
    if ($Provider) { $spec['Provider'] = $Provider }
    return (Invoke-GateConsoleLauncher -Spec $spec)
}

# =================================================================================================
# (1) THE HAPPY PATH -- origin holds the authorized sha, and the gate carries origin_tip_at_mint
# =================================================================================================
$t32A = New-T32Gate -Id 't32-live' -Tip $t32Tip -Url $t32OriginUrl
$t32AMinted = (Test-Path -LiteralPath $t32A.path)
Add-T32Row -Label '(1) a real push gate is minted through the console verified path' -Ok $t32AMinted -Said ("exit " + $t32A.result.exit)
$t32AMintText = if ($t32AMinted) { [System.IO.File]::ReadAllText($t32A.path) } else { '' }
$t32AMintTip  = Get-T32Field -Text $t32AMintText -Key 'origin_tip_at_mint'
Add-T32Row -Label '(1) the minted gate carries origin_tip_at_mint = the tip origin holds (M3)' -Ok ($t32AMintTip -ceq $t32Tip) -Said $t32AMintTip

$t32ALog = Join-Path $t32Root '.mission-runtime\operator-acts.log'
$t32ALogBefore = if (Test-Path -LiteralPath $t32ALog) { @([System.IO.File]::ReadAllLines($t32ALog)).Count } else { 0 }
$t32AS = Invoke-T32Settle -Id 't32-live'
$t32AText = if (Test-Path -LiteralPath $t32A.path) { [System.IO.File]::ReadAllText($t32A.path) } else { '' }
Add-T32Row -Label '(1) settle exits 0 and reports minted' -Ok (($t32AS.exit -eq 0) -and $t32AS.minted) -Said ("exit " + $t32AS.exit + ", stage " + $t32AS.stage)

foreach ($t32F in $t32Fields) {
    $t32C = Get-T32FieldCount -Text $t32AText -Key $t32F
    Add-T32Row -Label ("(1) {0} appears EXACTLY ONCE at column 0" -f $t32F) -Ok ($t32C -eq 1) -Said ("count " + $t32C)
}
Add-T32Row -Label '(1) consumed_origin_tip is what origin was OBSERVED to hold' -Ok ((Get-T32Field -Text $t32AText -Key 'consumed_origin_tip') -ceq $t32Tip) -Said (Get-T32Field -Text $t32AText -Key 'consumed_origin_tip')
Add-T32Row -Label '(1) consumed_ref is the gate''s own remote_ref' -Ok ((Get-T32Field -Text $t32AText -Key 'consumed_ref') -ceq 'refs/heads/main') -Said (Get-T32Field -Text $t32AText -Key 'consumed_ref')
Add-T32Row -Label '(1) consumed_origin_before is the gate''s origin_tip_at_mint, not the literal' -Ok ((Get-T32Field -Text $t32AText -Key 'consumed_origin_before') -ceq $t32Tip) -Said (Get-T32Field -Text $t32AText -Key 'consumed_origin_before')
Add-T32Row -Label '(1) consumed_basis is the ruling''s words, verbatim' -Ok ((Get-T32Field -Text $t32AText -Key 'consumed_basis') -ceq $t32Basis) -Said (Get-T32Field -Text $t32AText -Key 'consumed_basis')
# THE SENTINEL IS REPLACED, NOT DUPLICATED. `consumed_at: null` is what every minted gate carries;
# appending beside a surviving sentinel would put TWO consumed_at keys in an audit artifact.
Add-T32Row -Label '(1) the consumed_at: null sentinel is GONE, not left beside a second key' -Ok ($t32AText -notmatch '(?m)^consumed_at:[ \t]*null[ \t]*\r?$') -Said 'sentinel replaced in place'
# THE STATE PREDICATE EVERY OTHER CONSUMER READS now says CONSUMED. Asserting the text alone would
# pass for a field the shared predicate cannot see.
Add-T32Row -Label '(1) Get-LamGateState now reports CONSUMED' -Ok ((Get-LamGateState -Path $t32A.path).state -eq 'CONSUMED') -Said (Get-LamGateState -Path $t32A.path).state

# THE OUTER @() IS LOAD-BEARING AND ITS ABSENCE ABORTED THIS MEMBER'S FIRST TWO RED RUNS.
# PowerShell UNROLLS the value of an `if` STATEMENT on assignment, so an inner @() holding exactly
# ONE element arrives as the bare element -- here a single log line, as a [string] -- and .Count on
# a string is TERMINATING under StrictMode Latest. It is the mirror of this codebase's documented
# `return , $out` idiom: there the wrap must SURVIVE assignment, here it must be RE-APPLIED after
# one. Note what made it nasty: at RED the log holds one line and this throws, while at GREEN it
# holds two and the same code would have passed BY LUCK.
$t32ALogLines = @(if (Test-Path -LiteralPath $t32ALog) { @([System.IO.File]::ReadAllLines($t32ALog) | Where-Object { $_.Trim() }) } else { @() })
$t32ALogAdded = $t32ALogLines.Count - $t32ALogBefore
$t32ASettleLines = @($t32ALogLines | Where-Object { $_ -match 'verb=settle' })
Add-T32Row -Label '(1) exactly ONE operator-acts line was appended by the settle' -Ok ($t32ALogAdded -eq 1) -Said ("added " + $t32ALogAdded)
Add-T32Row -Label '(1) that line reads kind=gate-act verb=settle with tool_exit=0' -Ok (($t32ASettleLines.Count -eq 1) -and ($t32ASettleLines[0] -match 'kind=gate-act') -and ($t32ASettleLines[0] -match 'tool_exit=0')) -Said ($(if ($t32ASettleLines.Count -ge 1) { $t32ASettleLines[0] } else { '(no verb=settle line)' }))
# THE PREVIEW SHOWED WHAT WAS WRITTEN. A value the human never saw is not part of what they approved.
$t32APrev = [string]$t32AS.preview
$t32PrevOk = $true
foreach ($t32F in $t32Fields) { if ($t32APrev -notmatch [regex]::Escape($t32F)) { $t32PrevOk = $false } }
Add-T32Row -Label '(1) the PREVIEW carried all five consumed_* fields before the confirm' -Ok $t32PrevOk -Said ("preview " + $t32APrev.Length + " chars")

# =================================================================================================
# (2) SECOND SETTLE -- FIRST STAMP WINS, and the artifact is BYTE-UNCHANGED
# =================================================================================================
$t32AShaBefore = (Get-FileHash -Algorithm SHA256 -LiteralPath $t32A.path).Hash
$t32A2 = Invoke-T32Settle -Id 't32-live'
$t32AShaAfter = (Get-FileHash -Algorithm SHA256 -LiteralPath $t32A.path).Hash
Add-T32Row -Label '(2) a SECOND settle refuses (non-zero) and does not mint' -Ok (($t32A2.exit -ne 0) -and (-not $t32A2.minted)) -Said ("exit " + $t32A2.exit + ", stage " + $t32A2.stage)
Add-T32Row -Label '(2) the already-consumed artifact is BYTE-UNCHANGED' -Ok ($t32AShaAfter -eq $t32AShaBefore) -Said ($t32AShaBefore.Substring(0, 16) + ' -> ' + $t32AShaAfter.Substring(0, 16))
foreach ($t32F in $t32Fields) {
    $t32C = Get-T32FieldCount -Text ([System.IO.File]::ReadAllText($t32A.path)) -Key $t32F
    Add-T32Row -Label ("(2) {0} is STILL exactly once after the refused second settle" -f $t32F) -Ok ($t32C -eq 1) -Said ("count " + $t32C)
}

# =================================================================================================
# (3) ORIGIN NOT AT THE TIP -- refused, artifact byte-unchanged
# =================================================================================================
# The gate authorizes a sha origin does NOT carry. Nothing about the gate is wrong; the PUBLICATION
# it authorizes has not happened, so there is nothing to record and the authorization is not spent.
$t32B = New-T32Gate -Id 't32-notpublished' -Tip 'dead0000dead0000dead0000dead0000dead0000' -Url $t32OriginUrl
$t32BShaBefore = if (Test-Path -LiteralPath $t32B.path) { (Get-FileHash -Algorithm SHA256 -LiteralPath $t32B.path).Hash } else { '' }
$t32BS = Invoke-T32Settle -Id 't32-notpublished'
$t32BShaAfter = if (Test-Path -LiteralPath $t32B.path) { (Get-FileHash -Algorithm SHA256 -LiteralPath $t32B.path).Hash } else { '' }
$t32BText = if (Test-Path -LiteralPath $t32B.path) { [System.IO.File]::ReadAllText($t32B.path) } else { '' }
Add-T32Row -Label '(3) origin does NOT hold the authorized sha -> settle refuses' -Ok (($t32BS.exit -ne 0) -and (-not $t32BS.minted)) -Said ("exit " + $t32BS.exit)
Add-T32Row -Label '(3) the artifact is BYTE-UNCHANGED' -Ok (($t32BShaBefore -ne '') -and ($t32BShaAfter -eq $t32BShaBefore)) -Said ($t32BShaBefore.Substring(0, 16) + ' -> ' + $t32BShaAfter.Substring(0, 16))
Add-T32Row -Label '(3) not one consumed_* field was written' -Ok ((Get-T32FieldCount -Text $t32BText -Key 'consumed_origin_tip') -eq 0) -Said 'no consume block'
Add-T32Row -Label '(3) the gate is still open to the shared state predicate' -Ok ((Get-LamGateState -Path $t32B.path).state -eq 'open') -Said (Get-LamGateState -Path $t32B.path).state

# =================================================================================================
# (4) REVOKED -- refused; and (5) EXPIRED -- SETTLED, which is the ruling's first exercise
# =================================================================================================
$t32C = New-T32Gate -Id 't32-revoked' -Tip $t32Tip -Url $t32OriginUrl
$null = Invoke-GateConsoleLauncher -Spec @{ Verb = 'revoke'; Kind = 'push'; Id = 't32-revoked'; MissionRoot = $t32Root; Reason = 'T-32' }
$t32CShaBefore = (Get-FileHash -Algorithm SHA256 -LiteralPath $t32C.path).Hash
$t32CS = Invoke-T32Settle -Id 't32-revoked'
$t32CShaAfter = (Get-FileHash -Algorithm SHA256 -LiteralPath $t32C.path).Hash
Add-T32Row -Label '(4) a REVOKED gate refuses the settle' -Ok (($t32CS.exit -ne 0) -and (-not $t32CS.minted)) -Said ("exit " + $t32CS.exit)
Add-T32Row -Label '(4) the revoked artifact is BYTE-UNCHANGED' -Ok ($t32CShaAfter -eq $t32CShaBefore) -Said 'unchanged'

# EXPIRY DOES NOT BIND THE SETTLE. -ExpiresMinutes 0 makes expires_at equal created_at, so the gate
# is expired the instant it exists. The pre-push decider would refuse it; the settle must not,
# because a settle is a RECORD OF USE and not an authorization.
$t32D = New-T32Gate -Id 't32-expired' -Tip $t32Tip -Url $t32OriginUrl -Expires 0
$t32DExp = Get-T32Field -Text ([System.IO.File]::ReadAllText($t32D.path)) -Key 'expires_at'
$t32DCreated = Get-T32Field -Text ([System.IO.File]::ReadAllText($t32D.path)) -Key 'created_at'
Add-T32Row -Label '(5) the fixture gate really is expired (expires_at == created_at)' -Ok ($t32DExp -ceq $t32DCreated) -Said ($t32DCreated + ' / ' + $t32DExp)
$t32DS = Invoke-T32Settle -Id 't32-expired'
$t32DText = [System.IO.File]::ReadAllText($t32D.path)
Add-T32Row -Label '(5) THE RULING''S FIRST EXERCISE: an EXPIRED gate SETTLES' -Ok (($t32DS.exit -eq 0) -and $t32DS.minted) -Said ("exit " + $t32DS.exit)
Add-T32Row -Label '(5) and it carries the same five fields' -Ok ((@($t32Fields | Where-Object { (Get-T32FieldCount -Text $t32DText -Key $_) -ne 1 })).Count -eq 0) -Said 'five fields, once each'

# =================================================================================================
# (6) A GATE WITH NO origin_tip_at_mint -- consumed_origin_before is the ruling's literal
# =================================================================================================
# Every gate minted BEFORE M3 lacks the field, which is exactly the case the ruling names: "earlier
# gates settle with consumed_origin_before 'not observed at mint'." The field is stripped from a
# REAL minted artifact rather than hand-writing a gate, so the rest of the bytes stay the writer's.
$t32E = New-T32Gate -Id 't32-nomint' -Tip $t32Tip -Url $t32OriginUrl
$t32EText0 = [System.IO.File]::ReadAllText($t32E.path)
$t32EStripped = ($t32EText0 -replace '(?m)^origin_tip_at_mint:.*\r?\n', '')
[System.IO.File]::WriteAllText($t32E.path, $t32EStripped, (New-Object System.Text.UTF8Encoding($false)))
Add-T32Row -Label '(6) the fixture gate genuinely carries no origin_tip_at_mint' -Ok ((Get-T32FieldCount -Text $t32EStripped -Key 'origin_tip_at_mint') -eq 0) -Said 'field stripped'
$t32ES = Invoke-T32Settle -Id 't32-nomint'
$t32EText = [System.IO.File]::ReadAllText($t32E.path)
Add-T32Row -Label '(6) it settles' -Ok (($t32ES.exit -eq 0) -and $t32ES.minted) -Said ("exit " + $t32ES.exit)
Add-T32Row -Label '(6) consumed_origin_before reads the ruling''s literal, verbatim' -Ok ((Get-T32Field -Text $t32EText -Key 'consumed_origin_before') -ceq $t32NoMintText) -Said (Get-T32Field -Text $t32EText -Key 'consumed_origin_before')

# =================================================================================================
# (7) THE CONFIRM REFUSAL -- the injected seam's failure provider, NOT a cancelled credential prompt
# =================================================================================================
# Labelled precisely because an earlier measurement (G4) found that NO SESSION CAN OBTAIN ERROR_CANCELLED
# from the real dialog. This row measures the console's REFUSAL PATH -- nothing written, exit 3,
# stage confirm, and the attestation line still appended with tool_exit=3, because a refused act is
# still an act the record must carry.
$t32F = New-T32Gate -Id 't32-confirm' -Tip $t32Tip -Url $t32OriginUrl
$t32FShaBefore = (Get-FileHash -Algorithm SHA256 -LiteralPath $t32F.path).Hash
$t32FLogBefore = if (Test-Path -LiteralPath $t32ALog) { @([System.IO.File]::ReadAllLines($t32ALog) | Where-Object { $_.Trim() }).Count } else { 0 }
$t32FS = Invoke-T32Settle -Id 't32-confirm' -Provider 'failure'
$t32FShaAfter = (Get-FileHash -Algorithm SHA256 -LiteralPath $t32F.path).Hash
$t32FLogAfter = if (Test-Path -LiteralPath $t32ALog) { @([System.IO.File]::ReadAllLines($t32ALog) | Where-Object { $_.Trim() }).Count } else { 0 }
Add-T32Row -Label '(7) a refused CONFIRM gives exit 3 at stage confirm and mints nothing' -Ok (($t32FS.exit -eq 3) -and ($t32FS.stage -eq 'confirm') -and (-not $t32FS.minted)) -Said ("exit " + $t32FS.exit + ", stage " + $t32FS.stage)
Add-T32Row -Label '(7) the artifact is BYTE-UNCHANGED by a refused confirm' -Ok ($t32FShaAfter -eq $t32FShaBefore) -Said 'unchanged'
Add-T32Row -Label '(7) the refused act STILL attests -- one more line, tool_exit=3' -Ok (($t32FLogAfter - $t32FLogBefore) -eq 1) -Said ("added " + ($t32FLogAfter - $t32FLogBefore))
Add-T32Row -Label '(7) it is the injected seam, NOT the real credential path (amendment 44 G4)' -Ok ($t32AMintText -match '(?m)^operator_credential:[ \t]*injected-seam') -Said 'operator_credential: injected-seam'

# =================================================================================================
# (8) THE ARTIFACT IS THE AUTHORITY ON ITS OWN KIND -- revoke's lesson, applied to settle
# =================================================================================================
# `settle -Kind dispatch` against a file whose face says `kind: push` must refuse. A file NAMED for
# a kind is not a gate of that kind, and stamping one under the wrong name would record a
# publication against an artifact that authorizes something else entirely.
$t32GS = Invoke-GateConsoleLauncher -Spec @{ Verb = 'settle'; Kind = 'dispatch'; Id = 't32-live'; MissionRoot = $t32Root }
Add-T32Row -Label '(8) settle -Kind dispatch against a kind: push artifact refuses' -Ok ($t32GS.exit -ne 0) -Said ("exit " + $t32GS.exit)
$t32HS = Invoke-GateConsoleLauncher -Spec @{ Verb = 'settle'; Kind = 'push'; Id = 't32-absent'; MissionRoot = $t32Root }
Add-T32Row -Label '(8) settle of a gate that does not exist refuses' -Ok ($t32HS.exit -ne 0) -Said ("exit " + $t32HS.exit)

try { Remove-Item -LiteralPath $t32Base -Recurse -Force -ErrorAction Stop } catch { }
}
catch {
    Add-T32Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[
]+', ' '))
    try { Remove-Item -LiteralPath $t32Base -Recurse -Force -ErrorAction Stop } catch { }
}


Check -Id 'T-32' -Title 'operator ruling (i): the console gains `settle -Kind push -Id <id>`, which reads the gate, observes the gate''s OWN declared origin_url holding authorized_tip_sha at remote_ref, and appends consumed_at / consumed_origin_tip / consumed_ref / consumed_origin_before / consumed_basis exactly once each with the ruling''s basis words -- replacing the consumed_at: null sentinel rather than leaving a second key -- and appends exactly one operator-acts line kind=gate-act verb=settle; a second settle REFUSES byte-unchanged (first stamp wins), an origin not holding the sha REFUSES byte-unchanged, a revoked gate REFUSES, an EXPIRED gate SETTLES (expiry binds the pre-push decider, not the record of use -- the ruling''s named first exercise), a gate with no origin_tip_at_mint records the literal "not observed at mint", a refused CONFIRM writes nothing yet still attests with tool_exit=3, and a kind that disagrees with the artifact''s own face refuses. Every row drives the INJECTED SEAM, never the real secure-desktop credential, which amendment 44 (G4) measured no session can complete' `
      -Ok $t32ok -Detail ($t32rows -join "`n")

# =================================================================================================
# T-33 -- FIRST STAMP WINS ON THE HOOK SIDE: the PostToolUse settle never edits a CONSUMED gate
#         (operator ruling (i))
# =================================================================================================
# THE RULING: "The in-session PostToolUse settle stays; first stamp wins, the second refuses."
# T-32 measures the console half. This is the hook half, and it is NOT a restatement: the two settle
# through entirely different code, and only one of them had the property.
#
# WHAT LOOKED TRUE AND WAS NOT. Get-EvidencePushGateForSha filters consumed gates out of the
# SELECTION, so the write loop appeared unable to meet one. It can. Selection runs to completion for
# the WHOLE record BEFORE any write, so two entries naming the same ref both resolve to the same
# still-unconsumed gate, and the loop then visits it twice. DRIVEN at this build: the second visit
# appended consumed_origin_tip, consumed_ref, consumed_origin_before and consumed_basis a SECOND
# time, while the consumed_at guard correctly left that one field alone -- leaving TWO consume blocks
# under ONE consumed_at.
#
# THAT IS THE HARM THE GUARD ITSELF NAMES. Its own comment says appending beside a surviving sentinel
# "trades a missing record for an ambiguous one". The guard was attached to a FIELD when the property
# belongs to the GATE, so four later fields walked straight past it. The cure refuses the gate whole
# at the top of the loop; this member is what makes that a measurement.
#
# THE CONTROL IS THE POINT. A member that only drove the duplicate would pass against a settle that
# had stopped working altogether, so the ORDINARY single-entry case is driven in the same fixture and
# must still write all five fields exactly once. Refusing everything is not the cure.
$t33ok = $true
$t33rows = New-Object System.Collections.Generic.List[string]
function Add-T33Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t33ok = $false }
    $script:t33rows.Add(('      {0,-84} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + $Said } else { '' })))
}
function Get-T33KeyCount {
    param([string]$Text, [string]$Key)
    return @([regex]::Matches([string]$Text, '(?m)^' + [regex]::Escape($Key) + ':')).Count
}
function Invoke-T33Git {
    # $ErrorActionPreference saved and restored; both locals seeded before the try (StrictMode Latest
    # is inherited from evidence-common.ps1), and the code seeded NON-ZERO so a git that failed to
    # launch cannot inherit a stale success.
    param([string[]]$GitArgs)
    $gitOut = ''
    $gitCode = -1
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $gitOut = & git @GitArgs 2>&1
        $gitCode = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ out = ((@($gitOut) | ForEach-Object { [string]$_ }) -join "`n"); code = $gitCode }
}

$t33Fields = @('consumed_at', 'consumed_origin_tip', 'consumed_ref', 'consumed_origin_before', 'consumed_basis')

try {
# THE FIXTURE LIVES UNDER $env:TEMP AND NOT UNDER A DEEPER SCRATCH ROOT, AND THAT IS NOT ARBITRARY:
# a bare-repo push into a long path fails with "Filename too long" and the origin then advertises no
# tip at all, which would make every row below measure a broken fixture. Driven here before the
# member was written.
$t33Base = Join-Path $env:TEMP ('lam-wp4-t33-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
$t33Root = Join-Path $t33Base 'mission'
$t33Origin = Join-Path $t33Base 'origin.git'
$t33Work = Join-Path $t33Base 'work'
foreach ($t33d in @($t33Root, $t33Origin, $t33Work)) { New-Item -ItemType Directory -Path $t33d -Force | Out-Null }

$null = Invoke-T33Git -GitArgs @('init', '--bare', '--quiet', '--initial-branch=main', $t33Origin)
$null = Invoke-T33Git -GitArgs @('init', '--quiet', '--initial-branch=main', $t33Work)
# ASSERT THE GIT DIR BEFORE ANY git config (the 2026-09-13 rule): a fixture that configured first
# once fell through to the HOST repository's .git/config and rewrote its identity and hooksPath.
$t33Gd = (Invoke-T33Git -GitArgs @('-C', $t33Work, 'rev-parse', '--absolute-git-dir')).out.Trim()
$t33GdOk = $t33Gd.Replace('/', '\').StartsWith(([System.IO.Path]::GetFullPath($t33Work)), [StringComparison]::OrdinalIgnoreCase)
Add-T33Row -Label 'FIXTURE the work tree git dir resolves INSIDE the fixture, before any git config' -Ok $t33GdOk -Said $t33Gd
if ($t33GdOk) {
    $null = Invoke-T33Git -GitArgs @('-C', $t33Work, 'config', 'user.email', 't33@example.invalid')
    $null = Invoke-T33Git -GitArgs @('-C', $t33Work, 'config', 'user.name', 'T33')
    Write-Utf8 -Path (Join-Path $t33Work 'a.txt') -Text "t33`n"
    $null = Invoke-T33Git -GitArgs @('-C', $t33Work, 'add', '--', 'a.txt')
    $null = Invoke-T33Git -GitArgs @('-C', $t33Work, 'commit', '--quiet', '-m', 'seed')
}
# FORWARD SLASHES: a backslashed scratch remote URL in git config once broke the whole repository.
$t33Url = ($t33Origin -replace '\\', '/')
$null = Invoke-T33Git -GitArgs @('-C', $t33Work, 'push', '--quiet', $t33Url, 'HEAD:refs/heads/main')
$t33Ls = Invoke-T33Git -GitArgs @('ls-remote', $t33Url, 'refs/heads/main')
$t33Tip = ''
$t33LsM = [regex]::Match($t33Ls.out, '(?m)^([0-9a-f]{40})\s')
if ($t33LsM.Success) { $t33Tip = $t33LsM.Groups[1].Value }
Add-T33Row -Label 'FIXTURE the local bare origin really advertises a 40-hex tip (no network)' -Ok ([bool]$t33Tip) -Said $t33Tip

$t33GatesDir = Join-Path $t33Root '.mission\gates'
New-Item -ItemType Directory -Path $t33GatesDir -Force | Out-Null
function New-T33Gate {
    # A push gate carrying the shape the real writer produces, including the consumed_at: null
    # sentinel every minted gate has -- the state predicate's `(?!null)` is only exercised by a gate
    # that actually carries it, and lam-gate-class.ps1's header records that a fixture which simply
    # OMITS the line takes a different branch and makes a broken predicate look correct.
    param([string]$Name)
    $t33Now = (Get-Date).ToUniversalTime()
    $t33Gate = Join-Path $t33GatesDir $Name
    $t33Text = "kind: push`r`ngate_class: build-authorization`r`nid: $([System.IO.Path]::GetFileNameWithoutExtension($Name))`r`n" +
               "authorized_tip_sha: $t33Tip`r`norigin_url: $t33Url`r`nremote_ref: refs/heads/main`r`n" +
               "created_at: $($t33Now.ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture))`r`n" +
               "expires_at: $($t33Now.AddHours(4).ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture))`r`n" +
               "single_use: true`r`nconsumed_at: null`r`n"
    [System.IO.File]::WriteAllText($t33Gate, $t33Text, (New-Object System.Text.UTF8Encoding($false)))
    return $t33Gate
}
function New-T33Entry {
    param([string]$GatePath)
    # remote_sha_before must DIFFER from the observed tip, or the selection classes the push as
    # having published nothing and the entry never reaches the write loop at all -- the member would
    # then be measuring that branch instead of the one under test.
    return [pscustomobject]@{
        gate_path = $GatePath; authorized_sha = $t33Tip; remote_ref = 'refs/heads/main'
        remote_sha_before = '1111111111111111111111111111111111111111'
    }
}

# =================================================================================================
# (1) THE CONTROL -- one entry, the ordinary case, must still write all five fields exactly once
# =================================================================================================
$t33GateA = New-T33Gate -Name 'push-t33-single.yaml'
$null = Clear-EvidencePushInFlight -Root $t33Root
$null = Write-EvidencePushInFlight -Root $t33Root -Remote 'origin' -RemoteUrl $t33Url -Entries @((New-T33Entry -GatePath $t33GateA))
$t33RA = Complete-EvidencePushGate -Root $t33Root
$t33TextA = [System.IO.File]::ReadAllText($t33GateA)
$t33AOnce = @($t33Fields | Where-Object { (Get-T33KeyCount -Text $t33TextA -Key $_) -ne 1 })
Add-T33Row -Label '(1) CONTROL one entry: the settle still consumes the gate' -Ok ([bool]$t33RA.consumed) -Said (($t33RA.reason -replace '\s+', ' ').Substring(0, [Math]::Min(90, ($t33RA.reason -replace '\s+', ' ').Length)))
Add-T33Row -Label '(1) CONTROL all five consumed_* fields present EXACTLY ONCE' -Ok ($t33AOnce.Count -eq 0) -Said ($(if ($t33AOnce.Count -eq 0) { 'five fields, once each' } else { 'wrong count on: ' + ($t33AOnce -join ', ') }))

# =================================================================================================
# (2) THE ROW -- ONE record, TWO entries naming the SAME ref, against ONE gate
# =================================================================================================
# Both entries resolve during selection, while the gate is still unconsumed, so the write loop is
# handed the same path twice. Before the cure the second visit appended a second consume block.
$t33GateB = New-T33Gate -Name 'push-t33-double.yaml'
$t33EntryB = New-T33Entry -GatePath $t33GateB
$null = Clear-EvidencePushInFlight -Root $t33Root
$null = Write-EvidencePushInFlight -Root $t33Root -Remote 'origin' -RemoteUrl $t33Url -Entries @($t33EntryB, $t33EntryB)
$t33Recs = @(Get-EvidencePushInFlightRecords -Root $t33Root)
$t33RecEntries = 0
if ($t33Recs.Count -ge 1) { $t33RecEntries = @($t33Recs[0].entries).Count }
Add-T33Row -Label '(2) FIXTURE one record really carries two entries for the same ref' -Ok (($t33Recs.Count -eq 1) -and ($t33RecEntries -eq 2)) -Said ("records " + $t33Recs.Count + ", entries " + $t33RecEntries)

$t33RB = Complete-EvidencePushGate -Root $t33Root
$t33TextB = [System.IO.File]::ReadAllText($t33GateB)
foreach ($t33F in $t33Fields) {
    $t33N = Get-T33KeyCount -Text $t33TextB -Key $t33F
    Add-T33Row -Label ("(2) {0} appears EXACTLY ONCE -- never a second consume block" -f $t33F) -Ok ($t33N -eq 1) -Said ("count " + $t33N)
}
# THE GATE IS STILL A WELL-FORMED CONSUMED GATE, not merely un-duplicated: a cure that refused the
# FIRST visit too would satisfy every row above and leave the publication unrecorded.
Add-T33Row -Label '(2) the gate IS consumed -- the cure refuses the second visit, not the first' -Ok ((Get-LamGateState -Path $t33GateB).state -eq 'CONSUMED') -Said (Get-LamGateState -Path $t33GateB).state
Add-T33Row -Label '(2) consumed_origin_tip is the sha origin actually holds' -Ok (([regex]::Match($t33TextB, '(?m)^consumed_origin_tip:[ \t]*(\S+)')).Groups[1].Value -ceq $t33Tip) -Said $t33Tip
Add-T33Row -Label '(2) the settle REPORTS the consumption (the record is not silently dropped)' -Ok ([bool]$t33RB.consumed) -Said (($t33RB.reason -replace '\s+', ' ').Substring(0, [Math]::Min(110, ($t33RB.reason -replace '\s+', ' ').Length)))

# =================================================================================================
# (3) AN ALREADY-CONSUMED GATE IS LEFT BYTE-UNCHANGED BY A LATER SETTLE
# =================================================================================================
# The selection filter should stop this reaching the loop at all; the row exists because that is the
# property being claimed, and a claim nobody drives is the shape this build keeps finding.
$t33ShaBefore = (Get-FileHash -Algorithm SHA256 -LiteralPath $t33GateB).Hash
$null = Clear-EvidencePushInFlight -Root $t33Root
$null = Write-EvidencePushInFlight -Root $t33Root -Remote 'origin' -RemoteUrl $t33Url -Entries @($t33EntryB)
$t33RC = Complete-EvidencePushGate -Root $t33Root
$t33ShaAfter = (Get-FileHash -Algorithm SHA256 -LiteralPath $t33GateB).Hash
Add-T33Row -Label '(3) a later settle against the consumed gate leaves it BYTE-UNCHANGED' -Ok ($t33ShaAfter -eq $t33ShaBefore) -Said ($t33ShaBefore.Substring(0, 16) + ' -> ' + $t33ShaAfter.Substring(0, 16))
Add-T33Row -Label '(3) and it consumes nothing' -Ok (-not $t33RC.consumed) -Said (($t33RC.reason -replace '\s+', ' ').Substring(0, [Math]::Min(110, ($t33RC.reason -replace '\s+', ' ').Length)))

try { Remove-Item -LiteralPath $t33Base -Recurse -Force -ErrorAction Stop } catch { }
}
catch {
    Add-T33Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
    try { Remove-Item -LiteralPath $t33Base -Recurse -Force -ErrorAction Stop } catch { }
}

Check -Id 'T-33' -Title 'operator ruling (i), the HOOK half of first-stamp-wins: Complete-EvidencePushGate never edits a gate that is already consumed. Selection resolves every entry of a record BEFORE any write, so two entries naming one ref hand the write loop the same still-unconsumed gate twice -- and the pre-cure guard, attached to the consumed_at FIELD rather than to the GATE, let the four fields after it append a SECOND consume block under ONE consumed_at, which is verbatim the "missing record traded for an ambiguous one" its own comment exists to prevent. Driven with a local bare origin and no network: the duplicate case now writes each of the five fields exactly once and still CONSUMES the gate, an ordinary single-entry settle is unaffected (the control -- refusing everything is not the cure), and a later settle against the consumed gate leaves it byte-unchanged and consumes nothing' `
      -Ok $t33ok -Detail ($t33rows -join "`n")

# =================================================================================================
# T-34 -- A GATE KIND IS CASE-SIGNIFICANT AT THE MINT AND AT THE SETTLE
#         (the operator's ruling answering round 2's finding)
# =================================================================================================
# THE DEFECT, MEASURED BEFORE IT WAS CURED. `$script:LamGateClassByKind` is an `[ordered]@{}`, whose
# `.Contains()` FOLDS CASE, and mission-gate.ps1:1580 classifies a mint by asking exactly that. So
# `approve -Kind PUSH` was CLASSIFIED build-authorization and MINTED: `-ComposeOnly` exited 0 and
# composed a literal `kind: PUSH` artifact at the filename `PUSH-<id>.yaml`. `[ValidateSet]`
# validates case-insensitively and does NOT normalise, there is no assignment to `$Kind` and no
# `ToLower` in the file, so the spelling the operator typed reached the artifact's face.
#
# AND THEN THE SETTLE READ IT BACK WITH A DIFFERENT OPINION. `settle -Kind push` against that
# `kind: PUSH` artifact exited 0 and composed a full consume block -- byte-identical in size to the
# canonical row -- because `mission-gate.ps1:1050` compared the two with `-ne`, which folds. One
# artifact, two spellings, and the tool agreed with both.
#
# THE OPERATOR'S ROUND-3 RULING: "a non-canonical kind is REFUSED by the admission, by settle and by
# the decider alike; a WP-4 member drives `kind: PUSH` and `kind: Push` through settle (refused,
# artifact byte-unchanged) and a WP-3 member through the admission (refused), with lowercase
# controls."
#
# EVERY REFUSING ROW HERE HAS A CONTROL, because a cure that refused everything would satisfy a
# refuse-only member while BREAKING THE VERB: the lowercase artifact -- byte-identical to the
# refused one except for the kind token, asserted by SUBSTITUTION and not by eye -- must still
# settle and write the five consumed_* fields exactly once each, and `approve -Kind push` must
# still mint.
#
# THE MINT ROWS ARE DRIVEN TWICE, AND THE TWO DRIVES ANSWER DIFFERENT QUESTIONS. `-ComposeOnly`
# goes to mission-gate.ps1 DIRECTLY in a child process, so the exit code is unambiguously the
# TOOL'S (2 is its refusal code) and the planned writes are legible as LAMCOMPOSE lines -- that is
# where "nothing would have been written" is proved as an absence of a planned write rather than as
# an absence on disk. The console launcher then drives the REAL operator path, where "nothing was
# written" is proved against a sha256 inventory of the gates directory taken before and after.
#
# FIXTURE HERMETICITY, as T-31 and T-32 established it: every origin is a LOCAL BARE REPOSITORY, no
# network is touched, declared URLs are FORWARD-SLASHED, and each scratch root's git dir is ASSERTED
# to resolve INSIDE the fixture BEFORE the first `git config` (the 2026-09-13 rule).
#
# THE NON-LOWERCASE ARTIFACTS ARE MADE BY REWRITING ONE TOKEN IN A REAL MINTED GATE, never by hand:
# lam-gate-class.ps1's own header records that a hand-rolled fixture which merely OMITS a field
# takes a different branch and makes a broken predicate look correct. After the cure the tool will
# not mint such a gate at all, so the only honest way to obtain one is to take a gate the tool DID
# write and change the single token under test.
$t34ok = $true
$t34rows = New-Object System.Collections.Generic.List[string]
function Add-T34Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t34ok = $false }
    $script:t34rows.Add(('      {0,-86} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + $Said } else { '' })))
}
function Invoke-T34Git {
    # Every native git call with $ErrorActionPreference saved and restored: under 'Stop' any native
    # exe writing to stderr is a fatal NativeCommandError and 2>$null does not help. Both locals are
    # seeded BEFORE the try -- StrictMode Latest is inherited -- and $code NON-ZERO so a git that
    # failed to launch cannot inherit a stale success.
    param([string[]]$GitArgs)
    $gitOut = ''
    $gitCode = -1
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $gitOut = & git @GitArgs 2>&1
        $gitCode = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ out = ((@($gitOut) | ForEach-Object { [string]$_ }) -join "`n"); code = $gitCode }
}
function Get-T34FieldCount {
    param([string]$Text, [string]$Key)
    return @([regex]::Matches([string]$Text, '(?m)^' + [regex]::Escape($Key) + ':')).Count
}
function Get-T34Stamp {
    # THE BYTE-UNCHANGED WITNESS: sha256 AND length together. A hash alone answers "same content";
    # the length says so in a second currency, and an absent file is reported as ABSENT rather than
    # as an empty string that a later comparison would read as agreement.
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return 'ABSENT' }
    return ((Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash + '/' + (Get-Item -LiteralPath $Path).Length)
}
function Get-T34GatesInventory {
    # EVERY artifact in the gates directory, by name and sha256, sorted. "Nothing was written" is a
    # statement about the WHOLE directory: a refusal that wrote a differently-named file would pass
    # a check that only asked about the path it expected.
    param([string]$Dir)
    if (-not (Test-Path -LiteralPath $Dir -PathType Container)) { return '(no gates dir)' }
    $rows = @(Get-ChildItem -LiteralPath $Dir -File -ErrorAction SilentlyContinue | Sort-Object -Property Name |
              ForEach-Object { $_.Name + '=' + (Get-FileHash -Algorithm SHA256 -LiteralPath $_.FullName).Hash.Substring(0, 16) })
    return ($rows -join ' ; ')
}
function Invoke-T34ComposeOnly {
    # mission-gate.ps1 DIRECTLY, in a child process, with -ComposeOnly -- which authorizes nothing,
    # needs no console token, and WRITES NOTHING. Returns the tool's own exit code and the decoded
    # LAMCOMPOSE writes, so a planned write is visible as a plan.
    param([string]$Kind, [string]$Id, [string]$Root, [string]$Tip, [string]$Url, [string]$Ref)
    $t34Out = ''
    $t34Code = -1
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $t34Out = & powershell -NoProfile -ExecutionPolicy Bypass -File $gateTool approve -Kind $Kind -Id $Id `
                     -Binds 'bound.txt' -MissionRoot $Root -TipSha $Tip -OriginUrl $Url -RemoteRef $Ref -ComposeOnly 2>&1
        $t34Code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    $t34Text = ((@($t34Out) | ForEach-Object { [string]$_ }) -join "`n")
    $t34Names = New-Object System.Collections.Generic.List[string]
    $t34Bodies = New-Object System.Collections.Generic.List[string]
    foreach ($m in @([regex]::Matches($t34Text, '(?m)^LAMCOMPOSE write (\S+) (\d+) (\S+)\s*$'))) {
        [void]$t34Names.Add([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($m.Groups[1].Value)))
        [void]$t34Bodies.Add([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($m.Groups[3].Value)))
    }
    return [pscustomobject]@{ out = $t34Text; code = $t34Code; names = @($t34Names.ToArray()); bodies = @($t34Bodies.ToArray()) }
}

try {
$t34Base   = Join-Path $env:TEMP ('lam-wp4-t34-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
$t34Root   = Join-Path $t34Base 'mission'
$t34Origin = Join-Path $t34Base 'origin-declared.git'
$t34Gates  = Join-Path $t34Root '.mission\gates'
New-Item -ItemType Directory -Path (Join-Path $t34Root '.mission') -Force | Out-Null

# ---- the declared origin: a local bare repository carrying one commit on refs/heads/main --------
New-Item -ItemType Directory -Path $t34Origin -Force | Out-Null
$null = Invoke-T34Git -GitArgs @('init', '--bare', '--quiet', '--initial-branch=main', $t34Origin)
$t34Work = Join-Path $t34Base 'seed-work'
New-Item -ItemType Directory -Path $t34Work -Force | Out-Null
$null = Invoke-T34Git -GitArgs @('init', '--quiet', '--initial-branch=main', $t34Work)
$t34WorkGd = (Invoke-T34Git -GitArgs @('-C', $t34Work, 'rev-parse', '--absolute-git-dir')).out.Trim()
$t34WorkOk = $t34WorkGd.Replace('/', '\').StartsWith(([System.IO.Path]::GetFullPath($t34Work)), [StringComparison]::OrdinalIgnoreCase)
Add-T34Row -Label 'seed work tree: its git dir resolves INSIDE the fixture before any git config' -Ok $t34WorkOk -Said $t34WorkGd
if ($t34WorkOk) {
    $null = Invoke-T34Git -GitArgs @('-C', $t34Work, 'config', 'user.email', 't34@example.invalid')
    $null = Invoke-T34Git -GitArgs @('-C', $t34Work, 'config', 'user.name', 'T34')
    Write-Utf8 -Path (Join-Path $t34Work 'seed.txt') -Text "t34`n"
    $null = Invoke-T34Git -GitArgs @('-C', $t34Work, 'add', '--', 'seed.txt')
    $null = Invoke-T34Git -GitArgs @('-C', $t34Work, 'commit', '--quiet', '-m', 'seed')
    $null = Invoke-T34Git -GitArgs @('-C', $t34Work, 'push', '--quiet', ($t34Origin -replace '\\', '/'), 'HEAD:refs/heads/main')
}
$t34OriginUrl = ($t34Origin -replace '\\', '/')
$t34Ls = Invoke-T34Git -GitArgs @('ls-remote', $t34OriginUrl, 'refs/heads/main')
$t34Tip = ''
$t34LsMatch = [regex]::Match($t34Ls.out, '(?m)^([0-9a-f]{40})\s')
if ($t34LsMatch.Success) { $t34Tip = $t34LsMatch.Groups[1].Value }
Add-T34Row -Label 'declared origin (local bare) advertises a 40-hex tip at refs/heads/main' -Ok ([bool]$t34Tip) -Said $t34Tip

# ---- the mission root whose gates the console will mint and settle ------------------------------
$null = Invoke-T34Git -GitArgs @('init', '--quiet', '--initial-branch=main', $t34Root)
$t34RootGd = (Invoke-T34Git -GitArgs @('-C', $t34Root, 'rev-parse', '--absolute-git-dir')).out.Trim()
$t34RootOk = $t34RootGd.Replace('/', '\').StartsWith(([System.IO.Path]::GetFullPath($t34Root)), [StringComparison]::OrdinalIgnoreCase)
Add-T34Row -Label 'mission root: its git dir resolves INSIDE the fixture before any git config' -Ok $t34RootOk -Said $t34RootGd
if ($t34RootOk) {
    $null = Invoke-T34Git -GitArgs @('-C', $t34Root, 'config', 'user.email', 't34@example.invalid')
    $null = Invoke-T34Git -GitArgs @('-C', $t34Root, 'config', 'user.name', 'T34')
    $null = Invoke-T34Git -GitArgs @('-C', $t34Root, 'remote', 'add', 'origin', $t34OriginUrl)
}
Write-Utf8 -Path (Join-Path $t34Root 'bound.txt') -Text "t34 bound`n"

function New-T34Gate {
    # A REAL gate, minted through the console's verified path with the injected seam.
    param([string]$Id)
    $spec = @{ Verb = 'approve'; Kind = 'push'; Id = $Id; Binds = 'bound.txt'; MissionRoot = $t34Root
               TipSha = $t34Tip; OriginUrl = $t34OriginUrl; RemoteRef = 'refs/heads/main'; ExpiresMinutes = '60' }
    $r = Invoke-GateConsoleLauncher -Spec $spec
    return [pscustomobject]@{ result = $r; path = (Join-Path $t34Gates ("push-$Id.yaml")) }
}
function Set-T34GateKind {
    # REWRITE THE ONE TOKEN, leaving every other byte the writer's. Returns the new text.
    param([string]$Path, [string]$KindToken)
    $t = [System.IO.File]::ReadAllText($Path)
    $t2 = [regex]::Replace($t, '(?m)^kind:[ \t]*push[ \t]*(\r?)$', ('kind: ' + $KindToken + '$1'))
    [System.IO.File]::WriteAllText($Path, $t2, (New-Object System.Text.UTF8Encoding($false)))
    return $t2
}
function Invoke-T34Settle {
    param([string]$Id)
    return (Invoke-GateConsoleLauncher -Spec @{ Verb = 'settle'; Kind = 'push'; Id = $Id; MissionRoot = $t34Root })
}

$t34Fields = @('consumed_at', 'consumed_origin_tip', 'consumed_ref', 'consumed_origin_before', 'consumed_basis')
# THE FOUR APPENDED ONES, SEPARATELY, AND THE SEPARATION IS THE WHOLE POINT. `consumed_at` is
# present on EVERY gate mission-gate mints, as the literal sentinel `consumed_at: null` -- so
# "no consumed_* field is present" is FALSE of an untouched gate and would make a refused settle
# look like a written one. It is the `(?!null)` trap lam-gate-class.ps1's header records, reached
# from the other side: there a naive reader called a fresh gate CONSUMED, here a naive assertion
# would call an untouched gate STAMPED. What a refused settle leaves behind is these four ABSENT
# and the sentinel still reading `null`, which is T-32's own spelling for the same property.
$t34Appended = @('consumed_origin_tip', 'consumed_ref', 'consumed_origin_before', 'consumed_basis')

# =================================================================================================
# (1) kind: PUSH and kind: Push -- settle REFUSES, and the artifact is BYTE-UNCHANGED
# =================================================================================================
$t34Cases = @(@{ id = 't34-upper'; token = 'PUSH' }, @{ id = 't34-title'; token = 'Push' })
$t34LowerText = ''
foreach ($t34c in $t34Cases) {
    $t34Id = [string]$t34c.id
    $t34Tok = [string]$t34c.token
    $t34G = New-T34Gate -Id $t34Id
    Add-T34Row -Label ("(1) {0}: a real push gate is minted through the console verified path" -f $t34Tok) `
        -Ok ((Test-Path -LiteralPath $t34G.path) -and ($t34G.result.exit -eq 0)) -Said ("exit " + $t34G.result.exit)
    $t34Rewritten = Set-T34GateKind -Path $t34G.path -KindToken $t34Tok
    Add-T34Row -Label ("(1) {0}: its face now reads 'kind: {0}', exactly one column-0 kind line" -f $t34Tok) `
        -Ok (($t34Rewritten -cmatch ('(?m)^kind: ' + $t34Tok + '\r?$')) -and ((Get-T34FieldCount -Text $t34Rewritten -Key 'kind') -eq 1)) `
        -Said ("one kind: line, token " + $t34Tok)
    $t34Before = Get-T34Stamp -Path $t34G.path
    $t34S = Invoke-T34Settle -Id $t34Id
    $t34After = Get-T34Stamp -Path $t34G.path
    $t34Text = [System.IO.File]::ReadAllText($t34G.path)
    Add-T34Row -Label ("(1) THE ROW: settle -Kind push against kind: {0} is REFUSED" -f $t34Tok) `
        -Ok (($t34S.exit -ne 0) -and (-not $t34S.minted)) -Said ("exit " + $t34S.exit + ", stage " + $t34S.stage)
    Add-T34Row -Label ("(1) {0}: the artifact is BYTE-UNCHANGED (sha256 AND length)" -f $t34Tok) `
        -Ok (($t34Before -cne 'ABSENT') -and ($t34After -ceq $t34Before)) -Said ($t34Before.Substring(0, [Math]::Min(22, $t34Before.Length)) + ' -> ' + $t34After.Substring(0, [Math]::Min(22, $t34After.Length)))
    Add-T34Row -Label ("(1) {0}: not one consumed_* field was APPENDED" -f $t34Tok) `
        -Ok ((@($t34Appended | Where-Object { (Get-T34FieldCount -Text $t34Text -Key $_) -ne 0 })).Count -eq 0) -Said 'no consume block'
    Add-T34Row -Label ("(1) {0}: the consumed_at: null SENTINEL is still the sentinel" -f $t34Tok) `
        -Ok ([bool]($t34Text -cmatch '(?m)^consumed_at:[ \t]*null[ \t]*\r?$')) -Said 'consumed_at: null'
    Add-T34Row -Label ("(1) {0}: and the shared state predicate still reports open" -f $t34Tok) `
        -Ok ((Get-LamGateState -Path $t34G.path).state -eq 'open') -Said (Get-LamGateState -Path $t34G.path).state
    Add-T34Row -Label ("(1) {0}: the refusal NAMES THE CASE on the tool's own face" -f $t34Tok) `
        -Ok ([bool]($t34S.out -cmatch 'CASE-SIGNIFICANT')) -Said (($t34S.out -replace '\s+', ' ').Substring(0, [Math]::Min(108, ($t34S.out -replace '\s+', ' ').Length)))
    if ($t34Tok -ceq 'PUSH') {
        # THE SUBSTITUTION WITNESS. The lowercase control below must be the SAME BYTES with the one
        # token changed back, and that is asserted, not assumed: a control that differed in some
        # other field would explain the different outcome all by itself.
        $t34LowerText = $t34Rewritten.Replace('kind: PUSH', 'kind: push')
    }
}

# =================================================================================================
# (2) THE LOWERCASE CONTROL -- the byte-identical artifact still SETTLES
# =================================================================================================
$t34L = New-T34Gate -Id 't34-lower'
$t34LText0 = [System.IO.File]::ReadAllText($t34L.path)
# The two gates differ in the fields a mint necessarily varies (id, created_at, digest), so the
# substitution witness is applied to the PUSH artifact's own bytes: changing that one token back
# must reproduce a text whose kind line is the canonical one and whose every other line is
# unchanged. That is the claim "one token apart" reduced to an assertion.
Add-T34Row -Label '(2) SUBSTITUTION WITNESS: the PUSH artifact with its token changed back is canonical' `
    -Ok (($t34LowerText -cmatch '(?m)^kind: push\r?$') -and ($t34LowerText -cnotmatch '(?m)^kind: PUSH\r?$')) -Said 'one token apart'
Add-T34Row -Label '(2) CONTROL the lowercase gate really declares kind: push' `
    -Ok ($t34LText0 -cmatch '(?m)^kind: push\r?$') -Said 'kind: push'
$t34LS = Invoke-T34Settle -Id 't34-lower'
$t34LText = [System.IO.File]::ReadAllText($t34L.path)
Add-T34Row -Label '(2) CONTROL it SETTLES -- exit 0, minted -- so the verb is not broken' `
    -Ok (($t34LS.exit -eq 0) -and $t34LS.minted) -Said ("exit " + $t34LS.exit + ", stage " + $t34LS.stage)
foreach ($t34F in $t34Fields) {
    $t34C = Get-T34FieldCount -Text $t34LText -Key $t34F
    Add-T34Row -Label ("(2) CONTROL {0} appears EXACTLY ONCE at column 0" -f $t34F) -Ok ($t34C -eq 1) -Said ("count " + $t34C)
}
Add-T34Row -Label '(2) CONTROL the shared state predicate now reports CONSUMED' `
    -Ok ((Get-LamGateState -Path $t34L.path).state -eq 'CONSUMED') -Said (Get-LamGateState -Path $t34L.path).state

# =================================================================================================
# (3) THE OTHER-KIND CONTROL -- refused for ITS OWN reason, not the case reason
# =================================================================================================
$t34D = New-T34Gate -Id 't34-disp'
$null = Set-T34GateKind -Path $t34D.path -KindToken 'dispatch'
$t34DBefore = Get-T34Stamp -Path $t34D.path
$t34DS = Invoke-T34Settle -Id 't34-disp'
$t34DAfter = Get-T34Stamp -Path $t34D.path
Add-T34Row -Label '(3) CONTROL settle -Kind push against kind: dispatch is refused' `
    -Ok (($t34DS.exit -ne 0) -and (-not $t34DS.minted)) -Said ("exit " + $t34DS.exit)
Add-T34Row -Label '(3) CONTROL that artifact is BYTE-UNCHANGED too' `
    -Ok (($t34DBefore -cne 'ABSENT') -and ($t34DAfter -ceq $t34DBefore)) -Said 'unchanged'
Add-T34Row -Label '(3) THE CONTROL THAT MATTERS: its refusal does NOT name the case' `
    -Ok (-not ($t34DS.out -cmatch 'CASE-SIGNIFICANT')) -Said (($t34DS.out -replace '\s+', ' ').Substring(0, [Math]::Min(108, ($t34DS.out -replace '\s+', ' ').Length)))

# =================================================================================================
# (4) THE MINT -- approve -Kind PUSH is refused at the SOURCE, and NOTHING is written
# =================================================================================================
# THE HIGHEST-VALUE ROW IN THIS MEMBER. Every row above answers what a consumer does with a
# non-canonical artifact; this one answers where such an artifact came from. mission-gate.ps1:1580
# classifies through the case-blind lookup and :1581 refuses only 'unknown', so `-Kind PUSH` was
# classified build-authorization and composed a literal `kind: PUSH` gate at `PUSH-<id>.yaml`.
$t34CoBad = Invoke-T34ComposeOnly -Kind 'PUSH' -Id 't34-co' -Root $t34Root -Tip $t34Tip -Url $t34OriginUrl -Ref 'refs/heads/main'
Add-T34Row -Label '(4) THE ROW: mission-gate approve -Kind PUSH -ComposeOnly exits 2 (refused)' `
    -Ok ($t34CoBad.code -eq 2) -Said ("exit " + $t34CoBad.code)
Add-T34Row -Label '(4) and it plans NO write at all -- no LAMCOMPOSE write line' `
    -Ok ($t34CoBad.names.Count -eq 0) -Said ("planned writes: " + $t34CoBad.names.Count + " " + (@($t34CoBad.names) -join ','))
Add-T34Row -Label '(4) the refusal names the case rather than an unrecognised kind' `
    -Ok ([bool]($t34CoBad.out -cmatch 'CASE-SIGNIFICANT')) -Said (($t34CoBad.out -replace '\s+', ' ').Substring(0, [Math]::Min(108, ($t34CoBad.out -replace '\s+', ' ').Length)))
$t34CoOk = Invoke-T34ComposeOnly -Kind 'push' -Id 't34-co' -Root $t34Root -Tip $t34Tip -Url $t34OriginUrl -Ref 'refs/heads/main'
Add-T34Row -Label '(4) CONTROL -Kind push -ComposeOnly still exits 0 and plans ONE write' `
    -Ok (($t34CoOk.code -eq 0) -and ($t34CoOk.names.Count -eq 1)) -Said ("exit " + $t34CoOk.code + ", writes " + $t34CoOk.names.Count)
$t34CoName = if ($t34CoOk.names.Count -ge 1) { [string]$t34CoOk.names[0] } else { '(none)' }
$t34CoBody = if ($t34CoOk.bodies.Count -ge 1) { [string]$t34CoOk.bodies[0] } else { '' }
Add-T34Row -Label '(4) CONTROL that planned write is push-t34-co.yaml carrying kind: push' `
    -Ok (($t34CoName -cmatch 'push-t34-co\.yaml$') -and ($t34CoBody -cmatch '(?m)^kind: push\r?$')) -Said $t34CoName

# THE REAL OPERATOR PATH, and "nothing was written" against a sha256 inventory of the WHOLE
# directory -- a refusal that wrote a differently-named file would pass a check that only asked
# about the path it expected.
$t34InvBefore = Get-T34GatesInventory -Dir $t34Gates
$t34MintBad = Invoke-GateConsoleLauncher -Spec @{ Verb = 'approve'; Kind = 'PUSH'; Id = 't34-mint'; Binds = 'bound.txt'
    MissionRoot = $t34Root; TipSha = $t34Tip; OriginUrl = $t34OriginUrl; RemoteRef = 'refs/heads/main'; ExpiresMinutes = '60' }
$t34InvAfter = Get-T34GatesInventory -Dir $t34Gates
Add-T34Row -Label '(4) THE ROW: console approve -Kind PUSH is REFUSED and mints nothing' `
    -Ok (($t34MintBad.exit -ne 0) -and (-not $t34MintBad.minted)) -Said ("exit " + $t34MintBad.exit + ", stage " + $t34MintBad.stage)
Add-T34Row -Label '(4) the gates directory is UNCHANGED -- every name and sha256 identical' `
    -Ok ($t34InvAfter -ceq $t34InvBefore) -Said ("entries " + (@($t34InvAfter -split ' ; ')).Count)
Add-T34Row -Label '(4) neither PUSH-t34-mint.yaml nor push-t34-mint.yaml exists' `
    -Ok ((-not (Test-Path -LiteralPath (Join-Path $t34Gates 'PUSH-t34-mint.yaml'))) -and (-not (Test-Path -LiteralPath (Join-Path $t34Gates 'push-t34-mint.yaml')))) `
    -Said 'nothing on disk under either spelling'
$t34MintOk = New-T34Gate -Id 't34-mintok'
Add-T34Row -Label '(4) CONTROL console approve -Kind push STILL MINTS -- the verb is not broken' `
    -Ok (($t34MintOk.result.exit -eq 0) -and (Test-Path -LiteralPath $t34MintOk.path)) -Said ("exit " + $t34MintOk.result.exit)
$t34MintOkText = if (Test-Path -LiteralPath $t34MintOk.path) { [System.IO.File]::ReadAllText($t34MintOk.path) } else { '' }
Add-T34Row -Label '(4) CONTROL and that minted gate declares kind: push, gate_class build-authorization' `
    -Ok (($t34MintOkText -cmatch '(?m)^kind: push\r?$') -and ($t34MintOkText -cmatch '(?m)^gate_class: build-authorization\r?$')) -Said 'kind: push / build-authorization'

try { Remove-Item -LiteralPath $t34Base -Recurse -Force -ErrorAction Stop } catch { }
}
catch {
    Add-T34Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
    try { Remove-Item -LiteralPath $t34Base -Recurse -Force -ErrorAction Stop } catch { }
}

Check -Id 'T-34' -Title 'the operator''s ruling answering round 2''s finding: A GATE KIND IS CASE-SIGNIFICANT, and mission-gate must say so at the MINT and at the SETTLE alike. $script:LamGateClassByKind is an [ordered]@{} whose .Contains() FOLDS CASE, so :1580 classified `approve -Kind PUSH` as build-authorization and minted a literal `kind: PUSH` artifact at PUSH-<id>.yaml ([ValidateSet] validates case-insensitively and does not normalise), and :1050 then compared the artifact''s face to -Kind with a folding -ne, so `settle -Kind push` against that artifact exited 0 and composed a full consume block. Driven hermetically against a local bare origin: settle against kind: PUSH and kind: Push is REFUSED with the artifact BYTE-UNCHANGED by sha256 AND length, not one of the four consumed_* fields APPENDED, the consumed_at: null sentinel still the sentinel (asserting all FIVE absent would be false of any untouched gate -- the same (?!null) trap from the other side) and the gate still open to the shared state predicate, the refusal NAMES THE CASE, and `approve -Kind PUSH` is refused at the SOURCE -- -ComposeOnly exits 2 planning no write at all, and the console path leaves every name and sha256 in the gates directory identical under either spelling of the filename. Every refusing row carries its control, because a cure that refused everything would pass a refuse-only member and break the verb: the byte-identical kind: push artifact still settles with the five consumed_* fields exactly once each, -Kind push -ComposeOnly still plans push-t34-co.yaml carrying kind: push, `approve -Kind push` still mints, and the kind: dispatch control is refused for its own reason without borrowing the case one' `
      -Ok $t34ok -Detail ($t34rows -join "`n")

# =================================================================================================
# T-35 -- THE SETTLE GUARDS ARE KEYED ON THE GATE, NOT ON ONE FIELD OF IT
#         (a round 3 finding; an earlier revision disclosed this and did NOT cure it)
# =================================================================================================
# THE DEFECT, MEASURED AT THE TIP BEFORE IT WAS CURED. Settling a push gate appends FIVE fields --
# consumed_at, consumed_origin_tip, consumed_ref, consumed_origin_before, consumed_basis. BOTH
# guards that exist to stop a SECOND consume block tested exactly ONE of them:
#   * mission-gate.ps1's settle asked `$gstate.consumed`, which is Get-LamGateState's consumed_at;
#   * Complete-EvidencePushGate asked `Test-EvidenceGateFieldSet -Text $t -Field 'consumed_at'`.
# So a gate carrying the FOUR APPENDED fields while consumed_at still reads the literal sentinel
# `null` answers BOTH predicates FALSE. Driven at zero mutation through `settle -ComposeOnly`: the
# tool exited 0 and composed TWO consume blocks under ONE consumed_at -- counts of consumed_at=1 and
# consumed_origin_tip / consumed_ref / consumed_origin_before / consumed_basis = 2 each. That is
# verbatim the harm T-33 cured on the hook side, arriving by a different door.
#
# THE EARLIER DISCLOSURE WAS WRONG ABOUT WHICH GUARD. It disclosed this as "the same field-vs-gate
# weakness this section calls 'the defect' in the hook's OLD guard", and declined to cure it on the
# stated ground that "curing it is a change to the console's settle path that no member currently
# drives". Both halves are refuted here: the SHIPPED hook guard carries the identical gap -- driven
# below, not reasoned about -- and this member drives the console path at zero mutation.
#
# NEITHER WRITER PRODUCES THE PRECONDITION, AND THAT IS NOT THE SAME AS UNREACHABLE. In both writers
# consumed_at is fixed BEFORE the other four are appended, and the mint writes `consumed_at: null`
# as the artifact's LAST line. So an unreachability member would assert something false: the
# precondition is plantable by other means, because `.mission/gates` is in no protected-path list
# and the admission's own refusal text instructs an operator to hand-ANNOTATE a gate artifact AT
# COLUMN 0. The fixtures below take a gate the real writer MINTED and append,
# which is that route reduced to an act.
#
# WHAT PASSES AT BOTH COMMITS, SAID HERE RATHER THAN LEFT TO BE NOTICED (round 2's finding was about
# prose claiming more than a member measured): rows (b), (c), (d) and (f) are CONTROLS and pass at
# the member commit AND at the cure commit BY DESIGN. Only (a), (e2) and the drift rows in (e1)
# separate the two. A cure that refused every settle would pass a refuse-only member and BREAK THE
# VERB, which is what the controls are for.
$t35ok = $true
$t35rows = New-Object System.Collections.Generic.List[string]
function Add-T35Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t35ok = $false }
    $script:t35rows.Add(('      {0,-88} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + $Said } else { '' })))
}
function Get-T35KeyCount {
    param([string]$Text, [string]$Key)
    return @([regex]::Matches([string]$Text, '(?m)^' + [regex]::Escape($Key) + ':')).Count
}
function Get-T35Stamp {
    # THE BYTE-UNCHANGED WITNESS, T-34's spelling verbatim: sha256 AND length together. A hash alone
    # answers "same content"; the length says so in a second currency, and an absent file reports
    # ABSENT rather than an empty string a later comparison would read as agreement.
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return 'ABSENT' }
    return ((Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash + '/' + (Get-Item -LiteralPath $Path).Length)
}
function Invoke-T35Git {
    # $ErrorActionPreference saved and restored around every native git call: under 'Stop' any native
    # exe writing to stderr is a fatal NativeCommandError and 2>$null does not help. Both locals are
    # seeded BEFORE the try -- StrictMode Latest is inherited -- and the code seeded NON-ZERO so a
    # git that failed to launch cannot inherit a stale success.
    param([string[]]$GitArgs)
    $gitOut = ''
    $gitCode = -1
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $gitOut = & git @GitArgs 2>&1
        $gitCode = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ out = ((@($gitOut) | ForEach-Object { [string]$_ }) -join "`n"); code = $gitCode }
}

$t35Fields = @('consumed_at', 'consumed_origin_tip', 'consumed_ref', 'consumed_origin_before', 'consumed_basis')
# THE FOUR APPENDED ONES, SEPARATELY. consumed_at is present on EVERY minted gate as the literal
# sentinel `consumed_at: null`, so "no consumed_* field is present" is FALSE of an untouched gate --
# the (?!null) trap reached from the other side, exactly as T-34 records it.
$t35Appended = @('consumed_origin_tip', 'consumed_ref', 'consumed_origin_before', 'consumed_basis')

try {
# THE FIXTURE LIVES UNDER $env:TEMP, NOT UNDER A DEEPER SCRATCH ROOT: a bare-repo push into a long
# path fails with "Filename too long" and the origin then advertises no tip at all, which would make
# every row below measure a broken fixture. T-33 records the same measurement at its own fixture.
$t35Base   = Join-Path $env:TEMP ('lam-wp4-t35-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
$t35Root   = Join-Path $t35Base 'mission'
$t35Origin = Join-Path $t35Base 'origin-declared.git'
$t35Gates  = Join-Path $t35Root '.mission\gates'
New-Item -ItemType Directory -Path (Join-Path $t35Root '.mission') -Force | Out-Null

# ---- the declared origin: a local bare repository carrying one commit on refs/heads/main --------
New-Item -ItemType Directory -Path $t35Origin -Force | Out-Null
$null = Invoke-T35Git -GitArgs @('init', '--bare', '--quiet', '--initial-branch=main', $t35Origin)
$t35Work = Join-Path $t35Base 'seed-work'
New-Item -ItemType Directory -Path $t35Work -Force | Out-Null
$null = Invoke-T35Git -GitArgs @('init', '--quiet', '--initial-branch=main', $t35Work)
$t35WorkGd = (Invoke-T35Git -GitArgs @('-C', $t35Work, 'rev-parse', '--absolute-git-dir')).out.Trim()
$t35WorkOk = $t35WorkGd.Replace('/', '\').StartsWith(([System.IO.Path]::GetFullPath($t35Work)), [StringComparison]::OrdinalIgnoreCase)
Add-T35Row -Label 'FIXTURE seed work tree: its git dir resolves INSIDE the fixture before any git config' -Ok $t35WorkOk -Said $t35WorkGd
if ($t35WorkOk) {
    $null = Invoke-T35Git -GitArgs @('-C', $t35Work, 'config', 'user.email', 't35@example.invalid')
    $null = Invoke-T35Git -GitArgs @('-C', $t35Work, 'config', 'user.name', 'T35')
    Write-Utf8 -Path (Join-Path $t35Work 'seed.txt') -Text "t35`n"
    $null = Invoke-T35Git -GitArgs @('-C', $t35Work, 'add', '--', 'seed.txt')
    $null = Invoke-T35Git -GitArgs @('-C', $t35Work, 'commit', '--quiet', '-m', 'seed')
    $null = Invoke-T35Git -GitArgs @('-C', $t35Work, 'push', '--quiet', ($t35Origin -replace '\\', '/'), 'HEAD:refs/heads/main')
}
# FORWARD SLASHES: a backslashed scratch remote URL in git config once broke a whole repository.
$t35OriginUrl = ($t35Origin -replace '\\', '/')
$t35Ls = Invoke-T35Git -GitArgs @('ls-remote', $t35OriginUrl, 'refs/heads/main')
$t35Tip = ''
$t35LsMatch = [regex]::Match($t35Ls.out, '(?m)^([0-9a-f]{40})\s')
if ($t35LsMatch.Success) { $t35Tip = $t35LsMatch.Groups[1].Value }
Add-T35Row -Label 'FIXTURE the declared origin (local bare) advertises a 40-hex tip at refs/heads/main' -Ok ([bool]$t35Tip) -Said $t35Tip

# ---- the mission root whose gates the console mints ---------------------------------------------
$null = Invoke-T35Git -GitArgs @('init', '--quiet', '--initial-branch=main', $t35Root)
$t35RootGd = (Invoke-T35Git -GitArgs @('-C', $t35Root, 'rev-parse', '--absolute-git-dir')).out.Trim()
$t35RootOk = $t35RootGd.Replace('/', '\').StartsWith(([System.IO.Path]::GetFullPath($t35Root)), [StringComparison]::OrdinalIgnoreCase)
Add-T35Row -Label 'FIXTURE mission root: its git dir resolves INSIDE the fixture before any git config' -Ok $t35RootOk -Said $t35RootGd
if ($t35RootOk) {
    $null = Invoke-T35Git -GitArgs @('-C', $t35Root, 'config', 'user.email', 't35@example.invalid')
    $null = Invoke-T35Git -GitArgs @('-C', $t35Root, 'config', 'user.name', 'T35')
    $null = Invoke-T35Git -GitArgs @('-C', $t35Root, 'remote', 'add', 'origin', $t35OriginUrl)
}
Write-Utf8 -Path (Join-Path $t35Root 'bound.txt') -Text "t35 bound`n"

function New-T35Gate {
    # A REAL gate, minted through the console's verified path with the injected seam -- never
    # hand-rolled. lam-gate-class.ps1's header records that a fixture which merely OMITS a field
    # takes a different branch and makes a broken predicate look correct, and the field this member
    # is about is the `consumed_at: null` sentinel itself.
    param([string]$Id)
    $spec = @{ Verb = 'approve'; Kind = 'push'; Id = $Id; Binds = 'bound.txt'; MissionRoot = $t35Root
               TipSha = $t35Tip; OriginUrl = $t35OriginUrl; RemoteRef = 'refs/heads/main'; ExpiresMinutes = '60' }
    $r = Invoke-GateConsoleLauncher -Spec $spec
    return [pscustomobject]@{ result = $r; path = (Join-Path $t35Gates ("push-$Id.yaml")) }
}
function Invoke-T35SettleCompose {
    # mission-gate.ps1 DIRECTLY, in a child process, with -ComposeOnly -- which runs every refusal
    # and composition step and WRITES NOTHING, needs no console token, and does not run the four
    # operator session conditions. That is what makes this member ZERO-MUTATION and drivable from a
    # harness session at all, and it is why the planned write is legible as a PLAN rather than as an
    # absence on disk.
    param([string]$Id)
    $t35Out = ''
    $t35Code = -1
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $t35Out = & powershell -NoProfile -ExecutionPolicy Bypass -File $gateTool settle -Kind push -Id $Id `
                     -MissionRoot $t35Root -ComposeOnly 2>&1
        $t35Code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    $t35Text = ((@($t35Out) | ForEach-Object { [string]$_ }) -join "`n")
    $t35Names = New-Object System.Collections.Generic.List[string]
    $t35Bodies = New-Object System.Collections.Generic.List[string]
    foreach ($m in @([regex]::Matches($t35Text, '(?m)^LAMCOMPOSE write (\S+) (\d+) (\S+)\s*$'))) {
        [void]$t35Names.Add([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($m.Groups[1].Value)))
        [void]$t35Bodies.Add([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($m.Groups[3].Value)))
    }
    return [pscustomobject]@{ out = $t35Text; code = $t35Code; names = @($t35Names.ToArray()); bodies = @($t35Bodies.ToArray()) }
}

# =================================================================================================
# THE THREE ARTIFACTS. One template -- the console's own writer -- three states.
# =================================================================================================
$t35P = New-T35Gate -Id 't35-plant'
$t35O = New-T35Gate -Id 't35-open'
$t35S = New-T35Gate -Id 't35-spent'
Add-T35Row -Label 'FIXTURE three push gates minted through the console verified path' `
    -Ok (($t35P.result.exit -eq 0) -and ($t35O.result.exit -eq 0) -and ($t35S.result.exit -eq 0) -and
         (Test-Path -LiteralPath $t35P.path) -and (Test-Path -LiteralPath $t35O.path) -and (Test-Path -LiteralPath $t35S.path)) `
    -Said ('exits ' + $t35P.result.exit + '/' + $t35O.result.exit + '/' + $t35S.result.exit)

# THE PLANT. A gate the real writer produced, plus the FOUR appended fields and nothing else. The
# consumed_at sentinel is left exactly as minted, which is the whole shape of the finding.
$t35PlantText = [System.IO.File]::ReadAllText($t35P.path)
$t35PlantText = $t35PlantText.TrimEnd() + "`r`nconsumed_origin_tip: $t35Tip" +
                                          "`r`nconsumed_ref: refs/heads/main" +
                                          "`r`nconsumed_origin_before: 1111111111111111111111111111111111111111" +
                                          "`r`nconsumed_basis: planted by T-35 -- four appended fields, consumed_at untouched`r`n"
[System.IO.File]::WriteAllText($t35P.path, $t35PlantText, (New-Object System.Text.UTF8Encoding($false)))

# THE SPEND. The same writer's artifact with a REAL consumed_at timestamp replacing the sentinel and
# nothing else -- so the genuinely-consumed refusal is measured against a gate that differs from the
# planted one in exactly the field the old guard read.
$t35SpentStamp = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture)
$t35SpentText = [regex]::Replace([System.IO.File]::ReadAllText($t35S.path), '(?m)^consumed_at:[^\r\n]*', "consumed_at: $t35SpentStamp")
[System.IO.File]::WriteAllText($t35S.path, $t35SpentText, (New-Object System.Text.UTF8Encoding($false)))

$t35OpenText = [System.IO.File]::ReadAllText($t35O.path)
Add-T35Row -Label 'FIXTURE the PLANTED gate carries the four appended fields with consumed_at STILL null' `
    -Ok (((@($t35Appended | Where-Object { (Get-T35KeyCount -Text $t35PlantText -Key $_) -ne 1 })).Count -eq 0) -and
         ($t35PlantText -cmatch '(?m)^consumed_at:[ \t]*null[ \t]*\r?$')) -Said 'four appended, consumed_at: null'
Add-T35Row -Label 'FIXTURE the OPEN gate carries the sentinel and NO appended field' `
    -Ok (((@($t35Appended | Where-Object { (Get-T35KeyCount -Text $t35OpenText -Key $_) -ne 0 })).Count -eq 0) -and
         ($t35OpenText -cmatch '(?m)^consumed_at:[ \t]*null[ \t]*\r?$')) -Said 'sentinel only'
Add-T35Row -Label 'FIXTURE the SPENT gate carries a REAL consumed_at and no appended field' `
    -Ok (((@($t35Appended | Where-Object { (Get-T35KeyCount -Text $t35SpentText -Key $_) -ne 0 })).Count -eq 0) -and
         ($t35SpentText -cmatch ('(?m)^consumed_at:[ \t]*' + [regex]::Escape($t35SpentStamp)))) -Said $t35SpentStamp

# THE BYTE WITNESS, TAKEN BEFORE THE FIRST SETTLE. Every console row below is -ComposeOnly, which
# writes nothing at all, so "the artifacts did not move" is a statement about the whole run.
$t35BeforeP = Get-T35Stamp -Path $t35P.path
$t35BeforeO = Get-T35Stamp -Path $t35O.path
$t35BeforeS = Get-T35Stamp -Path $t35S.path

# =================================================================================================
# (a) THE ROW -- settle against the PLANTED gate REFUSES, and plans no write at all
# =================================================================================================
$t35RunP = Invoke-T35SettleCompose -Id 't35-plant'
$t35PlanP = if ($t35RunP.bodies.Count -ge 1) { [string]$t35RunP.bodies[0] } else { '' }
$t35CountsP = @($t35Fields | ForEach-Object { $_ + '=' + (Get-T35KeyCount -Text $t35PlanP -Key $_) })
Add-T35Row -Label '(a) THE ROW: settle -ComposeOnly against the PLANTED gate exits 2 (refused)' `
    -Ok ($t35RunP.code -eq 2) -Said ('exit ' + $t35RunP.code)
Add-T35Row -Label '(a) THE ROW: it plans ZERO writes -- no LAMCOMPOSE write line at all' `
    -Ok ($t35RunP.names.Count -eq 0) -Said ('planned writes ' + $t35RunP.names.Count + '; composed field counts ' + ($t35CountsP -join ' '))
Add-T35Row -Label '(a) the refusal NAMES the consume-block fields already present' `
    -Ok (($t35RunP.out -cmatch 'consume-block fields already present') -and
         ((@($t35Appended | Where-Object { $t35RunP.out -cmatch [regex]::Escape($_) })).Count -eq 4)) `
    -Said (($t35RunP.out -replace '\s+', ' ').Substring(0, [Math]::Min(150, ($t35RunP.out -replace '\s+', ' ').Length)))
Add-T35Row -Label '(a) and it does NOT tell the operator the gate is ALREADY CONSUMED (its consumed_at reads null)' `
    -Ok (-not ($t35RunP.out -cmatch 'is ALREADY CONSUMED')) `
    -Said 'a stamp that is not there must not be named as one'

# =================================================================================================
# (b) POSITIVE CONTROL -- an ordinary open gate still settles, five fields exactly once each
# =================================================================================================
# WITHOUT THIS ROW THE MEMBER IS SATISFIED BY A GUARD THAT REFUSES EVERY SETTLE, which would break
# the verb the cure is supposed to leave alone.
$t35RunO = Invoke-T35SettleCompose -Id 't35-open'
$t35PlanO = if ($t35RunO.bodies.Count -ge 1) { [string]$t35RunO.bodies[0] } else { '' }
Add-T35Row -Label '(b) CONTROL settle -ComposeOnly against the OPEN gate exits 0 and plans EXACTLY ONE write' `
    -Ok (($t35RunO.code -eq 0) -and ($t35RunO.names.Count -eq 1)) -Said ('exit ' + $t35RunO.code + ', writes ' + $t35RunO.names.Count)
Add-T35Row -Label '(b) CONTROL that planned write is push-t35-open.yaml' `
    -Ok ((@($t35RunO.names | Where-Object { $_ -cmatch 'push-t35-open\.yaml$' })).Count -eq 1) `
    -Said (@($t35RunO.names) -join ',')
foreach ($t35F in $t35Fields) {
    $t35C = Get-T35KeyCount -Text $t35PlanO -Key $t35F
    Add-T35Row -Label ("(b) CONTROL the composed bytes carry {0} EXACTLY ONCE at column 0" -f $t35F) -Ok ($t35C -eq 1) -Said ('count ' + $t35C)
}

# =================================================================================================
# (c) NEGATIVE CONTROL -- a genuinely consumed gate still refuses with the first-stamp-wins wording
# =================================================================================================
# The widening must not REPLACE the refusal that already existed: an operator meeting a real
# consumed_at must still be told that one, in the ruling's own words.
$t35RunS = Invoke-T35SettleCompose -Id 't35-spent'
Add-T35Row -Label '(c) CONTROL settle against the genuinely CONSUMED gate exits 2 and plans no write' `
    -Ok (($t35RunS.code -eq 2) -and ($t35RunS.names.Count -eq 0)) -Said ('exit ' + $t35RunS.code + ', writes ' + $t35RunS.names.Count)
Add-T35Row -Label '(c) CONTROL and its refusal keeps the FIRST STAMP WINS wording verbatim' `
    -Ok (($t35RunS.out -cmatch 'is ALREADY CONSUMED') -and ($t35RunS.out -cmatch 'first stamp wins')) `
    -Said (($t35RunS.out -replace '\s+', ' ').Substring(0, [Math]::Min(130, ($t35RunS.out -replace '\s+', ' ').Length)))

# =================================================================================================
# (d) INVERTED CONTROL -- THIS ROW VOIDS THE RUN IF IT FIRES
# =================================================================================================
# If the widened predicate reported OPEN gates as consumed, row (b) would fail and this row says in
# WHICH DIRECTION it broke. `consumed` must keep its exact meaning: every other consumer of
# Get-LamGateState -- mission-dispatch, mission-goal-check, mission-reclose, mission-gate's list,
# revoke and reapprove, instrument-WP-6 -- reads it, and the cure is required to be ADDITIVE.
$t35StateO = Get-LamGateState -Path $t35O.path
Add-T35Row -Label '(d) INVERTED CONTROL the OPEN gate still reports state=open' `
    -Ok ($t35StateO.state -eq 'open') -Said ('state ' + $t35StateO.state)
Add-T35Row -Label '(d) INVERTED CONTROL and consumed=False -- `consumed` did not change meaning' `
    -Ok (-not [bool]$t35StateO.consumed) -Said ('consumed ' + [bool]$t35StateO.consumed)
$t35StateS = Get-LamGateState -Path $t35S.path
Add-T35Row -Label '(d) INVERTED CONTROL the SPENT gate still reports state=CONSUMED' `
    -Ok ($t35StateS.state -eq 'CONSUMED') -Said ('state ' + $t35StateS.state)
$t35StateP = Get-LamGateState -Path $t35P.path
Add-T35Row -Label '(d) INVERTED CONTROL the PLANTED gate is NOT reported CONSUMED by the state predicate' `
    -Ok ((-not [bool]$t35StateP.consumed) -and ($t35StateP.state -eq 'open')) `
    -Said ('state ' + $t35StateP.state + ', consumed ' + [bool]$t35StateP.consumed)

# =================================================================================================
# (f) BYTE CONTROL -- nothing moved, over the whole console half of this member
# =================================================================================================
Add-T35Row -Label '(f) BYTE CONTROL all three artifacts unchanged by sha256 AND length across every run' `
    -Ok (($t35BeforeP -cne 'ABSENT') -and ((Get-T35Stamp -Path $t35P.path) -ceq $t35BeforeP) -and
         ((Get-T35Stamp -Path $t35O.path) -ceq $t35BeforeO) -and ((Get-T35Stamp -Path $t35S.path) -ceq $t35BeforeS)) `
    -Said 'three artifacts, sha256/length identical'

# =================================================================================================
# (e1) THE DRIFT TEST -- both consume-block readers over the SAME three texts (E113's price)
# =================================================================================================
# tools/lam must not dot-source the hooks library, and the hooks tree installs ALONE into a
# repository that need not contain tools/lam (LAM-INSTALL section 2), so the list of consume-block
# fields necessarily exists twice. E113 prices a disclosed duplication at a drift-detecting TEST.
# T-14 pays it for the three STATE fields and WP-1's H-21 for `kind`; the consume block was in
# neither list, and that gap is these rows.
$t35HaveLam  = [bool](Get-Command 'Get-LamGateConsumeBlock' -ErrorAction SilentlyContinue)
$t35HaveHook = [bool](Get-Command 'Get-EvidenceGateConsumeBlock' -ErrorAction SilentlyContinue)
Add-T35Row -Label '(e1) both consume-block readers are DEFINED -- one per tree' `
    -Ok ($t35HaveLam -and $t35HaveHook) -Said ('lam=' + $t35HaveLam + ' hook=' + $t35HaveHook)
$t35Texts = @(@{ n = 'PLANTED (four appended, consumed_at null)'; t = $t35PlantText; want = $true },
              @{ n = 'OPEN (sentinel only)                    '; t = $t35OpenText;  want = $false },
              @{ n = 'SPENT (real consumed_at)                '; t = $t35SpentText; want = $true })
foreach ($t35Case in $t35Texts) {
    $t35LamAny = '__ABSENT__'
    $t35LamJoin = '__ABSENT__'
    if ($t35HaveLam) {
        $t35LamR = Get-LamGateConsumeBlock -Text ([string]$t35Case.t)
        $t35LamAny = [string][bool]$t35LamR.any
        $t35LamJoin = [string]$t35LamR.joined
    }
    $t35HookAny = '__ABSENT__'
    $t35HookJoin = '__ABSENT__'
    if ($t35HaveHook) {
        $t35HookR = Get-EvidenceGateConsumeBlock -Text ([string]$t35Case.t)
        $t35HookAny = [string][bool]$t35HookR.any
        $t35HookJoin = [string]$t35HookR.joined
    }
    Add-T35Row -Label ('(e1) {0} -- the two readers AGREE, on any AND on the field list' -f $t35Case.n) `
        -Ok ($t35HaveLam -and $t35HaveHook -and ($t35LamAny -ceq $t35HookAny) -and ($t35LamJoin -ceq $t35HookJoin)) `
        -Said ('lam any=' + $t35LamAny + ' [' + $t35LamJoin + ']  hook any=' + $t35HookAny + ' [' + $t35HookJoin + ']')
    Add-T35Row -Label ('(e1) {0} -- and the verdict is the expected one' -f $t35Case.n) `
        -Ok ($t35HaveLam -and ($t35LamAny -ceq ([string][bool]$t35Case.want))) `
        -Said ('expected ' + [bool]$t35Case.want + ', got ' + $t35LamAny)
}
# THE OLD PREDICATE IS DRIVEN TOO, so the rows above are a MEASUREMENT of the gap rather than a
# claim about it: Test-EvidenceGateFieldSet on consumed_at answers FALSE for the planted text, which
# is exactly why both guards let it through.
Add-T35Row -Label '(e1) THE GAP ITSELF: the OLD one-field predicate answers consumed_at SET = False for the PLANTED text' `
    -Ok (-not (Test-EvidenceGateFieldSet -Text $t35PlantText -Field 'consumed_at')) `
    -Said 'one field of five is a guard against one fifth of the shape it names'

# =================================================================================================
# (e2) THE HOOK HALF, DRIVEN -- Complete-EvidencePushGate over a PLANTED gate
# =================================================================================================
# NOT A TEXT COMPARISON: the function the installed PostToolUse settle actually runs, over its own
# fixture, with a local bare origin and no network. This is also where the LOOP DEPTH is asserted
# rather than reasoned about -- the guard sits inside `foreach ($sv in $settle)`, and a cure that
# looped over the five field names with a bare `continue` would continue the INNER loop and FALL
# THROUGH TO THE WRITE. If that happened the planted gate would MOVE, and the byte row below says so.
$t35HookRoot = Join-Path $t35Base 'hookmission'
$t35HookGates = Join-Path $t35HookRoot '.mission\gates'
New-Item -ItemType Directory -Path $t35HookGates -Force | Out-Null
# THE RESOLVER IS ASKED, AND ITS ANSWER IS ASSERTED TO BE MINE (H-21's containment rule).
# Get-EvidenceGatesDir falls through to `git worktree list` when the directory is ABSENT, so an
# unasserted call could hand back some OTHER repository's real gates directory and this member would
# write fixtures into it. The directory is created FIRST so the resolver takes its direct branch.
$t35HookResolved = Get-EvidenceGatesDir -Root $t35HookRoot
Add-T35Row -Label '(e2) FIXTURE CONTAINMENT: the hook resolver answers THIS fixture gates directory' `
    -Ok (($t35HookResolved.Replace('\', '/').TrimEnd('/')) -eq ($t35HookGates.Replace('\', '/').TrimEnd('/'))) `
    -Said $t35HookResolved
function New-T35HookGate {
    # The hook half writes its own fixtures the way T-33 does: a gate carrying exactly the shape the
    # real writer produces, INCLUDING the consumed_at: null sentinel, because the (?!null) branch is
    # only exercised by a gate that actually carries the line.
    param([string]$Name, [string]$Extra)
    $t35Now = (Get-Date).ToUniversalTime()
    $t35HGate = Join-Path $t35HookGates $Name
    $t35HText = "kind: push`r`ngate_class: build-authorization`r`nid: $([System.IO.Path]::GetFileNameWithoutExtension($Name))`r`n" +
                "authorized_tip_sha: $t35Tip`r`norigin_url: $t35OriginUrl`r`nremote_ref: refs/heads/main`r`n" +
                "created_at: $($t35Now.ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture))`r`n" +
                "expires_at: $($t35Now.AddHours(4).ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture))`r`n" +
                "single_use: true`r`nconsumed_at: null`r`n" + $Extra
    [System.IO.File]::WriteAllText($t35HGate, $t35HText, (New-Object System.Text.UTF8Encoding($false)))
    return $t35HGate
}
# THE PLANTED GATE IS ALONE IN THIS DIRECTORY WHILE (e2) RUNS, AND THAT IS LOAD-BEARING RATHER THAN
# TIDY. Get-EvidencePushGateForSha SELECTS by scanning push-*.yaml and returning the FIRST match --
# the entry's own gate_path is not what the write loop is handed. With the (e3) control gate already
# on disk, `push-t35-hookopen.yaml` sorts before `push-t35-hookplant.yaml` and would be selected
# instead, leaving the planted gate byte-unchanged FOR THE WRONG REASON: row (e2) would have read
# green at both commits while measuring nothing. The control gate is therefore created in (e3).
$t35HookPlanted = New-T35HookGate -Name 'push-t35-hookplant.yaml' `
    -Extra ("consumed_origin_tip: $t35Tip`r`nconsumed_ref: refs/heads/main`r`n" +
            "consumed_origin_before: 1111111111111111111111111111111111111111`r`n" +
            "consumed_basis: planted by T-35 -- four appended fields, consumed_at untouched`r`n")
Add-T35Row -Label '(e2) FIXTURE the planted gate is the ONLY push-*.yaml the scan can select' `
    -Ok ((@(Get-ChildItem -LiteralPath $t35HookGates -File -Filter 'push-*.yaml' -ErrorAction SilentlyContinue)).Count -eq 1) `
    -Said ('push-*.yaml in the hook gates dir: ' + (@(Get-ChildItem -LiteralPath $t35HookGates -File -Filter 'push-*.yaml' -ErrorAction SilentlyContinue)).Count)
function New-T35HookEntry {
    # remote_sha_before must DIFFER from the observed tip, or the selection classes the push as
    # having published nothing and the entry never reaches the write loop at all -- the row would
    # then be measuring that branch instead of the one under test (T-33 records the same trap).
    param([string]$GatePath)
    return [pscustomobject]@{
        gate_path = $GatePath; authorized_sha = $t35Tip; remote_ref = 'refs/heads/main'
        remote_sha_before = '1111111111111111111111111111111111111111'
    }
}
$t35HookPlantBefore = Get-T35Stamp -Path $t35HookPlanted
$null = Clear-EvidencePushInFlight -Root $t35HookRoot
$null = Write-EvidencePushInFlight -Root $t35HookRoot -Remote 'origin' -RemoteUrl $t35OriginUrl -Entries @((New-T35HookEntry -GatePath $t35HookPlanted))
$t35HookRes = Complete-EvidencePushGate -Root $t35HookRoot
$t35HookPlantAfter = Get-T35Stamp -Path $t35HookPlanted
$t35HookPlantText = [System.IO.File]::ReadAllText($t35HookPlanted)
$t35HookReason = (([string]$t35HookRes.reason) -replace '\s+', ' ')
Add-T35Row -Label '(e2) THE ROW: the HOOK settle leaves the PLANTED gate BYTE-UNCHANGED (sha256 AND length)' `
    -Ok (($t35HookPlantBefore -cne 'ABSENT') -and ($t35HookPlantAfter -ceq $t35HookPlantBefore)) `
    -Said ($t35HookPlantBefore + ' -> ' + $t35HookPlantAfter)
Add-T35Row -Label '(e2) THE ROW: no second consume block -- each appended field still appears exactly once' `
    -Ok ((@($t35Appended | Where-Object { (Get-T35KeyCount -Text $t35HookPlantText -Key $_) -ne 1 })).Count -eq 0) `
    -Said (@($t35Appended | ForEach-Object { $_ + '=' + (Get-T35KeyCount -Text $t35HookPlantText -Key $_) }) -join ' ')
Add-T35Row -Label '(e2) THE ROW: and the sentinel was not stamped -- consumed_at still reads null' `
    -Ok ([bool]($t35HookPlantText -cmatch '(?m)^consumed_at:[ \t]*null[ \t]*\r?$')) -Said 'consumed_at: null'
Add-T35Row -Label '(e2) the hook settle consumes NOTHING and says which fields it found' `
    -Ok ((-not $t35HookRes.consumed) -and ($t35HookReason -cmatch 'ALREADY CARRIES part of a consume block')) `
    -Said $t35HookReason.Substring(0, [Math]::Min(150, $t35HookReason.Length))

# =================================================================================================
# (e3) THE HOOK CONTROL -- an ordinary open gate is still consumed, five fields once each
# =================================================================================================
# CREATED HERE, NOT BESIDE THE PLANTED ONE, for the selection reason recorded above (e2). It sorts
# BEFORE the planted gate, so the scan reaches it first and this control cannot accidentally be
# measuring the planted artifact.
$t35HookOpen = New-T35HookGate -Name 'push-t35-hookopen.yaml' -Extra ''
$null = Clear-EvidencePushInFlight -Root $t35HookRoot
$null = Write-EvidencePushInFlight -Root $t35HookRoot -Remote 'origin' -RemoteUrl $t35OriginUrl -Entries @((New-T35HookEntry -GatePath $t35HookOpen))
$t35HookRes2 = Complete-EvidencePushGate -Root $t35HookRoot
$t35HookOpenText = [System.IO.File]::ReadAllText($t35HookOpen)
Add-T35Row -Label '(e3) CONTROL the hook settle still CONSUMES an ordinary open gate' `
    -Ok ([bool]$t35HookRes2.consumed) -Said ((([string]$t35HookRes2.reason) -replace '\s+', ' ').Substring(0, [Math]::Min(110, ((([string]$t35HookRes2.reason) -replace '\s+', ' ')).Length)))
Add-T35Row -Label '(e3) CONTROL and it writes all five consumed_* fields EXACTLY ONCE' `
    -Ok ((@($t35Fields | Where-Object { (Get-T35KeyCount -Text $t35HookOpenText -Key $_) -ne 1 })).Count -eq 0) `
    -Said (@($t35Fields | ForEach-Object { $_ + '=' + (Get-T35KeyCount -Text $t35HookOpenText -Key $_) }) -join ' ')

try { Remove-Item -LiteralPath $t35Base -Recurse -Force -ErrorAction Stop } catch { }
}
catch {
    Add-T35Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
    try { Remove-Item -LiteralPath $t35Base -Recurse -Force -ErrorAction Stop } catch { }
}

Check -Id 'T-35' -Title 'a round 3 finding, which amendment 51 section 7 disclosed and did NOT cure: the settle guards on BOTH sides were keyed on ONE FIELD, consumed_at, while a settle appends FIVE. A gate carrying the four appended consumed_* fields with consumed_at still reading the literal null sentinel answers both predicates FALSE, so mission-gate settle -ComposeOnly exited 0 and composed TWO consume blocks under ONE consumed_at (counts 1 / 2 / 2 / 2 / 2), and Complete-EvidencePushGate -- the SHIPPED hook guard, not the old one section 7 blames -- proceeded and appended over the same shape. Neither writer produces the precondition (consumed_at is fixed before the other four, and the mint writes consumed_at: null as the artifact''s LAST line), so this is not an unreachability claim: .mission/gates is in no protected-path list and the admission''s own refusal text instructs an operator to hand-ANNOTATE a gate AT COLUMN 0, which is the route the fixtures take. Driven hermetically against a local bare origin: the console half at ZERO MUTATION through -ComposeOnly (planted gate exits 2, plans no write at all, and the refusal NAMES the fields present rather than calling a null consumed_at "already consumed"), the hook half through the real Complete-EvidencePushGate (planted gate byte-unchanged by sha256 AND length, no second block, sentinel unstamped) and the two consume-block readers compared over the SAME three texts, which is E113''s price for a duplication T-14''s field list and H-21''s kind test both missed. Every refusing row carries its control and those controls pass at BOTH commits by design: the ordinary open gate still settles with the five fields exactly once each on both sides, a genuinely consumed gate still refuses in the ruling''s own first-stamp-wins words, and the inverted control asserts Get-LamGateState''s `consumed` did not change meaning for the eight consumers that read it' `
      -Ok $t35ok -Detail ($t35rows -join "`n")

# =================================================================================================
# T-36 -- NO SECOND WRITER STAMPS A DISPATCH GATE (operator ruling (i), candidate C5;
#         B-3 of WP-B)
# =================================================================================================
# THE QUESTION: first stamp wins for dispatch gates on ANY second writer that exists. Besides the
# runner, two writers of a consume block exist -- mission-gate.ps1's settle (the console's stamping
# instrument) and Complete-EvidencePushGate (the in-session PostToolUse settle). This member DRIVES
# both at a dispatch gate the runner's own writer consumed, and at the same bytes under a push-*.yaml
# name so a filename is not what protects it; the hook half carries a control in which the identical
# artifact spelled `kind: push` IS consumed, so its refusal is about the gate's kind and not a hook
# that writes nothing. The second RUNNER is WP-2's R-D.
#
# THE CENSUS MAKES "TWO" A FIGURE. Every tracked .ps1/.psm1/.psd1/.py outside tests/lam/ (the
# instruments write fixture gates by design) is read; a PowerShell file counts as a writer when a
# STRING token it carries puts a consume-block key at COLUMN 0 of a line -- where a gate's top-level
# key sits, and where a nested record's key (the runner's anchors block, the origin-attestation
# anchor) does not. A Python file counts when a string literal opens with such a key. The census is
# put to four planted texts first: a column-0 composition is counted; an indented one, a display line
# with padding before its colon, and a comment are not.
$t36ok = $true
$t36rows = New-Object System.Collections.Generic.List[string]
function Add-T36Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t36ok = $false }
    $script:t36rows.Add(('      {0,-86} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function Get-T36Sha {
    param([string]$P)
    if (-not (Test-Path -LiteralPath $P)) { return '(absent)' }
    return (Get-FileHash -Algorithm SHA256 -LiteralPath $P).Hash.ToLowerInvariant()
}
function Get-T36Len {
    param([string]$P)
    if (-not (Test-Path -LiteralPath $P)) { return -1 }
    return [int](Get-Item -LiteralPath $P).Length
}
function Invoke-T36Git {
    param([string[]]$GitArgs)
    $gitOut = ''
    $gitCode = -1
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $gitOut = & git @GitArgs 2>&1
        $gitCode = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ out = ((@($gitOut) | ForEach-Object { [string]$_ }) -join "`n"); code = $gitCode }
}
# THE CENSUS OVER ONE TEXT. Returns the consume-block keys the text composes at column 0.
function Get-T36WriterKeys {
    param([string]$Name, [string]$Text)
    $keys = New-Object System.Collections.Generic.List[string]
    if ($Text -notmatch 'consumed_') { return @() }
    if ($Name -match '\.py$') {
        foreach ($m in [regex]::Matches($Text, '(?:["'']|\\n)(consumed_[a-z0-9_]+):')) { [void]$keys.Add($m.Groups[1].Value) }
        return @($keys.ToArray())
    }
    $perr = $null
    $toks = [System.Management.Automation.PSParser]::Tokenize($Text, [ref]$perr)
    foreach ($tk in $toks) {
        if ([string]$tk.Type -ne 'String') { continue }
        foreach ($m in [regex]::Matches([string]$tk.Content, '(?:^|[\r\n])(consumed_[a-z0-9_]+):')) { [void]$keys.Add($m.Groups[1].Value) }
    }
    return @($keys.ToArray())
}

try {
# ---- THE CENSUS's OWN CONTROLS -------------------------------------------------------------------
$t36c1 = @(Get-T36WriterKeys -Name 'x.ps1' -Text ('$b = $b + "`r`nconsumed_spawns: " + $v' + "`n"))
$t36c2 = @(Get-T36WriterKeys -Name 'x.ps1' -Text ('$b = "  consumed_at: " + $v' + "`n"))
$t36c3 = @(Get-T36WriterKeys -Name 'x.ps1' -Text ('Write-Output "  consumed_at            : $v"' + "`n"))
$t36c4 = @(Get-T36WriterKeys -Name 'x.ps1' -Text ('# consumed_at: this comment writes nothing' + "`n"))
Add-T36Row -Label 'CENSUS CONTROL a planted column-0 composition is counted' -Ok (($t36c1 -join ',') -ceq 'consumed_spawns') -Said ('keys [' + ($t36c1 -join ',') + ']')
Add-T36Row -Label 'CENSUS CONTROL an indented key, a padded display line and a comment are not' -Ok (($t36c2.Count -eq 0) -and ($t36c3.Count -eq 0) -and ($t36c4.Count -eq 0)) `
    -Said ('counts ' + $t36c2.Count + '/' + $t36c3.Count + '/' + $t36c4.Count)

# ---- THE CENSUS OVER THIS TREE's TRACKED SOURCE --------------------------------------------------
$t36Ls = Invoke-T36Git -GitArgs @('-C', $repoRoot, 'ls-files')
$t36Files = @(@($t36Ls.out -split "`n") | ForEach-Object { $_.Trim() } | Where-Object { ($_ -match '\.(ps1|psm1|psd1|py)$') -and ($_ -notmatch '^tests/lam/') })
$t36Writers = [ordered]@{}
$t36Read = 0
foreach ($t36f in $t36Files) {
    $t36p = Join-Path $repoRoot ($t36f -replace '/', '\')
    if (-not (Test-Path -LiteralPath $t36p -PathType Leaf)) { continue }
    $t36Read++
    $t36k = @(Get-T36WriterKeys -Name $t36f -Text ([System.IO.File]::ReadAllText($t36p)))
    if ($t36k.Count -gt 0) { $t36Writers[$t36f] = @($t36k | Sort-Object -Unique) }
}
# THE FLOOR, FROM THIS REPOSITORY's OWN TREE. It was a constant, 400, sized to the repository of record,
# whose tracked source outside tests/lam/ is its product and records as well as the framework; the framework repository
# commits fewer than that. It is now a second, independent reading -- the source files the commit HEAD names outside
# tests/lam/, by the same rule -- with git's exit and every listed file read: a census over nothing, or over less than the
# committed tree, still fails, and at a repository of record's size this is stricter than 400.
$t36Tree = Invoke-T36Git -GitArgs @('-C', $repoRoot, 'ls-tree', '-r', '--name-only', 'HEAD')
$t36Floor = if ($t36Tree.code -eq 0) { @(@($t36Tree.out -split "`n") | ForEach-Object { $_.Trim() } | Where-Object { ($_ -match '\.(ps1|psm1|psd1|py)$') -and ($_ -notmatch '^tests/lam/') }).Count } else { -1 }
$t36Expect = @('tools/evidence-hooks-next/hooks/lib/evidence-common.ps1', 'tools/lam/lam-dispatch-gate.ps1', 'tools/lam/mission-gate.ps1')
$t36Found = @($t36Writers.Keys | Sort-Object)
Add-T36Row -Label ('CENSUS the writers of a column-0 consume key are exactly three (' + $t36Files.Count + ' tracked source files listed, ' + $t36Read + ' read, the committed tree''s ' + $t36Floor + ')') `
    -Ok (($t36Ls.code -eq 0) -and ($t36Floor -gt 0) -and ($t36Files.Count -ge $t36Floor) -and ($t36Read -eq $t36Files.Count) -and (($t36Found -join ',') -ceq ($t36Expect -join ','))) `
    -Said ((@($t36Writers.Keys | ForEach-Object { $_ + ' [' + ($t36Writers[$_] -join ' ') + ']' })) -join ' ; ')
$t36DispatchKeyed = @($t36Writers.Keys | Where-Object { (@($t36Writers[$_]) -contains 'consumed_spawns') -or (@($t36Writers[$_]) -contains 'consumed_manifest_sha256') })
Add-T36Row -Label 'CENSUS only the runner''s library composes the dispatch keys (consumed_spawns, consumed_manifest_sha256)' `
    -Ok (($t36DispatchKeyed -join ',') -ceq 'tools/lam/lam-dispatch-gate.ps1') -Said ('files [' + ($t36DispatchKeyed -join ', ') + ']')

# ---- THE FIXTURE: a bare origin, a mission root, a manifest, and a gate the console minted --------
$t36Base = Join-Path $env:TEMP ('lam-wp4-t36-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
$t36Root = Join-Path $t36Base 'mission'
$t36Origin = Join-Path $t36Base 'origin.git'
$t36Work = Join-Path $t36Base 'work'
foreach ($t36d in @($t36Root, $t36Origin, $t36Work)) { New-Item -ItemType Directory -Path $t36d -Force | Out-Null }
$null = Invoke-T36Git -GitArgs @('init', '--bare', '--quiet', '--initial-branch=main', $t36Origin)
$null = Invoke-T36Git -GitArgs @('init', '--quiet', '--initial-branch=main', $t36Work)
# ASSERT THE GIT DIR BEFORE ANY git config (the 2026-09-13 rule).
$t36Gd = (Invoke-T36Git -GitArgs @('-C', $t36Work, 'rev-parse', '--absolute-git-dir')).out.Trim()
$t36GdOk = $t36Gd.Replace('/', '\').StartsWith(([System.IO.Path]::GetFullPath($t36Work)), [StringComparison]::OrdinalIgnoreCase)
if ($t36GdOk) {
    $null = Invoke-T36Git -GitArgs @('-C', $t36Work, 'config', 'user.email', 't36@example.invalid')
    $null = Invoke-T36Git -GitArgs @('-C', $t36Work, 'config', 'user.name', 'T36')
    Write-Utf8 -Path (Join-Path $t36Work 'a.txt') -Text "t36`n"
    $null = Invoke-T36Git -GitArgs @('-C', $t36Work, 'add', '--', 'a.txt')
    $null = Invoke-T36Git -GitArgs @('-C', $t36Work, 'commit', '--quiet', '-m', 'seed')
}
$t36Url = ($t36Origin -replace '\\', '/')
$null = Invoke-T36Git -GitArgs @('-C', $t36Work, 'push', '--quiet', $t36Url, 'HEAD:refs/heads/main')
$t36LsR = Invoke-T36Git -GitArgs @('ls-remote', $t36Url, 'refs/heads/main')
$t36Tip = ''
$t36LsM = [regex]::Match($t36LsR.out, '(?m)^([0-9a-f]{40})\s')
if ($t36LsM.Success) { $t36Tip = $t36LsM.Groups[1].Value }
$t36Gates = Join-Path $t36Root '.mission\gates'
$t36Disp  = Join-Path $t36Root '.mission\dispatches'
New-Item -ItemType Directory -Path $t36Gates -Force | Out-Null
Write-Utf8 -Path (Join-Path $t36Root '.mission\mission.yaml') -Text "id: mission-wp4-t36`nstate: executing`n"
Write-Utf8 -Path (Join-Path $t36Disp 'D-T36A.yaml') -Text "id: D-T36A`nkind: mainline`n"
Write-Utf8 -Path (Join-Path $t36Disp 'D-T36B.yaml') -Text "id: D-T36B`nkind: mainline`n"
$t36ShaA = Get-T36Sha (Join-Path $t36Disp 'D-T36A.yaml')
$t36ShaB = Get-T36Sha (Join-Path $t36Disp 'D-T36B.yaml')
Write-Utf8 -Path (Join-Path $t36Disp 'D-T36.manifest.yaml') -Text ("id: D-T36`nkind: validator-manifest`nspawn_order:`n- D-T36A`n- D-T36B`nartifacts:`n" +
    "- path: .mission/dispatches/D-T36A.yaml`n  sha256: $t36ShaA`n- path: .mission/dispatches/D-T36B.yaml`n  sha256: $t36ShaB`n")
$t36Mint = Invoke-Gate -Argv @('approve', '-Kind', 'dispatch', '-Id', 't36', '-Binds', '.mission\dispatches\D-T36.manifest.yaml', '-MissionRoot', $t36Root)
$t36MintU = Invoke-Gate -Argv @('approve', '-Kind', 'dispatch', '-Id', 't36u', '-Binds', '.mission\dispatches\D-T36.manifest.yaml', '-MissionRoot', $t36Root)
$t36Gate  = Join-Path $t36Gates 'dispatch-t36.yaml'
$t36GateU = Join-Path $t36Gates 'dispatch-t36u.yaml'
Add-T36Row -Label 'FIXTURE a bare origin tip, and two dispatch gates minted through the console' `
    -Ok ($t36GdOk -and [bool]$t36Tip -and ($t36Mint.exit -eq 0) -and ($t36MintU.exit -eq 0) -and (Test-Path -LiteralPath $t36Gate) -and (Test-Path -LiteralPath $t36GateU)) `
    -Said ('tip ' + $t36Tip + ', mint exits ' + $t36Mint.exit + '/' + $t36MintU.exit)

# ---- (1) THE RUNNER's WRITER CONSUMES dispatch-t36, driven in a child under StrictMode Latest -------
$t36Probe = Join-Path $t36Base 't36-stamp.ps1'
$t36Out = Join-Path $t36Base 't36-stamp.out.txt'
Write-Utf8 -Path $t36Probe -Text @'
param([string]$ClassLib, [string]$GateLib, [string]$Root, [string]$Out)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$r = 'ABORTED'
try {
    . $ClassLib
    . $GateLib
    $s = Invoke-LamDispatchGateStamp -MissionRoot $Root -GateId 't36' -DispatchId 'D-T36A' -DispatchPath (Join-Path $Root '.mission\dispatches\D-T36A.yaml')
    $r = [string]$s.ok + '/' + [string]$s.first + '/' + [string]$s.spawn_seq + '/' + [string]$s.code
} catch { $r = 'ABORTED line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' ') }
[System.IO.File]::WriteAllText($Out, $r)
'@
$prevEap = $ErrorActionPreference
$ErrorActionPreference = 'Continue'
try { $null = & powershell -NoProfile -ExecutionPolicy Bypass -File $t36Probe -ClassLib (Join-Path $repoRoot 'tools\lam\lam-gate-class.ps1') -GateLib (Join-Path $repoRoot 'tools\lam\lam-dispatch-gate.ps1') -Root $t36Root -Out $t36Out 2>&1 }
finally { $ErrorActionPreference = $prevEap }
$t36Said = if (Test-Path -LiteralPath $t36Out) { [System.IO.File]::ReadAllText($t36Out) } else { '(no probe output)' }
$t36GateText = if (Test-Path -LiteralPath $t36Gate) { [System.IO.File]::ReadAllText($t36Gate) } else { '' }
$t36Consumed = (Get-LamGateState -Path $t36Gate).consumed -and ($t36GateText -match '(?m)^  - \{seq: 1, dispatch_id: D-T36A\}\r?$')
Add-T36Row -Label '(1) the runner''s writer consumed dispatch-t36 (ok/first/seq 1, the spawn listed)' -Ok (($t36Said -ceq 'True/True/1/') -and $t36Consumed) -Said $t36Said

# ---- (2) THE CONSOLE's SETTLE, -Kind dispatch --------------------------------------------------------
$t36S0 = Get-T36Sha $t36Gate; $t36L0 = Get-T36Len $t36Gate
$t36S1 = Invoke-Gate -Argv @('settle', '-Kind', 'dispatch', '-Id', 't36', '-MissionRoot', $t36Root)
$t36Same1 = ((Get-T36Sha $t36Gate) -ceq $t36S0) -and ((Get-T36Len $t36Gate) -eq $t36L0)
# THE EXPECTED SENTENCE MOVED WITH settle's SCOPE (BATCH-6 WP-P (b); ruling Q3 of
# 2026-10-16): settle records push, amendment-material and reclose, and its refusal of every other kind names the
# three. dispatch stays refused -- operator ruling (i) routes it to the runner at spawn; T-58 drives the other four.
Add-T36Row -Label '(2) settle -Kind dispatch REFUSES (push, amendment-material and reclose only) and leaves the gate byte-unchanged' `
    -Ok ($t36Consumed -and ($t36S1.exit -eq 2) -and ($t36S1.out -match 'settle is defined for -Kind push, amendment-material and reclose only') -and $t36Same1) -Said ('gate consumed by (1) ' + $t36Consumed + ', exit ' + $t36S1.exit + ', unchanged ' + $t36Same1)

# ---- (3) THE SAME BYTES UNDER A PUSH NAME, settle -Kind push --------------------------------------
$t36AsPush = Join-Path $t36Gates 'push-t36.yaml'
[System.IO.File]::WriteAllBytes($t36AsPush, [System.IO.File]::ReadAllBytes($t36Gate))
$t36P0 = Get-T36Sha $t36AsPush; $t36PL0 = Get-T36Len $t36AsPush
$t36S2 = Invoke-Gate -Argv @('settle', '-Kind', 'push', '-Id', 't36', '-MissionRoot', $t36Root)
$t36Same2 = ((Get-T36Sha $t36AsPush) -ceq $t36P0) -and ((Get-T36Len $t36AsPush) -eq $t36PL0)
Add-T36Row -Label '(3) the consumed dispatch bytes named push-t36.yaml: settle -Kind push REFUSES on the kind' `
    -Ok ($t36Consumed -and ($t36S2.exit -eq 2) -and ($t36S2.out -match "declares 'kind: dispatch'") -and $t36Same2) -Said ('gate consumed by (1) ' + $t36Consumed + ', exit ' + $t36S2.exit + ', unchanged ' + $t36Same2)
Remove-Item -LiteralPath $t36AsPush -Force

# ---- (4)-(6) THE HOOK's SETTLE ---------------------------------------------------------------------
# Each artifact carries the push triple for the tip the bare origin really holds, so the only
# difference the hook's selection can act on is kind -- and, for (5), consumption.
$t36Triple = "authorized_tip_sha: $t36Tip`r`norigin_url: $t36Url`r`nremote_ref: refs/heads/main`r`n"
$t36H4 = Join-Path $t36Gates 'push-t36u.yaml'
[System.IO.File]::WriteAllText($t36H4, ([System.IO.File]::ReadAllText($t36GateU) + $t36Triple), (New-Object System.Text.UTF8Encoding($false)))
$t36H5 = Join-Path $t36Gates 'push-t36c.yaml'
[System.IO.File]::WriteAllText($t36H5, ([System.IO.File]::ReadAllText($t36Gate) + $t36Triple), (New-Object System.Text.UTF8Encoding($false)))
$t36H4s = Get-T36Sha $t36H4; $t36H5s = Get-T36Sha $t36H5
$t36Entry = [pscustomobject]@{ gate_path = $t36H4; authorized_sha = $t36Tip; remote_ref = 'refs/heads/main'; remote_sha_before = '1111111111111111111111111111111111111111' }
$null = Clear-EvidencePushInFlight -Root $t36Root
$null = Write-EvidencePushInFlight -Root $t36Root -Remote 'origin' -RemoteUrl $t36Url -Entries @($t36Entry)
$t36R4 = Complete-EvidencePushGate -Root $t36Root
Add-T36Row -Label '(4) the hook, an UNCONSUMED dispatch-kind artifact carrying the triple: consumes nothing' `
    -Ok ((-not $t36R4.consumed) -and ((Get-T36Sha $t36H4) -ceq $t36H4s)) -Said ([string]$t36R4.reason)
Add-T36Row -Label '(5) the hook, the RUNNER-CONSUMED dispatch bytes carrying the triple: byte-unchanged' `
    -Ok ($t36Consumed -and ((Get-T36Sha $t36H5) -ceq $t36H5s)) -Said ('gate consumed by (1) ' + $t36Consumed + ', sha ' + $t36H5s.Substring(0, 16))
# (6) CONTROL: the (4) bytes spelled kind: push ARE consumed by the same hook, in the same fixture.
$t36H6 = Join-Path $t36Gates 'push-t36p.yaml'
[System.IO.File]::WriteAllText($t36H6, ([regex]::Replace([System.IO.File]::ReadAllText($t36H4), '(?m)^kind: dispatch', 'kind: push')), (New-Object System.Text.UTF8Encoding($false)))
$null = Clear-EvidencePushInFlight -Root $t36Root
$null = Write-EvidencePushInFlight -Root $t36Root -Remote 'origin' -RemoteUrl $t36Url -Entries @($t36Entry)
$t36R6 = Complete-EvidencePushGate -Root $t36Root
Add-T36Row -Label '(6) CONTROL the same artifact spelled kind: push IS consumed by the hook' `
    -Ok (((Get-LamGateState -Path $t36H6).consumed) -and ((Get-T36Sha $t36H4) -ceq $t36H4s) -and ((Get-T36Sha $t36H5) -ceq $t36H5s)) `
    -Said ('push-t36p state ' + (Get-LamGateState -Path $t36H6).state + '; the two dispatch-kind artifacts still unchanged')
try { Remove-Item -LiteralPath $t36Base -Recurse -Force -ErrorAction Stop } catch { }
}
catch {
    Add-T36Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
    if (Get-Variable -Name 't36Base' -Scope Script -ErrorAction SilentlyContinue) { try { Remove-Item -LiteralPath $t36Base -Recurse -Force -ErrorAction Stop } catch { } }
}
