    foreach ($t56V in $script:t56GitVars) { $t56Saved[$t56V] = [Environment]::GetEnvironmentVariable($t56V); [Environment]::SetEnvironmentVariable($t56V, $null) }
    $t56Go = @()
    $t56Gc = -1
