    New-Item -ItemType Directory -Path $t56R -Force | Out-Null
    $t56In = Invoke-T56Git -Root $Base -GitArgs @('init', '--quiet', '--initial-branch=main', $t56R)
    $t56Gd = Invoke-T56Git -Root $t56R -GitArgs @('rev-parse', '--absolute-git-dir')
    $t56GdPath = [System.IO.Path]::GetFullPath($t56Gd.text.Trim().Replace('/', '\'))
    if (($t56In.exit -ne 0) -or ($t56Gd.exit -ne 0) -or ($t56GdPath -ine [System.IO.Path]::GetFullPath((Join-Path $t56R '.git')))) {
        throw ('FIXTURE REFUSED: the fixture git dir is not exactly <root>\.git (' + $t56Gd.text.Trim() + ')')
