function Get-T56GitSha {
    # sha256 of the bytes `git -C <root> <args>` writes to stdout, read as BYTES and never through PowerShell's
    # text pipeline; or a reason beginning 'UNREAD'.
    param([string]$Root, [string[]]$GitArgs)
    try {
        $t56Psi = New-Object System.Diagnostics.ProcessStartInfo
        $t56Psi.FileName = 'git'
        $t56Psi.Arguments = ('-C "{0}" {1}' -f $Root, ($GitArgs -join ' '))
        $t56Psi.UseShellExecute = $false
        $t56Psi.RedirectStandardOutput = $true
        $t56Psi.RedirectStandardError = $true
        $t56Psi.CreateNoWindow = $true
        foreach ($t56V in $script:t56GitVars) { if ($t56Psi.EnvironmentVariables.ContainsKey($t56V)) { $t56Psi.EnvironmentVariables.Remove($t56V) } }
        $t56P = [System.Diagnostics.Process]::Start($t56Psi)
        $t56Et = $t56P.StandardError.ReadToEndAsync()
        $t56Ms = New-Object System.IO.MemoryStream
        $t56P.StandardOutput.BaseStream.CopyTo($t56Ms)
        $t56P.WaitForExit()
        if ($t56P.ExitCode -ne 0) { return ('UNREAD: git exited ' + $t56P.ExitCode + ': ' + ([string]$t56Et.Result).Trim()) }
        $t56H = [System.Security.Cryptography.SHA256]::Create()
        try { return ([BitConverter]::ToString($t56H.ComputeHash($t56Ms.ToArray())) -replace '-', '').ToLowerInvariant() } finally { $t56H.Dispose() }
    } catch { return ('UNREAD: ' + $_.Exception.Message) }
}
function Get-T56ShapeFault {
    # THE LINE SHAPE S7 NAMES, spelled out here apart from the evaluator's Get-PlacementGateShapeFault: each of
    # the given column-0 keys appears once, and its value holds no ': ', no TAB and no CR, does not end with ':',
    # and starts with no blank and none of the indicators { [ ] } & * ! | > % @ ` ? , " ' -. '' when clean.
    param([string]$Text, [string[]]$Keys)
