        if ($t56Ms2.Count -ne 1) { return ($t56K + ' appears ' + $t56Ms2.Count + ' times') }
        $t56Val = [string]$t56Ms2[0].Groups[1].Value
        if ($t56Val.Contains(': ') -or $t56Val.Contains([string][char]9) -or $t56Val.Contains([string][char]13) -or $t56Val.EndsWith(':')) { return ($t56K + ': a value holding ": ", a TAB or a CR, or ending with ":"') }
        if (($t56Val.Length -eq 0) -or [regex]::IsMatch($t56Val, '\A\s') -or ('{[]}&*!|>%@`?,"''-'.IndexOf($t56Val[0]) -ge 0)) { return ($t56K + ': an empty value, or one starting with a blank or an indicator') }
    }
    return ''
}
