$t57rows = New-Object System.Collections.Generic.List[string]
function Add-T57Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t57ok = $false }
    $script:t57rows.Add(('      {0,-100} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function Invoke-T57Eval {
    # The TREE's evaluator over G-T57, by hand, in Invoke-T37Eval's form: LAM_DISPATCH cleared for the child and
    # put back; from the verdict file, the verdict, the AWAITING lines, the arm's detail, and gate_present's ok and
    # detail (each detector is written `  - type:`, `    ok:`, `    detail: '...'`, mission-goal-check.ps1:5384-:5398).
    param([string]$Root)
    $t57Ev = Join-Path $repoRoot 'tools\lam\mission-goal-check.ps1'
    $t57Vf = Join-Path $Root '.mission\goals\G-T57.verdict.yaml'
    if (Test-Path -LiteralPath $t57Vf) { Remove-Item -LiteralPath $t57Vf -Force }
    $t57SavedDispatch = $env:LAM_DISPATCH
    $env:LAM_DISPATCH = $null
    $t57O = @()
    $t57C = -1
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $t57O = @(& powershell -NoProfile -ExecutionPolicy Bypass -File $t57Ev -Goal 'G-T57' -MissionRoot $Root 2>&1); $t57C = $LASTEXITCODE }
    finally {
        $ErrorActionPreference = $prevEap
        if ($null -ne $t57SavedDispatch) { $env:LAM_DISPATCH = $t57SavedDispatch }
    }
    $t57Text = if (Test-Path -LiteralPath $t57Vf) { [System.IO.File]::ReadAllText($t57Vf) } else { '' }
    $t57V = '(no verdict file)'
    $t57Vm = [regex]::Match($t57Text, '(?m)^verdict:[ \t]*(\S+)')
    if ($t57Vm.Success) { $t57V = $t57Vm.Groups[1].Value }
    $t57Await = New-Object System.Collections.Generic.List[string]
    $t57In = $false
    foreach ($t57Ln in (($t57Text -replace "`r", '') -split "`n")) {
        if (-not $t57In) { if ($t57Ln -ceq 'awaiting_amendment_gate:') { $t57In = $true }; continue }
        $t57Lm = [regex]::Match($t57Ln, '^  - ''(.*)''$')
        if (-not $t57Lm.Success) { break }
        $t57Await.Add($t57Lm.Groups[1].Value.Replace("''", "'"))
    }
    $t57Arm = ''
    $t57Am = [regex]::Match($t57Text, '(?m)^  - type: ungated_placement_absent\r?\n    ok: \S+\r?\n    detail: ''(.*)''\r?$')
    if ($t57Am.Success) { $t57Arm = $t57Am.Groups[1].Value.Replace("''", "'") }
    $t57GpOk = '(absent)'
    $t57GpDetail = ''
    $t57Gm = [regex]::Match($t57Text, '(?m)^  - type: gate_present\r?\n    ok: (\S+)\r?\n    detail: ''(.*)''\r?$')
    if ($t57Gm.Success) { $t57GpOk = $t57Gm.Groups[1].Value; $t57GpDetail = $t57Gm.Groups[2].Value.Replace("''", "'") }
    return [pscustomobject]@{ exit = $t57C; verdict = $t57V; awaiting = $t57Await.ToArray(); arm = $t57Arm; gpOk = $t57GpOk; gpDetail = $t57GpDetail
                              out = ((@($t57O) | ForEach-Object { [string]$_ }) -join "`n") }
}
function Invoke-T57DatedCommit {
    # Row (10)'s git call under GIT_COMMITTER_DATE and GIT_AUTHOR_DATE set to <At> (unix seconds, +0000) for the call
    # alone and put back after it, so a fixture commit can carry a date earlier than its own ancestor's.
    param([string]$Root, [long]$At, [string[]]$GitArgs)
    $t57DSavedC = $env:GIT_COMMITTER_DATE
    $t57DSavedA = $env:GIT_AUTHOR_DATE
    $env:GIT_COMMITTER_DATE = ([string]$At + ' +0000')
    $env:GIT_AUTHOR_DATE = ([string]$At + ' +0000')
    try { return (Invoke-T56Git -Root $Root -GitArgs $GitArgs) }
    finally { $env:GIT_COMMITTER_DATE = $t57DSavedC; $env:GIT_AUTHOR_DATE = $t57DSavedA }
}
$t57Base = $null
$t57Basis = 'record of use by console -- the newest commit on HEAD holding the bound file at binds_sha256'
$t57Id = @('-c', 'user.name=wp4-t57', '-c', 'user.email=wp4-t57@example.invalid', '-c', 'commit.gpgsign=false')
try {
$t57Base = Join-Path $env:TEMP ('lam-wp4-t57-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
New-Item -ItemType Directory -Path $t57Base -Force | Out-Null
$t57Root = New-T56Repo -Base $t57Base -Name 'mission'
Write-Utf8 -Path (Join-Path $t57Root '.mission\mission.yaml') -Text "id: mission-wp4-t57`nstate: executing`n"
Write-Utf8 -Path (Join-Path $t57Root '.mission\amendments\AM-001-t57-tracked.yaml') -Text "id: AM-001`nnote: tracked`n"
New-Item -ItemType Directory -Path (Join-Path $t57Root '.mission\gates') -Force | Out-Null
$t57Add0 = Invoke-T56Git -Root $t57Root -GitArgs @('add', '--', '.mission/mission.yaml', '.mission/amendments/AM-001-t57-tracked.yaml')
$t57Seed = Invoke-T56Git -Root $t57Root -GitArgs ($t57Id + @('commit', '--quiet', '-m', 'seed'))
$t57Ref = (Invoke-T56Git -Root $t57Root -GitArgs @('symbolic-ref', 'HEAD')).text.Trim()
Write-Utf8 -Path (Join-Path $t57Root '.mission\goals\G-T57.yaml') -Text "id: G-T57`ndetectors:`n  - type: ungated_placement_absent`n  - type: gate_present`n    kind: amendment-material`n    id: am-957`n"
Add-T57Row -Label 'FIXTURE a repository under %TEMP%, git dir exactly <root>\.git, one commit; a goal with the placement arm and gate_present am-957' `
    -Ok (($t57Add0.exit -eq 0) -and ($t57Seed.exit -eq 0) -and ($t57Ref -ceq 'refs/heads/main')) -Said ('add exit ' + $t57Add0.exit + ', commit exit ' + $t57Seed.exit + ', HEAD ' + $t57Ref)

# (1) THE PLACEMENT, UNGATED: the arm sees it.
$t57Rel = '.mission\amendments\AM-957-t57.yaml'
$t57Git = '.mission/amendments/AM-957-t57.yaml'
$t57File = Join-Path $t57Root $t57Rel
Write-Utf8 -Path $t57File -Text "id: AM-957-t57`nnote: placed by WP-4 T-57, minted, committed, settled`n"
$t57Bytes = [System.IO.File]::ReadAllBytes($t57File)
$t57A = Invoke-T57Eval -Root $t57Root
Add-T57Row -Label '(1) the placement, ungated: the arm lists it AWAITING, one line naming am-957 (the control: the arm sees this placement)' `
    -Ok ((@($t57A.awaiting).Count -eq 1) -and (@($t57A.awaiting)[0] -match ' am-957 ')) -Said ('verdict ' + $t57A.verdict + '; awaiting [' + (@($t57A.awaiting) -join ' ; ') + ']')

# (2) THE MINT through the console's verified path.
$t57Mint = Invoke-Gate -Argv @('approve', '-Kind', 'amendment-material', '-Id', 'am-957', '-Binds', $t57Rel, '-MissionRoot', $t57Root)
$t57Gate = Join-Path $t57Root '.mission\gates\amendment-material-am-957.yaml'
$t57Bound = if (Test-Path -LiteralPath $t57Gate) { ([string](Get-T32Field -Text ([System.IO.File]::ReadAllText($t57Gate)) -Key 'binds_sha256')).ToLowerInvariant() } else { '(absent)' }
$t57Raw = (Get-FileHash -Algorithm SHA256 -LiteralPath $t57File).Hash.ToLowerInvariant()
Add-T57Row -Label '(2) the console mints amendment-material-am-957.yaml (exit 0); its binds_sha256 is the placement''s working-copy digest' `
    -Ok (($t57Mint.exit -eq 0) -and ($t57Bound -ceq $t57Raw)) -Said ('mint exit ' + $t57Mint.exit + '; bound ' + $t57Bound)

# (3) BEFORE THE AMENDMENT IS COMMITTED: nothing to observe, the authorization NOT spent.
$t57S0 = Get-T36Sha $t57Gate; $t57L0 = Get-T36Len $t57Gate
$t57Pre = Invoke-Gate -Argv @('settle', '-Kind', 'amendment-material', '-Id', 'am-957', '-MissionRoot', $t57Root)
Add-T57Row -Label '(3) BEFORE the amendment is committed: settle REFUSES (exit 2, "no use to record", NOT spent), the gate byte-unchanged' `
    -Ok (($t57Pre.exit -eq 2) -and ($t57Pre.out -match 'no use to record') -and ($t57Pre.out -match 'NOT spent') -and ((Get-T36Sha $t57Gate) -ceq $t57S0) -and ((Get-T36Len $t57Gate) -eq $t57L0)) `
    -Said ('exit ' + $t57Pre.exit + '; ' + ((@($t57Pre.out -split "`n") | Where-Object { $_ -match 'REFUSED' } | Select-Object -First 1)))

# (4) THE COMMIT, THEN THE REAL SETTLE through the console.
$t57Add1 = Invoke-T56Git -Root $t57Root -GitArgs @('add', '--', $t57Git)
$t57C1 = Invoke-T56Git -Root $t57Root -GitArgs ($t57Id + @('commit', '--quiet', '-m', 'the amendment am-957 commits'))
$t57Head = (Invoke-T56Git -Root $t57Root -GitArgs @('rev-parse', 'HEAD')).text.Trim()
$t57Co = Get-T56GitSha -Root $t57Root -GitArgs @('cat-file', '--filters', ('HEAD:' + $t57Git))
$t57Bl = Get-T56GitSha -Root $t57Root -GitArgs @('cat-file', 'blob', ('HEAD:' + $t57Git))
$t57Acrlf = (Invoke-T56Git -Root $t57Root -GitArgs @('config', '--get', 'core.autocrlf')).text.Trim()
$t57S = Invoke-GateConsoleLauncher -Spec @{ Verb = 'settle'; Kind = 'amendment-material'; Id = 'am-957'; MissionRoot = $t57Root }
$t57Text = if (Test-Path -LiteralPath $t57Gate) { [System.IO.File]::ReadAllText($t57Gate) } else { '' }
Add-T57Row -Label '(4) committed, then settle -Kind amendment-material through the console EXITS 0, the act attested, "settled amendment-material-am-957"' `
    -Ok (($t57Add1.exit -eq 0) -and ($t57C1.exit -eq 0) -and ($t57S.exit -eq 0) -and $t57S.minted -and $t57S.attested -and ($t57S.out -match 'mission-gate: settled amendment-material-am-957')) `
    -Said ('commit exit ' + $t57C1.exit + ', settle exit ' + $t57S.exit + '; MEASURED: core.autocrlf=' + $(if ($t57Acrlf) { $t57Acrlf } else { '(unset)' }) + ', bound ' + $t57Bound.Substring(0, [math]::Min(16, $t57Bound.Length)) + ', checked out ' + $t57Co.Substring(0, [math]::Min(16, $t57Co.Length)) + ', as stored ' + $t57Bl.Substring(0, [math]::Min(16, $t57Bl.Length)))
$t57Counts = @('consumed_at', 'consumed_commit', 'consumed_ref', 'consumed_basis' | ForEach-Object { Get-T32FieldCount -Text $t57Text -Key $_ })
$t57Stamp = Get-T32Field -Text $t57Text -Key 'consumed_at'
Add-T57Row -Label '(4) THE RECORD (Q4): consumed_at stamped, consumed_commit = the commit holding the bytes, consumed_ref = HEAD''s ref, the basis words -- each exactly once' `
    -Ok ((($t57Counts -join ',') -ceq '1,1,1,1') -and ($t57Stamp -match '\A\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z\z') -and ((Get-T32Field -Text $t57Text -Key 'consumed_commit') -ceq $t57Head) -and
         ((Get-T32Field -Text $t57Text -Key 'consumed_ref') -ceq $t57Ref) -and ((Get-T32Field -Text $t57Text -Key 'consumed_basis') -ceq $t57Basis) -and ((Get-LamGateState -Path $t57Gate).state -ceq 'CONSUMED')) `
    -Said ('counts ' + ($t57Counts -join '/') + '; commit ' + (Get-T32Field -Text $t57Text -Key 'consumed_commit') + ' (HEAD ' + $t57Head + '); ref ' + (Get-T32Field -Text $t57Text -Key 'consumed_ref'))
$t57Foreign = @('consumed_origin_tip', 'consumed_origin_before', 'consumed_spawns', 'consumed_manifest_sha256' | Where-Object { (Get-T32FieldCount -Text $t57Text -Key $_) -ne 0 })
$t57Shape = Get-T56ShapeFault -Text $t57Text -Keys @('consumed_at', 'consumed_commit', 'consumed_ref', 'consumed_basis')
$t57Cr = ([regex]::Matches($t57Text, "`r")).Count; $t57Lf = ([regex]::Matches($t57Text, "`n")).Count
Add-T57Row -Label '(4) no push field and no dispatch field; every value written SHAPE-SAFE by this member''s own reading (S7); CR == LF' `
    -Ok (($t57Foreign.Count -eq 0) -and (-not $t57Shape) -and ($t57Cr -eq $t57Lf)) -Said ('foreign [' + ($t57Foreign -join ' ') + ']; shape ' + $(if ($t57Shape) { $t57Shape } else { 'clean' }) + '; CR ' + $t57Cr + ' LF ' + $t57Lf)

# (5) S7, MEASURED BY THE EVALUATOR: an untracked copy of the committed bytes is released by the STAMPED gate.
$t57CopyRel = '.mission\amendments\AM-957-t57-copy.yaml'
[System.IO.File]::WriteAllBytes((Join-Path $t57Root $t57CopyRel), $t57Bytes)
$t57E = Invoke-T57Eval -Root $t57Root
Add-T57Row -Label '(5) S7 -- the tree''s evaluator: an untracked copy of the bound bytes is RELEASED by the STAMPED gate, nothing awaiting' `
    -Ok (($t57E.arm -match 'RELEASED by amendment-material-am-957\.yaml') -and (@($t57E.awaiting).Count -eq 0)) -Said ('the arm: ' + $t57E.arm)

# (6) S1 -- gate_present over the SETTLED gate. EXPECTED RED ON THIS BRANCH (the 10:38 ruling): see the header.
Add-T57Row -Label '(6) gate_present over the SETTLED am-957 reads it present and the goal MET -- EXPECTED RED ON THIS BRANCH until WP-Q''s C-1ax merges (:4705/:4758)' `
    -Ok (($t57E.gpOk -ceq 'true') -and ($t57E.verdict -ceq 'MET')) -Said ('gate_present ok ' + $t57E.gpOk + '; ' + $t57E.gpDetail + '; verdict ' + $t57E.verdict)

# (7) FIRST STAMP WINS.
$t57S2s = Get-T36Sha $t57Gate
$t57S2 = Invoke-Gate -Argv @('settle', '-Kind', 'amendment-material', '-Id', 'am-957', '-MissionRoot', $t57Root)
Add-T57Row -Label '(7) a second settle REFUSES in the first-stamp-wins words (exit 2), the gate byte-unchanged' `
    -Ok (($t57S2.exit -eq 2) -and ($t57S2.out -match 'ALREADY CONSUMED, and first stamp wins') -and ((Get-T36Sha $t57Gate) -ceq $t57S2s)) -Said ('exit ' + $t57S2.exit)

# (8) A GATE OVER BYTES NO COMMIT HOLDS: minted over one text, the file then edited and committed.
$t57QRel = '.mission\amendments\AM-958-t57.yaml'
Write-Utf8 -Path (Join-Path $t57Root $t57QRel) -Text "id: AM-958-t57`nnote: the bytes the gate binds`n"
$t57QMint = Invoke-Gate -Argv @('approve', '-Kind', 'amendment-material', '-Id', 'am-958', '-Binds', $t57QRel, '-MissionRoot', $t57Root)
Write-Utf8 -Path (Join-Path $t57Root $t57QRel) -Text "id: AM-958-t57`nnote: other bytes, the only ones ever committed`n"
$null = Invoke-T56Git -Root $t57Root -GitArgs @('add', '--', '.mission/amendments/AM-958-t57.yaml')
$t57QC = Invoke-T56Git -Root $t57Root -GitArgs ($t57Id + @('commit', '--quiet', '-m', 'am-958 committed over other bytes'))
$t57QGate = Join-Path $t57Root '.mission\gates\amendment-material-am-958.yaml'
$t57Q0 = Get-T36Sha $t57QGate
$t57QS = Invoke-Gate -Argv @('settle', '-Kind', 'amendment-material', '-Id', 'am-958', '-MissionRoot', $t57Root)
Add-T57Row -Label '(8) a gate over bytes NO commit holds (edited, then committed): settle REFUSES (exit 2, "no use to record"), byte-unchanged' `
    -Ok (($t57QMint.exit -eq 0) -and ($t57QC.exit -eq 0) -and ($t57QS.exit -eq 2) -and ($t57QS.out -match 'no use to record') -and ((Get-T36Sha $t57QGate) -ceq $t57Q0)) -Said ('mint exit ' + $t57QMint.exit + ', settle exit ' + $t57QS.exit)

# (9) AN EXPIRED GATE SETTLES (the question's own case: expired, consumed_at null).
$t57RRel = '.mission\amendments\AM-959-t57.yaml'
Write-Utf8 -Path (Join-Path $t57Root $t57RRel) -Text "id: AM-959-t57`nnote: minted with no time left`n"
$t57RMint = Invoke-Gate -Argv @('approve', '-Kind', 'amendment-material', '-Id', 'am-959', '-Binds', $t57RRel, '-ExpiresMinutes', '0', '-MissionRoot', $t57Root)
$null = Invoke-T56Git -Root $t57Root -GitArgs @('add', '--', '.mission/amendments/AM-959-t57.yaml')
$t57RC = Invoke-T56Git -Root $t57Root -GitArgs ($t57Id + @('commit', '--quiet', '-m', 'am-959 commits'))
$t57RS = Invoke-Gate -Argv @('settle', '-Kind', 'amendment-material', '-Id', 'am-959', '-MissionRoot', $t57Root)
$t57RGate = Join-Path $t57Root '.mission\gates\amendment-material-am-959.yaml'
Add-T57Row -Label '(9) an EXPIRED amendment-material gate (minted with -ExpiresMinutes 0), its amendment committed: settle EXITS 0, the gate CONSUMED' `
    -Ok (($t57RMint.exit -eq 0) -and ($t57RC.exit -eq 0) -and ($t57RS.exit -eq 0) -and ((Get-LamGateState -Path $t57RGate).state -ceq 'CONSUMED')) -Said ('mint exit ' + $t57RMint.exit + ', settle exit ' + $t57RS.exit)

# (10) A HOLDING COMMIT DATED BEFORE ITS OWN HOLDING ANCESTOR (validator round 1 finding). git log's default walk is by
# commit date, so a commit whose committer date is earlier than an ancestor's can be listed AFTER that ancestor; the
# observation must record the holding commit that descends from every other, whatever the dates say. A commits the
# bound bytes on main; a side line from A edits the file (E) and restores the bound bytes (B), B dated a day before
# A; main moves past A (P, another file); HEAD merges the side line (M, the bound path the same on both parents, so
# the log lists A, E and B and not M). B stands above A: settle records B and refuses nothing as AMBIGUOUS.
$t57TRel = '.mission\amendments\AM-960-t57.yaml'
$t57TGit = '.mission/amendments/AM-960-t57.yaml'
$t57TFile = Join-Path $t57Root $t57TRel
Write-Utf8 -Path $t57TFile -Text "id: AM-960-t57`nnote: committed on main, edited and restored on a side line dated in the past`n"
$t57TBytes = [System.IO.File]::ReadAllBytes($t57TFile)
$t57TMint = Invoke-Gate -Argv @('approve', '-Kind', 'amendment-material', '-Id', 'am-960', '-Binds', $t57TRel, '-MissionRoot', $t57Root)
$t57TZero = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
$null = Invoke-T56Git -Root $t57Root -GitArgs @('add', '--', $t57TGit)
$t57TcA = Invoke-T57DatedCommit -Root $t57Root -At $t57TZero -GitArgs ($t57Id + @('commit', '--quiet', '-m', 'A: am-960 commits on main'))
$t57ShaA = (Invoke-T56Git -Root $t57Root -GitArgs @('rev-parse', 'HEAD')).text.Trim()
$t57TcSide = Invoke-T56Git -Root $t57Root -GitArgs @('checkout', '--quiet', '-b', 't57-side')
Write-Utf8 -Path $t57TFile -Text "id: AM-960-t57`nnote: other bytes on the side line`n"
$null = Invoke-T56Git -Root $t57Root -GitArgs @('add', '--', $t57TGit)
$t57TcE = Invoke-T57DatedCommit -Root $t57Root -At ($t57TZero + 600) -GitArgs ($t57Id + @('commit', '--quiet', '-m', 'E: the side line edits am-960'))
[System.IO.File]::WriteAllBytes($t57TFile, $t57TBytes)
$null = Invoke-T56Git -Root $t57Root -GitArgs @('add', '--', $t57TGit)
$t57TcB = Invoke-T57DatedCommit -Root $t57Root -At ($t57TZero - 86400) -GitArgs ($t57Id + @('commit', '--quiet', '-m', 'B: the side line restores the bound bytes, dated a day before A'))
$t57ShaB = (Invoke-T56Git -Root $t57Root -GitArgs @('rev-parse', 'HEAD')).text.Trim()
$t57TcMain = Invoke-T56Git -Root $t57Root -GitArgs @('checkout', '--quiet', 'main')
Write-Utf8 -Path (Join-Path $t57Root 't57-main-moves.txt') -Text "main moves past A`n"
$null = Invoke-T56Git -Root $t57Root -GitArgs @('add', '--', 't57-main-moves.txt')
$t57TcP = Invoke-T57DatedCommit -Root $t57Root -At ($t57TZero + 1200) -GitArgs ($t57Id + @('commit', '--quiet', '-m', 'P: main moves past A'))
$t57TcM = Invoke-T57DatedCommit -Root $t57Root -At ($t57TZero + 1800) -GitArgs ($t57Id + @('merge', '--quiet', '--no-ff', '-m', 'M: HEAD merges the side line', 't57-side'))
$t57TAnc = (Invoke-T56Git -Root $t57Root -GitArgs @('merge-base', '--is-ancestor', $t57ShaA, $t57ShaB)).exit
$t57TLog = (Invoke-T56Git -Root $t57Root -GitArgs @('--literal-pathspecs', 'log', '--full-history', '--format=%H', 'HEAD', '--', $t57TGit)).text
$t57TOrder = (@(@($t57TLog -split "`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ -match '\A[0-9a-f]{40}\z' } | ForEach-Object { if ($_ -ceq $t57ShaA) { 'A' } elseif ($_ -ceq $t57ShaB) { 'B' } else { 'E' } })) -join ','
$t57TGate = Join-Path $t57Root '.mission\gates\amendment-material-am-960.yaml'
$t57TS = Invoke-Gate -Argv @('settle', '-Kind', 'amendment-material', '-Id', 'am-960', '-MissionRoot', $t57Root)
$t57TText = if (Test-Path -LiteralPath $t57TGate) { [System.IO.File]::ReadAllText($t57TGate) } else { '' }
$t57TRec = [string](Get-T32Field -Text $t57TText -Key 'consumed_commit')
$t57TWhy = [string](@($t57TS.out -split "`n") | Where-Object { $_ -match 'REFUSED' } | Select-Object -First 1)
Add-T57Row -Label '(10) a holding commit DATED BEFORE its own holding ancestor (B restores the bound bytes on a side line, a day before A; HEAD merges it): settle EXITS 0 and records B, the holding commit that descends from every other' `
    -Ok (($t57TMint.exit -eq 0) -and ($t57TcA.exit -eq 0) -and ($t57TcSide.exit -eq 0) -and ($t57TcE.exit -eq 0) -and ($t57TcB.exit -eq 0) -and ($t57TcMain.exit -eq 0) -and
         ($t57TcP.exit -eq 0) -and ($t57TcM.exit -eq 0) -and ($t57TAnc -eq 0) -and ($t57TS.exit -eq 0) -and ($t57TRec -ceq $t57ShaB)) `
    -Said ('mint exit ' + $t57TMint.exit + '; commits A/E/B/P/M exit ' + $t57TcA.exit + '/' + $t57TcE.exit + '/' + $t57TcB.exit + '/' + $t57TcP.exit + '/' + $t57TcM.exit + '; A ancestor of B: exit ' + $t57TAnc +
           '; git log''s default order lists ' + $t57TOrder + ' (A ' + $t57ShaA + ', B ' + $t57ShaB + '); settle exit ' + $t57TS.exit + '; consumed_commit ' + $(if ($t57TRec) { $t57TRec } else { '(none)' }) + $(if ($t57TWhy) { '; ' + $t57TWhy.Trim() } else { '' }))
try { Remove-Item -LiteralPath $t57Base -Recurse -Force -ErrorAction Stop } catch { }
}
catch {
    Add-T57Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
    if ($t57Base) { try { Remove-Item -LiteralPath $t57Base -Recurse -Force -ErrorAction Stop } catch { } }
}
