# =============================================================================================
# T-37 -- THE PLACEMENT-WINDOW ARM, RELEASED BY A REAL MINT (operator ruling
#         (ii), and the operator's later rulings; package WP-C)
# =============================================================================================
# WHY THIS IS WP-4's. The ruling makes "the amendment-material mint" the release of an admitted
# placement, and the one thing a forged gate cannot show is that the gate THE CONSOLE WRITES releases
# what the goal evaluator admits. WP-3's C-1x forges gates in the mint's line set; this member MINTS
# them through lam-console.ps1's verified path (the scrubbed launcher, the injected provider),
# reapproves and revokes through the same verbs, runs the reapprove the evaluator itself prescribes,
# and reads the tree's evaluator after every act.
#
# THE ONE PLACE THE TWO DIGESTS DIFFER, MEASURED. mission-gate.ps1 hashes the WORKING COPY; the arm's
# line carries the LF/blob digest. For a placement carrying CR LF the two differ -- row (f) measures
# it -- and the operator's ruling (1) of 2026-09-24 makes a gate over EITHER release, so the real mint
# over a CR LF placement releases it. Ruling (3): only the canonical gate path counts, so the same
# minted bytes renamed aside release nothing (row (f), third).
$t37ok = $true
$t37rows = New-Object System.Collections.Generic.List[string]
$t37GitVars = @('GIT_DIR', 'GIT_WORK_TREE', 'GIT_INDEX_FILE', 'GIT_COMMON_DIR')
function Add-T37Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t37ok = $false }
    $script:t37rows.Add(('      {0,-100} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function Invoke-T37Git {
    # git in the fixture, with the four redirecting variables removed from this process for the call,
    # so an inherited GIT_DIR cannot turn the fixture's init into a write to another repository.
    param([string]$Root, [string[]]$GitArgs)
    $t37Saved = @{}
    foreach ($t37V in $script:t37GitVars) { $t37Saved[$t37V] = [Environment]::GetEnvironmentVariable($t37V); [Environment]::SetEnvironmentVariable($t37V, $null) }
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $t37Go = @(& git -C $Root @GitArgs 2>&1); $t37Gc = $LASTEXITCODE }
    finally {
        $ErrorActionPreference = $prevEap
        foreach ($t37V in $script:t37GitVars) { [Environment]::SetEnvironmentVariable($t37V, $t37Saved[$t37V]) }
    }
    return [pscustomobject]@{ exit = $t37Gc; text = ((@($t37Go) | ForEach-Object { [string]$_ }) -join "`n") }
}
function Get-T37LfSha {
    # sha256 of a TEXT file with every CR LF pair collapsed to LF -- computed here, apart from the
    # evaluator. The two placements this member writes are text, so this is git's own blob basis for them.
    param([string]$Path)
    $t37Raw = [System.IO.File]::ReadAllBytes($Path)
    $t37Lf = New-Object System.Collections.Generic.List[byte]
    for ($t37I = 0; $t37I -lt $t37Raw.Length; $t37I++) {
        if (($t37Raw[$t37I] -eq 13) -and (($t37I + 1) -lt $t37Raw.Length) -and ($t37Raw[$t37I + 1] -eq 10)) { continue }
        $t37Lf.Add($t37Raw[$t37I])
    }
    $t37H = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($t37H.ComputeHash($t37Lf.ToArray()))).Replace('-', '').ToLowerInvariant() } finally { $t37H.Dispose() }
}
function Get-T37Bound {
    # The one column-0 binds_sha256 a gate on disk records, or '(absent)'.
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return '(absent)' }
    $t37Bm = [regex]::Match([System.IO.File]::ReadAllText($Path), '(?m)^binds_sha256:[ \t]*([0-9a-fA-F]{64})[ \t]*\r?$')
    if ($t37Bm.Success) { return $t37Bm.Groups[1].Value.ToLowerInvariant() }
    return '(none)'
}
function Get-T37PrescribedArgv {
    # The mint the arm PRINTED for one placement, parsed by PowerShell's own parser (never executed)
    # into the argv Invoke-Gate takes: verb, then each -Name and its value exactly as the parser reads
    # the pasted text. $null when nothing was printed or the text is not ONE clean statement.
    param([string]$Arm, [string]$Rel)
    $t37Rx = [regex]::Escape('mint for ' + $Rel) + '[^:]*: tools\\lam\\lam-console\.ps1 (?<cmd>.*?)(?= -- (?:mint for|about|no mint|\d+ placement|\d+ tracked|key)|\z)'
    $t37Pm = [regex]::Match($Arm, $t37Rx)
    if (-not $t37Pm.Success) { return $null }
    $t37Tok = $null; $t37Err = $null
    $t37Ast = [System.Management.Automation.Language.Parser]::ParseInput(('x ' + $t37Pm.Groups['cmd'].Value), [ref]$t37Tok, [ref]$t37Err)
    if ((@($t37Err).Count -gt 0) -or (@($t37Ast.EndBlock.Statements).Count -ne 1)) { return $null }
    $t37El = @(@($t37Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true))[0].CommandElements)
    $t37Argv = New-Object System.Collections.Generic.List[string]
    $t37Argv.Add([string]$t37El[1].Extent.Text)
    for ($t37K = 2; $t37K -lt $t37El.Count; $t37K++) {
        if ($t37El[$t37K] -is [System.Management.Automation.Language.CommandParameterAst]) {
            $t37Argv.Add('-' + $t37El[$t37K].ParameterName)
            if ((($t37K + 1) -lt $t37El.Count) -and ($t37El[$t37K + 1] -is [System.Management.Automation.Language.StringConstantExpressionAst])) { $t37Argv.Add($t37El[$t37K + 1].Value); $t37K++ }
        }
    }
    return , ($t37Argv.ToArray())
}
function Invoke-T37Eval {
    # The TREE's evaluator over the fixture goal, by hand or as the Stop hook runs it; LAM_DISPATCH is
    # cleared for the child (a dispatched worker's hook approves without evaluating) and put back. A hook
    # row that expects an admitted stop asserts exit 0 as well: exit 2 blocks whatever the JSON says.
    param([string]$Root, [switch]$Hook)
    $t37Ev = Join-Path $repoRoot 'tools\lam\mission-goal-check.ps1'
    $t37Vf = Join-Path $Root '.mission\goals\G-T37.verdict.yaml'
    if (Test-Path -LiteralPath $t37Vf) { Remove-Item -LiteralPath $t37Vf -Force }
    $t37SavedDispatch = $env:LAM_DISPATCH
    $env:LAM_DISPATCH = $null
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try {
        if ($Hook) {
            $t37Payload = (@{ session_id = 'wp4-t37'; hook_event_name = 'Stop' } | ConvertTo-Json -Compress)
            $t37O = $t37Payload | & powershell -NoProfile -ExecutionPolicy Bypass -File $t37Ev -Goal 'G-T37' -MissionRoot $Root -AsStopHook 2>&1
        } else {
            $t37O = & powershell -NoProfile -ExecutionPolicy Bypass -File $t37Ev -Goal 'G-T37' -MissionRoot $Root 2>&1
        }
        $t37C = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $prevEap
        if ($null -ne $t37SavedDispatch) { $env:LAM_DISPATCH = $t37SavedDispatch }
    }
    $t37Out = ((@($t37O) | ForEach-Object { [string]$_ }) -join "`n")
    $t37Text = if (Test-Path -LiteralPath $t37Vf) { [System.IO.File]::ReadAllText($t37Vf) } else { '' }
    $t37V = '(no verdict file)'
    $t37Vm = [regex]::Match($t37Text, '(?m)^verdict:[ \t]*(\S+)')
    if ($t37Vm.Success) { $t37V = $t37Vm.Groups[1].Value }
    $t37Dec = ''
    $t37Dm = [regex]::Match($t37Out, '"decision"\s*:\s*"(\w+)"')
    if ($t37Dm.Success) { $t37Dec = $t37Dm.Groups[1].Value }
    $t37Await = New-Object System.Collections.Generic.List[string]
    $t37In = $false
    foreach ($t37Ln in (($t37Text -replace "`r", '') -split "`n")) {
        if (-not $t37In) { if ($t37Ln -ceq 'awaiting_amendment_gate:') { $t37In = $true }; continue }
        $t37Lm = [regex]::Match($t37Ln, '^  - ''(.*)''$')
        if (-not $t37Lm.Success) { break }
        $t37Await.Add($t37Lm.Groups[1].Value.Replace("''", "'"))
    }
    $t37Arm = ''
    $t37Am = [regex]::Match($t37Text, '(?m)^  - type: ungated_placement_absent\r?\n    ok: \S+\r?\n    detail: ''(.*)''\r?$')
    if ($t37Am.Success) { $t37Arm = $t37Am.Groups[1].Value.Replace("''", "'") }
    return [pscustomobject]@{ exit = $t37C; out = $t37Out; verdict = $t37V; decision = $t37Dec; awaiting = $t37Await.ToArray(); arm = $t37Arm }
}
$t37Base = $null
try {
$t37Pfx = 'AWAITING AMENDMENT GATE'
$t37Base = Join-Path $env:TEMP ('lam-wp4-t37-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
