New-Item -ItemType Directory -Path (Join-Path $t37Root '.mission\gates') -Force | Out-Null
$t37Id = @('-c', 'user.name=wp4-t37', '-c', 'user.email=wp4-t37@example.invalid', '-c', 'commit.gpgsign=false')
$t37AddArgs = @('add', '--', '.mission/mission.yaml', '.mission/amendments/AM-001-t37-tracked.yaml')
$t37Add = Invoke-T37Git -Root $t37Root -GitArgs $t37AddArgs
$t37SeedArgs = $t37Id + @('commit', '--quiet', '-m', 'seed')
$t37Seed = Invoke-T37Git -Root $t37Root -GitArgs $t37SeedArgs
Write-Utf8 -Path (Join-Path $t37Root '.mission\goals\G-T37.yaml') -Text "id: G-T37`ndetectors:`n  - type: ungated_placement_absent`n"
Add-T37Row -Label 'FIXTURE a git repository under %TEMP%, its git dir exactly <root>\.git, one commit tracking mission.yaml and AM-001' `
    -Ok (($t37Add.exit -eq 0) -and ($t37Seed.exit -eq 0)) -Said ('add exit ' + $t37Add.exit + ', commit exit ' + $t37Seed.exit)

# (a) THE PLACEMENT, UNGATED: the tree's evaluator admits it.
$t37Rel = '.mission\amendments\AM-903-t37.yaml'
$t37File = Join-Path $t37Root $t37Rel
Write-Utf8 -Path $t37File -Text "id: AM-903-t37`nnote: placed by WP-4 T-37 for a real mint`n"
$t37Sha1 = Get-T37LfSha -Path $t37File
$t37Line1 = $t37Pfx + ' am-903 ' + $t37Sha1 + ' .mission/amendments/AM-903-t37.yaml'
$t37A = Invoke-T37Eval -Root $t37Root
Add-T37Row -Label '(a) the LF placement, ungated: AWAITING_AMENDMENT_GATE, exit 4, the line naming am-903 and its LF/blob digest' `
    -Ok (($t37A.verdict -ceq 'AWAITING_AMENDMENT_GATE') -and ($t37A.exit -eq 4) -and (@($t37A.awaiting).Count -eq 1) -and (@($t37A.awaiting)[0] -ceq $t37Line1)) `
    -Said ('verdict ' + $t37A.verdict + ', exit ' + $t37A.exit + '; awaiting [' + (@($t37A.awaiting) -join ' ; ') + ']')

# (b) THE MINT, through the console's verified path: its binds_sha256 IS the digest the arm reads.
$t37Mint = Invoke-Gate -Argv @('approve', '-Kind', 'amendment-material', '-Id', 'am-903', '-Binds', $t37Rel, '-MissionRoot', $t37Root)
$t37Gate = Join-Path $t37Root '.mission\gates\amendment-material-am-903.yaml'
$t37Bound1 = Get-T37Bound -Path $t37Gate
Add-T37Row -Label '(b) the console mints amendment-material-am-903.yaml; its binds_sha256 equals the placement''s LF/blob digest' `
    -Ok (($t37Mint.exit -eq 0) -and ($t37Bound1 -ceq $t37Sha1)) -Said ('mint exit ' + $t37Mint.exit + '; bound ' + $t37Bound1 + '; LF/blob ' + $t37Sha1)
$t37B = Invoke-T37Eval -Root $t37Root
$t37Bh = Invoke-T37Eval -Root $t37Root -Hook
Add-T37Row -Label '(b) the minted gate RELEASES: MET, exit 0, the gate named in the arm; the hook approves on MET and exits 0' `
    -Ok (($t37B.verdict -ceq 'MET') -and ($t37B.exit -eq 0) -and ($t37B.arm -match 'RELEASED by amendment-material-am-903\.yaml') -and ($t37Bh.verdict -ceq 'MET') -and ($t37Bh.decision -ceq 'approve') -and ($t37Bh.exit -eq 0)) `
    -Said ('verdict ' + $t37B.verdict + '; the arm: ' + $t37B.arm)

# (c) AN EDIT re-admits under the new digest: the minted gate binds other bytes now.
[System.IO.File]::AppendAllText($t37File, "restated: after the mint`n", (New-Object System.Text.UTF8Encoding($false)))
$t37Sha2 = Get-T37LfSha -Path $t37File
$t37Line2 = $t37Pfx + ' am-903 ' + $t37Sha2 + ' .mission/amendments/AM-903-t37.yaml'
$t37C = Invoke-T37Eval -Root $t37Root -Hook
Add-T37Row -Label '(c) the placement edited after the mint: re-admitted under the NEW digest (hook approves, exit 0), the gate named as binding other bytes' `
    -Ok (($t37C.verdict -ceq 'AWAITING_AMENDMENT_GATE') -and ($t37C.decision -ceq 'approve') -and ($t37C.exit -eq 0) -and (@($t37C.awaiting).Count -eq 1) -and (@($t37C.awaiting)[0] -ceq $t37Line2) -and ($t37C.arm -match 'amendment-material-am-903\.yaml names this file but binds OTHER bytes')) `
    -Said ('awaiting [' + (@($t37C.awaiting) -join ' ; ') + ']')

# (d) A REAPPROVE over the new bytes releases again; the prior gate is retired beside it, stamped.
$t37Re = Invoke-Gate -Argv @('reapprove', '-Kind', 'amendment-material', '-Id', 'am-903', '-Binds', $t37Rel, '-Reason', 'WP-4 T-37: the placement restated', '-MissionRoot', $t37Root)
$t37Bound2 = Get-T37Bound -Path $t37Gate
$t37Prior = Join-Path $t37Root '.mission\gates\amendment-material-am-903.revoked-1.yaml'
$t37D = Invoke-T37Eval -Root $t37Root
Add-T37Row -Label '(d) reapprove over the new bytes: exit 0, the new gate binds the new digest, the prior kept as .revoked-1 AND stamped revoked, MET' `
    -Ok (($t37Re.exit -eq 0) -and ($t37Bound2 -ceq $t37Sha2) -and (Test-Path -LiteralPath $t37Prior) -and ((Get-LamGateState -Path $t37Prior).revoked) -and ($t37D.verdict -ceq 'MET')) `
    -Said ('reapprove exit ' + $t37Re.exit + '; bound ' + $t37Bound2 + '; verdict ' + $t37D.verdict)

# (e) A REVOKE re-admits -- and the evaluator prescribes the verb that releases it.
$t37Rv = Invoke-Gate -Argv @('revoke', '-Kind', 'amendment-material', '-Id', 'am-903', '-Reason', 'WP-4 T-37: withdrawn', '-MissionRoot', $t37Root)
$t37Eh = Invoke-T37Eval -Root $t37Root -Hook
Add-T37Row -Label '(e) revoke: exit 0, the gate REVOKED to the shared state reader, the placement admitted again (hook approves, exit 0)' `
    -Ok (($t37Rv.exit -eq 0) -and ((Get-LamGateState -Path $t37Gate).revoked) -and ($t37Eh.verdict -ceq 'AWAITING_AMENDMENT_GATE') -and ($t37Eh.decision -ceq 'approve') -and ($t37Eh.exit -eq 0) -and (@($t37Eh.awaiting) -ccontains $t37Line2) -and ($t37Eh.arm -match 'binds these bytes and is REVOKED')) `
    -Said ('revoke exit ' + $t37Rv.exit + '; verdict ' + $t37Eh.verdict + '; the arm: ' + $t37Eh.arm)
$t37Argv = Get-T37PrescribedArgv -Arm $t37Eh.arm -Rel '.mission/amendments/AM-903-t37.yaml'
$t37ArgvText = if ($null -ne $t37Argv) { $t37Argv -join ' | ' } else { '(none parsed)' }
Add-T37Row -Label '(e) the arm PRINTS a reapprove (the canonical gate exists, so approve would be refused), with -MissionRoot this root' `
    -Ok (($null -ne $t37Argv) -and ($t37Argv[0] -ceq 'reapprove') -and ([array]::IndexOf($t37Argv, '-MissionRoot') -ge 0) -and ($t37Argv[[array]::IndexOf($t37Argv, '-MissionRoot') + 1] -ceq $t37Root)) -Said $t37ArgvText
$t37Re2 = if ($null -ne $t37Argv) { Invoke-Gate -Argv $t37Argv } else { [pscustomobject]@{ exit = 99; out = 'nothing printed' } }
$t37E2 = Invoke-T37Eval -Root $t37Root
Add-T37Row -Label '(e) running EXACTLY that printed command''s arguments through the console releases it: exit 0, MET' `
    -Ok (($t37Re2.exit -eq 0) -and ($t37E2.verdict -ceq 'MET')) -Said ('reapprove exit ' + $t37Re2.exit + '; verdict ' + $t37E2.verdict)

# (f) A CR LF PLACEMENT: the mint records the WORKING-COPY digest, the arm's line the LF/blob one, and a
#     gate over either releases (ruling (1) of 2026-09-24).
$t37CrRel = '.mission\amendments\AM-904-t37-crlf.yaml'
$t37Cr = Join-Path $t37Root $t37CrRel
[System.IO.File]::WriteAllBytes($t37Cr, (New-Object System.Text.UTF8Encoding($false)).GetBytes("id: AM-904-t37-crlf`r`nnote: carries CR LF in the working copy`r`n"))
$t37CrRaw = (Get-FileHash -Algorithm SHA256 -LiteralPath $t37Cr).Hash.ToLowerInvariant()
$t37CrLf = Get-T37LfSha -Path $t37Cr
$t37CrLine = $t37Pfx + ' am-904 ' + $t37CrLf + ' .mission/amendments/AM-904-t37-crlf.yaml'
$t37F0 = Invoke-T37Eval -Root $t37Root
Add-T37Row -Label '(f) the CR LF placement, ungated: its line carries the LF/blob digest, and the arm names both digests' `
    -Ok (($t37F0.verdict -ceq 'AWAITING_AMENDMENT_GATE') -and (@($t37F0.awaiting) -ccontains $t37CrLine) -and ($t37F0.arm -match $t37CrRaw)) `
    -Said ('awaiting [' + (@($t37F0.awaiting) -join ' ; ') + ']')
$t37CrMint = Invoke-Gate -Argv @('approve', '-Kind', 'amendment-material', '-Id', 'am-904', '-Binds', $t37CrRel, '-MissionRoot', $t37Root)
$t37CrGate = Join-Path $t37Root '.mission\gates\amendment-material-am-904.yaml'
$t37CrBound = Get-T37Bound -Path $t37CrGate
Add-T37Row -Label '(f) MEASURED the mint over it binds the WORKING-COPY digest, not the LF/blob one' `
    -Ok (($t37CrMint.exit -eq 0) -and ($t37CrRaw -cne $t37CrLf) -and ($t37CrBound -ceq $t37CrRaw)) `
    -Said ('mint exit ' + $t37CrMint.exit + '; bound ' + $t37CrBound + '; working copy ' + $t37CrRaw + '; LF/blob ' + $t37CrLf)
$t37F = Invoke-T37Eval -Root $t37Root
Add-T37Row -Label '(f) and it RELEASES the placement all the same: MET, exit 0, amendment-material-am-904.yaml named' `
    -Ok (($t37F.verdict -ceq 'MET') -and ($t37F.exit -eq 0) -and ($t37F.arm -match 'AM-904-t37-crlf\.yaml \S+ -- RELEASED by amendment-material-am-904\.yaml')) `
    -Said ('verdict ' + $t37F.verdict + '; the arm: ' + $t37F.arm)
$t37Aside = Join-Path $t37Root '.mission\gates\amendment-material-am-904 - Copy.yaml'
Move-Item -LiteralPath $t37CrGate -Destination $t37Aside
$t37F2 = Invoke-T37Eval -Root $t37Root
Move-Item -LiteralPath $t37Aside -Destination $t37CrGate
$t37F3 = Invoke-T37Eval -Root $t37Root
Add-T37Row -Label '(f) the SAME minted bytes renamed aside (" - Copy") release nothing -- only the canonical path -- and renamed back, release again' `
    -Ok (($t37F2.verdict -ceq 'AWAITING_AMENDMENT_GATE') -and (@($t37F2.awaiting) -ccontains $t37CrLine) -and ($t37F2.arm -match 'is NOT a canonical gate') -and ($t37F3.verdict -ceq 'MET')) `
    -Said ('aside: ' + $t37F2.verdict + '; back: ' + $t37F3.verdict)

# (g) COMMITTED, the placements are no longer placements, whatever their gates say.
Remove-Item -LiteralPath $t37Gate -Force
$t37Add2Args = @('add', '--', '.mission/amendments/AM-903-t37.yaml', '.mission/amendments/AM-904-t37-crlf.yaml')
$t37Add2 = Invoke-T37Git -Root $t37Root -GitArgs $t37Add2Args
$t37Commit2Args = $t37Id + @('commit', '--quiet', '-m', 'the placements committed')
$t37Commit2 = Invoke-T37Git -Root $t37Root -GitArgs $t37Commit2Args
$t37G = Invoke-T37Eval -Root $t37Root
Add-T37Row -Label '(g) both placements committed (am-903''s canonical gate removed): MET, 0 placements, 3 tracked' `
    -Ok (($t37Add2.exit -eq 0) -and ($t37Commit2.exit -eq 0) -and ($t37G.verdict -ceq 'MET') -and ($t37G.exit -eq 0) -and ($t37G.arm -match '\A0 AWAITING line\(s\)') -and ($t37G.arm -match '3 tracked file\(s\)')) `
    -Said ('verdict ' + $t37G.verdict + '; the arm: ' + $t37G.arm)
}
catch {
    Add-T37Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if (($null -ne $t37Base) -and (Test-Path -LiteralPath $t37Base)) { try { Remove-Item -LiteralPath $t37Base -Recurse -Force -ErrorAction Stop } catch { } }
Check -Id 'T-37' -Title 'THE PLACEMENT-WINDOW ARM RELEASED BY A REAL MINT (LAM-ACCEPT amendment 54, operator ruling (ii), and the operator''s rulings of 2026-09-24): through lam-console.ps1''s verified path, an amendment-material approve over an untracked LF placement records a binds_sha256 equal to the LF/blob digest the tree''s goal evaluator admits it under, and the evaluator then reads MET with that gate named; an edit re-admits it under the new digest, a reapprove over the new bytes releases it again with the prior retired and stamped, a revoke re-admits it, the evaluator then prescribes reapprove and running it releases; a mint over a CR LF placement records the working-copy digest (measured) and releases it all the same, and the same minted bytes renamed aside release nothing; committing the placements ends the admission whatever their gates say' `
      -Ok $t37ok -Detail ("      THE $(@($t37rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t37rows -join "`n"))

# =============================================================================================
# T-38 -- THE PLACEMENT-WINDOW ARM AGAINST REAL MINTS, SECOND PACKAGE (an acceptance amendment's
#         section 7; the findings of validator round 1)
# =============================================================================================
# WHY THIS IS WP-4's. Both findings are about what a REAL mint does. One: beside a committed amendment
# whose console-minted gate stands unrevoked -- the live plane's shape, an amendment and
# its amendment-material gate -- a placement named for it with a trailing dot was hashed as the neighbour
# and released by the neighbour's gate (a false MET), and the console's own approve over the name as
# written binds the NEIGHBOUR's bytes, so no mint can be printed for it. The other: over a gate the console
# minted and that was then consumed, the evaluator printed a reapprove, and the console refuses it.
# No tool consumes an amendment-material gate, so the consumption is stamped by hand, as the push
# settle writes consumed_at; everything else is minted and run through lam-console.ps1's verified path.
# Invoke-T37Eval, Invoke-T37Git, Get-T37Bound and Get-T37PrescribedArgv are T-37's, reused as they are;
# the fixture's goal is named G-T37 for that reason.
$t38ok = $true
$t38rows = New-Object System.Collections.Generic.List[string]
function Add-T38Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t38ok = $false }
    $script:t38rows.Add(('      {0,-100} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function Get-T38Sha256 {
    param([byte[]]$Bytes)
    $t38H = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($t38H.ComputeHash($Bytes))).Replace('-', '').ToLowerInvariant() } finally { $t38H.Dispose() }
}
$t38Base = $null
try {
$t38Pfx = 'AWAITING AMENDMENT GATE'
$t38Utf8 = New-Object System.Text.UTF8Encoding($false)
$t38Base = Join-Path $env:TEMP ('lam-wp4-t38-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
$t38Root = Join-Path $t38Base 'mission'
New-Item -ItemType Directory -Path $t38Root -Force | Out-Null
$t38Init = Invoke-T37Git -Root $t38Base -GitArgs @('init', '--quiet', $t38Root)
# THE GIT DIR MUST BE EXACTLY <root>\.git BEFORE git IS USED AGAIN (the 2026-09-13 rule); no git config
# is ever run here, and the commit carries its identity on the command line.
$t38Gd = Invoke-T37Git -Root $t38Root -GitArgs @('rev-parse', '--absolute-git-dir')
$t38GdPath = [System.IO.Path]::GetFullPath($t38Gd.text.Trim().Replace('/', '\'))
if (($t38Init.exit -ne 0) -or ($t38Gd.exit -ne 0) -or ($t38GdPath -ine [System.IO.Path]::GetFullPath((Join-Path $t38Root '.git')))) {
    throw ('FIXTURE REFUSED: the fixture git dir is not exactly <root>\.git (' + $t38Gd.text.Trim() + ')')
}
Write-Utf8 -Path (Join-Path $t38Root '.mission\mission.yaml') -Text "id: mission-wp4-t38`nstate: executing`n"
$t38NbRel = '.mission\amendments\AM-906-t38.yaml'
$t38Nb = Join-Path $t38Root $t38NbRel
Write-Utf8 -Path $t38Nb -Text "id: AM-906-t38`nnote: the RATIFIED text, committed`n"
New-Item -ItemType Directory -Path (Join-Path $t38Root '.mission\gates') -Force | Out-Null
$t38Id = @('-c', 'user.name=wp4-t38', '-c', 'user.email=wp4-t38@example.invalid', '-c', 'commit.gpgsign=false')
$t38AddArgs = @('add', '--', '.mission/mission.yaml', '.mission/amendments/AM-906-t38.yaml')
$t38Add = Invoke-T37Git -Root $t38Root -GitArgs $t38AddArgs
$t38SeedArgs = $t38Id + @('commit', '--quiet', '-m', 'seed')
$t38Seed = Invoke-T37Git -Root $t38Root -GitArgs $t38SeedArgs
Write-Utf8 -Path (Join-Path $t38Root '.mission\goals\G-T37.yaml') -Text "id: G-T37`ndetectors:`n  - type: ungated_placement_absent`n"
Add-T38Row -Label 'FIXTURE a git repository under %TEMP%, its git dir exactly <root>\.git, one commit tracking mission.yaml and AM-906-t38.yaml' `
    -Ok (($t38Add.exit -eq 0) -and ($t38Seed.exit -eq 0)) -Said ('add exit ' + $t38Add.exit + ', commit exit ' + $t38Seed.exit)

# (a) THE LIVE PLANE'S SHAPE: the committed amendment and its console-minted gate, unrevoked.
$t38NbMint = Invoke-Gate -Argv @('approve', '-Kind', 'amendment-material', '-Id', 'am-906', '-Binds', $t38NbRel, '-MissionRoot', $t38Root)
$t38NbSha = (Get-FileHash -Algorithm SHA256 -LiteralPath $t38Nb).Hash.ToLowerInvariant()
$t38NbGate = Join-Path $t38Root '.mission\gates\amendment-material-am-906.yaml'
$t38A = Invoke-T37Eval -Root $t38Root
Add-T38Row -Label '(a) the console mints amendment-material-am-906.yaml over the COMMITTED AM-906-t38.yaml; nothing is placed: MET' `
    -Ok (($t38NbMint.exit -eq 0) -and ((Get-T37Bound -Path $t38NbGate) -ceq $t38NbSha) -and ($t38A.verdict -ceq 'MET') -and ($t38A.exit -eq 0)) `
    -Said ('mint exit ' + $t38NbMint.exit + '; bound ' + (Get-T37Bound -Path $t38NbGate) + '; verdict ' + $t38A.verdict)

# (b) FALSIFIER: a placement named for it with a TRAILING DOT, other bytes, written by its name as written.
$t38Dot = $t38Nb + '.'
$t38DotBytes = $t38Utf8.GetBytes("id: AM-906-t38`nnote: NOT the ratified text -- its name ends in a dot`n")
$t38Fs = New-Object System.IO.FileStream(('\\?\' + $t38Dot), [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
try { $t38Fs.Write($t38DotBytes, 0, $t38DotBytes.Length) } finally { $t38Fs.Dispose() }
$t38DotSha = Get-T38Sha256 -Bytes $t38DotBytes
$t38B = Invoke-T37Eval -Root $t38Root -Hook
$t38BMine = @(@($t38B.awaiting) | Where-Object { $_ -cmatch ('\A' + [regex]::Escape($t38Pfx) + ' \S+ ' + $t38DotSha + ' \.mission/amendments/AM-906-t38\.yaml\.\z') })
Add-T38Row -Label '(b) FALSIFIER AM-906-t38.yaml. beside it is ADMITTED (hook approves, exit 0) under its OWN digest -- not released by am-906' `
    -Ok (($t38B.verdict -ceq 'AWAITING_AMENDMENT_GATE') -and ($t38B.decision -ceq 'approve') -and ($t38B.exit -eq 0) -and ($t38BMine.Count -eq 1) -and ($t38B.arm -notmatch 'RELEASED')) `
    -Said ('verdict ' + $t38B.verdict + '; awaiting [' + (@($t38B.awaiting) -join ' ; ') + ']; its own sha256 ' + $t38DotSha)
$t38BArgv = Get-T37PrescribedArgv -Arm $t38B.arm -Rel '.mission/amendments/AM-906-t38.yaml.'
Add-T38Row -Label '(b) and NO mint is printed for it' `
    -Ok (($null -eq $t38BArgv) -and $t38B.arm.Contains('no mint is printed for .mission/amendments/AM-906-t38.yaml.')) `
    -Said $(if ($null -ne $t38BArgv) { 'printed: ' + ($t38BArgv -join ' | ') } else { '' })

# (c) WHY NONE IS PRINTED, MEASURED: the console's own approve over the name as written binds the NEIGHBOUR.
$t38DotMint = Invoke-Gate -Argv @('approve', '-Kind', 'amendment-material', '-Id', 'am-906-dot', '-Binds', ($t38NbRel + '.'), '-MissionRoot', $t38Root)
$t38DotGate = Join-Path $t38Root '.mission\gates\amendment-material-am-906-dot.yaml'
$t38DotBound = Get-T37Bound -Path $t38DotGate
Add-T38Row -Label '(c) MEASURED the console''s approve with -Binds naming AM-906-t38.yaml. exits 0 and records the NEIGHBOUR''s digest, not the placement''s' `
    -Ok (($t38DotMint.exit -eq 0) -and ($t38DotBound -ceq $t38NbSha) -and ($t38DotBound -cne $t38DotSha)) `
    -Said ('mint exit ' + $t38DotMint.exit + '; bound ' + $t38DotBound + '; neighbour ' + $t38NbSha + '; placement ' + $t38DotSha)
$t38C = Invoke-T37Eval -Root $t38Root -Hook
Add-T38Row -Label '(c) FALSIFIER and that minted gate does NOT release the placement: still admitted (hook approves, exit 0), its own digest' `
    -Ok (($t38C.verdict -ceq 'AWAITING_AMENDMENT_GATE') -and ($t38C.exit -eq 0) -and (@(@($t38C.awaiting) | Where-Object { $_.Contains(' ' + $t38DotSha + ' ') }).Count -eq 1)) `
    -Said ('verdict ' + $t38C.verdict + '; awaiting [' + (@($t38C.awaiting) -join ' ; ') + ']')
[System.IO.File]::Delete('\\?\' + $t38Dot)
Remove-Item -LiteralPath $t38DotGate -Force

# (d) The other finding: a gate the console minted, then CONSUMED (stamped by hand as a push settle stamps it).
$t38Rel = '.mission\amendments\AM-905-t38.yaml'
$t38File = Join-Path $t38Root $t38Rel
Write-Utf8 -Path $t38File -Text "id: AM-905-t38`nnote: placed for T-38`n"
$t38Mint = Invoke-Gate -Argv @('approve', '-Kind', 'amendment-material', '-Id', 'am-905', '-Binds', $t38Rel, '-MissionRoot', $t38Root)
$t38Gate = Join-Path $t38Root '.mission\gates\amendment-material-am-905.yaml'
$t38D0 = Invoke-T37Eval -Root $t38Root
$t38GateText = [System.IO.File]::ReadAllText($t38Gate)
$t38NullCount = ([regex]::Matches($t38GateText, '(?m)^consumed_at: null\r?$')).Count
[System.IO.File]::WriteAllText($t38Gate, ([regex]::Replace($t38GateText, '(?m)^consumed_at: null(\r?)$', 'consumed_at: 2026-09-25T00:00:00.000Z$1')), $t38Utf8)
$t38Consumed = (Get-LamGateState -Path $t38Gate).consumed
$t38StampedSha = (Get-FileHash -Algorithm SHA256 -LiteralPath $t38Gate).Hash.ToLowerInvariant()
Add-T38Row -Label '(d) the console mints am-905 over AM-905-t38.yaml (MET), and its one consumed_at: null is stamped: CONSUMED to the shared state reader' `
    -Ok (($t38Mint.exit -eq 0) -and ($t38D0.verdict -ceq 'MET') -and ($t38NullCount -eq 1) -and $t38Consumed) `
    -Said ('mint exit ' + $t38Mint.exit + '; verdict ' + $t38D0.verdict + '; consumed_at: null lines ' + $t38NullCount + '; consumed ' + $t38Consumed)
