New-Item -ItemType Directory -Path (Join-Path $t40Root '.mission\gates') -Force | Out-Null
$t40IdArgs = @('-c', 'user.name=wp4-t40', '-c', 'user.email=wp4-t40@example.invalid', '-c', 'commit.gpgsign=false')
$t40Add = Invoke-T37Git -Root $t40Root -GitArgs @('add', '--', '.mission/mission.yaml')
