      -Ok $t40ok -Detail ("      THE $(@($t40rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t40rows -join "`n"))

# =============================================================================================
# T-41 -- THE SPAWN-LEDGER COMPOSER, tools/lam/spawn_ledger.py append (WP-D,
#         D-1; operator ruling (iv), candidate C3; the operator's WP-D
#         rulings)
# =============================================================================================
# WHY WP-4's. Ruling (iv) names a WP-4 member, and WP-4 already owns the two readers of the ledger's
# `round` (T-30), whose fixture helpers row (u) reuses as they are.
# WHAT STOOD BEFORE THIS MEMBER. No tracked tool wrote a spawn-ledger line: the runner,
# tools/lam/mission-dispatch.ps1, does not name the file, and an earlier arc's label lines were written by the
# seat's own session scratch scripts. The FALSIFIER is the composer's refusal of a label `round`; on a tree
# without the composer it reads False, and its reading says ABSENT, because that is what it finds there.
# EVERY FIXTURE LEDGER IS A FILE UNDER THIS INSTRUMENT'S SANDBOX; the live ledger is never named. Rows
# (v)-(x) build a scratch repository under %TEMP% by T-40's rule: the git dir is asserted to be exactly
# <root>\.git before git is used again, no git config is run, and the commit carries its identity on the
# command line.
$t41ok = $true
$t41rows = New-Object System.Collections.Generic.List[string]
function Add-T41Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t41ok = $false }
    $script:t41rows.Add(('      {0,-100} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
$t41Tool = Join-Path $repoRoot 'tools\lam\spawn_ledger.py'
$t41Base = Join-Path $sandbox 't41'
$t41Seed = '{"event":"spawn","seq":500,"kind":"validator","validates":"A-950","round":1}' + "`n" +
           '{"event":"complete","seq":500,"kind":"validator","validates":"A-950","round":1,"verdict":"PASS"}' + "`n"
$t41RepoBase = $null
$t41Stamp = ''
# A backslash built at run time: the surrogate rows spell their JSON escapes as ~BS~ so this file stays ASCII and holds
# no backslash-u sequence that an editing tool could decode into the character itself.
$t41Bs = [string][char]92
function Get-T41Sha {
    param([string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return '(absent)' }
    $t41H = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($t41H.ComputeHash([System.IO.File]::ReadAllBytes($Path)))).Replace('-', '').ToLowerInvariant() } finally { $t41H.Dispose() }
}
function Invoke-T41Py {
    # The composer under the interpreter T-30 resolved, stdout and stderr together, the exit code kept.
    param([string]$Tool, [string[]]$PyArgs)
    if (-not (Test-Path -LiteralPath $Tool -PathType Leaf)) {
        return [pscustomobject]@{ Code = $null; Text = ('ABSENT: ' + $Tool + ' does not exist in this tree -- nothing was composed, nothing was refused, nothing was audited') }
    }
    if (-not $t30PyExe) { return [pscustomobject]@{ Code = $null; Text = 'no Python interpreter resolved' } }
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $t41Raw = @(); $t41Code = $null
    try {
        $t41Raw = & $t30PyExe $Tool @PyArgs 2>&1
        $t41Code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prevEap }
    return [pscustomobject]@{ Code = $t41Code; Text = ((@($t41Raw) | ForEach-Object { "$_" }) -join "`n") }
}
function Invoke-T41Append {
    # ONE append against a fresh fixture ledger holding $Seed (none at all with -NoLedger), the line file
    # holding $Json exactly. Returns the exit, the text, the ledger's sha256 before and after, and its text.
    param([string]$Name, [string]$Json, [string]$Seed = $t41Seed, [string]$Tool = $t41Tool, [switch]$NoLedger)
    $t41Dir = Join-Path $t41Base $Name
    New-Item -ItemType Directory -Path $t41Dir -Force | Out-Null
    $t41Led = Join-Path $t41Dir 'spawn-ledger.jsonl'
    if (-not $NoLedger) { Write-Utf8 -Path $t41Led -Text $Seed }
    $t41Line = Join-Path $t41Dir 'line.json'
    Write-Utf8 -Path $t41Line -Text $Json
    $t41Before = Get-T41Sha $t41Led
    $t41Run = Invoke-T41Py -Tool $Tool -PyArgs @('append', '--ledger', $t41Led, '--line-file', $t41Line)
    $t41After = Get-T41Sha $t41Led
    $t41Text = if (Test-Path -LiteralPath $t41Led -PathType Leaf) { [System.IO.File]::ReadAllText($t41Led) } else { '' }
    return [pscustomobject]@{ Code = $t41Run.Code; Text = $t41Run.Text; Before = $t41Before; After = $t41After; Ledger = $t41Led; LedgerText = $t41Text; Seed = $Seed }
}
function Test-T41Refused {
    # exit 2, exactly ONE column-0 REFUSED line carrying every needle, no traceback, the ledger byte-unchanged.
    param($Run, [string[]]$Needles)
    $t41Lines = @([regex]::Matches([string]$Run.Text, '(?m)^REFUSED: .*$') | ForEach-Object { $_.Value.TrimEnd("`r") })
    $t41Pass = ($Run.Code -eq 2) -and ($t41Lines.Count -eq 1) -and ($Run.Before -eq $Run.After) -and ([string]$Run.Text -notmatch 'Traceback')
    foreach ($t41Need in $Needles) { if ($t41Pass) { $t41Pass = $t41Lines[0].Contains($t41Need) } }
    return $t41Pass
}
function Get-T41Appended {
    # exit 0, one column-0 APPENDED line, and the ledger is its seed plus EXACTLY ONE LF-terminated line equal
    # to the line the APPENDED line prints. Returns that line parsed, or $null.
    param($Run)
    if ($Run.Code -ne 0) { return $null }
    $t41Said = @([regex]::Matches([string]$Run.Text, '(?m)^APPENDED line \d+ to .*?: (\{.*\})\r?$') | ForEach-Object { $_.Groups[1].Value })
    if ($t41Said.Count -ne 1) { return $null }
    $t41All = [string]$Run.LedgerText
    if (-not $t41All.StartsWith([string]$Run.Seed, [System.StringComparison]::Ordinal)) { return $null }
    $t41New = $t41All.Substring(([string]$Run.Seed).Length)
    if (($t41New -ne ($t41Said[0] + "`n")) -or ($t41New.IndexOf("`n") -ne ($t41New.Length - 1))) { return $null }
    try { return ($t41Said[0] | ConvertFrom-Json) } catch { return $null }
}
function Get-T41Keys {
    param($Obj)
    if ($null -eq $Obj) { return @() }
    return @($Obj.PSObject.Properties | ForEach-Object { $_.Name })
}

