# ---- (v)-(x): the stamp is a committed blob, or nothing is written ----------------------------------------------
if (Test-Path -LiteralPath $t41Tool -PathType Leaf) {
    $t41RepoBase = Join-Path $env:TEMP ('lam-wp4-t41-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
    $t41Repo = Join-Path $t41RepoBase 'r'
    New-Item -ItemType Directory -Path (Join-Path $t41Repo 'tools\lam') -Force | Out-Null
    $t41Init = Invoke-T37Git -Root $t41RepoBase -GitArgs @('init', '--quiet', $t41Repo)
    $t41Gd = Invoke-T37Git -Root $t41Repo -GitArgs @('rev-parse', '--absolute-git-dir')
    $t41GdPath = [System.IO.Path]::GetFullPath($t41Gd.text.Trim().Replace('/', '\'))
    if (($t41Init.exit -ne 0) -or ($t41Gd.exit -ne 0) -or ($t41GdPath -ine [System.IO.Path]::GetFullPath((Join-Path $t41Repo '.git')))) {
        throw ('FIXTURE REFUSED: the fixture git dir is not exactly <root>\.git (' + $t41Gd.text.Trim() + ')')
    }
    # The composer's bytes with every CR LF collapsed to LF, so the scratch commit's blob is this repository's
    # blob basis whatever core.autocrlf the scratch repository inherits.
    $t41Bytes = [System.IO.File]::ReadAllBytes($t41Tool)
    $t41Lf = New-Object System.Collections.Generic.List[byte]
    for ($t41I = 0; $t41I -lt $t41Bytes.Length; $t41I++) {
        if (($t41Bytes[$t41I] -eq 13) -and (($t41I + 1) -lt $t41Bytes.Length) -and ($t41Bytes[$t41I + 1] -eq 10)) { continue }
        $t41Lf.Add($t41Bytes[$t41I])
    }
    $t41Copy = Join-Path $t41Repo 'tools\lam\spawn_ledger.py'
    [System.IO.File]::WriteAllBytes($t41Copy, $t41Lf.ToArray())
    $t41IdArgs = @('-c', 'user.name=wp4-t41', '-c', 'user.email=wp4-t41@example.invalid', '-c', 'commit.gpgsign=false')
    $t41Add = Invoke-T37Git -Root $t41Repo -GitArgs @('add', '--', 'tools/lam/spawn_ledger.py')
    $t41CommitArgs = $t41IdArgs + @('commit', '--quiet', '-m', 'the composer')
    $t41Commit = Invoke-T37Git -Root $t41Repo -GitArgs $t41CommitArgs
    $t41ScratchBlob = Invoke-T37Git -Root $t41Repo -GitArgs @('rev-parse', 'HEAD:tools/lam/spawn_ledger.py')
    $t41ScratchStamp = if ($t41ScratchBlob.exit -eq 0) { 'tools/lam/spawn_ledger.py@' + $t41ScratchBlob.text.Trim().Substring(0, 8) } else { '' }
    $t41R = Invoke-T41Append -Name 'v-scratch-committed' -Json '{"event":"spawn","seq":530,"round":1}' -Tool $t41Copy
    $t41O = Get-T41Appended -Run $t41R
    Add-T41Row -Label '(v) CONTROL the composer committed in a scratch repository: APPENDED, stamped with THAT repository''s blob of the file' `
        -Ok (($t41Add.exit -eq 0) -and ($t41Commit.exit -eq 0) -and [bool]$t41ScratchStamp -and ($null -ne $t41O) -and ($t41O.composed_by -ceq $t41ScratchStamp)) `
        -Said ('scratch stamp ' + $t41ScratchStamp + '; exit ' + $t41R.Code + ': ' + $t41R.Text)
    [System.IO.File]::AppendAllText($t41Copy, "# an edit nobody committed`n", (New-Object System.Text.UTF8Encoding($false)))
    $t41R = Invoke-T41Append -Name 'w-scratch-edited' -Json '{"event":"spawn","seq":531,"round":1}' -Tool $t41Copy
    Add-T41Row -Label '(w) the same composer edited and not committed: REFUSED, unchanged -- an uncommitted composer stamps nothing' `
        -Ok (Test-T41Refused -Run $t41R -Needles @('are not an admitted version of tools/lam/spawn_ledger.py')) -Said ("exit $($t41R.Code): " + $t41R.Text)
    $t41Loose = Join-Path $t41RepoBase 'loose\spawn_ledger.py'
    New-Item -ItemType Directory -Path (Split-Path -Parent $t41Loose) -Force | Out-Null
    [System.IO.File]::WriteAllBytes($t41Loose, $t41Lf.ToArray())
    $t41R = Invoke-T41Append -Name 'x-loose-copy' -Json '{"event":"spawn","seq":532,"round":1}' -Tool $t41Loose
    Add-T41Row -Label '(x) a byte-identical copy outside any repository: REFUSED, unchanged' `
        -Ok (Test-T41Refused -Run $t41R -Needles @('this composer is not inside a git repository')) -Said ("exit $($t41R.Code): " + $t41R.Text)
    # (x2) the copy's bytes ARE a committed blob of tools/lam/spawn_ledger.py, so only the path test can refuse it.
    $t41Other = Join-Path $t41Repo 'other\spawn_ledger.py'
    New-Item -ItemType Directory -Path (Split-Path -Parent $t41Other) -Force | Out-Null
    [System.IO.File]::WriteAllBytes($t41Other, $t41Lf.ToArray())
    $t41R = Invoke-T41Append -Name 'x2-other-path' -Json '{"event":"spawn","seq":533,"round":1}' -Tool $t41Other
    Add-T41Row -Label '(x2) a byte-identical copy INSIDE the repository at other/spawn_ledger.py, its bytes a committed blob of the composer: REFUSED by the path test' `
        -Ok (Test-T41Refused -Run $t41R -Needles @('this copy is not tools/lam/spawn_ledger.py of the repository')) -Said ("exit $($t41R.Code): " + $t41R.Text)
} else {
    Add-T41Row -Label '(v)-(x) the provenance rows: NOT RUN -- the composer is absent from this tree' -Ok $false -Said ('ABSENT: ' + $t41Tool)
}
}
catch {
    Add-T41Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
if (($null -ne $t41RepoBase) -and [System.IO.Directory]::Exists($t41RepoBase)) {
    try { Remove-Item -LiteralPath $t41RepoBase -Recurse -Force -ErrorAction Stop } catch { }
}
Check -Id 'T-41' -Title 'THE SPAWN-LEDGER COMPOSER (LAM-ACCEPT amendment 56, WP-D D-1; operator ruling (iv)): tools/lam/spawn_ledger.py append REFUSES, before a byte is written, with exit 2 and exactly one column-0 REFUSED line carrying the row''s own reason, each of these: a round that is a label, an earlier arc''s own label-plus-round_number shape, a numeral in a string, a float, true, false, null, 0 or a value beyond the gate''s [int]; a round_label with no integer round or empty; any round_number; a caller-supplied composed_by; an event other than spawn, complete or note; a key given twice; a non-object; a top-level key such as Round that the gate''s PowerShell would read as round; two keys equal ignoring case, an empty key, a key PowerShell reserves, a __type key -- at the top and nested one deep, spelled __type and __Type -- 33 or 41 containers deep, an infinite number and an integer beyond 64 bits; an unpaired surrogate in a key or in a value, which PowerShell reads as U+FFFD; a spawn line with no seq, a complete line with a string seq, or a spawn line at a seq the ledger''s spawn line already carries; a complete line binding validates with no round; a ledger not ending in LF, a ledger that does not exist, and (BATCH-4 WP-M) a note whose ts is a full stamp of another day, refused as not the clock at the write -- these, not every line it refuses; and it APPENDS exactly one line, written compact, in each of these: a pretty-printed line file, an integer round with no label (no round_label key written), a label beside an integer (both written), a worker line with no round (neither written), a note line whose ts is this instrument''s clock at the write, a line 32 containers deep, a valid surrogate pair (read back whole), a line file behind a byte-order mark -- each stamped composed_by tools/lam/spawn_ledger.py@ and the first 8 of the tree''s own blob of the file, and each read back by this PowerShell''s ConvertFrom-Json; the close-milestone roster gate and the transcription tool read a ledger it wrote; and a copy that is edited and uncommitted, outside any repository, or inside one at another path stamps nothing' `
      -Ok $t41ok -Detail ("      THE $(@($t41rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t41rows -join "`n"))

# =============================================================================================
# T-42 -- THE FORWARD-ONLY AUDIT OF THE LIVE SPAWN LEDGER, tools/lam/spawn_ledger.py audit (LAM-ACCEPT
#         WP-D, D-2; operator ruling (iv); the operator's WP-D rulings of
#         2026-09-25)
# =============================================================================================
# THE CUTOFF IS LINE 372. The ruling records "The last line at this writing is 372, and that is the boundary
# ruling (iv)'s forward-only enforcement is measured from." THE PREFIX PIN is the sha256 of those 372
# LF-terminated lines, 09a69d83...: the whole ledger's figure at an earlier revision's reading, and again at this
# member's writing, when the ledger still held 372 lines. Lines 1-372 are LEGACY: admitted without the check,
# the ones whose round is not an integer NAMED on this member's face. Every line after 372 must pass the
# composer's CHECK, carry a composed_by naming an admitted version of the composer, and be byte for byte the
# form the composer writes (its rule (11)), so a line a seat appends without that stamp, failing the CHECK or in
# any other form fails this member -- and a line written by hand that carries a copied stamp, passes the CHECK and
# is written in that exact form does not; the composer's own docstring says so. The pin also fails the member if a line at
# or before 372 is edited, inserted or removed.
# THE LIVE LEDGER IS READ AND NEVER WRITTEN. It sits in the PRIMARY checkout's gitignored runtime plane, and
# the member finds that checkout as WP-3's Get-PrimaryCheckoutRoot does (the first `worktree` line of
# `git worktree list --porcelain`, else the parent of the common git dir), so a reading from a linked worktree
# reads the file a reading at the root reads. A row whose ledger is not found FAILS and says so -- but for the two
# checkouts where no ledger can stand yet, each a named SKIP of row (L) alone: the framework repository, and a project
# whose runner has not yet written one (its primary checkout found, nothing at the ledger's path). -SpawnLedger
# names another file instead, and the member's face then says OVERRIDDEN.
$t42ok = $true
$t42Skip = ''
$t42rows = New-Object System.Collections.Generic.List[string]
$t42Cutoff = 372
$t42Pin = '09a69d8324b56548dcb47c809689d2072c9eb7c5f5581db65c6541a92e35a0e6'
function Add-T42Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t42ok = $false }
    $script:t42rows.Add(('      {0,-100} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function Get-T42PrimaryRoot {
    param([string]$From)
    $t42Root = ''
    $t42Wl = Invoke-T37Git -Root $From -GitArgs @('worktree', 'list', '--porcelain')
    if ($t42Wl.exit -eq 0) {
        foreach ($t42Line in @($t42Wl.text -split "`n")) {
            if ($t42Line -match '^worktree\s+(.+?)\s*$') { $t42Root = $Matches[1]; break }
        }
    }
    if (-not $t42Root) {
        $t42Cd = Invoke-T37Git -Root $From -GitArgs @('rev-parse', '--git-common-dir')
        if (($t42Cd.exit -eq 0) -and $t42Cd.text.Trim()) {
            $t42Cdp = $t42Cd.text.Trim()
            if (-not [System.IO.Path]::IsPathRooted($t42Cdp)) { $t42Cdp = Join-Path $From $t42Cdp }
            $t42Root = Split-Path -Parent $t42Cdp
        }
    }
    if ($t42Root -and (Test-Path -LiteralPath $t42Root)) { return (Resolve-Path -LiteralPath $t42Root).Path }
    return ''
}
function Invoke-T42Audit {
    param([string]$Ledger, [int]$After, [string]$Pin)
    return (Invoke-T41Py -Tool $t41Tool -PyArgs @('audit', '--ledger', $Ledger, '--after', ([string]$After), '--prefix-sha256', $Pin))
}
function Get-T42Lines {
    param($Run, [string]$Head)
    return @([regex]::Matches([string]$Run.Text, ('(?m)^' + [regex]::Escape($Head) + '.*$')) | ForEach-Object { $_.Value.TrimEnd("`r") })
}
function Test-T42Verdict {
    # the exit, exactly ONE column-0 RESULT line and its verdict
    param($Run, [int]$Exit, [string]$Verdict)
    $t42Res = @(Get-T42Lines -Run $Run -Head 'RESULT ')
    return (($Run.Code -eq $Exit) -and ($t42Res.Count -eq 1) -and $t42Res[0].StartsWith('RESULT ' + $Verdict + ' ', [System.StringComparison]::Ordinal) -and ([string]$Run.Text -notmatch 'Traceback'))
}
function Test-T42Violation {
    # FAIL exit 1, and exactly ONE VIOLATION line: at $Line, carrying $Needle
    param($Run, [int]$Line, [string]$Needle)
    $t42V = @(Get-T42Lines -Run $Run -Head 'VIOLATION ')
    return ((Test-T42Verdict -Run $Run -Exit 1 -Verdict 'FAIL') -and ($t42V.Count -eq 1) -and $t42V[0].StartsWith(('VIOLATION line ' + $Line + ': '), [System.StringComparison]::Ordinal) -and $t42V[0].Contains($Needle))
}
# THE FIXTURE PREFIX: four lines, the third and fourth carrying an earlier arc's label shape, cut off after line 4.
$t42Prefix = '{"event":"note","ts":"t","note":"fixture"}' + "`n" +
             '{"event":"spawn","seq":600,"kind":"validator","validates":"A-960","round":1}' + "`n" +
             '{"event":"spawn","seq":601,"kind":"validator","validates":"A-961","round":"R-FX-1","round_number":1}' + "`n" +
             '{"event":"complete","seq":601,"kind":"validator","validates":"A-961","round":"R-FX-1"}' + "`n"
$t42PrefixPin = Get-T30Sha $t42Prefix
$t42Base = Join-Path $sandbox 't42'
function Invoke-T42Fixture {
    # A fixture ledger of $Text, audited after line $After against $Pin.
    param([string]$Name, [string]$Text, [int]$After = 4, [string]$Pin = $t42PrefixPin)
    New-Item -ItemType Directory -Path $t42Base -Force | Out-Null
    $t42Led = Join-Path $t42Base ($Name + '.jsonl')
    Write-Utf8 -Path $t42Led -Text $Text
    return (Invoke-T42Audit -Ledger $t42Led -After $After -Pin $Pin)
}

try {
# ---- (L) THE LIVE LEDGER ----------------------------------------------------------------------------------------
$t42Primary = Get-T42PrimaryRoot -From $repoRoot
$t42Live = if ($SpawnLedger) { $SpawnLedger } elseif ($t42Primary) { Join-Path $t42Primary '.mission-runtime\lam\spawn-ledger.jsonl' } else { '' }
$t42rows.Add('      primary checkout: ' + $(if ($t42Primary) { $t42Primary } else { '(not found)' }) + ' ; ledger read: ' + $(if ($t42Live) { $t42Live } else { '(none)' }) + $(if ($SpawnLedger) { ' -- OVERRIDDEN by -SpawnLedger; this is NOT a reading of the live ledger' } else { '' }))
if ($t42Live -and (Test-Path -LiteralPath $t42Live -PathType Leaf)) {
    $t42A = Invoke-T42Audit -Ledger $t42Live -After $t42Cutoff -Pin $t42Pin
    foreach ($t42Said in @(Get-T42Lines -Run $t42A -Head 'AUDIT ') + @(Get-T42Lines -Run $t42A -Head 'PREFIX ') + @(Get-T42Lines -Run $t42A -Head 'LEGACY ') + @(Get-T42Lines -Run $t42A -Head 'AFTER ') + @(Get-T42Lines -Run $t42A -Head 'VIOLATION ')) {
        $t42rows.Add('        ' + $t42Said)
    }
    $t42Named = @(Get-T42Lines -Run $t42A -Head 'LEGACY line ' | ForEach-Object { if ($_ -match '^LEGACY line (\d+): ') { [int]$Matches[1] } })
    $t42Expect = @(363..372)
    $t42NamedOk = ($t42Named.Count -eq $t42Expect.Count)
    if ($t42NamedOk) { for ($t42I = 0; $t42I -lt $t42Expect.Count; $t42I++) { if ($t42Named[$t42I] -ne $t42Expect[$t42I]) { $t42NamedOk = $false } } }
    $t42Res = @(Get-T42Lines -Run $t42A -Head 'RESULT ')
    Add-T42Row -Label '(L) THE LEDGER READ after line 372: RESULT PASS, exit 0; lines 1-372 byte-equal to the pin; the ten label lines 363-372 NAMED legacy' `
        -Ok ((Test-T42Verdict -Run $t42A -Exit 0 -Verdict 'PASS') -and (@(@(Get-T42Lines -Run $t42A -Head 'PREFIX lines 1-372 ') | Where-Object { $_.EndsWith(' EQUAL') }).Count -eq 1) -and $t42NamedOk) `
        -Said ('exit ' + $t42A.Code + '; ' + $(if ($t42Res.Count -gt 0) { $t42Res -join ' ' } else { [string]$t42A.Text }) + '; legacy lines named: ' + ($t42Named -join ','))
} elseif ($isFrameworkRepo -and -not $SpawnLedger) {
    # The live ledger is the host's engagement record; the framework repository runs none of the host's
    # missions and holds no copy, so row (L) is UNMEASURED here -- a named SKIP, never a pass. Every other row stands.
    $t42Skip = 'host runtime file: row (L) reads the host''s live spawn ledger (the primary checkout''s .mission-runtime\lam\spawn-ledger.jsonl), cut after line 372 at its prefix pin -- an engagement record of the host''s own missions; this is the framework repository, which runs none of them and holds no copy'
    $t42rows.Add('      (L) THE LIVE LEDGER: SKIPPED -- ' + $t42Skip + ' ; looked for ' + $(if ($t42Live) { $t42Live } else { 'a primary checkout, and found none' }))
} elseif ($t42Primary -and -not $SpawnLedger -and -not (Test-Path -LiteralPath $t42Live)) {
    # A PROJECT WHOSE RUNNER HAS NOT DISPATCHED: the primary checkout was found and nothing stands at its ledger's
    # path, so there is no record to audit -- row (L) is UNMEASURED, a named SKIP, never a pass. Every other row stands.
    # Still a FAIL: no primary checkout found; a -SpawnLedger naming no file; anything that is not a file at that path.
    $t42Skip = 'no live spawn ledger yet: this project''s runner has not dispatched, so there is nothing to audit -- row (L) reads the primary checkout''s .mission-runtime\lam\spawn-ledger.jsonl, and no file stands there'
    $t42rows.Add('      (L) THE LIVE LEDGER: SKIPPED -- ' + $t42Skip + ' ; looked for ' + $t42Live)
} else {
    Add-T42Row -Label '(L) THE LIVE LEDGER: NOT FOUND -- this member does not pass a ledger it did not read' -Ok $false -Said ('looked for ' + $(if ($t42Live) { $t42Live } else { 'a primary checkout, and found none' }))
}
Add-T42Row -Label '(L0) the ledger read is the LIVE ledger: no -SpawnLedger was given, so this reading can stand as one' `
    -Ok (-not $SpawnLedger) -Said $(if ($SpawnLedger) { 'OVERRIDDEN by -SpawnLedger ' + $SpawnLedger + ' -- row (L) above judged that file, and this member cannot pass' } else { 'the primary checkout''s ledger' })

# ---- the fixtures: the cutoff after line 4, lines 3 and 4 a legacy label pair ----------------------------------------
$t42rows.Add('      the stamp the fixtures carry (this tree''s composer, from git): ' + $(if ($t41Stamp) { $t41Stamp } else { '(none)' }))
$t42F = Invoke-T42Fixture -Name 'f1-label-after' -Text ($t42Prefix + '{"event":"spawn","seq":602,"kind":"validator","validates":"A-962","round":"R-FX-2","composed_by":"' + $t41Stamp + '"}' + "`n")
Add-T42Row -Label '(f1) FALSIFIER a label round after the cutoff, carrying a VALID stamp: RESULT FAIL, exit 1, one VIOLATION at line 5 naming the round and not the stamp' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle "round 'R-FX-2' is not a JSON integer") -and (@(@(Get-T42Lines -Run $t42F -Head 'VIOLATION ') | Where-Object { $_.Contains('composed_by') }).Count -eq 0)) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f14-case-variant' -Text ($t42Prefix + '{"event":"spawn","seq":609,"validates":"A-969","Round":"R-FX-2","composed_by":"' + $t41Stamp + '"}' + "`n")
Add-T42Row -Label '(f14) a stamped line after the cutoff whose Round the gate''s PowerShell reads as round: FAIL at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle "the top-level key 'Round' is not written in a-z, 0-9 and _ only")) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f15-seq-reused' -Text ($t42Prefix + '{"event":"spawn","seq":601,"round":1,"composed_by":"' + $t41Stamp + '"}' + "`n")
Add-T42Row -Label '(f15) a stamped spawn line after the cutoff at seq 601, which a LEGACY spawn line carries: FAIL at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'seq 601 already has a spawn line on the ledger')) -Said ("exit $($t42F.Code): " + $t42F.Text)
# (f16)-(f19) VALIDATOR ROUND 1's FINDINGS: a line after the cutoff must be byte for byte the form the composer
# writes. Both readers split lines on CR as well as LF (the gate's ReadAllLines, the tool's text-mode read), so a CR
# between members is two broken lines to them and one good line to a reader splitting on LF alone.
$t42F = Invoke-T42Fixture -Name 'f16-cr-between-members' -Text ($t42Prefix + '{"event":"note",' + [string][char]13 + '"note":"x","composed_by":"' + $t41Stamp + '"}' + "`n")
Add-T42Row -Label '(f16) a stamped line after the cutoff with a CR between its members, which both readers split into two non-JSON lines: FAIL at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'carries a CR byte')) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f17-spaced' -Text ($t42Prefix + '{"event": "note", "note": "x", "composed_by": "' + $t41Stamp + '"}' + "`n")
Add-T42Row -Label '(f17) a stamped line after the cutoff written with spaces, valid JSON the composer never writes: FAIL at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'is not in the form the composer writes')) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f18-type-key' -Text ($t42Prefix + '{"event":"note","note":"x","meta":{"__type":{"a":1}},"composed_by":"' + $t41Stamp + '"}' + "`n")
Add-T42Row -Label '(f18) a stamped line after the cutoff carrying a nested __type object, which makes the gate refuse the whole ledger: FAIL at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle "carries the key '__type'")) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f20-surrogate-key-pair' -Text ($t42Prefix + ('{"event":"note","m":{"a~BS~ud800":1,"A~BS~udc00":2},"composed_by":"' + $t41Stamp + '"}').Replace('~BS~', $t41Bs) + "`n")
Add-T42Row -Label '(f20) a stamped line after the cutoff whose nested keys a+D800 and A+DC00 make the gate refuse the whole ledger (a validator round 2 finding): FAIL at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'an unpaired surrogate')) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f19-raw-non-ascii' -Text ($t42Prefix + '{"event":"note","note":"caf' + [string][char]0xE9 + '","composed_by":"' + $t41Stamp + '"}' + "`n")
Add-T42Row -Label '(f19) a stamped line after the cutoff holding a raw non-ASCII letter where the composer writes an escape: FAIL at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'is not in the form the composer writes')) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f2-unstamped' -Text ($t42Prefix + '{"event":"spawn","seq":603,"kind":"validator","validates":"A-963","round":1}' + "`n")
Add-T42Row -Label '(f2) an integer-round line after the cutoff with NO composed_by -- a line a seat wrote by hand: FAIL at line 5' `
    -Ok (Test-T42Violation -Run $t42F -Line 5 -Needle 'no composed_by') -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f3-fabricated-blob' -Text ($t42Prefix + '{"event":"spawn","seq":604,"round":1,"composed_by":"tools/lam/spawn_ledger.py@deadbeef"}' + "`n")
Add-T42Row -Label '(f3) a stamp naming a blob the composer never had (deadbeef): FAIL at line 5' `
    -Ok (Test-T42Violation -Run $t42F -Line 5 -Needle 'composed_by names blob deadbeef') -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f4-other-tool' -Text ($t42Prefix + '{"event":"spawn","seq":605,"round":1,"composed_by":"tools/lam/other.py@0123abcd"}' + "`n")
Add-T42Row -Label '(f4) a stamp naming another tool: FAIL at line 5' `
    -Ok (Test-T42Violation -Run $t42F -Line 5 -Needle 'does not read tools/lam/spawn_ledger.py@<8 hex>') -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f5-round-number' -Text ($t42Prefix + '{"event":"spawn","seq":606,"round":1,"round_number":1,"composed_by":"' + $t41Stamp + '"}' + "`n")
Add-T42Row -Label '(f5) a stamped line after the cutoff carrying round_number: FAIL at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'round_number 1 is present')) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f6-not-json' -Text ($t42Prefix + '{"event":"spawn","seq":607,' + "`n")
Add-T42Row -Label '(f6) a line after the cutoff that is not JSON: FAIL at line 5' `
    -Ok (Test-T42Violation -Run $t42F -Line 5 -Needle 'is not one JSON object') -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f7-empty-line' -Text ($t42Prefix + "`n")
Add-T42Row -Label '(f7) an empty line after the cutoff: FAIL at line 5' `
    -Ok (Test-T42Violation -Run $t42F -Line 5 -Needle 'an empty line') -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f8-unterminated' -Text ($t42Prefix + '{"event":"note","note":"x","composed_by":"' + $t41Stamp + '"}')
Add-T42Row -Label '(f8) a last line after the cutoff with no final LF: FAIL at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'not terminated by LF')) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f9-legacy-edited' -Text ($t42Prefix.Replace('"seq":600,"kind":"validator","validates":"A-960","round":1}', '"seq":600,"kind":"validator","validates":"A-960","round":2}'))
Add-T42Row -Label '(f9) a legacy line edited in place (round 1 to 2 at line 2), nothing after the cutoff: FAIL, the prefix DIFFERS from its pin' `
    -Ok ((Test-T42Verdict -Run $t42F -Exit 1 -Verdict 'FAIL') -and (@(@(Get-T42Lines -Run $t42F -Head 'PREFIX lines 1-4 ') | Where-Object { $_.Contains(' DIFFERS') }).Count -eq 1)) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f10-inserted-before' -Text ('{"event":"note","note":"inserted"}' + "`n" + $t42Prefix)
Add-T42Row -Label '(f10) a line inserted before the cutoff: FAIL, the prefix DIFFERS from its pin' `
    -Ok ((Test-T42Verdict -Run $t42F -Exit 1 -Verdict 'FAIL') -and (@(@(Get-T42Lines -Run $t42F -Head 'PREFIX lines 1-4 ') | Where-Object { $_.Contains(' DIFFERS') }).Count -eq 1)) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f11-short' -Text ($t42Prefix.Substring(0, $t42Prefix.LastIndexOf('{')))
Add-T42Row -Label '(f11) a ledger of 3 lines against a cutoff of 4: FAIL, fewer lines than the cutoff' `
    -Ok ((Test-T42Verdict -Run $t42F -Exit 1 -Verdict 'FAIL') -and (@(@(Get-T42Lines -Run $t42F -Head 'PREFIX FAIL: ') | Where-Object { $_.Contains('fewer than the cutoff 4') }).Count -eq 1)) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 'f12-nothing-after' -Text $t42Prefix
$t42FNamed = @(Get-T42Lines -Run $t42F -Head 'LEGACY line ')
Add-T42Row -Label '(f12) CONTROL nothing after the cutoff: PASS, exit 0, the label lines 3 and 4 NAMED legacy' `
    -Ok ((Test-T42Verdict -Run $t42F -Exit 0 -Verdict 'PASS') -and ($t42FNamed.Count -eq 2) -and ($t42FNamed[0] -like 'LEGACY line 3: *') -and ($t42FNamed[1] -like 'LEGACY line 4: *')) -Said ("exit $($t42F.Code): " + $t42F.Text)
# (f13) the line after the cutoff is COMPOSED: the composer appends it to the fixture, then the audit reads it.
New-Item -ItemType Directory -Path $t42Base -Force | Out-Null
$t42Led13 = Join-Path $t42Base 'f13-composed.jsonl'
Write-Utf8 -Path $t42Led13 -Text $t42Prefix
$t42Line13 = Join-Path $t42Base 'f13-line.json'
Write-Utf8 -Path $t42Line13 -Text '{"event":"spawn","seq":608,"kind":"validator","validates":"A-968","round":2,"round_label":"R-FX-2"}'
$t42Ap = Invoke-T41Py -Tool $t41Tool -PyArgs @('append', '--ledger', $t42Led13, '--line-file', $t42Line13)
$t42F = Invoke-T42Audit -Ledger $t42Led13 -After 4 -Pin $t42PrefixPin
Add-T42Row -Label '(f13) CONTROL a line the COMPOSER appended after the cutoff (round 2, round_label ''R-FX-2''): PASS, exit 0, one line checked' `
    -Ok (($t42Ap.Code -eq 0) -and (Test-T42Verdict -Run $t42F -Exit 0 -Verdict 'PASS') -and (@(Get-T42Lines -Run $t42F -Head 'RESULT PASS after_cutoff=1 ')).Count -eq 1) `
    -Said ("append exit $($t42Ap.Code); audit exit $($t42F.Code): " + $t42F.Text)
}
catch {
    Add-T42Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
$t42Title = 'THE FORWARD-ONLY AUDIT OF THE SPAWN LEDGER (LAM-ACCEPT amendment 56, WP-D D-2; operator ruling (iv); the operator''s WP-D rulings of 2026-09-25): tools/lam/spawn_ledger.py audit over the LIVE ledger in the primary checkout, cut off after line 372, PASSES, with lines 1-372 byte-equal to their pinned sha256 and the ten whose round is a label, lines 363-372, NAMED legacy on this face, and the member cannot pass when -SpawnLedger names another file; and over fixtures it FAILS a label round after the cutoff that carries a valid stamp -- naming the round and not the stamp -- a line with no composed_by, a stamp naming a blob the composer never had or another tool, a round_number, a top-level Round, a __type key, nested keys holding unpaired surrogates, a spawn line reusing a legacy seq, a line not written in the composer''s own form -- a CR between its members, spaces, a raw non-ASCII letter -- a line that is not JSON, an empty line, an unterminated last line, a legacy line edited or one inserted before the cutoff, and a ledger shorter than the cutoff; while it PASSES a line the composer appended and a ledger with nothing after the cutoff'
$t42Detail = "      THE $(@($t42rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t42rows -join "`n")
if ($t42ok -and $t42Skip) {
    Check -Id 'T-42' -Title ($t42Title + '   [SKIPPED -- ' + $t42Skip + ']') -Ok $false -Skipped -Detail ("      SKIPPED: " + $t42Skip + "`n" + $t42Detail)
} else {
    Check -Id 'T-42' -Title $t42Title -Ok $t42ok -Detail $t42Detail
}

# =============================================================================================
# T-43 -- THE COMPOSER BINDS THE PLACED COPY, AND GIVES THE RUNNER'S REFUSAL NOTE A FORM (BATCH-2 WP-G:
#         "the composer binds the COPY's sha256 on the complete line (the
#         source's beside it)")
# =============================================================================================
# THE INTERFACE THIS MEMBER HOLDS. The goal's validator_pass_count counts a PASS file at tests/lam only
# if Test-LamLedgerBound (tools/lam/lam-verify-admission.ps1, never edited by this package) finds a complete line whose
# result_sha256 equals the file's sha256. So result_sha256 keeps its name and its meaning -- the sha256 of the COPY at
# tests/lam -- and the placement's other facts ride NEW sibling fields: result_source_sha256, result_source_path and
# result_dest_path. A complete line declaring any of them must carry all of them and result_sha256, both hashes 64
# lowercase hex and EQUAL; and at APPEND, the moment of the act, the composer re-derives the file at result_dest_path
# and refuses it absent or holding other bytes. The AUDIT applies the line's own half only: an audit reads a ledger
# later, when a placed copy may since have been archived, so it does not re-read the destination (row (p) reads that).
# THE RUNNER'S REFUSAL NOTE gets a form: a note carrying `refusal` carries a token of A-Z, 0-9 and single hyphens, a
# non-empty dispatch_id and reason, and an integer runner_exit -- at append and at audit.
# EVERY FILE IS UNDER THIS INSTRUMENT'S SANDBOX; the live ledger is never named. The composer is the tree's own
# (T-41's $t41Tool, under T-30's interpreter); the stamp the audit rows copy is T-41's $t41Stamp, from git.
$t43ok = $true
$t43rows = New-Object System.Collections.Generic.List[string]
function Add-T43Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t43ok = $false }
    $script:t43rows.Add(('      {0,-104} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
$t43Base = Join-Path $sandbox 't43'
function New-T43Complete {
    # A validator complete line in the new form; -Drop removes named fields, to build the partial set.
    param([int]$Seq, [string]$Sha, [string]$SrcSha, [string]$SrcPath, [string]$DstPath, [string[]]$Drop = @())
    $t43Rec = [ordered]@{
        event = 'complete'; seq = $Seq; kind = 'validator'; validates = 'A-970'; round = 1; verdict = 'PASS'
        result_path = 'tests/lam/validator-A-970.result.yaml'; result_sha256 = $Sha; result_source_sha256 = $SrcSha
        result_source_path = $SrcPath; result_dest_path = $DstPath
    }
    foreach ($t43D in $Drop) { $t43Rec.Remove($t43D) }
    return ($t43Rec | ConvertTo-Json -Compress)
}
try {
New-Item -ItemType Directory -Path $t43Base -Force | Out-Null
# THE PLACEMENT'S FILES: a source in a validator's tree and its copy at a root's tests/lam (the same bytes); a destination
# holding OTHER bytes, a prior round's result at the same name; and a destination nothing was ever written to.
$t43Src     = Join-Path $t43Base 'wt\tests\lam\validator-A-970.result.yaml'
$t43Dst     = Join-Path $t43Base 'root\tests\lam\validator-A-970.result.yaml'
$t43Other   = Join-Path $t43Base 'root\tests\lam\validator-A-971.result.yaml'
$t43Missing = Join-Path $t43Base 'root\tests\lam\validator-A-972.result.yaml'
Write-Utf8 -Path $t43Src -Text "# the T-43 fixture result`nid: validator-A-970`nverdict: PASS`n"
Write-Utf8 -Path $t43Dst -Text "# the T-43 fixture result`nid: validator-A-970`nverdict: PASS`n"
Write-Utf8 -Path $t43Other -Text "# a prior round's result at the same name`nid: validator-A-971`nverdict: REFUTED`n"
$t43Sha = Get-T41Sha $t43Dst
$t43OtherSha = Get-T41Sha $t43Other
$t43rows.Add('      the copy and its source: ' + $t43Sha + ' (both); the other bytes: ' + $t43OtherSha + '; the stamp the audit rows copy: ' + $(if ($t41Stamp) { $t41Stamp } else { '(none)' }))

# ---- C1: append --------------------------------------------------------------------------------------------------
$t43R = Invoke-T41Append -Name 't43-a-new-form' -Json (New-T43Complete -Seq 700 -Sha $t43Sha -SrcSha $t43Sha -SrcPath $t43Src -DstPath $t43Dst)
$t43O = Get-T41Appended -Run $t43R
Add-T43Row -Label '(a) CONTROL a validator complete binding the copy: result_sha256 the copy''s, result_source_sha256 beside it, EQUAL, both paths -- APPENDED' `
    -Ok (($null -ne $t43O) -and ([string]$t43O.result_sha256 -ceq $t43Sha) -and ([string]$t43O.result_source_sha256 -ceq $t43Sha) -and
         ([string]$t43O.result_source_path -ceq $t43Src) -and ([string]$t43O.result_dest_path -ceq $t43Dst) -and ($t43O.composed_by -ceq $t41Stamp) -and [bool]$t41Stamp) `
    -Said ("exit $($t43R.Code): " + $t43R.Text)
$t43R = Invoke-T41Append -Name 't43-b-differ' -Json (New-T43Complete -Seq 701 -Sha $t43Sha -SrcSha $t43OtherSha -SrcPath $t43Src -DstPath $t43Dst)
Add-T43Row -Label '(b) FALSIFIER the two hashes DIFFER (the source''s is another file''s): REFUSED, the ledger unchanged' `
    -Ok (Test-T41Refused -Run $t43R -Needles @('differ: the copy the line binds is not the source')) -Said ("exit $($t43R.Code): " + $t43R.Text)
$t43R = Invoke-T41Append -Name 't43-c-absent' -Json (New-T43Complete -Seq 702 -Sha $t43Sha -SrcSha $t43Sha -SrcPath $t43Src -DstPath $t43Missing)
Add-T43Row -Label '(c) FALSIFIER the DESTINATION ABSENT -- no file at result_dest_path: REFUSED, the ledger unchanged' `
    -Ok (Test-T41Refused -Run $t43R -Needles @('no file at result_dest_path')) -Said ("exit $($t43R.Code): " + $t43R.Text)
$t43R = Invoke-T41Append -Name 't43-d-other-bytes' -Json (New-T43Complete -Seq 703 -Sha $t43Sha -SrcSha $t43Sha -SrcPath $t43Src -DstPath $t43Other)
Add-T43Row -Label '(d) FALSIFIER the destination holds OTHER bytes than result_sha256 (a prior round''s file): REFUSED naming the hash it found' `
    -Ok (Test-T41Refused -Run $t43R -Needles @(('hashes to ' + $t43OtherSha), 'not result_sha256')) -Said ("exit $($t43R.Code): " + $t43R.Text)
$t43R = Invoke-T41Append -Name 't43-e-partial' -Json (New-T43Complete -Seq 704 -Sha $t43Sha -SrcSha $t43Sha -SrcPath $t43Src -DstPath $t43Dst -Drop @('result_source_path'))
Add-T43Row -Label '(e) a PARTIAL placement set (result_source_path missing): REFUSED naming the field' `
    -Ok (Test-T41Refused -Run $t43R -Needles @('a complete line declaring a placement carries no result_source_path')) -Said ("exit $($t43R.Code): " + $t43R.Text)
$t43R = Invoke-T41Append -Name 't43-f-not-hex' -Json (New-T43Complete -Seq 705 -Sha ($t43Sha.ToUpperInvariant()) -SrcSha ($t43Sha.ToUpperInvariant()) -SrcPath $t43Src -DstPath $t43Dst)
Add-T43Row -Label '(f) the hashes written in UPPER-CASE hex: REFUSED, 64 lowercase hex required' `
    -Ok (Test-T41Refused -Run $t43R -Needles @('is not 64 lowercase hex')) -Said ("exit $($t43R.Code): " + $t43R.Text)
$t43R = Invoke-T41Append -Name 't43-g-old-form' -Json ('{"event":"complete","seq":706,"kind":"validator","validates":"A-970","round":1,"verdict":"PASS","result_sha256":"' + $t43Sha + '"}')
Add-T43Row -Label '(g) RESIDUAL, READ: a complete line in the OLD form -- result_sha256 and no placement field -- is still APPENDED (the ceremony''s brief retires it)' `
    -Ok ($null -ne (Get-T41Appended -Run $t43R)) -Said ("exit $($t43R.Code): " + $t43R.Text)
$t43R = Invoke-T41Append -Name 't43-h-refusal-note' -Json '{"event":"note","dispatch_id":"D-T43","outcome":"REFUSED-BEFORE-SPAWN","refusal":"LOGIN-PROBE-NOT-OK","runner_exit":7,"reason":"the probe answered NOT OK"}'
Add-T43Row -Label '(h) CONTROL the runner''s refusal note -- refusal token, dispatch_id, integer runner_exit, reason: APPENDED' `
    -Ok ($null -ne (Get-T41Appended -Run $t43R)) -Said ("exit $($t43R.Code): " + $t43R.Text)
foreach ($t43Case in @(
        @('t43-i-no-reason', '{"event":"note","dispatch_id":"D-T43","refusal":"LOGIN-PROBE-EMPTY","runner_exit":7}', 'a refusal note carries no reason', '(i) FALSIFIER a refusal note with NO reason: REFUSED'),
        @('t43-j-exit-string', '{"event":"note","dispatch_id":"D-T43","refusal":"LOGIN-PROBE-EMPTY","runner_exit":"7","reason":"x"}', "a refusal note's runner_exit '7' is not a JSON integer", '(j) FALSIFIER a refusal note whose runner_exit is the string "7": REFUSED'),
        @('t43-k-token-case', '{"event":"note","dispatch_id":"D-T43","refusal":"login-probe-not-ok","runner_exit":7,"reason":"x"}', "a refusal note's refusal 'login-probe-not-ok'", '(k) FALSIFIER a refusal token in lower case: REFUSED'),
        @('t43-l-no-dispatch', '{"event":"note","refusal":"RESULT-PLACEMENT-DESTINATION-PRESENT","runner_exit":3,"reason":"x"}', 'a refusal note carries no dispatch_id', '(l) FALSIFIER a refusal note naming NO dispatch_id: REFUSED'))) {
    $t43R = Invoke-T41Append -Name $t43Case[0] -Json $t43Case[1]
    Add-T43Row -Label $t43Case[3] -Ok (Test-T41Refused -Run $t43R -Needles @($t43Case[2])) -Said ("exit $($t43R.Code): " + $t43R.Text)
}

# ---- C2: the forward-only audit over new-form lines ------------------------------------------------------------------
New-Item -ItemType Directory -Path $t42Base -Force | Out-Null
$t43Led = Join-Path $t42Base 't43-m-composed.jsonl'
Write-Utf8 -Path $t43Led -Text $t42Prefix
$t43Appends = @()
foreach ($t43Json in @(
        (New-T43Complete -Seq 700 -Sha $t43Sha -SrcSha $t43Sha -SrcPath $t43Src -DstPath $t43Dst),
        '{"event":"note","dispatch_id":"D-T43","outcome":"REFUSED-BEFORE-SPAWN","refusal":"LOGIN-PROBE-NOT-OK","runner_exit":7,"reason":"the probe answered NOT OK"}',
        '{"event":"spawn","seq":711,"kind":"validator","validates":"A-971","round":2,"round_label":"R-FX-3"}')) {
    $t43LineFile = Join-Path $t42Base 't43-m-line.json'
    Write-Utf8 -Path $t43LineFile -Text $t43Json
    $t43Appends += (Invoke-T41Py -Tool $t41Tool -PyArgs @('append', '--ledger', $t43Led, '--line-file', $t43LineFile)).Code
}
$t43A = Invoke-T42Audit -Ledger $t43Led -After 4 -Pin $t42PrefixPin
Add-T43Row -Label '(m) C2 CONTROL a ledger carrying a new-form complete, a refusal note and a spawn line, each APPENDED by the composer after the cutoff: the audit PASSES' `
    -Ok ((($t43Appends -join ',') -ceq '0,0,0') -and (Test-T42Verdict -Run $t43A -Exit 0 -Verdict 'PASS') -and (@(Get-T42Lines -Run $t43A -Head 'RESULT PASS after_cutoff=3 ').Count -eq 1)) `
    -Said ("appends exit $($t43Appends -join ','); audit exit $($t43A.Code): " + (@(Get-T42Lines -Run $t43A -Head 'RESULT ') -join ' '))
$t43Hand = '{"event":"complete","seq":712,"kind":"validator","validates":"A-970","round":1,"verdict":"PASS","result_path":"tests/lam/validator-A-970.result.yaml","result_sha256":"' + $t43Sha + '","result_source_sha256":"' + $t43OtherSha + '","result_source_path":"C:/t43/wt/src.yaml","result_dest_path":"C:/t43/root/dst.yaml","composed_by":"' + $t41Stamp + '"}'
$t42F = Invoke-T42Fixture -Name 't43-n-differ' -Text ($t42Prefix + $t43Hand + "`n")
Add-T43Row -Label '(n) FALSIFIER a stamped complete after the cutoff, in the composer''s own form, whose two hashes DIFFER: FAIL, one VIOLATION at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'differ: the copy the line binds is not the source')) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t42F = Invoke-T42Fixture -Name 't43-o-no-reason' -Text ($t42Prefix + '{"event":"note","dispatch_id":"D-T43","refusal":"LOGIN-PROBE-EMPTY","runner_exit":7,"composed_by":"' + $t41Stamp + '"}' + "`n")
Add-T43Row -Label '(o) FALSIFIER a stamped refusal note after the cutoff with NO reason: FAIL, one VIOLATION at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'a refusal note carries no reason')) -Said ("exit $($t42F.Code): " + $t42F.Text)
Remove-Item -LiteralPath $t43Dst -Force
$t43A2 = Invoke-T42Audit -Ledger $t43Led -After 4 -Pin $t42PrefixPin
Add-T43Row -Label '(p) READ the audit is the line''s own half: with the placed copy since removed, the same ledger still PASSES (append re-derives the file; audit does not)' `
    -Ok ((-not (Test-Path -LiteralPath $t43Dst)) -and (Test-T42Verdict -Run $t43A2 -Exit 0 -Verdict 'PASS')) -Said ("audit exit $($t43A2.Code): " + (@(Get-T42Lines -Run $t43A2 -Head 'RESULT ') -join ' '))
}
catch {
    Add-T43Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
Check -Id 'T-43' -Title 'THE COMPOSER BINDS THE PLACED COPY (BATCH-2 WP-G): tools/lam/spawn_ledger.py append takes a validator complete line carrying result_sha256 -- the COPY''s sha256, the field Test-LamLedgerBound reads, name and meaning unchanged -- with result_source_sha256, result_source_path and result_dest_path beside it, and REFUSES, before a byte is written, one whose two hashes differ, whose destination is absent, whose destination holds other bytes, whose placement set is partial, or whose hashes are not 64 lowercase hex; it takes the runner''s refusal note with its refusal token, dispatch_id, integer runner_exit and reason, and refuses one missing its reason or its dispatch_id, with a string runner_exit or a lower-case token; and the forward-only audit PASSES a ledger carrying such lines appended after the cutoff and FAILS a stamped line after it whose two hashes differ or whose refusal note has no reason -- the audit judging the line alone, so an archived copy does not fail it; an old-form complete line with no placement field is still appended, a residual read here' `
      -Ok $t43ok -Detail ("      THE $(@($t43rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t43rows -join "`n"))

# =============================================================================================
# T-44 -- THE COMPOSER GIVES A REFUSAL ON A COMPLETE LINE ITS FORM, AND THE TWO READERS SET THAT LINE ASIDE
#         (BATCH-3 WP-K: "The composer admits that line under its rules; the
#         close CLI's roster gate, as cured by an earlier revision, sets it aside as a line that binds no result")
# =============================================================================================
# THE LINE. A validator session that exits leaving no result is refused by the runner under a NAMED code,
# NO-RESULT-AT-SESSION-END-<CODE> (WP-2 R-55 drives the runner). The runner writes ONE note for it (rule (13), as for
# its other two refusals); the complete line stays the ceremony's and carries the same code in `refusal`, the
# runner's sentence in `reason`, beside the null result of live line 428. NO FIELD IS ADDED TO THE LEDGER: `refusal`,
# `reason`, `dispatch_id` and `runner_exit` are rule (13)'s, and result_sha256 keeps its name and its meaning.
# RULE (14) gives that complete line its form: a complete line that carries `refusal` carries rule (13)'s token,
# dispatch_id, reason and integer runner_exit, and BINDS NO RESULT -- result_sha256 absent or JSON null, and none of
# rule (12)'s placement fields -- at append and at audit. A complete line with no `refusal` is not checked by it; a
# BARE null-result line -- result_sha256 JSON null and no `refusal` -- is refused at APPEND since BATCH-4 WP-M (row
# (k) here, and T-48), by a rule the audit does not apply.
# THE READERS are the tree's own (T-30's harness): the roster gate and the transcription tool's bare-id path, over
# a ledger written ONLY by the composer. EVERY FILE IS UNDER THIS INSTRUMENT'S SANDBOX; the live ledger is never named.
$t44ok = $true
$t44rows = New-Object System.Collections.Generic.List[string]
function Add-T44Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t44ok = $false }
    $script:t44rows.Add(('      {0,-104} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function New-T44Complete {
    # The ceremony's complete line for a validator that left no result: live line 428's null form, with the runner's
    # refusal beside it. -Set replaces or adds named fields; -Drop removes them.
    param([int]$Seq, [string]$Aid = 'A-980', [int]$Round = 1, [hashtable]$Set = @{}, [string[]]$Drop = @())
    $t44Rec = [ordered]@{
        event = 'complete'; seq = $Seq; kind = 'validator'; role = 'qa-validator'; dispatch_id = "D-V-$Aid-$Seq"; validates = $Aid; round = $Round
        result_path = $null; result_bytes = $null; result_sha256 = $null
        refusal = 'NO-RESULT-AT-SESSION-END-BOUND-ELAPSED'
        reason = 'no result stood at tests/lam/validator-' + $Aid + '.result.yaml when the session exited; 2 descendants alive (pid 4242 powershell, pid 4243 conhost); the 300 s bound ELAPSED with 2 still alive'
        worker_exit_code = 0; runner_exit = 3
    }
    foreach ($t44K in $Set.Keys) { $t44Rec[$t44K] = $Set[$t44K] }
    foreach ($t44D in $Drop) { $t44Rec.Remove($t44D) }
    return ($t44Rec | ConvertTo-Json -Compress)
}
try {
$t44Sha = Get-T30Sha 'the T-44 fixture bytes'
# ---- C1: append --------------------------------------------------------------------------------------------------
$t44R = Invoke-T41Append -Name 't44-a-note' -Json '{"event":"note","dispatch_id":"D-V-A-980-720","outcome":"NO-RESULT-AT-SESSION-END","refusal":"NO-RESULT-AT-SESSION-END-DESCENDANTS-ENDED","runner_exit":3,"reason":"no result stood at the source when the session exited","descendants_seen":2,"descendant_pids":[4242,4243],"wait_bound_seconds":300,"waited_ms":3120,"bound_elapsed":false,"register_row":365}'
Add-T44Row -Label '(a) CONTROL the runner''s note for a session that left no result -- rule (13)''s token, dispatch_id, integer runner_exit, reason: APPENDED' `
    -Ok ($null -ne (Get-T41Appended -Run $t44R)) -Said ("exit $($t44R.Code): " + $t44R.Text)
$t44R = Invoke-T41Append -Name 't44-b-refusal-complete' -Json (New-T44Complete -Seq 720)
$t44O = Get-T41Appended -Run $t44R
Add-T44Row -Label '(b) CONTROL the complete line of that session: the null result of live line 428, the refusal and its reason beside it -- APPENDED, stamped' `
    -Ok (($null -ne $t44O) -and ($null -eq $t44O.result_sha256) -and ([string]$t44O.refusal -ceq 'NO-RESULT-AT-SESSION-END-BOUND-ELAPSED') -and ($t44O.runner_exit -eq 3) -and ($t44O.composed_by -ceq $t41Stamp) -and [bool]$t41Stamp) `
    -Said ("exit $($t44R.Code): " + $t44R.Text)
foreach ($t44Case in @(
        @('t44-c-no-reason', (New-T44Complete -Seq 721 -Drop @('reason')), 'a complete line naming a refusal carries no reason', '(c) FALSIFIER a complete line naming a refusal with NO reason: REFUSED, the ledger unchanged'),
        @('t44-d-token-case', (New-T44Complete -Seq 722 -Set @{ refusal = 'no-result-at-session-end' }), "a complete line's refusal 'no-result-at-session-end' is not a token", '(d) FALSIFIER its refusal token in lower case: REFUSED'),
        @('t44-e-exit-string', (New-T44Complete -Seq 723 -Set @{ runner_exit = '3' }), "a runner_exit '3' that is not a JSON integer", '(e) FALSIFIER its runner_exit the string "3": REFUSED'),
        @('t44-f-no-dispatch', (New-T44Complete -Seq 724 -Drop @('dispatch_id')), 'a complete line naming a refusal carries no dispatch_id', '(f) FALSIFIER it names NO dispatch_id: REFUSED'),
        @('t44-g-binds', (New-T44Complete -Seq 725 -Set @{ result_sha256 = $t44Sha }), 'a line that names a refusal binds no result', '(g) FALSIFIER a complete line that names a refusal AND binds a result (result_sha256 64 hex): REFUSED -- it cannot be both'),
        @('t44-h-empty-string', (New-T44Complete -Seq 726 -Set @{ result_sha256 = '' }), 'a line that names a refusal binds no result', '(h) FALSIFIER result_sha256 the EMPTY STRING beside a refusal: REFUSED -- neither null nor absent (amendment 61''s (D3))'),
        @('t44-i-placement', (New-T44Complete -Seq 727 -Set @{ result_dest_path = 'C:/t44/root/dst.yaml' }), 'a line that names a refusal declares no placement', '(i) FALSIFIER a complete line that names a refusal AND declares a placement field: REFUSED'))) {
    $t44R = Invoke-T41Append -Name $t44Case[0] -Json $t44Case[1]
    Add-T44Row -Label $t44Case[3] -Ok (Test-T41Refused -Run $t44R -Needles @($t44Case[2])) -Said ("exit $($t44R.Code): " + $t44R.Text)
