Add-T44Row -Label '(k) FALSIFIER a BARE null-result complete line -- live line 428''s form, a null_reason and no refusal -- is REFUSED at append: a complete line whose result_sha256 is JSON null names its refusal (BATCH-4 WP-M; this row read the bare line APPENDED, a residual, until then)' `
    -Ok (Test-T41Refused -Run $t44R -Needles @('a complete line whose result_sha256 is JSON null carries no refusal')) -Said ("exit $($t44R.Code): " + $t44R.Text)

# ---- C2: the forward-only audit ------------------------------------------------------------------------------------
New-Item -ItemType Directory -Path $t42Base -Force | Out-Null
$t44Led = Join-Path $t42Base 't44-l-composed.jsonl'
Write-Utf8 -Path $t44Led -Text $t42Prefix
$t44Appends = @()
foreach ($t44Json in @(
        '{"event":"spawn","seq":730,"kind":"validator","dispatch_id":"D-V-A-980-730","validates":"A-980","round":1}',
        '{"event":"note","dispatch_id":"D-V-A-980-730","outcome":"NO-RESULT-AT-SESSION-END","refusal":"NO-RESULT-AT-SESSION-END-NO-DESCENDANTS","runner_exit":3,"reason":"no result stood at the source when the session exited"}',
        (New-T44Complete -Seq 730))) {
