$t44A = Invoke-T42Audit -Ledger $t44Led -After 4 -Pin $t42PrefixPin
Add-T44Row -Label '(l) C2 CONTROL a ledger carrying the spawn, the runner''s note and the complete line naming the refusal, each APPENDED after the cutoff: the audit PASSES' `
    -Ok ((($t44Appends -join ',') -ceq '0,0,0') -and (Test-T42Verdict -Run $t44A -Exit 0 -Verdict 'PASS') -and (@(Get-T42Lines -Run $t44A -Head 'RESULT PASS after_cutoff=3 ').Count -eq 1)) `
    -Said ("appends exit $($t44Appends -join ','); audit exit $($t44A.Code): " + (@(Get-T42Lines -Run $t44A -Head 'RESULT ') -join ' '))
$t44Hand = '{"event":"complete","seq":731,"kind":"validator","dispatch_id":"D-V-A-980-731","validates":"A-980","round":1,"result_sha256":null,"refusal":"NO-RESULT-AT-SESSION-END-NO-DESCENDANTS","runner_exit":3,"composed_by":"' + $t41Stamp + '"}'
$t42F = Invoke-T42Fixture -Name 't44-m-no-reason' -Text ($t42Prefix + $t44Hand + "`n")
Add-T44Row -Label '(m) FALSIFIER a stamped complete after the cutoff, in the composer''s own form, naming a refusal with NO reason: FAIL, one VIOLATION at line 5' `
    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'a complete line naming a refusal carries no reason')) -Said ("exit $($t42F.Code): " + $t42F.Text)
$t44Hand = '{"event":"complete","seq":732,"kind":"validator","dispatch_id":"D-V-A-980-732","validates":"A-980","round":1,"result_sha256":"' + $t44Sha + '","refusal":"NO-RESULT-AT-SESSION-END-NO-DESCENDANTS","runner_exit":3,"reason":"x","composed_by":"' + $t41Stamp + '"}'
$t42F = Invoke-T42Fixture -Name 't44-n-binds' -Text ($t42Prefix + $t44Hand + "`n")
