    -Ok ([bool]$t41Stamp -and (Test-T42Violation -Run $t42F -Line 5 -Needle 'a line that names a refusal binds no result')) -Said ("exit $($t42F.Code): " + $t42F.Text)

# ---- C3: THE READERS, over ledgers written ONLY by the composer ----------------------------------------------------------
function New-T44ReaderRoot {
    # T-30's scratch root with an EMPTY ledger, then every line through the tree's composer. Returns the root and the
    # append exits. -Lines: JSON texts, in order.
    param([string]$Name, [string]$Aid, [string[]]$Lines)
    $t44Res = @{}
    $t44Res[$Aid] = (Get-T30ResultText -Aid $Aid -Verdict 'PASS')
    $t44Root = New-T30MissionRoot -Name $Name -Roster @($Aid) -Lines @() -Results $t44Res
    $t44RootLed = Join-Path $t44Root '.mission-runtime\lam\spawn-ledger.jsonl'
    Write-Utf8 -Path $t44RootLed -Text ''
    $t44Exits = @()
    foreach ($t44L in $Lines) {
        $t44F = Join-Path $t44Root 't44-line.json'
        Write-Utf8 -Path $t44F -Text $t44L
        $t44Exits += (Invoke-T41Py -Tool $t41Tool -PyArgs @('append', '--ledger', $t44RootLed, '--line-file', $t44F)).Code
    }
    return [pscustomobject]@{ root = $t44Root; exits = ($t44Exits -join ','); sha = (Get-T30Sha $t44Res[$Aid]) }
}
function New-T44Bound {
    param([int]$Seq, [string]$Aid, [int]$Round)
    return ('{"event":"complete","seq":' + $Seq + ',"kind":"validator","role":"qa-validator","dispatch_id":"D-V-' + $Aid + '-' + $Seq + '","validates":"' + $Aid + '","round":' + $Round + ',"verdict":"PASS","result_sha256":"' + (Get-T30Sha (Get-T30ResultText -Aid $Aid -Verdict 'PASS')) + '","result_path":"tests/lam/validator-' + $Aid + '.result.yaml","tip_judged":"' + $t30Tip + '"}')
}
function New-T44Spawn {
    param([int]$Seq, [string]$Aid, [int]$Round)
    return ('{"event":"spawn","seq":' + $Seq + ',"kind":"validator","dispatch_id":"D-V-' + $Aid + '-' + $Seq + '","validates":"' + $Aid + '","round":' + $Round + '}')
}
# An earlier arc's A-596 shape: the refusal line (seq 741) and the bound line (seq 742) at the SAME round.
$t44P = New-T44ReaderRoot -Name 't44-same-round' -Aid 'A-981' -Lines @(
    (New-T44Spawn -Seq 741 -Aid 'A-981' -Round 2), (New-T44Complete -Seq 741 -Aid 'A-981' -Round 2),
    (New-T44Spawn -Seq 742 -Aid 'A-981' -Round 2), (New-T44Bound -Seq 742 -Aid 'A-981' -Round 2))
$t44G = Invoke-T30Gate -Root $t44P.root
Add-T44Row -Label '(o) READERS the roster gate over a composer-written ledger, the refusal line beside a bound line at the same round: PERMITS, the [PASS] line naming it SET ASIDE' `
    -Ok (($t44P.exits -ceq '0,0,0,0') -and ($t44G.Code -eq 0) -and ($t44G.Text -match 'roster gate PERMITS M-99') -and ($t44G.Text -match "(?m)^.*\[PASS\] roster closable: .*SET ASIDE, claiming no round: 1 'complete' line\(s\) that bind no result -- A-981 seq 741 \(round 2\)\.") -and ($t44G.Text -notmatch $t30Crash)) `
    -Said ("appends exit $($t44P.exits); gate exit $($t44G.Code): " + ((Get-T30Line -Text $t44G.Text -Pattern '^.*(roster closable|PERMITS|REFUSED).*$') -join ' // '))
New-Item -ItemType Directory -Path (Join-Path $t44P.root '.mission\validator-results') -Force | Out-Null
Write-Utf8 -Path (Join-Path $t44P.root '.mission\validator-results\manifest.json') -Text "{`"entries`": []}`n"
$t44T = Invoke-T30Transcribe -Root $t44P.root -Target 'A-981'
Add-T44Row -Label '(p) READERS the transcription tool''s bare-id path over the same ledger: it resolves the bound seq 742 and names seq 741 SET ASIDE' `
    -Ok (($t44T.Code -eq 0) -and ($t44T.Text -match 'A-981\s+seq 742\s') -and ($t44T.Text -match 'SET ASIDE, claiming no round: 1 complete line\(s\) that bind no result -- seq 741 \(round 2\)') -and ($t44T.Text -notmatch $t30Crash)) `
    -Said ("exit $($t44T.Code): " + ((Get-T30Line -Text $t44T.Text -Pattern '^.*(A-981|SET ASIDE|STOP).*$') -join ' // '))
# FAIL-CLOSED KEPT: the refusal line ALONE at the highest round, over an older bound round.
$t44Q = New-T44ReaderRoot -Name 't44-higher-round' -Aid 'A-982' -Lines @(
    (New-T44Spawn -Seq 751 -Aid 'A-982' -Round 1), (New-T44Bound -Seq 751 -Aid 'A-982' -Round 1),
    (New-T44Spawn -Seq 752 -Aid 'A-982' -Round 2), (New-T44Complete -Seq 752 -Aid 'A-982' -Round 2))
$t44G2 = Invoke-T30Gate -Root $t44Q.root
New-Item -ItemType Directory -Path (Join-Path $t44Q.root '.mission\validator-results') -Force | Out-Null
Write-Utf8 -Path (Join-Path $t44Q.root '.mission\validator-results\manifest.json') -Text "{`"entries`": []}`n"
$t44T2 = Invoke-T30Transcribe -Root $t44Q.root -Target 'A-982'
Add-T44Row -Label '(q) CONTROL fail-closed kept: the refusal line ALONE at the highest round, an older bound round beneath it -- the gate REFUSES and the tool STOPS, neither falling back to round 1' `
    -Ok (($t44Q.exits -ceq '0,0,0,0') -and ($t44G2.Code -ne 0) -and ($t44G2.Text -match "the highest round \(2\) for A-982 is held only by 1 'complete' line\(s\) that bind no result \(seq 752\)") -and
         ($t44T2.Code -ne 0) -and ($t44T2.Text -match 'STOP: A-982: the highest round \(2\) is held only by complete line\(s\) that bind no result -- seqs \[752\]') -and (($t44G2.Text + $t44T2.Text) -notmatch $t30Crash)) `
    -Said ("appends exit $($t44Q.exits); gate exit $($t44G2.Code): " + ((Get-T30Line -Text $t44G2.Text -Pattern '^.*(REFUSED|PERMITS).*$') -join ' // ') + " ; tool exit $($t44T2.Code): " + ((Get-T30Line -Text $t44T2.Text -Pattern '^.*STOP.*$') -join ' // '))
}
catch {
    Add-T44Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
Check -Id 'T-44' -Title 'THE COMPOSER GIVES A REFUSAL ON A COMPLETE LINE ITS FORM (BATCH-3 WP-K): tools/lam/spawn_ledger.py append takes the runner''s note for a validator session that left no result, and the complete line of that session -- the null result of live line 428 with the runner''s refusal token and its reason beside it, no field added to the ledger -- and REFUSES, before a byte is written, a complete line naming a refusal that has no reason or no dispatch_id, whose token is not in form, whose runner_exit is a string, that binds a result (64 hex, or the empty string) or that declares a placement; the forward-only audit PASSES a ledger carrying such lines appended after the cutoff and FAILS a stamped complete after it that names a refusal with no reason or beside a bound result; and the close CLI''s roster gate and the transcription tool''s bare-id path, over ledgers written only by the composer, set the refusal line aside beside a bound line at the same round -- the gate naming it on its [PASS] line -- and both still refuse where it stands alone at the highest round; and a bare null-result complete line that names no refusal is REFUSED at append (BATCH-4 WP-M: until then it was appended, a residual this member read)' `
      -Ok $t44ok -Detail ("      THE $(@($t44rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t44rows -join "`n"))

# =============================================================================================
# T-45 -- THE COMMIT-LEDGER COMPOSER, tools/lam/commit_ledger.py (BATCH-4 WP-M (a):
#         "a tracked composer with a member, in the spawn ledger composer's form")
# =============================================================================================
# THE ROW. No tracked tool wrote a line of .mission-runtime/lam/commit-ledger.jsonl: each recording seat composed its
# lines with a session scratch script, and the file came to hold more than one shape -- lines with `backfilled` and
# lines without, note lines, lines carrying an 8-hex sha, compact lines and spaced ones. THE COMPOSER takes the commit's
# id and the three fields git does not hold (by, attested_by, note), reads the commit's own committer time and subject
# from git, and appends ONE compact line of ten keys ending in composed_by. It creates no ledger file: whether a
# mission holds its own commit ledger is itself read by Test-LamAdvanceAdmission (tools/lam/lam-verify-admission.ps1),
# the ledger's one reader, which this package does not edit and which row (l) drives as it stands.
# ON A TREE WITHOUT THE COMPOSER every row reads False and its reading says ABSENT, because that is what it finds.
# THE FIXTURE is a scratch repository under %TEMP% by T-41 rows (v)-(x)'s rule: the git dir is asserted to be exactly
# <root>\.git before git is used again, no git config is run, and each commit carries its identity on the command
# line. The composer's bytes are COMMITTED there at their own path, so the copy stamps; a linked worktree of that
# scratch repository is added for row (j2) and removed with it. The live commit ledger is never named. The fixture
# stands until T-46 has used it and is removed there.
$t45ok = $true
$t45rows = New-Object System.Collections.Generic.List[string]
function Add-T45Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t45ok = $false }
    $script:t45rows.Add(('      {0,-104} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
$t45Tool = Join-Path $repoRoot 'tools\lam\commit_ledger.py'
$t45RepoBase = $null
$t45Repo = ''
$t45Copy = ''
$t45Ledger = ''
$t45Stamp = ''
$t45C1 = ''
$t45Good = '{"by":"the T-45 fixture seat","attested_by":"the T-45 fixture recorder","note":"composed by WP-4 T-45"}'
function Invoke-T45Py {
    # The commit composer under the interpreter T-30 resolved. On a tree that does not hold it: ABSENT.
    param([string]$Tool, [string[]]$PyArgs)
    if (-not (Test-Path -LiteralPath $t45Tool -PathType Leaf)) {
        return [pscustomobject]@{ Code = $null; Text = 'ABSENT: tools/lam/commit_ledger.py does not exist in this tree -- nothing was composed and nothing was refused' }
    }
    return (Invoke-T41Py -Tool $Tool -PyArgs $PyArgs)
}
function Invoke-T45Append {
    # ONE append by the scratch repository's composer. -Line: the line file's text. -DefaultLedger passes no --ledger,
    # so the composer names the ledger itself. Returns the exit, the text, and the ledger's sha256 before and after.
    param([string]$Sha, [string]$Line = $t45Good, [string]$Ledger = $t45Ledger, [string[]]$More = @(), [string]$Tool = $t45Copy, [switch]$DefaultLedger)
    $t45LineFile = Join-Path $t45RepoBase 'line.json'
    Write-Utf8 -Path $t45LineFile -Text $Line
    $t45Args = @('append', '--sha', $Sha, '--line-file', $t45LineFile)
    if (-not $DefaultLedger) { $t45Args += @('--ledger', $Ledger) }
    $t45Args += $More
    $t45Before = Get-T41Sha $Ledger
    $t45Run = Invoke-T45Py -Tool $Tool -PyArgs $t45Args
    return [pscustomobject]@{ Code = $t45Run.Code; Text = $t45Run.Text; Before = $t45Before; After = (Get-T41Sha $Ledger); Ledger = $Ledger }
}
function Get-T45Line {
    # exit 0, ONE column-0 APPENDED line, and the ledger's LAST LF-terminated line is byte for byte the line it prints.
    # Returns that line's text, or ''.
    param($Run)
    if ($Run.Code -ne 0) { return '' }
    $t45Said = @([regex]::Matches([string]$Run.Text, '(?m)^APPENDED line \d+ to .*?: (\{.*\})\r?$') | ForEach-Object { $_.Groups[1].Value })
    if ($t45Said.Count -ne 1) { return '' }
    $t45All = if (Test-Path -LiteralPath $Run.Ledger -PathType Leaf) { [System.IO.File]::ReadAllText($Run.Ledger) } else { '' }
    if (-not $t45All.EndsWith(("`n" + $t45Said[0] + "`n"), [System.StringComparison]::Ordinal) -and ($t45All -cne ($t45Said[0] + "`n"))) { return '' }
    return $t45Said[0]
}
function Get-T45Obj {
    param([string]$LineText)
    if (-not $LineText) { return $null }
    try { return ($LineText | ConvertFrom-Json) } catch { return $null }
}
function Invoke-T45Admission {
    # THE LEDGER'S ONE READER, AS IT STANDS: Test-LamAdvanceAdmission, by dot-sourcing the tree's
    # lam-verify-admission.ps1 in a child process (as the runner and the evaluator load it), over the scratch
    # repository. The four redirecting git variables are removed for the child and put back.
    param([string]$Root, [string]$Recorded)
    $t45Script = Join-Path $t45RepoBase 'admission.ps1'
    Write-Utf8 -Path $t45Script -Text ("param([string]`$Lib, [string]`$Root, [string]`$Recorded)`n" +
        ". `$Lib`n" +
        "`$a = Test-LamAdvanceAdmission -MissionRoot `$Root -RecordedHeadSha `$Recorded`n" +
        "Write-Output ('admitted=' + `$a.admitted + ' ledger_match=' + `$a.ledger_match + ' commit_count=' + `$a.commit_count + ' reason=' + ((([string]`$a.reason) -replace '\s+', ' ')))`n")
    $t45Saved = @{}
    foreach ($t45V in $script:t37GitVars) { $t45Saved[$t45V] = [Environment]::GetEnvironmentVariable($t45V); [Environment]::SetEnvironmentVariable($t45V, $null) }
    $prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { $t45Out = @(& powershell -NoProfile -ExecutionPolicy Bypass -File $t45Script -Lib (Join-Path $repoRoot 'tools\lam\lam-verify-admission.ps1') -Root $Root -Recorded $Recorded 2>&1) }
    finally {
        $ErrorActionPreference = $prevEap
        foreach ($t45V in $script:t37GitVars) { [Environment]::SetEnvironmentVariable($t45V, $t45Saved[$t45V]) }
    }
    return ((@($t45Out) | ForEach-Object { [string]$_ }) -join ' ')
}
function New-T45Commit {
    # One fixture commit of one new file, its message from a file, its dates from the environment for the call.
    param([string]$File, [string]$Message, [string]$AuthorDate, [string]$CommitterDate)
    Write-Utf8 -Path (Join-Path $t45Repo $File) -Text ("fixture " + $File + "`n")
    $t45Msg = Join-Path $t45RepoBase 'message.txt'
    Write-Utf8 -Path $t45Msg -Text $Message
    $t45SavedA = $env:GIT_AUTHOR_DATE; $t45SavedC = $env:GIT_COMMITTER_DATE
    try {
        $env:GIT_AUTHOR_DATE = $AuthorDate; $env:GIT_COMMITTER_DATE = $CommitterDate
        $t45A = Invoke-T37Git -Root $t45Repo -GitArgs @('add', '--', $File)
        $t45CommitArgs = $t45IdArgs + @('commit', '--quiet', '-F', $t45Msg)
        $t45Cm = Invoke-T37Git -Root $t45Repo -GitArgs $t45CommitArgs
    } finally { $env:GIT_AUTHOR_DATE = $t45SavedA; $env:GIT_COMMITTER_DATE = $t45SavedC }
    $t45Head = Invoke-T37Git -Root $t45Repo -GitArgs @('rev-parse', 'HEAD')
    if (($t45A.exit -ne 0) -or ($t45Cm.exit -ne 0) -or ($t45Head.exit -ne 0)) { throw ('FIXTURE REFUSED: the commit of ' + $File + ' failed (' + $t45Cm.text + ')') }
    return $t45Head.text.Trim()
}
try {
$t45RepoBase = Join-Path $env:TEMP ('lam-wp4-t45-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
$t45Repo = Join-Path $t45RepoBase 'r'
New-Item -ItemType Directory -Path (Join-Path $t45Repo 'tools\lam') -Force | Out-Null
$t45Init = Invoke-T37Git -Root $t45RepoBase -GitArgs @('init', '--quiet', $t45Repo)
$t45Gd = Invoke-T37Git -Root $t45Repo -GitArgs @('rev-parse', '--absolute-git-dir')
$t45GdPath = [System.IO.Path]::GetFullPath($t45Gd.text.Trim().Replace('/', '\'))
if (($t45Init.exit -ne 0) -or ($t45Gd.exit -ne 0) -or ($t45GdPath -ine [System.IO.Path]::GetFullPath((Join-Path $t45Repo '.git')))) {
    throw ('FIXTURE REFUSED: the fixture git dir is not exactly <root>\.git (' + $t45Gd.text.Trim() + ')')
}
$t45HasTool = Test-Path -LiteralPath $t45Tool -PathType Leaf
$t45Copy = Join-Path $t45Repo 'tools\lam\commit_ledger.py'
$t45LfBytes = [byte[]]@()
if ($t45HasTool) {
    # The composer's bytes with every CR LF collapsed to LF, as T-41 row (v) commits its composer.
    $t45Bytes = [System.IO.File]::ReadAllBytes($t45Tool)
    $t45Lf = New-Object System.Collections.Generic.List[byte]
    for ($t45I = 0; $t45I -lt $t45Bytes.Length; $t45I++) {
        if (($t45Bytes[$t45I] -eq 13) -and (($t45I + 1) -lt $t45Bytes.Length) -and ($t45Bytes[$t45I + 1] -eq 10)) { continue }
        $t45Lf.Add($t45Bytes[$t45I])
    }
    $t45LfBytes = $t45Lf.ToArray()
    [System.IO.File]::WriteAllBytes($t45Copy, $t45LfBytes)
}
Write-Utf8 -Path (Join-Path $t45Repo '.gitignore') -Text ".mission-runtime/`n"
$t45IdArgs = @('-c', 'user.name=wp4-t45', '-c', 'user.email=wp4-t45@example.invalid', '-c', 'commit.gpgsign=false')
$t45AddArgs = if ($t45HasTool) { @('add', '--', '.gitignore', 'tools/lam/commit_ledger.py') } else { @('add', '--', '.gitignore') }
$t45Add = Invoke-T37Git -Root $t45Repo -GitArgs $t45AddArgs
$t45SeedArgs = $t45IdArgs + @('commit', '--quiet', '-m', 'T-45 fixture: the seed')
$t45SeedRun = Invoke-T37Git -Root $t45Repo -GitArgs $t45SeedArgs
$t45S = (Invoke-T37Git -Root $t45Repo -GitArgs @('rev-parse', 'HEAD')).text.Trim()
# c0 is ledgered by a LEGACY line with no `backfilled` key; c1 and c2 are the composer's. c1's author time and
# committer time differ, and both are written with a -04:00 offset, as git prints them on this host's ledger.
$t45C0 = New-T45Commit -File 'a.txt' -Message "T-45 fixture: c0`n" -AuthorDate '2026-10-05T09:00:00-04:00' -CommitterDate '2026-10-05T09:00:00-04:00'
$t45C1 = New-T45Commit -File 'b.txt' -Message "T-45 fixture: the first line of the subject`nand its second line`n`nthe body, which is not the subject`n" -AuthorDate '2026-10-05T10:00:00-04:00' -CommitterDate '2026-10-05T18:17:03-04:00'
$t45C2 = New-T45Commit -File 'c.txt' -Message "T-45 fixture: seen at 2026-10-02T11:4xZ, a malformed time git holds`n" -AuthorDate '2026-10-05T19:00:00-04:00' -CommitterDate '2026-10-05T19:00:00-04:00'
$t45TreeId = (Invoke-T37Git -Root $t45Repo -GitArgs @('rev-parse', 'HEAD^{tree}')).text.Trim()
$t45OrphanArgs = $t45IdArgs + @('commit-tree', $t45TreeId, '-m', 'T-45 fixture: an orphan, in no history of HEAD')
$t45Orphan = (Invoke-T37Git -Root $t45Repo -GitArgs $t45OrphanArgs).text.Trim()
$t45BlobId = (Invoke-T37Git -Root $t45Repo -GitArgs @('rev-parse', 'HEAD:.gitignore')).text.Trim()
$t45ScratchBlob = Invoke-T37Git -Root $t45Repo -GitArgs @('rev-parse', 'HEAD:tools/lam/commit_ledger.py')
$t45Stamp = if (($t45ScratchBlob.exit -eq 0) -and ($t45ScratchBlob.text.Trim() -match '^[0-9a-f]{40}$')) { 'tools/lam/commit_ledger.py@' + $t45ScratchBlob.text.Trim().Substring(0, 8) } else { '' }
$t45Ledger = Join-Path $t45Repo '.mission-runtime\lam\commit-ledger.jsonl'
$t45FixtureOk = ($t45Add.exit -eq 0) -and ($t45SeedRun.exit -eq 0) -and ($t45S -match '^[0-9a-f]{40}$') -and ($t45C0 -match '^[0-9a-f]{40}$') -and ($t45C1 -match '^[0-9a-f]{40}$') -and
                ($t45C2 -match '^[0-9a-f]{40}$') -and ($t45Orphan -match '^[0-9a-f]{40}$') -and ($t45BlobId -match '^[0-9a-f]{40}$')
$t45rows.Add('      the fixture repository: ' + $t45Repo + ' ; git dir ' + $t45Gd.text.Trim() + ' ; seed ' + $t45S.Substring(0, [Math]::Min(8, $t45S.Length)) + ', c0 ' + $t45C0.Substring(0, 8) + ', c1 ' + $t45C1.Substring(0, 8) + ', c2 ' + $t45C2.Substring(0, 8) + ', orphan ' + $t45Orphan.Substring(0, [Math]::Min(8, $t45Orphan.Length)) + ' ; built=' + $t45FixtureOk)
$t45rows.Add('      the stamp the scratch repository''s composer must write, from git rev-parse HEAD:tools/lam/commit_ledger.py there: ' + $(if ($t45Stamp) { $t45Stamp } else { '(none -- ABSENT: tools/lam/commit_ledger.py is not in this tree, so it was not committed there)' }))

# ---- (a): no ledger, no file -----------------------------------------------------------------------------------
$t45R = Invoke-T45Append -Sha $t45C1
Add-T45Row -Label '(a) FALSIFIER no ledger file: REFUSED, exit 2, one column-0 line, and NO file is created -- the composer appends to an existing ledger and creates none' `
    -Ok ($t45FixtureOk -and (Test-T41Refused -Run $t45R -Needles @('no ledger file at', 'creates none')) -and ($t45R.After -eq '(absent)')) -Said ("exit $($t45R.Code): " + $t45R.Text)

# THE LEGACY LEDGER: a note line; c0's line written spaced and with NO `backfilled` key; a line carrying c2's 8-hex
# sha with `backfilled` true; and a line that is not JSON. Four shapes the live file holds, none the composer's.
$t45Legacy = '{"event":"note","ts":"t","note":"a note line"}' + "`n" +
             '{"event": "commit", "repo": "r", "sha": "' + $t45C0 + '", "ts": "2026-10-05T09:00:00-04:00", "by": "a seat", "attested_by": "a recorder", "subject": "T-45 fixture: c0", "note": "a legacy line: spaced, and no backfilled key"}' + "`n" +
             '{"event":"commit","repo":"r","sha":"' + $t45C2.Substring(0, 8) + '","ts":"2026-10-05T23:00:00Z","by":"a seat","attested_by":"a recorder","subject":"x","note":"a legacy line carrying a SHORT sha","backfilled":true}' + "`n" +
             'this line is not JSON' + "`n"
Write-Utf8 -Path $t45Ledger -Text $t45Legacy
$t45Before = Invoke-T45Admission -Root $t45Repo -Recorded $t45S

# ---- (b)-(c): what IS written ----------------------------------------------------------------------------------
$t45R = Invoke-T45Append -Sha $t45C1 -DefaultLedger
$t45L1 = Get-T45Line -Run $t45R
$t45O = Get-T45Obj $t45L1
$t45K = Get-T41Keys $t45O
Add-T45Row -Label '(b) FALSIFIER a commit in HEAD''s history, with NO --ledger given: ONE line is appended to the checkout''s own commit ledger -- ten keys in order, the sha whole, backfilled false, stamped' `
    -Ok (($null -ne $t45O) -and (($t45K -join ',') -ceq 'event,repo,sha,ts,by,attested_by,subject,note,backfilled,composed_by') -and ($t45O.event -ceq 'commit') -and ($t45O.sha -ceq $t45C1) -and
         ($t45O.backfilled -is [bool]) -and (-not $t45O.backfilled) -and [bool]$t45Stamp -and ($t45O.composed_by -ceq $t45Stamp) -and ($t45O.repo -ceq 'r')) `
    -Said ("exit $($t45R.Code): " + $t45R.Text)
Add-T45Row -Label '(b1) its ts is the commit''s own COMMITTER time as the same instant in UTC (18:17:03-04:00 reads 2026-10-05T22:17:03Z; the author time is another), and its subject is git''s: the first paragraph on one line' `
    -Ok (($null -ne $t45O) -and ([string]$t45O.ts -ceq '2026-10-05T22:17:03Z') -and ([string]$t45O.subject -ceq 'T-45 fixture: the first line of the subject and its second line')) `
    -Said $(if ($null -ne $t45O) { 'ts ' + [string]$t45O.ts + ' ; subject ' + [string]$t45O.subject } else { $t45R.Text })
$t45Want = '{"event":"commit","repo":"r","sha":"' + $t45C1 + '","ts":"2026-10-05T22:17:03Z","by":"the T-45 fixture seat","attested_by":"the T-45 fixture recorder","subject":"T-45 fixture: the first line of the subject and its second line","note":"composed by WP-4 T-45","backfilled":false,"composed_by":"' + $t45Stamp + '"}'
$t45Now = if (Test-Path -LiteralPath $t45Ledger -PathType Leaf) { [System.IO.File]::ReadAllText($t45Ledger) } else { '' }
Add-T45Row -Label '(b2) the ledger is its legacy bytes and EXACTLY that one line and LF after them -- compact, ASCII, the keys in their order, the stamp last' `
    -Ok ([bool]$t45Stamp -and ($t45Now -ceq ($t45Legacy + $t45Want + "`n"))) -Said ('the line: ' + $t45L1)
$t45R = Invoke-T45Append -Sha $t45C2
$t45L2 = Get-T45Line -Run $t45R
$t45O2 = Get-T45Obj $t45L2
Add-T45Row -Label '(c) FALSIFIER a commit whose 8-hex spelling stands on a legacy line is NOT "already ledgered": APPENDED; and its subject carries a malformed time as git holds it -- the subject is git''s bytes, not the caller''s' `
    -Ok (($null -ne $t45O2) -and ($t45O2.sha -ceq $t45C2) -and ([string]$t45O2.subject -ceq 'T-45 fixture: seen at 2026-10-02T11:4xZ, a malformed time git holds') -and ([string]$t45O2.ts -ceq '2026-10-05T23:00:00Z') -and ($t45O2.composed_by -ceq $t45Stamp) -and [bool]$t45Stamp) `
    -Said ("exit $($t45R.Code): " + $t45R.Text)

# ---- (d)-(i): refused BEFORE a byte is written --------------------------------------------------------------------
# (b3) what "ASCII" holds for a caller's letter that is not: a ledger of its own, so the line numbers above stand.
$t45Ascii = Join-Path $t45RepoBase 'ascii-ledger.jsonl'
Write-Utf8 -Path $t45Ascii -Text ''
$t45R = Invoke-T45Append -Sha $t45C1 -Ledger $t45Ascii -Line ('{"by":"Jos' + [string][char]0xE9 + ' of the T-45 fixture","attested_by":"a recorder","note":"a by that holds a letter outside ASCII"}')
$t45La = Get-T45Line -Run $t45R
$t45High = if (Test-Path -LiteralPath $t45Ascii -PathType Leaf) { @([System.IO.File]::ReadAllBytes($t45Ascii) | Where-Object { $_ -ge 128 }).Count } else { -1 }
Add-T45Row -Label '(b3) FALSIFIER a by that holds a letter outside ASCII: APPENDED with the letter as its JSON escape, and the ledger holds no byte at or above 0x80 (a builder-side review finding)' `
    -Ok ([bool]$t45La -and $t45La.Contains('Jos' + [string][char]92 + 'u00e9 of the T-45 fixture') -and ($t45High -eq 0)) -Said ("bytes at or above 0x80: $t45High; exit $($t45R.Code): " + $t45R.Text)
$t45R = Invoke-T45Append -Sha $t45C1
Add-T45Row -Label '(d) FALSIFIER the same sha a second time: REFUSED naming the line it stands on, the ledger byte-unchanged' `
    -Ok (Test-T41Refused -Run $t45R -Needles @(('a commit line for ' + $t45C1 + ' already stands on the ledger, at line 5'))) -Said ("exit $($t45R.Code): " + $t45R.Text)
$t45R = Invoke-T45Append -Sha $t45C0
Add-T45Row -Label '(d2) a sha that stands on a legacy line with NO backfilled key, written spaced: REFUSED as already ledgered -- the scan reads a line without the key as it reads one with it' `
    -Ok (Test-T41Refused -Run $t45R -Needles @(('a commit line for ' + $t45C0 + ' already stands on the ledger, at line 2'))) -Said ("exit $($t45R.Code): " + $t45R.Text)
$t45Bom = Join-Path $t45RepoBase 'bom-ledger.jsonl'
[System.IO.File]::WriteAllBytes($t45Bom, [byte[]](@(0xEF, 0xBB, 0xBF) + [System.Text.Encoding]::ASCII.GetBytes('{"event":"Commit","repo":"r","sha":"' + $t45C2.ToUpperInvariant() + '"}' + "`n")))
$t45R = Invoke-T45Append -Sha $t45C2 -Ledger $t45Bom
Add-T45Row -Label '(d3) FALSIFIER a sha that stands on a legacy line behind a byte-order mark, its event written Commit and its sha in upper case -- a line the ledger''s PowerShell reader takes as that commit''s: REFUSED as already ledgered (a review finding)' `
    -Ok (Test-T41Refused -Run $t45R -Needles @(('a commit line for ' + $t45C2 + ' already stands on the ledger, at line 1'))) -Said ("exit $($t45R.Code): " + $t45R.Text)
$t45Fresh = Join-Path $t45RepoBase 'fresh-ledger.jsonl'
Write-Utf8 -Path $t45Fresh -Text ''
foreach ($t45Case in @(
        @($t45C2.Substring(0, 8), $t45Good, 'is not a full 40-hex commit id', '(e) FALSIFIER a SHORT sha, 8 hex: REFUSED'),
        @($t45Orphan, $t45Good, 'is not in HEAD''s history', '(f) FALSIFIER a commit that is in no history of HEAD (made by commit-tree, on no branch): REFUSED'),
        @($t45BlobId, $t45Good, 'names no commit', '(f2) FALSIFIER 40 hex that name a blob, not a commit: REFUSED'),
        @($t45C2, '{"by":"a","attested_by":"b","note":"c","ts":"2026-10-05T23:00:00Z"}', 'ts is supplied by the caller', '(g) FALSIFIER a caller-supplied ts: REFUSED -- the time is the commit''s own, read from git'),
        @($t45C2, '{"by":"a","attested_by":"b","note":"c","subject":"x"}', 'subject is supplied by the caller', '(g2) FALSIFIER a caller-supplied subject: REFUSED'),
        @($t45C2, '{"by":"a","attested_by":"b","note":"c","composed_by":"tools/lam/commit_ledger.py@00000000"}', 'composed_by is supplied by the caller', '(g3) FALSIFIER a caller-supplied composed_by: REFUSED'),
        @($t45C2, '{"by":"a","attested_by":"b","note":"c","backfilled":true}', 'backfilled is supplied by the caller', '(g4) FALSIFIER a caller-supplied backfilled: REFUSED -- the composer writes false and takes no other word for it'),
        @($t45C2, '{"by":"a","attested_by":"b","note":"c","seat":"x"}', 'the key ''seat'', which is not by, attested_by or note', '(h) FALSIFIER a key that is none of the three: REFUSED by name'),
        @($t45C2, '{"by":"a","attested_by":"b"}', 'the line file carries no note', '(h2) FALSIFIER no note: REFUSED'),
        @($t45C2, '{"by":"  ","attested_by":"b","note":"c"}', 'is not a non-empty string', '(h3) FALSIFIER a by of spaces: REFUSED'))) {
    $t45R = Invoke-T45Append -Sha $t45Case[0] -Line $t45Case[1] -Ledger $t45Fresh
    Add-T45Row -Label $t45Case[3] -Ok ((Test-T41Refused -Run $t45R -Needles @($t45Case[2])) -and ((Get-Item -LiteralPath $t45Fresh).Length -eq 0)) -Said ("exit $($t45R.Code): " + $t45R.Text)
}
$t45NoLf = Join-Path $t45RepoBase 'no-final-lf.jsonl'
Write-Utf8 -Path $t45NoLf -Text '{"event":"note","note":"no final LF"}'
$t45R = Invoke-T45Append -Sha $t45C2 -Ledger $t45NoLf
Add-T45Row -Label '(i) FALSIFIER a ledger whose last byte is not LF: REFUSED, unchanged' -Ok (Test-T41Refused -Run $t45R -Needles @('last byte is not LF')) -Said ("exit $($t45R.Code): " + $t45R.Text)

# ---- (j): the repo tag ------------------------------------------------------------------------------------------
$t45R = Invoke-T45Append -Sha $t45C2 -Ledger $t45Fresh -More @('--repo', 'lam-smoke')
$t45Oj = Get-T45Obj (Get-T45Line -Run $t45R)
Add-T45Row -Label '(j) --repo names the tag: the line''s repo is lam-smoke, not the default' -Ok (($null -ne $t45Oj) -and ($t45Oj.repo -ceq 'lam-smoke')) -Said ("exit $($t45R.Code): " + $t45R.Text)
$t45Wt = Join-Path $t45RepoBase 'linked'
$t45WtAdd = Invoke-T37Git -Root $t45Repo -GitArgs @('worktree', 'add', '--quiet', '--detach', $t45Wt, 'HEAD')
$t45WtLedger = Join-Path $t45Wt '.mission-runtime\lam\commit-ledger.jsonl'
Write-Utf8 -Path $t45WtLedger -Text ''
$t45R = Invoke-T45Append -Sha $t45C1 -Ledger $t45WtLedger -Tool (Join-Path $t45Wt 'tools\lam\commit_ledger.py') -DefaultLedger
$t45Ow = Get-T45Obj (Get-T45Line -Run $t45R)
Add-T45Row -Label '(j2) from a LINKED WORKTREE of the scratch repository (folder "linked"), no --ledger and no --repo: appended to THAT checkout''s commit ledger, repo "r" -- the PRIMARY checkout''s directory name' `
    -Ok (($t45WtAdd.exit -eq 0) -and ($null -ne $t45Ow) -and ($t45Ow.repo -ceq 'r') -and ($t45Ow.sha -ceq $t45C1) -and ((Get-Item -LiteralPath $t45WtLedger).Length -gt 0)) `
    -Said ("worktree add exit $($t45WtAdd.exit); exit $($t45R.Code): " + $t45R.Text)
$null = Invoke-T37Git -Root $t45Repo -GitArgs @('worktree', 'remove', '--force', $t45Wt)

# ---- (l): the ledger's one reader, as it stands -------------------------------------------------------------------
$t45After = Invoke-T45Admission -Root $t45Repo -Recorded $t45S
$t45BeforeOk = ($t45Before -match 'admitted=False') -and ($t45Before -match 'FOREIGN COMMIT\(S\)') -and $t45Before.Contains($t45C1.Substring(0, 8)) -and $t45Before.Contains($t45C2.Substring(0, 8)) -and (-not $t45Before.Contains($t45C0.Substring(0, 8)))
$t45AfterOk = ($t45After -match 'admitted=True') -and ($t45After -match 'ledger_match=True') -and ($t45After -match 'commit_count=3')
Add-T45Row -Label '(l) THE REAL Test-LamAdvanceAdmission over the scratch repository, seed..HEAD: before the composer''s lines it reads c1 and c2 FOREIGN -- the short-sha line admitted nothing -- and after them it ADMITS the advance of 3, c0 through a line with no backfilled key' `
    -Ok ($t45BeforeOk -and $t45AfterOk) -Said ('before: ' + $t45Before + ' ;; after: ' + $t45After)

# ---- (n), (m): the stamp ----------------------------------------------------------------------------------------
$t45St = Invoke-T45Py -Tool $t45Copy -PyArgs @('stamp')
Add-T45Row -Label '(n) stamp prints the value the appended lines carry' `
    -Ok (($t45St.Code -eq 0) -and [bool]$t45Stamp -and ([string]$t45St.Text -match ('(?m)^composed_by: ' + [regex]::Escape($t45Stamp) + '\r?$'))) -Said ("exit $($t45St.Code): " + $t45St.Text)
if ($t45HasTool) { [System.IO.File]::AppendAllText($t45Copy, "# an edit nobody committed`n", (New-Object System.Text.UTF8Encoding($false))) }
$t45R = Invoke-T45Append -Sha $t45C1 -Ledger $t45Fresh
Add-T45Row -Label '(m) FALSIFIER the same composer edited and not committed: REFUSED -- an uncommitted composer stamps nothing' `
    -Ok (Test-T41Refused -Run $t45R -Needles @('are not an admitted version of tools/lam/commit_ledger.py')) -Said ("exit $($t45R.Code): " + $t45R.Text)
if ($t45HasTool) { [System.IO.File]::WriteAllBytes($t45Copy, $t45LfBytes) }

# ---- (o): a commit whose encoding header names a codec that cannot decode ------------------------------------------
# The LAST row: it moves the scratch repository's HEAD one commit on, and row (l) above counts seed..HEAD.
Write-Utf8 -Path (Join-Path $t45Repo 'd.txt') -Text "fixture d.txt`n"
$t45MsgE = Join-Path $t45RepoBase 'message-e.txt'
Write-Utf8 -Path $t45MsgE -Text "T-45 fixture: a commit whose encoding header is undefined`n"
$t45AddE = Invoke-T37Git -Root $t45Repo -GitArgs @('add', '--', 'd.txt')
$t45CmE = Invoke-T37Git -Root $t45Repo -GitArgs ($t45IdArgs + @('-c', 'i18n.commitEncoding=undefined', 'commit', '--quiet', '-F', $t45MsgE))
$t45CE = (Invoke-T37Git -Root $t45Repo -GitArgs @('rev-parse', 'HEAD')).text.Trim()
$t45HeadE = Invoke-T37Git -Root $t45Repo -GitArgs @('cat-file', 'commit', $t45CE)
$t45SubE = (Invoke-T37Git -Root $t45Repo -GitArgs @('log', '-1', '--format=%s', $t45CE)).text.Trim()
$t45LedE = Join-Path $t45RepoBase 't45-encoding-ledger.jsonl'
Write-Utf8 -Path $t45LedE -Text ''
$t45R = Invoke-T45Append -Sha $t45CE -Ledger $t45LedE
$t45OE = Get-T45Obj (Get-T45Line -Run $t45R)
Add-T45Row -Label '(o) FALSIFIER a commit whose encoding header names a codec that cannot decode (git -c i18n.commitEncoding=undefined): APPENDED, exit 0, no traceback, and its subject is git''s (a validator round 2 finding)' `
    -Ok (($t45AddE.exit -eq 0) -and ($t45CmE.exit -eq 0) -and ([string]$t45HeadE.text -match 'encoding undefined') -and
         ($t45SubE -ceq 'T-45 fixture: a commit whose encoding header is undefined') -and ([string]$t45R.Text -notmatch 'Traceback') -and
         ($null -ne $t45OE) -and ([string]$t45OE.sha -ceq $t45CE) -and ([string]$t45OE.subject -ceq $t45SubE)) `
    -Said ("exit $($t45R.Code): " + $t45R.Text)
}
catch {
    Add-T45Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
Check -Id 'T-45' -Title 'THE COMMIT-LEDGER COMPOSER (BATCH-4 WP-M (a)): tools/lam/commit_ledger.py append, committed in a scratch repository, takes a commit''s full id and a line file of by, attested_by and note, and appends to the checkout''s own commit ledger ONE compact ASCII line -- a letter outside ASCII written as its escape -- of ten keys in order -- event, repo, sha, ts, by, attested_by, subject, note, backfilled, composed_by -- its ts the commit''s own committer time as the same instant in UTC, its subject git''s, backfilled false, repo the primary checkout''s directory name from a linked worktree as from the primary unless --repo names another, stamped tools/lam/commit_ledger.py@ and the first 8 of that repository''s blob of the file; it REFUSES, before a byte is written, with exit 2 and exactly one column-0 REFUSED line carrying the row''s own reason, a missing ledger -- and creates none -- a ledger not ending in LF, the same sha twice, a sha that stands on a legacy line with no backfilled key or behind a byte-order mark with its event and sha in another case, a short sha, a commit in no history of HEAD, 40 hex naming no commit, a caller-supplied ts, subject, composed_by or backfilled, a key that is none of its three, a missing or empty one, and a composer edited and not committed; a legacy line carrying a commit''s 8-hex spelling does not make it already ledgered; a commit whose encoding header names a codec that cannot decode is appended with git''s subject, not traced; and the real Test-LamAdvanceAdmission, as it stands, reads the composed commits FOREIGN before their lines and ADMITS the advance after them, beside a legacy line with no backfilled key' `
      -Ok $t45ok -Detail ("      THE $(@($t45rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t45rows -join "`n") +
          "`n      WHAT THIS MEMBER DOES NOT CLAIM: anything about the live commit ledger, which it never names; that any seat uses the composer;`n" +
          "        or that a stamp proves who wrote a line -- nothing audits this ledger's lines.")

# =============================================================================================
# T-46 -- THE TIME FORM, AND THE LINE'S OWN ts (BATCH-4 WP-M (b)), BOTH COMPOSERS
# =============================================================================================
# THE ROW. Live spawn-ledger line 428 carries, in the prose of its census_bracket, "0 RUNNING at 2026-10-02T11:4xZ" --
# a typed placeholder minute -- and "12:27:40.140Z", a clock with no date; the composer appended it. THE RULE, at
# APPEND ONLY and over the caller's object: at every depth and in every string, a token that opens like a stamp (a
# date, the letter T, two digits and a colon) is a full RFC 3339 UTC stamp naming a real instant -- Z or +00:00, 0 to
# 9 fractional digits -- and a clock-only HH:MM:SSZ token is refused; detection is by the value's shape, never by its
# key's name, and the refusal names the path. A file-name spelling whose clock is written with dashes opens no stamp.
# THE LINE'S OWN ts, where a caller supplies one, is a full stamp within 120 seconds of the composer's clock at the
# write; a line with no ts is appended as before. THE AUDIT APPLIES NEITHER: row (j) reads line 428's own form PASS
# after a cutoff, as T-42 row (L) reads the live ledger. The commit composer holds the caller's three fields to the
# same form (rows (k)); its own ts is the commit's, read from git (T-45 row (b1)).
$t46ok = $true
$t46rows = New-Object System.Collections.Generic.List[string]
function Add-T46Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t46ok = $false }
    $script:t46rows.Add(('      {0,-104} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function Get-T46Clock {
    # This instrument's clock, offset by a number of seconds, in the runner's own form (ms, Z).
    param([int]$OffsetSeconds = 0)
    return [DateTime]::UtcNow.AddSeconds($OffsetSeconds).ToString('yyyy-MM-ddTHH:mm:ss.fffZ', [System.Globalization.CultureInfo]::InvariantCulture)
}
