Add-T46Row -Label '(k2) FALSIFIER the COMMIT composer, an attested_by holding a clock-only time: REFUSED naming attested_by' -Ok (Test-T41Refused -Run $t46R -Needles @("attested_by holds the clock-only time '12:27:40Z'")) -Said ("exit $($t46R.Code): " + $t46R.Text)
