$t47Refused = '{"event":"complete","seq":915,"kind":"validator","role":"qa-validator","dispatch_id":"D-V-A-993","validates":"A-993","round":1,"result_path":null,"result_bytes":null,"result_sha256":null,"anchors_sha256":null,"refusal":"REFUSED-BEFORE-SPAWN-VERIFY-GATE-EXIT-2","reason":"the runner''s ADR-022 verify gate refused; no worker ran and no anchors exist","runner_exit":2}'
$t47R = Invoke-T47Append -Json $t47Refused
