        -Ok ((Test-T49Said -Run $t49S -Exit 0 -Needles @()) -and $t49S.named -and (Test-T49Line -Run $t49S -Line $t49Want) -and (@(Get-T49Lines -Run $t49S -Head 'COLUMN ').Count -eq 1) -and (Test-T49Line -Run $t49S -Line 'ARM none: NOT_MET (failing: instrument_exit0)') -and (Test-T49Said -Run $t49R -Exit 0 -Needles @()) -and (Test-T49Line -Run $t49R -Line $t49Want) -and (@(Get-T49Lines -Run $t49R -Head 'COLUMN ').Count -eq 1) -and ($t49R.Before -eq $t49R.After)) `
        -Said ('copy: ' + (Get-T49Face -Run $t49S -Heads @('COPIED ', 'COLUMN ')) + ' ; read: ' + (Get-T49Face -Run $t49R))
}
# ---- (f): keys this tool does not know, one of them a PREFIX-twin of a key it reads ------------------------------------
$t49K3 = New-T49Kept -Root $t49R3 -Key 'G-T49.3' -Elapsed 13 -Header @('input_tree: 0123456789abcdef')
$t49T = New-T49Verdict -Root $t49R3 -At '2026-01-02T03:04:15.000Z' -Verdict 'MET' `
    -Lists ([ordered]@{ open_halts = @(); instrument_inputs_except = @(); instrument_input_tree_matched = @('a fixture item'); instrument_engine_reads = @(); instrument_captures_kept_on_disk = @('G-T49.9.stub-instrument.ps1.ffffffff.stdout.txt'); instrument_captures_reused = @($t49K3.live + ' sha256 ' + $t49K3.sha); instrument_captures_kept = @($t49K3.item) }) `
    -Entries @(@{ type = 'instrument_exit0'; ok = $true; detail = $t49K3.detail })
$t49S = Invoke-T49Syn -Key 'new-keys' -Text $t49T -Name 'G-T49.verdict.20260102T030415.000Z.MET.instrument-REUSED.yaml'
Add-T49Row -Label '(f) FALSIFIER SYNTHETIC four keys this tool does not know, instrument_captures_kept_on_disk standing BEFORE instrument_captures_kept with ANOTHER name: the same statement, the RIGHT kept path, EQUAL' `
    -Ok ((Test-T49Said -Run $t49S -Exit 0 -Needles @()) -and $t49S.named -and (Test-T49Line -Run $t49S -Line ('COLUMN REUSED exit 0 kept ' + $t49K3.path + ' sha256 ' + $t49K3.sha + ' on disk: EQUAL')) -and (-not ([string]$t49S.Text).Contains('ffffffff'))) -Said (Get-T49Short $t49S 380)

# ---- (e): what copy REFUSES, nothing written -----------------------------------------------------------------------------
$t49Good = Join-Path $t49Base 'syn\new-keys.yaml'
$t49S = Invoke-T49Syn -Key 'new-keys' -Text $t49T -Name ''
Add-T49Row -Label '(e) FALSIFIER the same verdict copied AGAIN: REFUSED, exit 2 -- a file already stands at that name, said BYTE-EQUAL; a seating copy is never written over' `
    -Ok (Test-T41Refused -Run $t49S -Needles @('a file already stands at', 'BYTE-EQUAL to the verdict read')) -Said (Get-T49Short $t49S 300)
$t49R = Invoke-T49Seat -PyArgs @('copy', '--root', $t49R3, '--goal', 'G-NONE', '--close-folder', 'fx-syn') -Target $t49Syn
Add-T49Row -Label '(e) FALSIFIER a goal with NO verdict at either place: REFUSED, both places named' `
    -Ok (Test-T41Refused -Run $t49R -Needles @('no verdict of G-NONE stands at', '.mission\goals\G-NONE.verdict.yaml', '.mission-runtime\lam\goals\G-NONE.verdict.yaml')) -Said (Get-T49Short $t49R 300)
# A FOLDER WHERE A GOAL's VERDICT IS LOOKED FOR is said to be a folder under --goal, as it is under --verdict.
$t49FolderAt = Join-Path $t49R3 '.mission\goals\GF.verdict.yaml'
New-Item -ItemType Directory -Path $t49FolderAt -Force | Out-Null
$t49R = Invoke-T49Seat -PyArgs @('copy', '--root', $t49R3, '--goal', 'GF', '--close-folder', 'fx-syn') -Target $t49Syn
Add-T49Row -Label '(e) FALSIFIER a FOLDER standing at .mission\goals\GF.verdict.yaml, the first place goal GF''s verdict is looked for, and no --verdict: REFUSED -- a folder stands there, said as that and never as "no verdict of GF"' `
    -Ok ((Test-T41Refused -Run $t49R -Needles @(('a folder stands at ' + $t49FolderAt + ' where a verdict is looked for'))) -and (Test-Path -LiteralPath $t49FolderAt -PathType Container) -and (-not ([string]$t49R.Text).Contains('no verdict of GF'))) -Said (Get-T49Short $t49R 300)
Remove-Item -LiteralPath $t49FolderAt -Force
# AND UNDER --verdict ITSELF: the flag names a folder, in this member's own syn folder, and it is said to be one.
$t49FolderNamed = Join-Path $t49Base 'syn\a-folder.verdict.yaml'
New-Item -ItemType Directory -Path $t49FolderNamed -Force | Out-Null
$t49R = Invoke-T49Seat -PyArgs @('copy', '--root', $t49R3, '--goal', 'G-T49', '--close-folder', 'fx-syn', '--verdict', $t49FolderNamed) -Target $t49Syn
Add-T49Row -Label '(e) FALSIFIER --verdict naming a FOLDER: REFUSED -- a folder stands there, said as that; the close folder''s listing digest unchanged' `
    -Ok ((Test-T41Refused -Run $t49R -Needles @(('a folder stands at ' + $t49FolderNamed + ' where a verdict is looked for'))) -and (Test-Path -LiteralPath $t49FolderNamed -PathType Container)) -Said (Get-T49Short $t49R 300)
$t49Lines = @($t49T -split "`r`n")
$t49S = Invoke-T49Syn -Key 'cut-at-line' -Text ((@($t49Lines[0..($t49Lines.Count - 5)]) -join "`r`n") + "`r`n") -Name ''
Add-T49Row -Label '(e) FALSIFIER a verdict CUT SHORT AT A LINE END, its one entry gone: REFUSED -- detector_count says 1 and no entry stands (a half file: the write is not atomic)' `
    -Ok (Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'where detector_count says 1')) -Said (Get-T49Short $t49S 300)
# The text cut inside its last line takes a stamp of its own first: under the verdict's own stamp its copy would be
# named as row (f)'s copy, which stands, and a tool that copied a half file would be refused for that name.
$t49CutMid = $t49T.Replace('evaluated_at: 2026-01-02T03:04:15.000Z', 'evaluated_at: 2026-01-02T03:04:31.000Z')
$t49S = Invoke-T49Syn -Key 'cut-mid-line' -Text $t49CutMid.Substring(0, $t49CutMid.Length - 40) -Name ''
Add-T49Row -Label '(e) FALSIFIER a verdict cut INSIDE its last line: REFUSED -- it does not end in a line end' `
    -Ok (Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'does not end in a line end')) -Said (Get-T49Short $t49S 300)
# TWO MORE HALF FILES THAT END ON A LINE END: the entry counted and not whole; and the last key of the artifact gone.
$t49S = Invoke-T49Syn -Key 'cut-after-type' -Text ((@($t49Lines[0..($t49Lines.Count - 4)]) -join "`r`n") + "`r`n") -Name ''
Add-T49Row -Label '(e) FALSIFIER a verdict CUT SHORT AT A LINE END after its last entry''s "  - type:" line, that entry''s ok and detail lines gone: REFUSED -- the entry is counted, and it lacks its lines (a half file)' `
    -Ok (Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'its entry `instrument_exit0` lacks its `ok:` or its `detail:` line (a half file)')) -Said (Get-T49Short $t49S 300)
$t49AbsentText = $t49Utf8.GetString([System.IO.File]::ReadAllBytes((Join-Path $t49Base 'syn\absent.yaml')))
$t49S = Invoke-T49Syn -Key 'cut-absent-goal' -Text ($t49AbsentText.Substring(0, $t49AbsentText.IndexOf('goal_searched:')).Replace('evaluated_at: 2026-01-02T03:04:06.000Z', 'evaluated_at: 2026-01-02T03:04:18.000Z')) -Name ''
Add-T49Row -Label '(e) FALSIFIER SYNTHETIC the absent goal''s artifact (detector_count 0, its own stamp) CUT SHORT after its short_circuited line, its "detectors: []" line gone: REFUSED -- no column-0 detectors line stands (a half file)' `
    -Ok ((Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'it holds 0 column-0 `detectors:` line(s), not one (a half file)')) -and $t49AbsentText.EndsWith("detectors: []`r`n", [System.StringComparison]::Ordinal)) -Said (Get-T49Short $t49S 300)
# AND ONE MORE THAT ENDS ON A LINE END, THE ENTRY's `detail:` LINE ALONE GONE: row (f)'s verdict again, cut so that its
# last entry keeps its "  - type:" line and its "    ok:" line. The text takes a stamp of its own first, so that no
# name a copy of it could take stands in the folder.
$t49CutOk = ((@($t49Lines[0..($t49Lines.Count - 3)]) -join "`r`n") + "`r`n").Replace('evaluated_at: 2026-01-02T03:04:15.000Z', 'evaluated_at: 2026-01-02T03:04:38.000Z')
$t49S = Invoke-T49Syn -Key 'cut-after-ok' -Text $t49CutOk -Name ''
Add-T49Row -Label '(e) FALSIFIER SYNTHETIC a verdict, of its own stamp, CUT SHORT AT A LINE END after its last entry''s "    ok:" line, that entry''s detail line ALONE gone: REFUSED -- the entry is counted, it has its ok, and it lacks its detail (a half file)' `
    -Ok ((Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'its entry `instrument_exit0` lacks its `ok:` or its `detail:` line (a half file)')) -and $t49CutOk.EndsWith("`r`n  - type: instrument_exit0`r`n    ok: true`r`n", [System.StringComparison]::Ordinal) -and $t49CutOk.Contains("`r`nevaluated_at: 2026-01-02T03:04:38.000Z`r`n") -and (-not $t49CutOk.Contains('    detail: '))) -Said (Get-T49Short $t49S 300)
# A KEY LINE THAT STANDS AND CARRIES NO VALUE. ONE whole synthetic verdict -- it ends in a line end, its one entry is
# whole -- with ONE line changed: its `verdict:` line with nothing after the colon, then its `evaluated_at:` line
# reading `[]`. Neither file holds the word, or the stamp, a copy is named from.
$t49Whole = New-T49Verdict -Root $t49R3 -At '2026-01-02T03:04:27.000Z' -Verdict 'MET' -Lists ([ordered]@{ open_halts = @() }) -Entries @(@{ type = 'instrument_exit0'; ok = $true; detail = $t49Fresh })
$t49NoWord = $t49Whole.Replace("`r`nverdict: MET`r`n", "`r`nverdict:`r`n")
$t49S = Invoke-T49Syn -Key 'no-verdict-word' -Text $t49NoWord -Name ''
Add-T49Row -Label '(e) FALSIFIER SYNTHETIC a whole verdict but for its `verdict:` line, which stands and carries NO VALUE: REFUSED as not one whole verdict -- "its `verdict:` line carries no value" -- and no traceback' `
    -Ok ((Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'its `verdict:` line carries no value')) -and $t49NoWord.Contains("`r`nverdict:`r`n") -and ($t49NoWord.Length -eq ($t49Whole.Length - 4))) -Said (Get-T49Short $t49S 300)
$t49NoStamp = $t49Whole.Replace("`r`nevaluated_at: 2026-01-02T03:04:27.000Z`r`n", "`r`nevaluated_at: []`r`n")
$t49S = Invoke-T49Syn -Key 'no-stamp' -Text $t49NoStamp -Name ''
Add-T49Row -Label '(e) FALSIFIER SYNTHETIC the same whole verdict but for its `evaluated_at:` line, which reads `evaluated_at: []`: REFUSED as not one whole verdict -- "its `evaluated_at:` line carries no value" -- and no traceback' `
    -Ok ((Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'its `evaluated_at:` line carries no value')) -and $t49NoStamp.Contains("`r`nevaluated_at: []`r`n") -and $t49NoStamp.Contains("`r`nverdict: MET`r`n")) -Said (Get-T49Short $t49S 300)
# THE `goal:` LINE WITH THEM. Two more whole verdicts, EACH OF ITS OWN STAMP, each with ONE line changed: the first's
# `goal:` line gone, the second's standing with nothing after its colon. --goal G-T49 is given: a copy is named for the
# goal its bytes name, and these bytes name none. The stamps are two so that, over a tool that copied both, each copy
# would take a name of its own and neither row would be refused for the other's copy.
$t49Goalless = New-T49Verdict -Root $t49R3 -At '2026-01-02T03:04:28.000Z' -Verdict 'MET' -Lists ([ordered]@{ open_halts = @() }) -Entries @(@{ type = 'instrument_exit0'; ok = $true; detail = $t49Fresh })
$t49NoGoal = $t49Goalless.Replace("`r`ngoal: G-T49`r`n", "`r`n")
$t49S = Invoke-T49Syn -Key 'no-goal-line' -Text $t49NoGoal -Name ''
Add-T49Row -Label '(e) FALSIFIER SYNTHETIC a whole verdict but for its `goal:` line, which is GONE, copied under --goal G-T49: REFUSED as not one whole verdict -- "it holds 0 column-0 `goal:` line(s), not one" -- and nothing written' `
    -Ok ((Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'it holds 0 column-0 `goal:` line(s), not one')) -and $t49Goalless.Contains("`r`ngoal: G-T49`r`n") -and ($t49NoGoal.Length -eq ($t49Goalless.Length - 13)) -and $t49NoGoal.Contains("`r`ngoal_file: ")) -Said (Get-T49Short $t49S 300)
$t49Valueless = New-T49Verdict -Root $t49R3 -At '2026-01-02T03:04:29.000Z' -Verdict 'MET' -Lists ([ordered]@{ open_halts = @() }) -Entries @(@{ type = 'instrument_exit0'; ok = $true; detail = $t49Fresh })
$t49BareGoal = $t49Valueless.Replace("`r`ngoal: G-T49`r`n", "`r`ngoal:`r`n")
$t49S = Invoke-T49Syn -Key 'no-goal-word' -Text $t49BareGoal -Name ''
Add-T49Row -Label '(e) FALSIFIER SYNTHETIC a whole verdict of its OWN stamp but for its `goal:` line, which stands and carries NO VALUE, copied under --goal G-T49: REFUSED as not one whole verdict -- "its `goal:` line carries no value" -- and nothing written' `
    -Ok ((Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'its `goal:` line carries no value')) -and $t49BareGoal.Contains("`r`ngoal:`r`n") -and ($t49BareGoal.Length -eq ($t49Valueless.Length - 6)) -and $t49BareGoal.Contains("`r`nevaluated_at: 2026-01-02T03:04:29.000Z`r`n") -and $t49NoGoal.Contains("`r`nevaluated_at: 2026-01-02T03:04:28.000Z`r`n")) -Said (Get-T49Short $t49S 300)
# AND THE `verdict:` LINE TWICE. Exactly one column-0 `verdict:` line is a whole verdict's: here a whole verdict of its
# own stamp holds a second one beneath the first, naming another word.
$t49Twice = (New-T49Verdict -Root $t49R3 -At '2026-01-02T03:04:40.000Z' -Verdict 'MET' -Lists ([ordered]@{ open_halts = @() }) -Entries @(@{ type = 'instrument_exit0'; ok = $true; detail = $t49Fresh })).Replace("`r`nverdict: MET`r`n", "`r`nverdict: MET`r`nverdict: NOT_MET`r`n")
$t49S = Invoke-T49Syn -Key 'two-verdict-lines' -Text $t49Twice -Name ''
Add-T49Row -Label '(e) FALSIFIER SYNTHETIC a whole verdict, of its own stamp, that holds TWO column-0 `verdict:` lines (MET, then NOT_MET): REFUSED as not one whole verdict -- "it holds 2 column-0 `verdict:` line(s), not one" -- and nothing written' `
    -Ok ((Test-T41Refused -Run $t49S -Needles @('is not one whole verdict', 'it holds 2 column-0 `verdict:` line(s), not one')) -and $t49Twice.Contains("`r`nverdict: MET`r`nverdict: NOT_MET`r`n") -and $t49Twice.Contains("`r`nevaluated_at: 2026-01-02T03:04:40.000Z`r`n")) -Said (Get-T49Short $t49S 300)
$t49R = Invoke-T49Seat -PyArgs @('copy', '--root', $t49R3, '--goal', 'HALT-X', '--close-folder', 'fx-syn', '--verdict', $t49Good) -Target $t49Syn
Add-T49Row -Label '(e) FALSIFIER a goal id HALT-X: REFUSED -- its copy''s name would begin HALT-, which the evaluator''s scan reads as an OPEN HALT, by name' `
    -Ok ((Test-T41Refused -Run $t49R -Needles @('begins HALT-', 'reads as an OPEN HALT')) -and (@(Get-ChildItem -LiteralPath $t49R3 -Recurse -File -Filter 'HALT-*' -ErrorAction SilentlyContinue).Count -eq 0)) -Said (Get-T49Short $t49R 300)
$t49R = Invoke-T49Seat -PyArgs @('copy', '--root', $t49R3, '--goal', 'G-T49', '--close-folder', '..\elsewhere', '--verdict', $t49Good) -Target $t49Syn
Add-T49Row -Label '(e) FALSIFIER a close folder named ..\elsewhere: REFUSED -- an id composed into a path is ONE token, the evaluator''s own rule' `
    -Ok (Test-T41Refused -Run $t49R -Needles @('--close-folder', 'is not one token [A-Za-z0-9][A-Za-z0-9._-]*')) -Said (Get-T49Short $t49R 300)
# THE NAME GUARDS, EVERY ID AND EVERY SPELLING. Each run is held over the WHOLE runtime plane of the root -- what a
# faulty tool writes lands outside the folder named -- and conjoined with THE EVALUATOR's OWN SCAN LINE over
# .mission-runtime\lam returning no file (tools/lam/mission-goal-check.ps1, Get-OpenHalts). Under Windows PowerShell
# 5.1 that filter matches a file's 8.3 name too, on a volume that keeps one, and the file system builds the 8.3 name
# from the long one with its dots dropped: the count is the volume's, the refusal is not. HA.LT-x stands LAST, and its
# verdict stands at the goal's own first place, so that nothing but the guard is between the tool and a write.
$t49Plane = Join-Path $t49R3 '.mission-runtime'
function New-T49GoalText {
    # A SYNTHETIC VERDICT OF ANOTHER GOAL THAN G-T49: row (f)'s stamp, word, REUSED entry and kept capture, without its
    # four unknown keys -- so its copy is named ...verdict.20260102T030415.000Z.MET.instrument-REUSED.yaml and its kept
    # capture reads EQUAL -- its `goal:` and `goal_file:` lines naming -Goal. A copy is named for the goal its bytes
    # name, so a verdict that stands at a goal's own place, or that a row copies under a goal, is written as that
    # goal's: G-BOTH's, G-LOCK-N's and G-LOCK-RW's below, and HA.LT-x's here. Returns the text.
    param([string]$Goal)
    return (New-T49Verdict -Root $t49R3 -Goal $Goal -At '2026-01-02T03:04:15.000Z' -Verdict 'MET' `
        -Lists ([ordered]@{ open_halts = @(); instrument_captures_reused = @($t49K3.live + ' sha256 ' + $t49K3.sha); instrument_captures_kept = @($t49K3.item) }) `
        -Entries @(@{ type = 'instrument_exit0'; ok = $true; detail = $t49K3.detail }))
}
Write-T49Bytes -Path (Join-Path $t49R3 '.mission\goals\HA.LT-x.verdict.yaml') -Bytes ($t49Utf8.GetBytes((New-T49GoalText -Goal 'HA.LT-x')))
$t49Guards = @(
    @('a goal id halt-x, in small letters: REFUSED -- it begins HALT- whatever its letter case, as the scan reads it', @('--goal', 'halt-x', '--verdict', $t49Good), @('--goal', 'begins HALT-')),
    @('a goal id HaLt-9, in mixed letters: REFUSED -- it begins HALT- whatever its letter case', @('--goal', 'HaLt-9', '--verdict', $t49Good), @('--goal', 'begins HALT-')),
    @('a hand-tee label x\..\..\HALT-9, which would leave the folder for a name beginning HALT-: REFUSED -- the label is ONE token too', @('--goal', 'G-T49', '--verdict', $t49Good, '--hand-tee', 'x\..\..\HALT-9'), @('--hand-tee', 'is not one token [A-Za-z0-9][A-Za-z0-9._-]*')),
    @('a goal id a\b: REFUSED -- the goal is ONE token too', @('--goal', 'a\b', '--verdict', $t49Good), @('--goal', 'is not one token [A-Za-z0-9][A-Za-z0-9._-]*')),
    @('a goal id HA.LT-x, one token that does not begin HALT-, its verdict standing: REFUSED -- it begins HALT- once its dots are dropped, as its copy''s 8.3 name would', @('--goal', 'HA.LT-x'), @('--goal', 'begins HALT-')))
foreach ($t49Case in $t49Guards) {
    $t49R = Invoke-T49Seat -PyArgs (@('copy', '--root', $t49R3, '--close-folder', 'fx-syn') + $t49Case[1]) -Target $t49Plane
    $t49Scan = @(Get-ChildItem -LiteralPath (Join-Path $t49R3 '.mission-runtime\lam') -File -Recurse -Filter 'HALT-*' -ErrorAction SilentlyContinue)
    Add-T49Row -Label ('(e) FALSIFIER ' + $t49Case[0] + '; nothing written anywhere under the runtime plane, and the evaluator''s scan line returns 0 files') `
        -Ok ((Test-T41Refused -Run $t49R -Needles $t49Case[2]) -and ($t49Scan.Count -eq 0)) -Said ('the scan line returned ' + $t49Scan.Count + ' file(s) ; ' + (Get-T49Short $t49R 300))
}
$t49Both = $t49Utf8.GetBytes((New-T49GoalText -Goal 'G-BOTH'))
# THE SECOND PLACE's VERDICT HAS A STAMP OF ITS OWN: the copy --verdict asks for is then the second place's by its name
# and by its bytes, and over a tool that copied the first place's where it should refuse, the row after would not be
# refused for that copy.
$t49Both2 = $t49Utf8.GetBytes((New-T49GoalText -Goal 'G-BOTH').Replace('evaluated_at: 2026-01-02T03:04:15.000Z', 'evaluated_at: 2026-01-02T03:04:30.000Z'))
Write-T49Bytes -Path (Join-Path $t49R3 '.mission\goals\G-BOTH.verdict.yaml') -Bytes $t49Both
Write-T49Bytes -Path (Join-Path $t49R3 '.mission-runtime\lam\goals\G-BOTH.verdict.yaml') -Bytes $t49Both2
$t49R = Invoke-T49Seat -PyArgs @('copy', '--root', $t49R3, '--goal', 'G-BOTH', '--close-folder', 'fx-syn') -Target $t49Syn
Add-T49Row -Label '(e) FALSIFIER a verdict standing at BOTH places (beside a goal under .mission and under the runtime plane) and no --verdict: REFUSED, both named' `
    -Ok (Test-T41Refused -Run $t49R -Needles @('stands at BOTH', 'name the one meant with --verdict')) -Said (Get-T49Short $t49R 300)
$t49R = Invoke-T49Seat -PyArgs @('copy', '--root', $t49R3, '--goal', 'G-BOTH', '--close-folder', 'fx-syn', '--verdict', (Join-Path $t49R3 '.mission-runtime\lam\goals\G-BOTH.verdict.yaml')) -Target $t49Syn
Add-T49Row -Label '(e) FALSIFIER and with --verdict naming the second place: copied, exit 0, named for that goal' `
    -Ok ((Test-T49Said -Run $t49R -Exit 0 -Needles @()) -and ((Get-T41Sha (Join-Path $t49Syn 'G-BOTH.verdict.20260102T030430.000Z.MET.instrument-REUSED.yaml')) -eq (Get-T49BytesSha $t49Both2)) -and ((Get-T49BytesSha $t49Both2) -ne (Get-T49BytesSha $t49Both)) -and ($t49R.Before -ne $t49R.After)) -Said (Get-T49Short $t49R 200)
# THE GOAL OF THE NAME IS HELD TO THE BYTES. The whole verdict written above says `goal: G-T49` on its own line;
# --verdict names its file and --goal names another goal. (The row before this one copies, under --goal G-BOTH and
# by --verdict, a verdict whose own line says G-BOTH.)
$t49WholeFile = Join-Path $t49Base 'syn\whole.yaml'
Write-T49Bytes -Path $t49WholeFile -Bytes ($t49Utf8.GetBytes($t49Whole))
$t49R = Invoke-T49Seat -PyArgs @('copy', '--root', $t49R3, '--goal', 'G-OTHER', '--close-folder', 'fx-syn', '--verdict', $t49WholeFile) -Target $t49Syn
Add-T49Row -Label '(e) FALSIFIER SYNTHETIC --goal G-OTHER with --verdict naming a whole verdict whose own `goal:` line says G-T49: REFUSED, the two goals named -- a copy is named for the goal its bytes name; the close folder''s listing digest unchanged' `
