$t51R51d = New-T51Root -Name 'r51d' -Status $t51Plain
$t51NoFileRel = '.mission-runtime/lam/HANDOFF-FX-no-such-brief.md'
$t51NoFile = Join-Path $t51R51d '.mission-runtime\lam\HANDOFF-FX-no-such-brief.md'
$t51NoFileStood = Test-Path -LiteralPath $t51NoFile
$t51R = Invoke-T51Head -Root $t51R51d -Lines ($t49Utf8.GetBytes('HANDOFF AT 5% ' + $t51NoBytes + '; ' + $t51NoBytes + ' ' + $t51NoFileRel + "`n" + $t51Second)) -More @('--place-handoff') -Target (Join-Path $t51R51d '.mission-runtime')
Add-T51Row -Label '(c) FALSIFIER --place-handoff, line 1 a head whose path names NO FILE AT ALL and both slots the sha256 of no bytes: REFUSED, its one line whole -- no file stands at that path: an absent brief is not read as no bytes -- the runtime folder''s listing digest unchanged: STATUS.md byte-identical, no temporary file, no record' `
    -Ok ((-not $t51NoFileStood) -and (Test-T41Refused -Run $t51R -Needles @('and no file stands at ')) -and (Test-T49Line -Run $t51R -Line ('REFUSED: the new line 1 names the brief ' + $t51NoFileRel + ', and no file stands at ' + $t51NoFile + ' -- nothing was written')) -and (-not $t51R.temp)) -Said (Get-T49Short $t51R 300)
$t51R = Invoke-T51Head -Root $t51F6.root -Lines ($t49Utf8.GetBytes($t51F6.head + "`n" + $t51Second)) -More @('--place-handoff')
$t51Now = [System.IO.File]::ReadAllText($t51F6.status)
$t51PlaceM = [regex]::Match($t51Now, ('\A' + [regex]::Escape($t51F6.head) + '\nTHE SEAM OF ARC-FX SEAT 1, written (?<at>' + $t51StampRx + ')\n' + [regex]::Escape($t51Plain) + '\z'))
$t51PlaceAt = ''
if ($t51PlaceM.Success) { $t51PlaceAt = $t51PlaceM.Groups['at'].Value }
Add-T51Row -Label '(c) FALSIFIER --place-handoff, the line whose two digests ARE the brief''s: placed, exit 0 -- line 1 the head, line 2 the stamp filled, inside 120 s of this member''s clock, the old bytes beneath' `
    -Ok ((Test-T49Said -Run $t51R -Exit 0 -Needles @('LINE 1 PLACED IS A HANDOFF head IN THE FORM over ')) -and $t51PlaceM.Success -and ((Get-T49Clock $t51PlaceAt) -lt 120) -and (-not $t51R.temp)) `
    -Said ('the stamp filled ' + $t51PlaceAt + ', ' + $(if ($t51PlaceAt) { [string][Math]::Round((Get-T49Clock $t51PlaceAt), 1) } else { '?' }) + ' s from this clock; ' + (Get-T49Short $t51R 300))
# (h) THIS TREE's EVALUATOR reads the head the tool placed: eligible.
$t51Ev = Invoke-T49Eval -Root $t51F6.root
$t51EvD = Get-T49Detail -Text $t51Ev.text -Type 'handoff_brief_present'
Add-T51Row -Label '(h) FALSIFIER THIS TREE''s EVALUATOR BY HAND over that root, after the place: verdict HANDOFF_ADMITTED, exit 6, "ADMITTED BY HAND, NOT RECORDED" -- the head the tool placed is one the evaluator admits' `
    -Ok ((Test-T49Said -Run $t51R -Exit 0 -Needles @()) -and ($t51Ev.verdict -ceq 'HANDOFF_ADMITTED') -and ($t51Ev.exit -eq 6) -and $t51EvD.StartsWith('ADMITTED BY HAND, NOT RECORDED', [System.StringComparison]::Ordinal) -and (-not (Test-Path -LiteralPath $t51F6.record))) `
    -Said ('verdict ' + $t51Ev.verdict + ', exit ' + $t51Ev.exit + '; the handoff entry: ' + $t51EvD.Substring(0, [Math]::Min(140, $t51EvD.Length)))
# a CR LF brief: its two digests DIFFER, and each slot is held to its own basis.
$t51CrBrief = Join-Path $t51F6.root '.mission-runtime\lam\HANDOFF-FX-seat-2.md'
[System.IO.File]::WriteAllBytes($t51CrBrief, $t49Utf8.GetBytes("# a fixture brief with CR LF line ends`r`nits second line`r`n"))
$t51CrRaw = Get-T41Sha $t51CrBrief
$t51CrLf = Get-T37LfSha -Path $t51CrBrief
$t51CrHead = 'HANDOFF AT 77% ' + $t51CrLf + '; ' + $t51CrRaw + ' .mission-runtime/lam/HANDOFF-FX-seat-2.md'
