    -Ok (($t51CrRaw -cne $t51CrLf) -and (Test-T41Refused -Run $t51R -Needles @('its LF/blob slot reads', 'its working slot reads')) -and (-not $t51R.temp)) -Said (Get-T49Short $t51R 300)
$t51R = Invoke-T51Head -Root $t51F6.root -Lines ($t49Utf8.GetBytes($t51CrHead + "`n")) -More @('--place-handoff')
Add-T51Row -Label '(c) FALSIFIER the same brief, the slots in their places (LF/blob first, working second): placed, exit 0' `
    -Ok ((Test-T49Said -Run $t51R -Exit 0 -Needles @('LINE 1 PLACED IS A HANDOFF head IN THE FORM over ')) -and [System.IO.File]::ReadAllText($t51F6.status).StartsWith($t51CrHead + "`n" + $t51F6.head + "`n", [System.StringComparison]::Ordinal)) -Said (Get-T49Short $t51R 200)
# (h) THE EVALUATOR's OWN DIGESTS of that brief: its handoff entry prints the two it computed, and they are read
