$t52IDir = Join-Path $t52Close 'fx-i-one'
Write-T49Bytes -Path (Join-Path $t52IDir 'index.verdict-notes.yaml') -Bytes ($t49Utf8.GetBytes("copies:`r`n  - 'a list a seat kept beside its copies: no verdict'`r`n"))
Write-T49Bytes -Path (Join-Path $t52IDir 'G-T52.verdict.half.yaml') -Bytes ($t49Utf8.GetBytes("goal: G-T52`r`nverdict: MET`r`n"))
Write-T49Bytes -Path (Join-Path $t52IDir ($t52Lone.name + '.seated')) -Bytes ($t49Utf8.GetBytes("2026-01-02T12:00:01.000Z`n"))
$t52R = Invoke-T52Census -Prefix 'fx-i-'
Add-T52Row -Label '(i) FALSIFIER two files named as a copy is and holding no verdict -- one with neither key, one with verdict: and no evaluated_at: -- are each NAMED, NOT A VERDICT, counted apart; exit 0' `
    -Ok ((Test-T52Ran -Run $t52R -Exit 0 -Lines @('NOT A VERDICT, counted apart: fx-i-one\G-T52.verdict.half.yaml', 'NOT A VERDICT, counted apart: fx-i-one\index.verdict-notes.yaml')) -and (@(Get-T49Lines -Run $t52R -Head 'NOT A VERDICT').Count -eq 2) -and
         (@(Get-T49Lines -Run $t52R -Head 'FINDING: ').Count -eq 0)) -Said (Get-T52Face -Run $t52R -Heads @('NOT A VERDICT'))
Add-T52Row -Label '(i) FALSIFIER and are NOT COUNTED: 1 verdict copy in 1 folder, one row, FRESH 1 -- 1; the copy''s .seated stamp beside it, which the name filter does not take, is named nowhere' `
    -Ok ((Test-T52Ran -Run $t52R -Exit 0 -Lines @((Get-T52Head -Counted '1 verdict copy in 1' -Prefix 'fx-i-'), 'HOOK STOPS REUSED 0 / FRESH 1 / NOT EVALUATED 0 -- 1 (unread 0); HAND TEES 0', 'SECONDS SAVED 0 s over 0 REUSED hook stop(s)')) -and
         (Test-T52Table -Run $t52R -Rows @($t52Lone.row)) -and (Test-Path -LiteralPath (Join-Path $t52IDir ($t52Lone.name + '.seated')) -PathType Leaf) -and (-not ([string]$t52R.Text).Contains('.seated'))) -Said (Get-T49Short $t52R 200)
# --machine over that same folder: the two names the plain run above printed are the object's not_verdicts.
$t52NotHead = 'NOT A VERDICT, counted apart: '
$t52IPrinted = @(Get-T49Lines -Run $t52R -Head $t52NotHead | ForEach-Object { $_.Substring($t52NotHead.Length) })
$t52IM = Invoke-T52Census -Prefix 'fx-i-' -More @('--machine')
$t52IJ = $null
try { $t52IJ = ([string]$t52IM.Text) | ConvertFrom-Json } catch { $t52IJ = $null }
$t52IApart = @()
$t52IApartSaid = 'not_verdicts: no such key'
if (($null -ne $t52IJ) -and ($null -ne $t52IJ.PSObject.Properties['not_verdicts'])) {
    $t52IApart = @($t52IJ.not_verdicts)
    $t52IApartSaid = 'not_verdicts ' + $t52IApart.Count + ': ' + ($t52IApart -join ' // ')
}
Add-T52Row -Label '(e) FALSIFIER --machine over the same folder: exit 0, one JSON object whose not_verdicts holds those TWO files that are no verdict, each <folder>\<name>, in the order of names -- the plain run''s two NOT A VERDICT lines, less their head -- beside copies 1, its one row the printed row, and no finding' `
    -Ok ((Test-T52Ran -Run $t52IM -Exit 0) -and (@(Get-T52Out $t52IM).Count -eq 1) -and ($null -ne $t52IJ) -and ($t52IApart.Count -eq 2) -and (($t52IApart -join "`n") -ceq ('fx-i-one\G-T52.verdict.half.yaml' + "`n" + 'fx-i-one\index.verdict-notes.yaml')) -and
         ($t52IPrinted.Count -eq 2) -and (($t52IApart -join "`n") -ceq ($t52IPrinted -join "`n")) -and ($t52IJ.copies -eq 1) -and (@($t52IJ.rows).Count -eq 1) -and ([string]@($t52IJ.rows)[0] -ceq $t52Lone.row) -and (@($t52IJ.findings).Count -eq 0)) `
    -Said $(if ($null -eq $t52IJ) { Get-T49Short $t52IM 200 } else { 'exit ' + $t52IM.Code + ': copies ' + $t52IJ.copies + ', rows ' + @($t52IJ.rows).Count + ', ' + $t52IApartSaid + ', findings ' + @($t52IJ.findings).Count })

# ---- (i): THE NAME FILTER -- *.verdict*.yaml and no other name: a file of another name is read by no line ----------------------
# Two folders of one prefix. In the first, beside ONE copy the census counts, a file named notes.yaml and a file
# named x.verdict.txt, each THE BYTES OF A WHOLE VERDICT of a stamp of its own: a filter that took either would owe
# it a row. In the second, which holds no copy, the same two names over a text that is no verdict -- the bytes of
# (i)'s index.verdict-notes.yaml, which the census names NOT A VERDICT under that name: a filter that took either
# would name it so here. The two whole verdicts are written first as two copies, under a copy's name, in a folder
# of ANOTHER prefix, and their bytes are copied from there: the census over that prefix counts both.
$t52YCopy = New-T52Copy -Folder 'fx-y-one' -Name 'G-T52.verdict.1500.MET.instrument-FRESH.yaml' -At '2026-01-02T15:00:00.039Z' -Verdict 'MET' -Shown 'FRESH' -Detail $t52Fresh
$t52ZTwo = @(
    (New-T52Copy -Folder 'fx-z-one' -Name 'G-T52.verdict.1510.MET.instrument-FRESH.yaml' -At '2026-01-02T15:10:00.040Z' -Verdict 'MET' -Shown 'FRESH' -Detail $t52Fresh),
    (New-T52Copy -Folder 'fx-z-one' -Name 'G-T52.verdict.1520.MET.instrument-FRESH.yaml' -At '2026-01-02T15:20:00.041Z' -Verdict 'MET' -Shown 'FRESH' -Detail $t52Fresh)
)
$t52YOne = Join-Path $t52Close 'fx-y-one'
$t52YTwo = Join-Path $t52Close 'fx-y-two'
$t52YNames = @('notes.yaml', 'x.verdict.txt')
$t52NoVerdictSha = Get-T41Sha (Join-Path $t52IDir 'index.verdict-notes.yaml')
for ($t52I = 0; $t52I -lt 2; $t52I++) {
    Write-T49Bytes -Path (Join-Path $t52YOne $t52YNames[$t52I]) -Bytes ([System.IO.File]::ReadAllBytes($t52ZTwo[$t52I].path))
    Write-T49Bytes -Path (Join-Path $t52YTwo $t52YNames[$t52I]) -Bytes ([System.IO.File]::ReadAllBytes((Join-Path $t52IDir 'index.verdict-notes.yaml')))
}
$t52YWhole = $true
$t52YNone = ($t52NoVerdictSha -ne '(absent)')
for ($t52I = 0; $t52I -lt 2; $t52I++) {
    if ((Get-T41Sha (Join-Path $t52YOne $t52YNames[$t52I])) -cne (Get-T41Sha $t52ZTwo[$t52I].path)) { $t52YWhole = $false }
    if ((Get-T41Sha (Join-Path $t52YTwo $t52YNames[$t52I])) -cne $t52NoVerdictSha) { $t52YNone = $false }
}
$t52YWhole = $t52YWhole -and ((Get-T41Sha $t52ZTwo[0].path) -cne (Get-T41Sha $t52ZTwo[1].path)) -and ((Get-T41Sha $t52ZTwo[0].path) -ne '(absent)') -and (@(Get-ChildItem -LiteralPath $t52YOne -Force).Count -eq 3)
$t52YNone = $t52YNone -and (@(Get-ChildItem -LiteralPath $t52YTwo -Force).Count -eq 2)
$t52HeadY = Get-T52Head -Counted '1 verdict copy in 2' -Prefix 'fx-y-'
$t52LineY = 'HOOK STOPS REUSED 0 / FRESH 1 / NOT EVALUATED 0 -- 1 (unread 0); HAND TEES 0'
$t52SumY = 'SECONDS SAVED 0 s over 0 REUSED hook stop(s)'
$t52ZRun = Invoke-T52Census -Prefix 'fx-z-'
$t52YRun = Invoke-T52Census -Prefix 'fx-y-'
$t52YNamed = @(Get-T52Out $t52YRun | Where-Object { $_.Contains('notes.yaml') -or $_.Contains('x.verdict.txt') })
Add-T52Row -Label '(i) FALSIFIER THE NAME FILTER, *.verdict*.yaml and no other name: beside the ONE copy of a counted folder, a file named notes.yaml and one named x.verdict.txt, each the bytes of a WHOLE verdict of a stamp of its own -- of two copies the census COUNTS under a copy''s name in a folder of another prefix: 2 verdict copies in 1 folder, FRESH 2 -- 2 -- are NOT ROWS here: 1 verdict copy in 2 folders, the table that one row, FRESH 1 -- 1; exit 0 of both runs' `
    -Ok ($t52YWhole -and (Test-T52Ran -Run $t52ZRun -Exit 0 -Lines @((Get-T52Head -Counted '2 verdict copies in 1' -Prefix 'fx-z-'), $t52ZTwo[0].row, $t52ZTwo[1].row, 'HOOK STOPS REUSED 0 / FRESH 2 / NOT EVALUATED 0 -- 2 (unread 0); HAND TEES 0')) -and
         (Test-T52Table -Run $t52ZRun -Rows @($t52ZTwo | ForEach-Object { $_.row })) -and (Test-T52Ran -Run $t52YRun -Exit 0 -Lines @($t52HeadY, $t52YCopy.row, $t52LineY)) -and (Test-T52Table -Run $t52YRun -Rows @($t52YCopy.row))) `
    -Said $(if ($null -eq $t52YRun.Code) { Get-T49Short $t52YRun } else { (Get-T52Face -Run $t52ZRun -Heads @('THE CENSUS ', 'HOOK STOPS ')) + ' /// ' + (Get-T52Face -Run $t52YRun -Heads @('THE CENSUS ', 'HOOK STOPS ')) + ' ; ' + @(Get-T52Out $t52YRun | Where-Object { $_.StartsWith('| 2') }).Count + ' row(s)' })
Add-T52Row -Label '(i) FALSIFIER and in the folder beside it, which holds no copy, the same two names over a text that is no verdict -- the bytes (i) saw named NOT A VERDICT under index.verdict-notes.yaml -- are NOT NAMED: no NOT A VERDICT line, neither name on any line; the output is those six lines and no seventh, no FINDING' `
    -Ok ($t52YNone -and (Test-T52Ran -Run $t52YRun -Exit 0) -and ((@(Get-T52Out $t52YRun) -join "`n") -ceq (@($t52HeadY, $t52Header, $t52Rule, $t52YCopy.row, $t52LineY, $t52SumY) -join "`n")) -and
         (@(Get-T49Lines -Run $t52YRun -Head 'NOT A VERDICT').Count -eq 0) -and ($t52YNamed.Count -eq 0)) `
    -Said $(if ($null -eq $t52YRun.Code) { Get-T49Short $t52YRun } else { 'exit ' + $t52YRun.Code + ': ' + @(Get-T52Out $t52YRun).Count + ' line(s); NOT A VERDICT lines ' + @(Get-T49Lines -Run $t52YRun -Head 'NOT A VERDICT').Count + '; lines holding either name ' + $t52YNamed.Count })
$t52Bare = Join-Path $t52Base 'bare'
New-Item -ItemType Directory -Path (Join-Path $t52Bare '.mission-runtime\lam') -Force | Out-Null
$t52R = Invoke-T49Py -Tool $t49Seat -PyArgs @('census', '--root', $t52Bare, '--prefix', 'fx-a-') -Target $t52Bare
Add-T52Row -Label '(i) FALSIFIER a root that holds no close folder: REFUSED, exit 2, one column-0 line naming the folder it looked for; the root unchanged and the folder not made' `
    -Ok ((Test-T41Refused -Run $t52R -Needles @('no close folder at ' + (Join-Path $t52Bare '.mission-runtime\lam\close'))) -and ($t52R.Before -ne '(absent)') -and (-not (Test-Path -LiteralPath (Join-Path $t52Bare '.mission-runtime\lam\close')))) -Said (Get-T49Short $t52R)

# ---- (i2): a VERDICT COPY of a close folder that a second process HOLDS with no sharing -- REFUSED by name ------------------------
# Two FRESH hook stops of one folder; the holder has the SECOND copy in the order of the names, so the tool has read
# one copy when it meets the hold. A refusal is its one line and nothing else: no table, and under --machine no JSON.
$t52V2 = @(
    (New-T52Copy -Folder 'fx-l-one' -Name 'G-T52.verdict.1230.MET.instrument-FRESH.yaml' -At '2026-01-02T12:30:00.034Z' -Verdict 'MET' -Shown 'FRESH' -Detail $t52Fresh),
    (New-T52Copy -Folder 'fx-l-one' -Name 'G-T52.verdict.1240.MET.instrument-FRESH.yaml' -At '2026-01-02T12:40:00.035Z' -Verdict 'MET' -Shown 'FRESH' -Detail $t52Fresh)
)
$t52V2Sha = Get-T41Sha $t52V2[1].path
$t52V2Needles = @(('the verdict copy at ' + $t52V2[1].path + ' '), 'could not be opened in five tries 200 ms apart', 'it is not read as absent -- nothing was written')
$t52LockV = Invoke-T52Locked -Key 'copy' -Path $t52V2[1].path -Prefix 'fx-l-'
$t52LockM = Invoke-T52Locked -Key 'copy-machine' -Path $t52V2[1].path -Prefix 'fx-l-' -More @('--machine')
$t52V2Stands = ($t52V2Sha -ne '(absent)') -and ((Get-T41Sha $t52V2[1].path) -ceq $t52V2Sha)
Add-T52Row -Label '(i2) FALSIFIER a verdict copy of the folder HELD by a second process with NO SHARING: REFUSED by name, exit 2 after not less than 0.8 s -- ONE column-0 line naming the copy, it is not read as absent; no traceback and NO TABLE: the output is that one line, and nothing was written' `
    -Ok ($t52LockV.Live -and $t52V2Stands -and (Test-T41Refused -Run $t52LockV -Needles $t52V2Needles) -and ($t52LockV.Before -ne '(absent)') -and ($t52LockV.WideBefore -eq $t52LockV.WideAfter) -and (@(Get-T52Out $t52LockV).Count -eq 1) -and
         (@(Get-T52Out $t52LockV | Where-Object { $_.StartsWith('|') }).Count -eq 0) -and ($t52LockV.Took -ge 0.8)) -Said ('holder live ' + $t52LockV.Live + '; ' + [Math]::Round($t52LockV.Took, 2) + ' s; ' + (Get-T49Short $t52LockV 620))
Add-T52Row -Label '(i2) FALSIFIER census --machine under the same hold: the same refusal by name, exit 2 after not less than 0.8 s, no traceback -- and NO JSON OBJECT is printed: the output is that one line, and nothing was written' `
    -Ok ($t52LockM.Live -and $t52V2Stands -and (Test-T41Refused -Run $t52LockM -Needles $t52V2Needles) -and ($t52LockM.Before -ne '(absent)') -and ($t52LockM.WideBefore -eq $t52LockM.WideAfter) -and (@(Get-T52Out $t52LockM).Count -eq 1) -and
         (@(Get-T52Out $t52LockM | Where-Object { $_.StartsWith('{') }).Count -eq 0) -and ($t52LockM.Took -ge 0.8)) -Said ('holder live ' + $t52LockM.Live + '; ' + [Math]::Round($t52LockM.Took, 2) + ' s; ' + (Get-T49Short $t52LockM 620))
$t52R = Invoke-T52Census -Prefix 'fx-l-'
Add-T52Row -Label '(i2) CONTROL the refusal was the hold''s: the holder ended, the same census reads both copies -- exit 0, 2 verdict copies in 1 folder, their two rows, FRESH 2 -- 2' `
    -Ok ($t52V2Stands -and (Test-T52Ran -Run $t52R -Exit 0 -Lines @((Get-T52Head -Counted '2 verdict copies in 1' -Prefix 'fx-l-'), $t52V2[0].row, $t52V2[1].row, 'HOOK STOPS REUSED 0 / FRESH 2 / NOT EVALUATED 0 -- 2 (unread 0); HAND TEES 0', 'SECONDS SAVED 0 s over 0 REUSED hook stop(s)')) -and
         (Test-T52Table -Run $t52R -Rows @($t52V2 | ForEach-Object { $_.row }))) -Said (Get-T52Face -Run $t52R -Heads @('THE CENSUS ', 'HOOK STOPS '))

# ---- (j): a stop of TWO instrument entries -- both REUSED; and one REUSED beside one FRESH ---------------------------------------
$t52KJA = New-T49Kept -Root $t52Root -Key 'kja' -Elapsed 3
$t52KJB = New-T49Kept -Root $t52Root -Key 'kjb' -Elapsed 4
$t52KJC = New-T49Kept -Root $t52Root -Key 'kjc' -Elapsed 61
function New-T52Two {
    # ONE synthetic verdict of TWO instrument entries in the folder fx-j-one, and the table row the census owes it.
    param([string]$Name, [string]$At, [string]$Shown, [object[]]$Entries, [string[]]$Kept, [string]$KeptCell)
    $t52Text = New-T49Verdict -Root $t52Root -Goal 'G-T52' -At $At -Verdict 'MET' -Lists ([ordered]@{ instrument_captures_kept = $Kept }) -Entries $Entries
    $t52Path = Join-Path (Join-Path $t52Close 'fx-j-one') $Name
    Write-T49Bytes -Path $t52Path -Bytes ($t49Utf8.GetBytes($t52Text))
    return ('| ' + $At + ' | G-T52 | MET | **' + $Shown + '** | hook stop | fx-j-one : ' + $t52Tick + $Name + $t52Tick + ' ' + (Get-Item -LiteralPath $t52Path).Length + ' B sha256 ' + $t52Tick + (Get-T41Sha $t52Path) + $t52Tick + ' | ' + $KeptCell + ' |')
}
$t52RowBoth = New-T52Two -Name 'G-T52.verdict.1300.MET.two.yaml' -At '2026-01-02T13:00:00.029Z' -Shown 'REUSED' -Kept @($t52KJA.item, $t52KJB.item) `
    -KeptCell ((Get-T52Cell -Kept $t52KJA -Seconds '3') + ' ; ' + (Get-T52Cell -Kept $t52KJB -Seconds '4')) `
    -Entries @(@{ type = 'instrument_exit0'; ok = $true; detail = $t52KJA.detail }, @{ type = 'instrument_exit0'; ok = $true; detail = $t52KJB.detail })
$t52RowMixed = New-T52Two -Name 'G-T52.verdict.1310.MET.two.yaml' -At '2026-01-02T13:10:00.030Z' -Shown 'MIXED' -Kept @($t52KJC.item) -KeptCell (Get-T52Cell -Kept $t52KJC -Seconds '61') `
    -Entries @(@{ type = 'instrument_exit0'; ok = $true; detail = $t52KJC.detail }, @{ type = 'instrument_exit0'; ok = $true; detail = $t52Fresh })
$t52R = Invoke-T52Census -Prefix 'fx-j-'
Add-T52Row -Label '(j) FALSIFIER a stop of TWO instrument entries, BOTH REUSED: its row REUSED, BOTH kept captures in its cell, and BOTH summed -- SECONDS SAVED 7 s over 1 REUSED hook stop(s), 3 and 4' `
    -Ok ((Test-T52Ran -Run $t52R -Exit 0 -Lines @($t52RowBoth, 'SECONDS SAVED 7 s over 1 REUSED hook stop(s)')) -and $t52RowBoth.EndsWith('ON DISK, EQUAL; 3 s ; ' + (Get-T52Cell -Kept $t52KJB -Seconds '4') + ' |')) -Said (Get-T52Face -Run $t52R -Heads @('SECONDS SAVED ', 'FINDING: '))
Add-T52Row -Label '(j) FALSIFIER a stop of one REUSED entry beside one FRESH: its row MIXED, its capture in the cell, counted in the tail -- REUSED 1 ... -- 2 (unread 0) ... -- also MIXED 1 -- and its 61 s NOT in the sum' `
    -Ok ((Test-T52Ran -Run $t52R -Exit 0 -Lines @($t52RowMixed, 'HOOK STOPS REUSED 1 / FRESH 0 / NOT EVALUATED 0 -- 2 (unread 0); HAND TEES 0 -- also MIXED 1', 'SECONDS SAVED 7 s over 1 REUSED hook stop(s)')) -and
         (Test-T52Table -Run $t52R -Rows @($t52RowBoth, $t52RowMixed)) -and $t52RowMixed.EndsWith('ON DISK, EQUAL; 61 s |') -and (@(Get-T49Lines -Run $t52R -Head 'FINDING: ').Count -eq 0)) -Said (Get-T52Face -Run $t52R -Heads @('HOOK STOPS ', 'SECONDS SAVED ', 'FINDING: '))

# ---- (k): A STOP IS ONE VERDICT's BYTES -- one REUSED hook stop's copy standing, byte for byte, in two folders of one prefix -----
# As two ordinary copy runs of one verdict leave it: one name, the same bytes, a folder each; both cite the one kept
# capture, which stands under the root at its digest (71 s). The folder the order of names reaches SECOND is written
# FIRST. The census owes ONE row -- the copy of the folder first in that order -- and names the copy met again.
$t52KV = New-T49Kept -Root $t52Root -Key 'kv' -Elapsed 71
$t52SameName = 'G-T52.verdict.1400.MET.instrument-REUSED.yaml'
$t52SameTwo = New-T52Reused -Folder 'fx-s-two' -Name $t52SameName -At '2026-01-02T14:00:00.036Z' -Kept $t52KV -Seconds '71'
$t52SameOne = New-T52Reused -Folder 'fx-s-one' -Name $t52SameName -At '2026-01-02T14:00:00.036Z' -Kept $t52KV -Seconds '71'
$t52SameSha = Get-T41Sha $t52SameOne.path
$t52SameBuilt = ($t52SameSha -ne '(absent)') -and ((Get-T41Sha $t52SameTwo.path) -ceq $t52SameSha) -and ($t52SameOne.path -cne $t52SameTwo.path) -and ([string]::CompareOrdinal($t52SameOne.folder, $t52SameTwo.folder) -lt 0) -and
                ($t52SameOne.row -cne $t52SameTwo.row) -and ((Get-T41Sha $t52KV.path) -ceq $t52KV.sha)
$t52HeadS = Get-T52Head -Counted '1 verdict copy in 2' -Prefix 'fx-s-'
$t52LineS = 'HOOK STOPS REUSED 1 / FRESH 0 / NOT EVALUATED 0 -- 1 (unread 0); HAND TEES 0'
$t52SumS = 'SECONDS SAVED 71 s over 1 REUSED hook stop(s)'
$t52SameAgain = 'THE SAME VERDICT AGAIN, counted once: fx-s-two\' + $t52SameName + ' (the bytes of fx-s-one\' + $t52SameName + ')'
$t52Once = Invoke-T52Census -Prefix 'fx-s-'
Add-T52Row -Label '(k) FALSIFIER A STOP IS ONE VERDICT''s BYTES: one REUSED hook stop''s verdict copy standing BYTE FOR BYTE in two folders of one prefix, its kept capture on disk: the head line says 1 verdict copy in 2 folders, and the table is ONE row -- the copy of the folder first in the order of names; exit 0' `
    -Ok ($t52SameBuilt -and (Test-T52Ran -Run $t52Once -Exit 0 -Lines @($t52HeadS, $t52SameOne.row)) -and (Test-T52Table -Run $t52Once -Rows @($t52SameOne.row)) -and $t52SameOne.row.EndsWith('ON DISK, EQUAL; 71 s |')) `
    -Said $(if ($null -eq $t52Once.Code) { Get-T49Short $t52Once } else { (Get-T52Face -Run $t52Once -Heads @('THE CENSUS ')) + ' ; the table''s rows, by folder: ' + (@(Get-T52Out $t52Once | Where-Object { $_.StartsWith('| 2') } | ForEach-Object { [regex]::Match($_, ' \| (\S+) : ').Groups[1].Value }) -join ', ') })
Add-T52Row -Label '(k) FALSIFIER the stop is counted ONCE and its capture''s seconds are summed ONCE: HOOK STOPS REUSED 1 / FRESH 0 / NOT EVALUATED 0 -- 1 (unread 0); HAND TEES 0, and SECONDS SAVED 71 s over 1 REUSED hook stop(s) -- not REUSED 2, and not 142 s over 2' `
    -Ok ((Test-T52Ran -Run $t52Once -Exit 0 -Lines @($t52LineS, $t52SumS)) -and (@(Get-T49Lines -Run $t52Once -Head 'HOOK STOPS ').Count -eq 1) -and (@(Get-T49Lines -Run $t52Once -Head 'SECONDS SAVED ').Count -eq 1)) `
    -Said (Get-T52Face -Run $t52Once -Heads @('HOOK STOPS ', 'SECONDS SAVED '))
Add-T52Row -Label '(k) FALSIFIER the copy met again is NAMED, in ONE whole line: THE SAME VERDICT AGAIN, counted once: <folder>\<name> (the bytes of <folder>\<name>) -- the second folder''s copy, then the first''s, the one counted; the output is those seven lines and no eighth, no FINDING' `
    -Ok ((Test-T52Ran -Run $t52Once -Exit 0 -Lines @($t52SameAgain)) -and (@(Get-T49Lines -Run $t52Once -Head 'THE SAME VERDICT AGAIN').Count -eq 1) -and
         ((@(Get-T52Out $t52Once) -join "`n") -ceq (@($t52HeadS, $t52Header, $t52Rule, $t52SameOne.row, $t52LineS, $t52SumS, $t52SameAgain) -join "`n"))) `
    -Said $(if ($null -eq $t52Once.Code) { Get-T49Short $t52Once } else { (Get-T52Face -Run $t52Once -Heads @('THE SAME VERDICT AGAIN', 'FINDING: ')) + ' ; ' + @(Get-T52Out $t52Once).Count + ' line(s)' })
$t52OnceM = Invoke-T52Census -Prefix 'fx-s-' -More @('--machine')
$t52OnceJ = $null
try { $t52OnceJ = ([string]$t52OnceM.Text) | ConvertFrom-Json } catch { $t52OnceJ = $null }
# same_again is a key the tool as first committed does not print: it is asked for by name before it is read.
$t52OnceAgain = @()
$t52OnceAgainSaid = 'same_again: no such key'
if (($null -ne $t52OnceJ) -and ($null -ne $t52OnceJ.PSObject.Properties['same_again'])) {
    $t52OnceAgain = @($t52OnceJ.same_again)
    $t52OnceAgainSaid = 'same_again ' + $t52OnceAgain.Count + ': ' + ($t52OnceAgain -join ' // ')
}
