$t52Held = @($t52Runs | Where-Object { ($_.Code -in @(0, 1)) -and ($_.Before -eq $_.After) -and ($_.Before -ne '(absent)') -and ($_.WideBefore -eq $_.WideAfter) -and ([string]$_.Text -notmatch 'Traceback') })
Add-T52Row -Label '(h) FALSIFIER each of the twenty-eight census runs above that was not a refusal: exit 0 or 1, the close tree''s listing digest the same before and after, and the digest of everything this member built the same too' `
    -Ok (($t52Runs.Count -eq 28) -and ($t52Held.Count -eq 28)) `
