# =============================================================================================
# T-53 -- THE GENERATOR OVER A SEAT's MINIMAL BRIEF, tools/lam/gen_brief.py compose --minimal
# =============================================================================================
# This member re-read a seat brief and the runtime records it was written over, in the runtime plane of the project
# the framework was extracted from. That project is not part of this distribution, so the rows that read that world
# are a named SKIP -- never a pass, and not counted as a failure. THE THREE SKELETON ROWS (s) read no byte of that
# world and ARE MEASURED: gen_brief.py skeleton --minimal --out writes the prose into a folder of this member's own
# under %TEMP%, removed when the member ends. The member reads SKIP only while those three rows hold; a row of them
# that reads False turns the member to FAIL. ON A TREE WITHOUT THE TOOL each of the three reads False.
$t53ok = $true
$t53rows = New-Object System.Collections.Generic.List[string]
function Add-T53Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t53ok = $false }
    $script:t53rows.Add(('      {0,-104} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function Get-T53Bytes {
    # Every byte of one file by ONE whole read; $null where no file stands there.
    param([string]$Path)
    if ((-not $Path) -or (-not (Test-Path -LiteralPath $Path -PathType Leaf))) { return $null }
    return , ([System.IO.File]::ReadAllBytes($Path))
}
function Get-T53PyBytes {
    # THE BYTES one run of a seam tool prints on stdout, under the interpreter T-30 resolved, read from the process's
    # own stream in Get-T49GitBytes's form: no shell redirection and no text decoding stands between the tool and the
    # array. (PowerShell's capture of a native tool's output is its LINES: a CR the tool prints never arrives there.)
    # Returns the exit and the bytes. On a tree that does not hold the tool the run is ABSENT, in Invoke-T49Py's form:
    # Code null, no byte, and Said says so.
    param([string]$Tool, [string[]]$PyArgs)
    if (-not (Test-Path -LiteralPath $Tool -PathType Leaf)) { return [pscustomobject]@{ Code = $null; Bytes = (New-Object byte[] 0); Said = ('ABSENT: tools/lam/' + (Split-Path -Leaf $Tool) + ' does not exist in this tree -- nothing was run and no byte was read') } }
    if (-not $t30PyExe) { return [pscustomobject]@{ Code = $null; Bytes = (New-Object byte[] 0); Said = 'no Python interpreter resolved' } }
    $t53Psi = New-Object System.Diagnostics.ProcessStartInfo
    $t53Psi.FileName = $t30PyExe
    $t53Psi.Arguments = ((@($Tool) + $PyArgs) | ForEach-Object { '"' + (([string]$_) -replace '"', '\"') + '"' }) -join ' '
    $t53Psi.UseShellExecute = $false
    $t53Psi.RedirectStandardOutput = $true
    $t53Psi.RedirectStandardError = $true
    $t53Psi.CreateNoWindow = $true
    $t53P = [System.Diagnostics.Process]::Start($t53Psi)
    try {
        $t53Mem = New-Object System.IO.MemoryStream
        $t53Err = $t53P.StandardError.ReadToEndAsync()
        $t53P.StandardOutput.BaseStream.CopyTo($t53Mem)
        $t53P.WaitForExit()
        [void]$t53Err.Result
        return [pscustomobject]@{ Code = $t53P.ExitCode; Bytes = $t53Mem.ToArray(); Said = '' }
    } finally { $t53P.Dispose() }
}
$t53Skip = 'host runtime file: this member re-read a seat brief and runtime records of the project the framework was extracted from; that project is not part of this distribution, so the member is not measurable here'
$t53Base = ''
try {
$t53rows.Add('      THE ROWS THAT READ THE BRIEF''s WORLD: SKIPPED -- ' + $t53Skip + ' ; the three skeleton rows (s), which read no byte of it, are measured')
$t53Base = Join-Path $env:TEMP ('lam-wp4-t53-' + [guid]::NewGuid().ToString('N').Substring(0, 10))
$t53ProseDir = Join-Path $t53Base 'prose'
New-Item -ItemType Directory -Path $t53ProseDir -Force | Out-Null
# ---- (s): the skeleton --------------------------------------------------------------------------------------------------------
# THE TOOL's OWN BYTES. The prose is the file `skeleton --minimal --out` WROTE: this member writes no byte of it. It
# reads it -- to hold the tool's own line about it and, after the refused second write, to hold that its bytes have
# not moved. The stdout form is read from the process's own stream (Get-T53PyBytes): a prose rebuilt from
# PowerShell's captured lines could not show a CR the tool printed.
$t53SkProse = Join-Path $t53ProseDir 'skeleton-minimal.md'
$t53SkWas = [string[]]@(Get-ChildItem -LiteralPath $t53ProseDir -Force | ForEach-Object { $_.Name })
$t53Sk = Invoke-T49Py -Tool $t49Gen -PyArgs @('skeleton', '--minimal', '--out', $t53SkProse) -Target $t53ProseDir
$t53SkNew = @(Get-ChildItem -LiteralPath $t53ProseDir -Force | ForEach-Object { $_.Name } | Where-Object { $t53SkWas -cnotcontains $_ })
$t53SkBytes = Get-T53Bytes $t53SkProse
$t53SkSha = ''; $t53SkLen = -1; $t53SkCr = -1; $t53SkLf = -1; $t53SkOdd = -1; $t53SkEnd = $false; $t53SkText = ''
if ($null -ne $t53SkBytes) {
    $t53SkSha = Get-T49BytesSha $t53SkBytes
    $t53SkLen = $t53SkBytes.Length
    $t53SkCr = @($t53SkBytes | Where-Object { $_ -eq 13 }).Count
    $t53SkLf = @($t53SkBytes | Where-Object { $_ -eq 10 }).Count
    $t53SkOdd = @($t53SkBytes | Where-Object { ($_ -gt 126) -or (($_ -lt 32) -and ($_ -ne 10)) }).Count
    $t53SkEnd = ($t53SkLen -gt 2) -and ($t53SkBytes[$t53SkLen - 1] -eq 10) -and ($t53SkBytes[$t53SkLen - 2] -ne 10)
    $t53SkText = [System.Text.Encoding]::GetEncoding(28591).GetString($t53SkBytes)
}
$t53SkWant = 'WROTE ' + $t53SkProse + ': ' + $t53SkLen + ' B, ' + $t53SkLf + ' lines, ASCII, LF only, no byte-order mark; sha256 ' + $t53SkSha
Add-T53Row -Label '(s) THE SKELETON IS THE TOOL''s OWN FILE: skeleton --minimal --out <a file in this member''s prose folder>: exit 0 and ONE line, whole -- WROTE <that path>: <n> B, <k> lines, ASCII, LF only, no byte-order mark; sha256 <sha> -- its bytes, lines and sha256 those of the file as this member reads it; the file holds NO CR and no byte outside ASCII and LF, ends in ONE LF and names {KEEP_TABLE} and {SEAM_BASES} once each; the folder gained that one file and no other' `
    -Ok (($t53Sk.Code -eq 0) -and ($null -ne $t53SkBytes) -and [string]::Equals([string]$t53Sk.Text, $t53SkWant, [System.StringComparison]::Ordinal) -and ($t53SkCr -eq 0) -and ($t53SkOdd -eq 0) -and $t53SkEnd -and (@([regex]::Matches($t53SkText, '\{KEEP_TABLE\}')).Count -eq 1) -and (@([regex]::Matches($t53SkText, '\{SEAM_BASES\}')).Count -eq 1) -and (($t53SkNew -join ',') -ceq 'skeleton-minimal.md')) `
    -Said ((Get-T49Short $t53Sk 300) + ' ; the file as read here: ' + $(if ($null -eq $t53SkBytes) { 'NOT WRITTEN' } else { [string]$t53SkLen + ' B, LF ' + $t53SkLf + ', CR ' + $t53SkCr + ', other bytes outside ASCII and LF ' + ($t53SkOdd - $t53SkCr) + ', sha256 ' + $t53SkSha }) + ' ; new in the prose folder: ' + $(if ($t53SkNew.Count -gt 0) { $t53SkNew -join ',' } else { 'nothing' }))
$t53SkOut = Get-T53PyBytes -Tool $t49Gen -PyArgs @('skeleton', '--minimal')
$t53OutCr = @($t53SkOut.Bytes | Where-Object { $_ -eq 13 }).Count
$t53OutSha = Get-T49BytesSha $t53SkOut.Bytes
Add-T53Row -Label '(s) THE SAME BYTES ON STDOUT: what skeleton --minimal prints, read from the process''s own stream -- no shell redirect and no text decoding between the tool and the array -- exit 0; the bytes hold NO CR and are byte-equal to the file --out wrote' `
    -Ok (($t53SkOut.Code -eq 0) -and ($t53Sk.Code -eq 0) -and ($null -ne $t53SkBytes) -and ($t53SkOut.Bytes.Length -gt 0) -and ($t53OutCr -eq 0) -and ($t53SkOut.Bytes.Length -eq $t53SkLen) -and ($t53OutSha -ceq $t53SkSha)) `
    -Said ('exit ' + $(if ($null -eq $t53SkOut.Code) { '(none): ' + $t53SkOut.Said } else { [string]$t53SkOut.Code + ': ' + $t53SkOut.Bytes.Length + ' B from the stream, CR ' + $t53OutCr + ', sha256 ' + $t53OutSha }) + ' ; the file --out wrote: ' + $(if ($null -eq $t53SkBytes) { 'NOT WRITTEN' } else { [string]$t53SkLen + ' B, sha256 ' + $t53SkSha }))
$t53Sk2 = Invoke-T49Py -Tool $t49Gen -PyArgs @('skeleton', '--minimal', '--out', $t53SkProse) -Target $t53ProseDir
$t53Sk2Want = 'REFUSED: a file already stands at ' + $t53SkProse + ': a skeleton is never written over -- nothing was written'
Add-T53Row -Label '(s) FALSIFIER the skeleton STANDS and the same skeleton --minimal --out is given again: REFUSED, exit 2, ONE line, whole -- a file already stands at <that path>: a skeleton is never written over; the prose folder''s listing digest unchanged, and the file''s bytes those the first run wrote' `
    -Ok ((Test-T41Refused -Run $t53Sk2 -Needles @($t53Sk2Want)) -and [string]::Equals([string]$t53Sk2.Text, $t53Sk2Want, [System.StringComparison]::Ordinal) -and ($t53Sk.Code -eq 0) -and ($null -ne $t53SkBytes) -and ((Get-T41Sha $t53SkProse) -ceq $t53SkSha)) -Said (Get-T49Short $t53Sk2 300)
}
catch {
    Add-T53Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
# THE ROOT IS REMOVED HERE, whatever the rows read; a root that could not be removed is NAMED on the face.
if ($t53Base -and (Test-Path -LiteralPath $t53Base)) { try { Remove-Item -LiteralPath $t53Base -Recurse -Force -ErrorAction Stop } catch { $t53rows.Add('      NOT REMOVED: ' + $t53Base + ' (' + ($_.Exception.Message -replace '[\r\n]+', ' ') + ')') } }
$t53Title = 'THE GENERATOR OVER A SEAT''s MINIMAL BRIEF: tools/lam/gen_brief.py compose --minimal held to a brief a seat wrote and the runtime records it was written over'
$t53Detail = "      THE $(@($t53rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t53rows -join "`n") +
          "`n      WHAT THIS MEMBER DOES NOT CLAIM: anything about compose over a seat's world -- every row that reads one is SKIPPED here -- or about the`n" +
          "        HANDOFF head and the arm line, which T-51 and T-55 hold."
if ($t53ok) {
    Check -Id 'T-53' -Title ($t53Title + '   [SKIPPED -- ' + $t53Skip + ']') -Ok $false -Skipped -Detail ("      SKIPPED: " + $t53Skip + "`n" + $t53Detail)
} else {
    Check -Id 'T-53' -Title ($t53Title + '   [a skeleton row (s) reads False: the rows that read the seat''s world are SKIPPED -- ' + $t53Skip + ']') -Ok $false -Detail $t53Detail
}

# =============================================================================================
# T-54 -- THE GENERATOR OVER A SEAT's FULL BRIEF, tools/lam/gen_brief.py compose
# =============================================================================================
# This member re-read a seat brief and the runtime records it was written over, in the runtime plane of the project
# the framework was extracted from. That project is not part of this distribution, so the member keeps its id and
# reports a named SKIP -- never a pass, and not counted as a failure.
$t54Skip = 'host runtime file: this member re-read a seat brief and runtime records of the project the framework was extracted from; that project is not part of this distribution, so the member is not measurable here'
$t54Title = 'THE GENERATOR OVER A SEAT''s FULL BRIEF: tools/lam/gen_brief.py compose held to the three tables of a brief a seat wrote and the runtime records it was written over'
