$t55Named = @([regex]::Matches($t55ProseText, '\{[A-Z][A-Z0-9_]*\}') | ForEach-Object { $_.Value } | Sort-Object -Unique)
Add-T55Row -Label '(fixture) CONTROL the first root holds a plain STATUS.md and an empty close folder; the scratchpad three files, one nested; the seated file ONE stamp of this instrument''s clock; the prose names sixteen tokens; the second root, the same STATUS.md and an empty close folder, stands under %TEMP%, outside this tree' `
    -Ok ((Test-Path -LiteralPath $t55Status -PathType Leaf) -and (@(Get-ChildItem -LiteralPath $t55CloseDir -Force).Count -eq 0) -and ($t55Keep.Count -eq 3) -and (@($t55Names | Where-Object { $_.Contains('\') }).Count -eq 1) -and ((Get-T49Clock $t55First) -lt 120) -and ((Get-T55Text $t55Seated) -ceq ($t55First + "`n")) -and ($t55Named.Count -eq 16) -and
          (Test-Path -LiteralPath $t55Status2 -PathType Leaf) -and (@(Get-ChildItem -LiteralPath $t55Close2 -Force).Count -eq 0) -and (-not ($t55Root2 + '\').StartsWith(($repoRoot.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase))) `
    -Said ('seated ' + $t55First + '; keep rows ' + $t55Keep.Count + ', ' + $t55Total + ' bytes; tokens ' + $t55Named.Count + '; second root ' + $t55Root2)

# ---- (a): THE PATTERN, LIFTED from this tree's evaluator source at this reading -------------------------------------
$t55EvalText = Get-T55Text $t49Eval
$t55Open = '$script:HandoffHeadPattern = '''
$t55Opens = @([regex]::Matches($t55EvalText, ('(?m)^' + [regex]::Escape($t55Open)))).Count
$t55LiftAt = @([regex]::Matches($t55EvalText, ('(?m)^' + [regex]::Escape($t55Open) + '(.*)''\r?$')))
$t55Lifted = if (($t55Opens -eq 1) -and ($t55LiftAt.Count -eq 1)) { $t55LiftAt[0].Groups[1].Value } else { '' }
$t55LiftRx = New-Object System.Text.RegularExpressions.Regex('(?!)')
$t55LiftOk = $false
if ($t55Lifted) { try { $t55LiftRx = New-Object System.Text.RegularExpressions.Regex($t55Lifted); $t55LiftOk = $true } catch { $t55LiftOk = $false } }
$t55Groups = @($t55LiftRx.GetGroupNames())
Add-T55Row -Label '(a) CONTROL this tree''s evaluator source holds exactly ONE line beginning $script:HandoffHeadPattern = '' ; the text between its quotes is lifted here -- it is typed nowhere in this file -- and is a .NET pattern naming ctx, lf, raw and path' `
    -Ok (($t55Opens -eq 1) -and $t55LiftOk -and ($t55Groups -ccontains 'ctx') -and ($t55Groups -ccontains 'lf') -and ($t55Groups -ccontains 'raw') -and ($t55Groups -ccontains 'path')) `
    -Said ('lines so beginning: ' + $t55Opens + '; lifted ' + $t55Lifted.Length + ' characters, sha256 ' + (Get-T30Sha $t55Lifted) + '; groups ' + (($t55Groups | Where-Object { $_ -ne '0' }) -join ', '))

# ---- (e): no flag takes a time -- compose given --now, BEFORE the brief is written ------------------------------------
$t55ComposeArgs = @('compose', '--root', $t55Root, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55Prose, '--scratch', $t55Scratch, '--ctx', '77', '--session', 'fx-session-1', '--seated', $t55Seated, '--head-prose', $t55HeadProse, '--head-out', $t55HeadOut)
$t55NowCompose = Invoke-T49Py -Tool $t49Gen -PyArgs ($t55ComposeArgs + @('--now', $t55FixFirst)) -Target $t55Rt
$t55NowComposePut = Remove-T55Written @($t55Brief, $t55HeadOut)

# ---- (a), (b), (c): THE COMPOSE -----------------------------------------------------------------------------------------
$t55C = Invoke-T49Py -Tool $t49Gen -PyArgs $t55ComposeArgs -Target $t55Rt
$t55ArmLines = @(Get-T49Lines -Run $t55C -Head 'HANDOFF AT ')
$t55Arm = if ($t55ArmLines.Count -eq 1) { [string]$t55ArmLines[0] } else { '' }
Add-T55Row -Label '(a) compose over the fixture -- a prose of sixteen tokens, the scratchpad, the seated file, ctx 77 -- exits 0 and prints exactly ONE line beginning HANDOFF AT' `
    -Ok ((Test-T49Said -Run $t55C -Exit 0 -Needles @()) -and ($t55ArmLines.Count -eq 1)) -Said (Get-T49Short $t55C 520)
Add-T55Row -Label '(e) FALSIFIER NO FLAG TAKES A TIME, gen_brief.py compose: the line that composes above, given --now and a stamp besides, is argparse''s usage error -- exit 2, unrecognized arguments, no REFUSED line -- and the root''s .mission-runtime is unchanged' `
    -Ok ((Test-T55Usage -Run $t55NowCompose -Prog 'gen_brief.py' -ErrorLine ('gen_brief.py: error: unrecognized arguments: --now ' + $t55FixFirst)) -and (Test-T49Said -Run $t55C -Exit 0 -Needles @())) -Said ((Get-T49Short $t55NowCompose 300) + $t55NowComposePut)
$t55M = $t55LiftRx.Match($t55Arm)
$t55BriefLf = if (Test-Path -LiteralPath $t55Brief -PathType Leaf) { Get-T37LfSha -Path $t55Brief } else { '(absent)' }
$t55BriefRaw = Get-T41Sha $t55Brief
Add-T55Row -Label '(a) FALSIFIER that line matches the pattern lifted from the evaluator, whole; its ctx is 77, its path .mission-runtime/lam/HANDOFF-ARC-FX-9-seat-3.md, and its two slots hold the brief''s LF/blob digest and its working digest as this member re-derives them -- ONE value, this brief holding no CR' `
    -Ok ((Test-T49Said -Run $t55C -Exit 0 -Needles @()) -and $t55LiftOk -and $t55M.Success -and ($t55M.Groups['ctx'].Value -ceq '77') -and ($t55M.Groups['path'].Value -ceq $t55Rel) -and ($t55M.Groups['lf'].Value -ceq $t55BriefLf) -and ($t55M.Groups['raw'].Value -ceq $t55BriefRaw) -and ($t55BriefLf -ceq $t55BriefRaw)) `
    -Said ('matched ' + $t55M.Success + '; ctx ' + $t55M.Groups['ctx'].Value + ', path ' + $t55M.Groups['path'].Value + '; slots ' + $t55M.Groups['lf'].Value + ' ; ' + $t55M.Groups['raw'].Value + '; the brief re-derived: LF/blob ' + $t55BriefLf + ', working ' + $t55BriefRaw + $t55NoGen)

# ---- (b): the brief's bytes, and the brief whole -----------------------------------------------------------------------
$t55BriefText = Get-T55Text $t55Brief
$t55Bl = $t55BriefText.Split("`n")
$t55Odd = @([regex]::Matches($t55BriefText, '[^\x0A\x20-\x7E]')).Count
$t55Left = @([regex]::Matches($t55BriefText, '\{[A-Z][A-Z0-9_]*\}') | ForEach-Object { $_.Value })
Add-T55Row -Label '(b) the brief''s bytes: every byte LF or 32 to 126 -- so ASCII, no CR, no TAB, no byte-order mark -- ending in exactly ONE LF, and no {NAME} left standing' `
    -Ok ((Test-T49Said -Run $t55C -Exit 0 -Needles @()) -and ($t55BriefText.Length -gt 2) -and ($t55Odd -eq 0) -and $t55BriefText.EndsWith("`n") -and (-not $t55BriefText.EndsWith("`n`n")) -and ($t55Left.Count -eq 0)) `
    -Said ($t55BriefText.Length.ToString() + ' B, ' + (Get-T55Count -Text $t55BriefText -Needle "`n") + ' LF, ' + (Get-T55Count -Text $t55BriefText -Needle "`r") + ' CR, ' + $t55Odd + ' byte(s) outside LF and 32 to 126, tokens left: ' + $(if ($t55Left.Count) { $t55Left -join ' ' } else { 'none' }) + $(if (-not $t55BriefText) { ' -- no brief stands' }) + $t55NoGen)
$t55Wm = @([regex]::Matches($t55BriefText, '(?m)^Written (\S+) by seat 3 of ARC-FX-9 '))
$t55W = if ($t55Wm.Count -eq 1) { $t55Wm[0].Groups[1].Value } else { '' }
$t55Own = Get-T55Span -From $t55First -To $t55W
$t55CopyAt = [Array]::IndexOf($t55ProseLines, '    {COPY_LINE}')
$t55CompareAt = [Array]::IndexOf($t55ProseLines, '    {COMPARE_LINE}')
$t55CopyFound = Get-T55At $t55Bl $t55CopyAt
$t55CompareFound = Get-T55At $t55Bl $t55CompareAt
$t55CopyOpen = '    Copy-Item -LiteralPath ''' + $t55Scratch + ''' -Destination .mission-runtime\scratch-copies\arc-fx-9-seat3 -Recurse '
$t55CompareOpen = '    $b=''.mission-runtime\lam\HANDOFF-ARC-FX-9-seat-3.md''; $d=''.mission-runtime\scratch-copies\arc-fx-9-seat3''; '
$t55ExpL = New-Object System.Collections.Generic.List[string]
foreach ($t55L in $t55ProseLines) {
    if ($t55L -ceq '{KEEP_TABLE}') { foreach ($t55K in $t55Keep) { $t55ExpL.Add($t55K) }; continue }
    if ($t55L -ceq '    {COPY_LINE}') { $t55ExpL.Add($t55CopyFound); continue }
    if ($t55L -ceq '    {COMPARE_LINE}') { $t55ExpL.Add($t55CompareFound); continue }
    $t55ExpL.Add($t55L.Replace('{ARC}', 'ARC-FX-9').Replace('{SEAT}', '3').Replace('{CTX}', '77').Replace('{SESSION}', 'fx-session-1').Replace('{CLOCKMS}', $t55W).Replace('{COMPOSED_BY}', ('tools/lam/gen_brief.py@' + $t55Blob8)).Replace('{BRIEF_REL}', $t55Rel).Replace('{FIRST}', $t55First).Replace('{OWN}', $t55Own).Replace('{SCRATCH}', $t55Scratch).Replace('{ROWS}', [string]$t55Keep.Count).Replace('{ROWS_BYTES}', [string]$t55Total).Replace('{SEAM_BASES}', ('SEAM BASES first ' + $t55First + ' end ' + $t55W)))
}
$t55ExpText = ($t55ExpL -join "`n") + "`n"
$t55ExpArr = $t55ExpText.Split("`n")
$t55DiffAt = -1
for ($t55I = 0; $t55I -lt [Math]::Max($t55Bl.Count, $t55ExpArr.Count); $t55I++) { if ((Get-T55At $t55Bl $t55I) -cne (Get-T55At $t55ExpArr $t55I)) { $t55DiffAt = $t55I; break } }
Add-T55Row -Label '(b) FALSIFIER THE WHOLE BRIEF IS THE PROSE WITH EACH TOKEN FILLED AS THIS MEMBER DERIVES IT, byte for byte but for two lines read as found (the copy line, the compare line): the arc, the seat, ctx, the session, the brief''s path, the scratchpad''s path, its rows and bytes, the keep-table (name | bytes | sha256, a nested name with a backslash, by lowercased name), the first base byte-equal to the seated file''s stamp, the span between the two stamps AS PRINTED, the SEAM BASES line of those two, and composed_by with the blob id this member computes' `
    -Ok ((Test-T49Said -Run $t55C -Exit 0 -Needles @()) -and [bool]$t55W -and [bool]$t55Own -and ($t55BriefText -ceq $t55ExpText)) `
    -Said ($(if ($t55DiffAt -lt 0) { 'equal: ' + $t55ExpArr.Count + ' pieces on LF, ' + $t55ExpText.Length + ' B; written ' + $t55W + ', own span ' + $t55Own + ', composed_by @' + $t55Blob8 } else { 'FIRST DIFFERING LINE ' + ($t55DiffAt + 1) + ': the brief reads [' + (Get-T55At $t55Bl $t55DiffAt) + '] and this member derives [' + (Get-T55At $t55ExpArr $t55DiffAt) + ']' }) + $t55NoGen)
Add-T55Row -Label '(b) the two lines read as found open as the operator''s copy line and compare line do -- the scratchpad''s path, the brief''s path, the destination scratch-copies\arc-fx-9-seat3 -- the compare line closes on his count of mismatches, and neither holds a {NAME}' `
    -Ok ((Test-T49Said -Run $t55C -Exit 0 -Needles @()) -and $t55CopyFound.StartsWith($t55CopyOpen, [System.StringComparison]::Ordinal) -and $t55CompareFound.StartsWith($t55CompareOpen, [System.StringComparison]::Ordinal) -and $t55CompareFound.EndsWith(' mismatches"', [System.StringComparison]::Ordinal) -and
          ($t55CopyFound -cnotmatch '\{[A-Z][A-Z0-9_]*\}') -and ($t55CompareFound -cnotmatch '\{[A-Z][A-Z0-9_]*\}')) `
    -Said ('line ' + ($t55CopyAt + 1) + ' opens [' + $(if ($t55CopyFound.Length -gt 60) { $t55CopyFound.Substring(0, 60) } else { $t55CopyFound }) + '...], ' + $t55CopyFound.Length + ' characters; line ' + ($t55CompareAt + 1) + ' opens [' + $(if ($t55CompareFound.Length -gt 60) { $t55CompareFound.Substring(0, 60) } else { $t55CompareFound }) + '...], ' + $t55CompareFound.Length + ' characters' + $t55NoGen)
Add-T55Row -Label '(b) THE CLOCK ON THE BRIEF: its written stamp is in the clock''s form, within 120 s of this instrument''s clock, and not earlier than the seated stamp' `
    -Ok ((Test-T49Said -Run $t55C -Exit 0 -Needles @()) -and ((Get-T49Clock $t55W) -lt 120) -and ((Get-T55Ticks $t55W) -ge (Get-T55Ticks $t55First)) -and ((Get-T55Ticks $t55First) -gt 0)) `
    -Said ('seated ' + $t55First + ', written ' + $(if ($t55W) { $t55W } else { '(none)' }) + ', ' + [Math]::Round((Get-T49Clock $t55W), 3) + ' s from this clock' + $t55NoGen)

# ---- (c): the head file, as written by --head-out ---------------------------------------------------------------------
$t55HeadWant = $t55Arm + "`n" + $t55HeadFilled + "`n"
$t55HeadText = Get-T55Text $t55HeadOut
Add-T55Row -Label '(c) FALSIFIER --head-out holds exactly two lines: the arm line, byte for byte, and the seat''s second line with its figures filled and {CLOCKMS}, {SEAM_FROM_FIRST} and {SEAM_FROM_END} STILL STANDING' `
    -Ok ((Test-T49Said -Run $t55C -Exit 0 -Needles @()) -and [bool]$t55Arm -and ($t55HeadText -ceq $t55HeadWant)) `
    -Said ($t55HeadText.Length.ToString() + ' B; line 2 reads [' + (Get-T55At ($t55HeadText.Split("`n")) 1) + ']' + $t55NoGen)

# ---- (h), (a), (e): what seat.py head refuses of that file, BEFORE it is placed -------------------------------------------
$t55Lines = Join-Path $t55Base 'lines'
$t55HeadArgs = @('head', '--root', $t55Root, '--line-file', $t55HeadOut, '--place-handoff', '--predecessor-brief', $t55Brief)
Add-T55Row -Label '(h) CONTROL this member''s own span of the two fixture stamps 2026-01-02T03:04:05.678Z and 2026-01-02T03:06:35.473Z reads 2 min 29.795 s (149.795 s), the seats'' form' `
    -Ok ((Get-T55Span -From $t55FixFirst -To $t55FixEnd) -ceq '2 min 29.795 s (149.795 s)') -Said (Get-T55Span -From $t55FixFirst -To $t55FixEnd)
function Invoke-T55Probe {
    # ONE seat.py head --place-handoff over the first root that its row expects REFUSED: the run, its target the
    # runtime folder, and -- as .Put -- what this member put back where the run changed the fixture STATUS.md.
    param([string]$LineFile, [string]$Brief = '')
    $t55A = @('head', '--root', $t55Root, '--line-file', $LineFile, '--place-handoff')
    if ($Brief) { $t55A += @('--predecessor-brief', $Brief) }
    $t55Run = Invoke-T49Py -Tool $t49Seat -PyArgs $t55A -Target $t55Lam
    return [pscustomobject]@{ Code = $t55Run.Code; Text = $t55Run.Text; Before = $t55Run.Before; After = $t55Run.After; Put = (Reset-T55Status $t55Status) }
}
$t55NowFile = Join-Path $t55Lines 'fourth-token.txt'
Write-Utf8 -Path $t55NowFile -Text ($t55Arm + "`n" + $t55HeadFilled + '; now {NOW}' + "`n")
$t55R = Invoke-T55Probe -LineFile $t55NowFile -Brief $t55Brief
Add-T55Row -Label '(h) FALSIFIER the same two lines with a FOURTH token, {NOW}, on the second: REFUSED naming it -- the tool fills its three clock tokens and no other -- and the runtime folder is unchanged' `
    -Ok (Test-T41Refused -Run $t55R -Needles @('the line file holds {NOW}:', 'and no other token')) -Said ((Get-T49Short $t55R) + $t55R.Put)
$t55NoSeam = Join-Path $t55Lines 'no-seam-line.md'
Write-Utf8 -Path $t55NoSeam -Text ("# a brief that holds no seam line, and three lines that are near it`n`n SEAM BASES first $t55FixFirst end $t55FixEnd`nSEAM BASES first $t55FixFirst`nseam bases first $t55FixFirst end $t55FixEnd`n")
$t55R = Invoke-T55Probe -LineFile $t55HeadOut -Brief $t55NoSeam
Add-T55Row -Label '(h) FALSIFIER {SEAM_FROM_FIRST} asked of a --predecessor-brief that holds no line SEAM BASES first <stamp> end <stamp> (three near it: indented, with no end, in small letters): REFUSED, 0 line(s), not one' `
    -Ok (Test-T41Refused -Run $t55R -Needles @('the line file asks a seam span', 'holds 0 line(s) `SEAM BASES first <stamp> end <stamp>`, not one')) -Said ((Get-T49Short $t55R) + $t55R.Put)
$t55TwoSeam = Join-Path $t55Lines 'two-seam-lines.md'
Write-Utf8 -Path $t55TwoSeam -Text ("# a brief that holds two seam lines`n`nSEAM BASES first $t55FixFirst end $t55FixEnd`nSEAM BASES first $t55FixFirst end $t55FixEnd`n")
$t55R = Invoke-T55Probe -LineFile $t55HeadOut -Brief $t55TwoSeam
Add-T55Row -Label '(h) FALSIFIER the same asked of a brief that holds TWO such lines: REFUSED, 2 line(s), not one' `
    -Ok (Test-T41Refused -Run $t55R -Needles @('the line file asks a seam span', 'holds 2 line(s) `SEAM BASES first <stamp> end <stamp>`, not one')) -Said ((Get-T49Short $t55R) + $t55R.Put)
$t55R = Invoke-T55Probe -LineFile $t55HeadOut
Add-T55Row -Label '(h) FALSIFIER the same asked with no --predecessor-brief at all: REFUSED -- there is nothing to read the two bases from' `
    -Ok (Test-T41Refused -Run $t55R -Needles @('the line file asks a seam span and no --predecessor-brief is given')) -Said ((Get-T49Short $t55R) + $t55R.Put)
$t55LateSeam = Join-Path $t55Lines 'late-bases.md'
Write-Utf8 -Path $t55LateSeam -Text "# a brief whose two bases are of the year 2099`n`nSEAM BASES first 2099-01-02T03:04:05.678Z end 2099-01-02T03:06:35.473Z`n"
$t55R = Invoke-T55Probe -LineFile $t55HeadOut -Brief $t55LateSeam
$t55CutSeam = Join-Path $t55Lines 'cut-bases.md'
Write-Utf8 -Path $t55CutSeam -Text "# a brief whose two bases lack their milliseconds`n`nSEAM BASES first 2026-01-02T03:04:05Z end 2026-01-02T03:06:35Z`n"
$t55R2 = Invoke-T55Probe -LineFile $t55HeadOut -Brief $t55CutSeam
Add-T55Row -Label '(h) FALSIFIER THE TWO BASES ARE HELD TO THE CLOCK: a SEAM BASES line of the year 2099 is REFUSED as later than the clock at the write, and one whose stamps lack their milliseconds as not two stamps; the runtime folder is unchanged each time' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('a base of the SEAM BASES line is later than the clock at the write')) -and (Test-T41Refused -Run $t55R2 -Needles @('does not hold two stamps YYYY-MM-DDTHH:MM:SS.mmmZ'))) -Said ((Get-T49Short $t55R 220) + $t55R.Put + ' ; ' + (Get-T49Short $t55R2 260) + $t55R2.Put)
$t55FormLine = $t55Arm.Replace('HANDOFF AT 77% ', 'HANDOFF AT 101% ')
$t55FormFile = Join-Path $t55Lines 'ctx-101.txt'
Write-Utf8 -Path $t55FormFile -Text ($t55FormLine + "`n" + $t55HeadFilled + "`n")
$t55Form = Invoke-T55Probe -LineFile $t55FormFile -Brief $t55Brief
$t55NowHead = Invoke-T49Py -Tool $t49Seat -PyArgs ($t55HeadArgs + @('--now', $t55FixFirst)) -Target $t55Rt
$t55NowHeadPut = Reset-T55Status $t55Status

# ---- (c), (h): THE PLACE -- seat.py head --place-handoff takes the head file -------------------------------------------
$t55OldText = Get-T55Text $t55Status
$t55P = Invoke-T49Py -Tool $t49Seat -PyArgs $t55HeadArgs -Target $t55Lam
$t55NewText = Get-T55Text $t55Status
$t55Nl = $t55NewText.Split("`n")
$t55Hm = [regex]::Match((Get-T55At $t55Nl 1), '\ASEAT 3 of ARC-FX-9 hands over at (\S+) \(ctx 77%\); ')
$t55Hs = if ($t55Hm.Success) { $t55Hm.Groups[1].Value } else { '' }
$t55Bm = @([regex]::Matches($t55BriefText, '(?m)^SEAM BASES first (\S+) end (\S+)$'))
$t55B1 = if ($t55Bm.Count -eq 1) { $t55Bm[0].Groups[1].Value } else { '' }
$t55B2 = if ($t55Bm.Count -eq 1) { $t55Bm[0].Groups[2].Value } else { '' }
$t55SpanFirst = Get-T55Span -From $t55B1 -To $t55Hs
$t55SpanEnd = Get-T55Span -From $t55B2 -To $t55Hs
$t55Line2 = $t55HeadFilled.Replace('{CLOCKMS}', $t55Hs).Replace('{SEAM_FROM_FIRST}', $t55SpanFirst).Replace('{SEAM_FROM_END}', $t55SpanEnd)
$t55NewWant = $t55Arm + "`n" + $t55Line2 + "`n" + $t55OldText
Add-T55Row -Label '(c) FALSIFIER seat.py head --place-handoff takes that file, exit 0: STATUS.md is now the arm line, then the second line with its stamp filled in the clock''s form within 120 s of this clock, then EVERY PRIOR BYTE -- new == placed + old, re-derived here from the bytes on disk, the tool''s own sentence not read' `
    -Ok ((Test-T49Said -Run $t55P -Exit 0 -Needles @()) -and [bool]$t55Arm -and ((Get-T49Clock $t55Hs) -lt 120) -and [bool]$t55SpanFirst -and [bool]$t55SpanEnd -and ($t55NewText -ceq $t55NewWant) -and ($t55NewText.Length -eq ($t55Arm.Length + $t55Line2.Length + 2 + $t55OldText.Length)) -and ($t55OldText -ceq $t55StatusText)) `
    -Said ('exit ' + $(if ($null -eq $t55P.Code) { '(none)' } else { [string]$t55P.Code }) + '; STATUS.md ' + $t55OldText.Length + ' B -> ' + $t55NewText.Length + ' B; line 1 is the arm line: ' + ((Get-T55At $t55Nl 0) -ceq $t55Arm) + '; line 2 reads [' + (Get-T55At $t55Nl 1) + ']; stamp ' + [Math]::Round((Get-T49Clock $t55Hs), 3) + ' s from this clock' + $(if ($null -eq $t55P.Code) { ' -- ' + $t55P.Text }))
$t55SpanRx = '(\d+ min \d+\.\d{3} s \(\d+\.\d{3} s\))'
$t55Sm = [regex]::Match((Get-T55At $t55Nl 1), ('; from the first base ' + $t55SpanRx + '; from the end base ' + $t55SpanRx + '; the brief '))
$t55ClockSaid = @(Get-T49Lines -Run $t55P -Head 'CLOCK ')
Add-T55Row -Label '(h) FALSIFIER the two spans on that line are in the form <m> min <s>.<mmm> s (<S>.<mmm> s) and are what this member computes from the brief''s own SEAM BASES line -- first the seated stamp, end the brief''s written stamp -- to the stamp on the line; and the tool''s CLOCK line says the same three' `
    -Ok ((Test-T49Said -Run $t55P -Exit 0 -Needles @()) -and $t55Sm.Success -and ($t55Sm.Groups[1].Value -ceq $t55SpanFirst) -and ($t55Sm.Groups[2].Value -ceq $t55SpanEnd) -and ($t55B1 -ceq $t55First) -and ($t55B2 -ceq $t55W) -and [bool]$t55W -and
          ($t55ClockSaid.Count -eq 1) -and ($t55ClockSaid[0] -ceq ('CLOCK ' + $t55Hs + '; from the first base ' + $t55B1 + ': ' + $t55SpanFirst + '; from the end base ' + $t55B2 + ': ' + $t55SpanEnd))) `
    -Said ('bases ' + $t55B1 + ' and ' + $t55B2 + ', stamp ' + $t55Hs + '; on the line [' + $t55Sm.Groups[1].Value + '] and [' + $t55Sm.Groups[2].Value + ']; computed here [' + $t55SpanFirst + '] and [' + $t55SpanEnd + ']; ' + ($t55ClockSaid -join ' ') + $t55Absent)
$t55Held = @(Get-ChildItem -LiteralPath $t55Lam -Recurse -File -Force | ForEach-Object { $_.FullName.Substring($t55Lam.Length + 1) })
Add-T55Row -Label '(c) after the compose and the place the root''s runtime folder holds exactly THREE files -- STATUS.md, the brief, the head file: no temporary file, no admissions record -- and the brief''s bytes are as they were before the place' `
