$t55Needle = 'HANDOFF_HEAD_PATTERN = r"' + $t55Lifted + '"'
$t55SeatLines = $t55SeatText.Split("`n")
$t55ConstN = @($t55SeatLines | Where-Object { $_.TrimEnd("`r") -ceq $t55Needle }).Count
