$t55ArmAgain = @(Get-T49Lines -Run $t55R -Head 'HANDOFF AT ')
Add-T55Row -Label '(c) gen_brief.py arm, the same root, arc, seat and ctx, prints the SAME arm line from the standing brief -- one line, byte-equal to compose''s -- exit 0, and writes nothing' `
