$t55Root7 = Join-Path $t55Tmp 'r7'
$t55Lam7 = Join-Path $t55Root7 '.mission-runtime\lam'
$t55Close7 = Join-Path $t55Lam7 'close\fx-t55-same-flags'
$t55Brief7 = Join-Path $t55Lam7 'HANDOFF-ARC-FX-9-seat-3.md'
$t55HeadOut7 = Join-Path $t55Close7 'head.txt'
$t55Seated7 = Join-Path $t55Root7 'fx-same-flags.verdict.yaml.seated'
New-Item -ItemType Directory -Path $t55Close7 -Force | Out-Null
Write-Utf8 -Path $t55Seated7 -Text ((Get-T49Clock) + "`n")
$t55SameFlags = @('--root', $t55Root7, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55Prose, '--scratch', $t55Scratch, '--ctx', '77', '--session', 'fx-session-1', '--seated', $t55Seated7, '--head-prose', $t55HeadProse, '--head-out', $t55HeadOut7)
$t55SameC = Invoke-T49Py -Tool $t49Gen -PyArgs (@('compose') + $t55SameFlags) -Target $t55Lam7
$t55SameArmLines = @(Get-T49Lines -Run $t55SameC -Head 'HANDOFF AT ')
$t55SameArm = ''
if ($t55SameArmLines.Count -eq 1) { $t55SameArm = [string]$t55SameArmLines[0] }
$t55SameComposed = Get-T55Text $t55HeadOut7
$t55SameRemoved = $false
if (Test-Path -LiteralPath $t55HeadOut7 -PathType Leaf) { Remove-Item -LiteralPath $t55HeadOut7 -Force; $t55SameRemoved = $true }
$t55SameGone = -not (Test-Path -LiteralPath $t55HeadOut7)
$t55SameBriefSha = Get-T41Sha $t55Brief7
$t55SameA = Invoke-T49Py -Tool $t49Gen -PyArgs (@('arm') + $t55SameFlags) -Target $t55Lam7
$t55SameAgain = Get-T55Text $t55HeadOut7
$t55SameHeld = @(Get-ChildItem -LiteralPath $t55Lam7 -Recurse -File -Force | ForEach-Object { $_.FullName.Substring($t55Lam7.Length + 1) })
Add-T55Row -Label '(c) FALSIFIER arm TAKES compose''s OWN COMMAND LINE, --prose AMONG ITS FLAGS: in a seventh root under %TEMP% the composing line -- its --prose, --scratch, --session and --seated, a head prose, and --head-out a file in that root''s one close folder -- composes, exit 0, and this member removes the head file that run wrote, so the brief stands and the head file does not; arm given THE SAME FLAGS, flag for flag, exits 0, prints the SAME arm line -- one line, whole, byte-equal to compose''s -- and writes the head file again, byte-equal to the one removed: the arm line and the seat''s second line, the three clock tokens standing; the runtime folder then holds the brief, its bytes as they were, and that head file, and no other file' `
    -Ok ((Test-T49Said -Run $t55SameC -Exit 0 -Needles @()) -and [bool]$t55SameArm -and ($t55SameComposed -ceq ($t55SameArm + "`n" + $t55HeadFilled + "`n")) -and $t55SameRemoved -and $t55SameGone -and
          (Test-T49Said -Run $t55SameA -Exit 0 -Needles @()) -and (@(Get-T49Lines -Run $t55SameA -Head 'HANDOFF AT ').Count -eq 1) -and (Test-T55Lines -Run $t55SameA -Lines @($t55SameArm)) -and
          ($t55SameAgain -ceq $t55SameComposed) -and ($t55SameA.Before -ne $t55SameA.After) -and ($t55SameHeld.Count -eq 2) -and ($t55SameHeld -ccontains 'HANDOFF-ARC-FX-9-seat-3.md') -and ($t55SameHeld -ccontains 'close\fx-t55-same-flags\head.txt') -and
          ((Get-T41Sha $t55Brief7) -ceq $t55SameBriefSha) -and ($t55SameFlags -ccontains '--prose') -and ($t55SameFlags -ccontains '--head-prose') -and ($t55SameFlags -ccontains '--head-out')) `
    -Said ('compose: exit ' + $(if ($null -eq $t55SameC.Code) { '(none)' } else { [string]$t55SameC.Code }) + ', the head file it wrote: ' + $t55SameComposed.Length + ' B; this member removed it: ' + $t55SameRemoved + '; a file stands at --head-out before arm: ' + (-not $t55SameGone) + ' ; arm, the same flags: ' + (Get-T49Short $t55SameA 420) +
           ' ; the head file after arm: ' + $t55SameAgain.Length + ' B against ' + $t55SameComposed.Length + ' B composed; the runtime folder holds: ' + (($t55SameHeld | Sort-Object) -join ' ; '))
# the three figures of the brief ITSELF, which only a head prose may name: its length and its two digests, as read back
$t55FigProse = Join-Path $t55Base 'prose\head.figures.txt'
Write-Utf8 -Path $t55FigProse -Text "the brief {BRIEF_REL}, {BRIEF_BYTES} B, sha256 {BRIEF_SHA}, LF/blob {BRIEF_LF_SHA}`n"
$t55HeadFig = Join-Path $t55CloseDir 'head-figures.txt'
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('arm', '--root', $t55Root, '--arc', 'ARC-FX-9', '--seat', '3', '--ctx', '77', '--head-prose', $t55FigProse, '--head-out', $t55HeadFig) -Target $t55Lam
$t55FigText = Get-T55Text $t55HeadFig
