# ---- (b), (c), (e): THE SECOND ROOT, where no brief of seat 3 stands -- what compose refuses ---------------------------------
$t55Brief2 = Join-Path $t55Lam2 'HANDOFF-ARC-FX-9-seat-3.md'
function Invoke-T55Second {
    # ONE compose over the second root: the first root's line but for the root, -Prose, -SeatedFile and -HeadOut (with
    # it, the head prose too). Its target is the second root's runtime folder. -Refusal: the row expects REFUSED, and
    # what the run wrote regardless -- the brief, the head file -- is removed afterwards and said as .Put.
    param([string]$Prose = $t55Prose, [string]$SeatedFile = $t55Seated, [string]$HeadOut = '', [switch]$Refusal)
    $t55A = @('compose', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $Prose, '--scratch', $t55Scratch, '--ctx', '77', '--session', 'fx-session-1', '--seated', $SeatedFile)
    if ($HeadOut) { $t55A += @('--head-prose', $t55HeadProse, '--head-out', $HeadOut) }
    $t55Run = Invoke-T49Py -Tool $t49Gen -PyArgs $t55A -Target $t55Lam2
    return [pscustomobject]@{ Code = $t55Run.Code; Text = $t55Run.Text; Before = $t55Run.Before; After = $t55Run.After; Put = $(if ($Refusal) { Remove-T55Written @($t55Brief2, $HeadOut) } else { '' }) }
}
$t55Fault = 'the prose holds a CR, a TAB, a control character or a byte above 126 once filled (code point(s) '
$t55Page = 'a fixture''s page'
$t55Cases = @(
    [pscustomobject]@{ k = 'crlf'; what = 'whose every line ends CR LF'; bytes = $t49Utf8.GetBytes($t55ProseText.Replace("`n", "`r`n")); need = ($t55Fault + '13)') },
    [pscustomobject]@{ k = 'tab'; what = 'with ONE blank made a TAB'; bytes = $t49Utf8.GetBytes($t55ProseText.Replace('The scratchpad {SCRATCH}', "The scratchpad`t{SCRATCH}")); need = ($t55Fault + '9)') },
    [pscustomobject]@{ k = 'b127'; what = 'with ONE byte 127 added, the lowest byte above 126'; bytes = $t49Utf8.GetBytes($t55ProseText.Replace($t55Page, ($t55Page + [char]127))); need = ($t55Fault + '127)') },
    [pscustomobject]@{ k = 'u233'; what = 'with ONE character above 126 added as UTF-8 (the two bytes 195 169)'; bytes = $t49Utf8.GetBytes($t55ProseText.Replace($t55Page, ($t55Page + [char]233))); need = ($t55Fault + '233)') },
    [pscustomobject]@{ k = 'b233'; what = 'with ONE lone byte 233 added, which is not UTF-8'; bytes = $t55Latin.GetBytes($t55ProseText.Replace($t55Page, ($t55Page + [char]233))); need = 'is not UTF-8' }
)
foreach ($t55Case in $t55Cases) {
    $t55BadProse = Join-Path $t55Base ('prose\bad-' + $t55Case.k + '.md')
    Write-T49Bytes -Path $t55BadProse -Bytes $t55Case.bytes
    $t55R = Invoke-T55Second -Prose $t55BadProse -Refusal
    Add-T55Row -Label ('(b) FALSIFIER the same prose ' + $t55Case.what + ': REFUSED, and the second root''s runtime folder is unchanged -- no brief is written') `
        -Ok ((Test-T41Refused -Run $t55R -Needles @($t55Case.need)) -and ($t55Latin.GetString($t55Case.bytes) -cne $t55ProseText)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
}
$t55BadProse = Join-Path $t55Base 'prose\bad-no-lf.md'
Write-T49Bytes -Path $t55BadProse -Bytes ($t49Utf8.GetBytes($t55ProseText.TrimEnd("`n")))
$t55R = Invoke-T55Second -Prose $t55BadProse -Refusal
$t55BadProse = Join-Path $t55Base 'prose\bad-two-lf.md'
Write-T49Bytes -Path $t55BadProse -Bytes ($t49Utf8.GetBytes($t55ProseText + "`n"))
$t55R2 = Invoke-T55Second -Prose $t55BadProse -Refusal
Add-T55Row -Label '(b) FALSIFIER the same prose with its final LF cut, and the same prose with a second final LF: each REFUSED -- it does not end in exactly one LF -- and the runtime folder is unchanged' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('the prose does not end in exactly one LF once filled')) -and (Test-T41Refused -Run $t55R2 -Needles @('the prose does not end in exactly one LF once filled'))) -Said ((Get-T49Short $t55R 200) + $t55R.Put + ' ; ' + (Get-T49Short $t55R2 200) + $t55R2.Put)
# ---- (b): THE GUARD OVER EVERY BRIEF, THE SEAM LINE ALONE, THE SCRATCHPAD's FLAGS -- more that compose refuses of that line -----
function Invoke-T55Variant {
    # ONE compose over the second root that its row expects REFUSED: the composing line's root, arc, seat and ctx, and
    # after them the flags the row gives, whole. Its target is the second root's runtime folder; what the run wrote
    # regardless -- the brief, and each file of -Wrote -- is removed afterwards and said as .Put.
    param([string[]]$Flags, [string[]]$Wrote)
    $t55Run = Invoke-T49Py -Tool $t49Gen -PyArgs (@('compose', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '3', '--ctx', '77') + $Flags) -Target $t55Lam2
    return [pscustomobject]@{ Code = $t55Run.Code; Text = $t55Run.Text; Before = $t55Run.Before; After = $t55Run.After; Put = (Remove-T55Written (@($t55Brief2) + @($Wrote | Where-Object { $_ }))) }
}
$t55Guard = 'the operator''s row pattern finds 4 line(s) in the filled brief and the walk has 3 row(s) placed 1 time(s): another table of the prose reads as keep rows'
foreach ($t55Case in @(
        [pscustomobject]@{ k = 'capitals'; hex = ('AB' * 32); label = '(b) FALSIFIER THE GUARD READS AS THE OPERATOR''s LINE READS, without regard to letter case: the same prose with ANOTHER table of one line -- | X | 7 | and 64 hex digits in CAPITAL letters: REFUSED, four lines read as keep rows and the walk has three; the second root''s runtime folder is unchanged -- no brief is written' },
        [pscustomobject]@{ k = 'small'; hex = ('ab' * 32); label = '(b) CONTROL the same line with its 64 hex digits in small letters is REFUSED in the same words -- the letter case was the one thing the row above changed' })) {
    $t55BadProse = Join-Path $t55Base ('prose\bad-row-' + $t55Case.k + '.md')
    Write-Utf8 -Path $t55BadProse -Text ($t55ProseText + "`n| another | table | of this page |`n|---|---|---|`n| X | 7 | " + $t55Case.hex + " |`n")
    $t55R = Invoke-T55Second -Prose $t55BadProse -Refusal
    Add-T55Row -Label $t55Case.label -Ok (Test-T41Refused -Run $t55R -Needles @($t55Guard)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
}
$t55BadProse = Join-Path $t55Base 'prose\bad-mistyped-table.md'
Write-Utf8 -Path $t55BadProse -Text ($t55ProseText.Replace('{KEEP_TABLE}', '{KEEP-TABLE}'))
$t55R = Invoke-T55Second -Prose $t55BadProse -Refusal
Add-T55Row -Label '(b) FALSIFIER THE GUARD ALWAYS RUNS: the same prose with its table token MISTYPED {KEEP-TABLE} -- no token, so no table is placed -- and {COMPARE_LINE} still named: REFUSED, the compare line would find no keep row; no brief is written' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('the prose names {COMPARE_LINE} and places no {KEEP_TABLE}')) -and ((Get-T55Count -Text (Get-T55Text $t55BadProse) -Needle '{KEEP_TABLE}') -eq 0)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
$t55Empty = Join-Path $t55Base 'scratch-empty'
New-Item -ItemType Directory -Path $t55Empty -Force | Out-Null
$t55R = Invoke-T55Variant -Flags @('--prose', $t55Prose, '--scratch', $t55Empty, '--session', 'fx-session-1', '--seated', $t55Seated)
Add-T55Row -Label '(b) FALSIFIER the composing line over an EMPTY --scratch folder: REFUSED -- the walk finds no file -- and no brief is written' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @(('the walk of --scratch ' + $t55Empty + ' finds no file'))) -and (@(Get-ChildItem -LiteralPath $t55Empty -Force).Count -eq 0)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
$t55BadProse = Join-Path $t55Base 'prose\bad-stray-row.md'
Write-Utf8 -Path $t55BadProse -Text ("# {ARC}, SEAT {SEAT}: a page that names no token of the scratchpad`n`n| name | bytes | sha256 |`n|---|---|---|`n| X | 7 | " + ('ab' * 32) + " |`n")
$t55R = Invoke-T55Variant -Flags @('--prose', $t55BadProse)
Add-T55Row -Label '(b) FALSIFIER a prose that names NO token of the scratchpad, composed with no --scratch, and holds one line in the keep-row form: REFUSED -- the pattern finds 1 line where no table is placed -- and no brief is written' `
    -Ok (Test-T41Refused -Run $t55R -Needles @('the operator''s row pattern finds 1 line(s) in the filled brief and the walk has 0 row(s) placed 0 time(s): another table of the prose reads as keep rows')) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
foreach ($t55Case in @(
        [pscustomobject]@{ k = 'in-sentence'; what = 'with {SEAM_BASES} INSIDE A SENTENCE -- The bases: {SEAM_BASES}.'; text = $t55ProseText.Replace('{SEAM_BASES}', 'The bases: {SEAM_BASES}.'); n = 0 },
        [pscustomobject]@{ k = 'twice'; what = 'with {SEAM_BASES} TWICE, each alone on its line'; text = ($t55ProseText + "{SEAM_BASES}`n"); n = 2 })) {
    $t55BadProse = Join-Path $t55Base ('prose\bad-seam-' + $t55Case.k + '.md')
    Write-Utf8 -Path $t55BadProse -Text $t55Case.text
    $t55R = Invoke-T55Second -Prose $t55BadProse -Refusal
    Add-T55Row -Label ('(b) FALSIFIER THE SEAM LINE STANDS ALONE ON ITS LINE, ONCE: the same prose ' + $t55Case.what + ': REFUSED -- ' + $t55Case.n + ' line(s) of the filled brief are the SEAM BASES line whole, not one -- and no brief is written') `
        -Ok (Test-T41Refused -Run $t55R -Needles @(('the prose names {SEAM_BASES} and the filled brief holds ' + $t55Case.n + ' line(s) that are the SEAM BASES line whole, not one'))) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
}
# ONE CHARACTER GLUED AFTER THE TOKEN, AND NOTHING BEFORE IT. The first row above gives a prefix and a suffix together.
# This prose is the composing prose with ONE byte added -- its seam line {SEAM_BASES} becomes {SEAM_BASES}. -- and the
# seam line of a brief the run wrote regardless is read, for this row's face, before this member removes that brief.
$t55GluedProse = Join-Path $t55Base 'prose\bad-seam-glued-after.md'
$t55GluedText = $t55ProseText.Replace("`n{SEAM_BASES}`n", "`n{SEAM_BASES}.`n")
Write-Utf8 -Path $t55GluedProse -Text $t55GluedText
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55GluedProse, '--scratch', $t55Scratch, '--ctx', '77', '--session', 'fx-session-1', '--seated', $t55Seated) -Target $t55Lam2
$t55GluedWrote = @((Get-T55Text $t55Brief2).Split("`n") | Where-Object { $_.StartsWith('SEAM BASES ', [System.StringComparison]::Ordinal) })
$t55Put = Remove-T55Written @($t55Brief2)
$t55GluedSaid = 'REFUSED: the prose names {SEAM_BASES} and the filled brief holds 0 line(s) that are the SEAM BASES line whole, not one: the token stands alone on its line, once -- the successor''s `seat.py head` reads its spans from that one line -- nothing was written'
Add-T55Row -Label '(b) FALSIFIER THE SEAM LINE IS THE LINE WHOLE, ONE CHARACTER GLUED AFTER THE TOKEN AND NOTHING BEFORE IT: the same prose with its seam line written {SEAM_BASES}. -- a full stop after the token, the one byte this prose adds: REFUSED in ONE line, whole -- 0 line(s) of the filled brief are the SEAM BASES line whole, not one -- and no brief is written whose seam line ends in that full stop: the second root''s runtime folder is unchanged' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('the prose names {SEAM_BASES} and the filled brief holds 0 line(s) that are the SEAM BASES line whole, not one')) -and (Test-T55Lines -Run $t55R -Lines @($t55GluedSaid)) -and (-not $t55Put) -and ($t55GluedText.Length -eq ($t55ProseText.Length + 1)) -and
          $t55GluedText.EndsWith("`n{SEAM_BASES}.`n", [System.StringComparison]::Ordinal) -and ((Get-T55Count -Text $t55GluedText -Needle '{SEAM_BASES}') -eq 1)) `
    -Said ((Get-T49Short $t55R 300) + $t55Put + $(if ($t55GluedWrote.Count -gt 0) { ' -- THE BRIEF THE RUN WROTE read its seam line [' + [string]$t55GluedWrote[0] + ']' } else { '' }))
# A SECOND LINE IN THE SEAM LINE's FORM, beside the token alone on its line: the token again with a full stop glued after
# it, and a line TYPED in the form with two other stamps. The successor's seat.py head counts every line in that form,
# and refuses a brief that holds two. What a brief the run wrote regardless held is read, for the row's face, before this
# member removes that brief.
foreach ($t55Case in @(
        [pscustomobject]@{ k = 'alone-and-glued'; what = 'with {SEAM_BASES} alone on its line and, on the line after it, {SEAM_BASES}. -- the token again, a full stop glued after it'; text = ($t55ProseText + "{SEAM_BASES}.`n") },
        [pscustomobject]@{ k = 'alone-and-typed'; what = 'with {SEAM_BASES} alone on its line and, on the line after it, a line TYPED in the same form with the two fixture stamps of January'; text = ($t55ProseText + 'SEAM BASES first ' + $t55FixFirst + ' end ' + $t55FixEnd + "`n") })) {
    $t55BadProse = Join-Path $t55Base ('prose\bad-seam-' + $t55Case.k + '.md')
    Write-Utf8 -Path $t55BadProse -Text $t55Case.text
    $t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55BadProse, '--scratch', $t55Scratch, '--ctx', '77', '--session', 'fx-session-1', '--seated', $t55Seated) -Target $t55Lam2
    $t55SeamWrote = @((Get-T55Text $t55Brief2).Split("`n") | Where-Object { $_.StartsWith('SEAM BASES ', [System.StringComparison]::Ordinal) })
    $t55Put = Remove-T55Written @($t55Brief2)
    Add-T55Row -Label ('(b) FALSIFIER NO SECOND LINE STANDS IN THE SEAM LINE''s FORM: the same prose ' + $t55Case.what + ': REFUSED -- 2 line(s) of the filled brief are the SEAM BASES line whole, not one -- and no brief is written holding two lines the successor''s seat.py head counts: the second root''s runtime folder is unchanged') `
        -Ok ((Test-T41Refused -Run $t55R -Needles @('the prose names {SEAM_BASES} and the filled brief holds 2 line(s) that are the SEAM BASES line whole, not one')) -and (-not $t55Put)) `
        -Said ((Get-T49Short $t55R 300) + $t55Put + $(if ($t55SeamWrote.Count -gt 0) { ' -- THE BRIEF THE RUN WROTE held ' + $t55SeamWrote.Count + ' line(s) beginning SEAM BASES: [' + ($t55SeamWrote -join '] [') + ']' } else { '' }))
}
$t55Scratch2 = Join-Path $t55Base 'scratch-two'
Write-Utf8 -Path (Join-Path $t55Scratch2 'own.txt') -Text "this seat's own file`n"
Write-Utf8 -Path (Join-Path $t55Scratch2 'seat3\theirs.txt') -Text "a file of the predecessor's copy`n"
$t55R = Invoke-T55Variant -Flags @('--prose', $t55Prose, '--scratch', $t55Scratch2, '--exclude', 'seat3\', '--session', 'fx-session-1', '--seated', $t55Seated)
Add-T55Row -Label '(b) FALSIFIER --exclude MUST NAME A FOLDER: over a scratchpad of one file and a folder seat3 holding another, the composing line with --exclude seat3\ -- a trailing separator, so the name of no top-level folder -- is REFUSED by the flag''s value; no brief is written with the folder''s file among its rows' `
    -Ok (Test-T41Refused -Run $t55R -Needles @('--exclude ''seat3\\'' is not the bare name of a top-level folder of --scratch', $t55Scratch2)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
$t55ExProse = Join-Path $t55Base 'prose\excluded.md'
Write-Utf8 -Path $t55ExProse -Text "{ROWS}|{EXCLUDED_FILES}|{WHOLE}`n"
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('facts', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55ExProse, '--scratch', $t55Scratch2, '--exclude', 'seat3') -Target $t55Lam2
Add-T55Row -Label '(b) CONTROL the bare name seat3 leaves that folder out: facts over the same scratchpad reads ROWS = 1, EXCLUDED_FILES = 1 and WHOLE = 2, exit 0, and writes nothing' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R -Lines @('ROWS = 1  [the walk of --scratch]', 'EXCLUDED_FILES = 1  [the walk of --scratch]', 'WHOLE = 2  [the walk of --scratch]', 'FACTS: 3 token(s) named; nothing was written')) -and ($t55R.Before -eq $t55R.After)) -Said (Get-T49Short $t55R 300)
$t55R = Invoke-T55Variant -Flags @('--prose', $t55Prose, '--scratch', $t55Scratch2, '--exclude', 'own.txt', '--session', 'fx-session-1', '--seated', $t55Seated)
$t55FileSaid = '--exclude ''own.txt'' is not the bare name of a top-level folder of --scratch ' + $t55Scratch2 + ': nothing would be left out'
Add-T55Row -Label '(b) FALSIFIER --exclude MUST NAME A FOLDER, AND A FILE IS NONE: over the same scratchpad, the composing line with --exclude own.txt -- the bare name of the FILE that stands at the top of --scratch: REFUSED in ONE line, whole, by the flag''s value, as the name of no top-level folder -- nothing would be left out; no brief is written' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @($t55FileSaid)) -and (Test-T55Lines -Run $t55R -Lines @(('REFUSED: ' + $t55FileSaid + ' -- nothing was written'))) -and (-not $t55R.Put) -and (Test-Path -LiteralPath (Join-Path $t55Scratch2 'own.txt') -PathType Leaf)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
$t55R = Invoke-T55Variant -Flags @('--prose', $t55Prose, '--scratch', $t55Scratch, '--seated', $t55Seated)
$t55R2 = Invoke-T55Variant -Flags @('--prose', $t55Prose, '--session', 'fx-session-1', '--seated', $t55Seated)
Add-T55Row -Label '(b) FALSIFIER A FLAG THE PROSE NEEDS AND THE LINE LACKS IS REFUSED BY THE FLAG''s NAME: the composing line without --session, its prose naming {SESSION}: --session is not given; and without --scratch, its prose naming {ROWS}: --scratch is not given; no brief is written either time' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('{SESSION} is named and --session is not given')) -and (Test-T41Refused -Run $t55R2 -Needles @('a figure of the scratchpad is named and --scratch is not given'))) -Said ((Get-T49Short $t55R 200) + $t55R.Put + ' ; ' + (Get-T49Short $t55R2 200) + $t55R2.Put)
# ---- (b): THE SCRATCHPAD AS THE SYSTEM OPENS IT, AND AS THE OPERATOR's COPY LINE READS IT ------------------------------------------
# A SHORT (8.3) SPELLING IS THE SYSTEM's OWN: Get-T55Short asks for it, and this member composes none. Where it is given
# none, the row that wants one SAYS SO on its face and holds the refusal of the long name alone. The two scratchpads
# made here -- one named with an apostrophe, one holding a file marked hidden -- stand under this member's %TEMP% root
# and go with it; the hidden mark is taken off again before its row is added.
$t55Lam2Short = Get-T55Short $t55Lam2
$t55PadDriven = ($t55Lam2Short -ine $t55Lam2)
$t55R = Invoke-T55Variant -Flags @('--prose', $t55Prose, '--scratch', $t55Lam2Short, '--session', 'fx-session-1', '--seated', $t55Seated)
Add-T55Row -Label '(b) FALSIFIER NOTHING IS WRITTEN UNDER --scratch, THE FOLDER HELD AS THE SYSTEM OPENS IT: the composing line with --scratch naming the second root''s runtime folder -- the folder the brief is written in -- BY ITS SHORT (8.3) SPELLING, which the system gives: REFUSED, the brief''s path lies inside --scratch; no brief is written into the very folder the keep-table is walked from, and the runtime folder is unchanged. WHERE THE VOLUME KEEPS NO SHORT NAME THERE this row cannot drive that: its reading then says NOT DRIVEN ON THIS VOLUME, and it holds the refusal of the long name alone' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @(('the brief''s path ' + $t55Brief2 + ' lies inside --scratch ' + $t55Lam2Short + ': nothing is written under the scratch folder'))) -and (-not $t55R.Put)) `
    -Said ($(if ($t55PadDriven) { 'the short spelling the system gave: --scratch ' + $t55Lam2Short + ' ; ' } else { 'NOT DRIVEN ON THIS VOLUME: this member was given no short spelling of ' + $t55Lam2 + ', and the refusal held is the long name''s ; ' }) + (Get-T49Short $t55R 300) + $t55R.Put)
$t55AposPad = Join-Path $t55Tmp 'pads\o''brien pad'
Write-Utf8 -Path (Join-Path $t55AposPad 'kept.txt') -Text "the one file of a scratchpad whose folder is named with an apostrophe`n"
$t55AposProse = Join-Path $t55Base 'prose\copy-line.md'
Write-Utf8 -Path $t55AposProse -Text "{COPY_LINE}`n"
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('facts', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55AposProse, '--scratch', $t55AposPad) -Target $t55Lam2
$t55AposOpen = 'COPY_LINE = '
$t55AposClose = '  [the walk of --scratch]'
$t55AposWant = $t55AposOpen + 'Copy-Item -LiteralPath ''' + $t55AposPad.Replace("'", "''") + ''' -Destination .mission-runtime\scratch-copies\arc-fx-9-seat3 -Recurse '
# THE LINE AS THE OPERATOR's SHELL READS IT: what the tool printed between the token's name and its source is given to
# this shell's own tokenizer -- it is NOT RUN -- and the string that tokenizer reads after -LiteralPath is taken.
$t55AposSaid = @(Get-T49Lines -Run $t55R -Head $t55AposOpen)
$t55AposFound = ''
$t55AposLine = ''
if ($t55AposSaid.Count -eq 1) { $t55AposFound = [string]$t55AposSaid[0] }
if ($t55AposFound.EndsWith($t55AposClose, [System.StringComparison]::Ordinal)) { $t55AposLine = $t55AposFound.Substring($t55AposOpen.Length, ($t55AposFound.Length - $t55AposOpen.Length - $t55AposClose.Length)) }
$t55AposErr = $null
$t55AposTok = @([System.Management.Automation.PSParser]::Tokenize($t55AposLine, [ref]$t55AposErr))
$t55AposRead = ''
for ($t55I = 0; $t55I -lt ($t55AposTok.Count - 1); $t55I++) { if (([string]$t55AposTok[$t55I].Type -ceq 'CommandParameter') -and ([string]$t55AposTok[$t55I].Content -ceq '-LiteralPath')) { $t55AposRead = [string]$t55AposTok[$t55I + 1].Content; break } }
Add-T55Row -Label '(b) FALSIFIER AN APOSTROPHE IN THE SCRATCHPAD''s PATH IS WRITTEN TWICE, as the operator''s shell reads one between single quotes: facts over the one-line prose {COPY_LINE}, --scratch a folder named o''brien pad, exits 0 and prints ONE copy line, which opens as his does -- that path WHOLE between its single quotes, each apostrophe of it doubled, then the destination scratch-copies\arc-fx-9-seat3; this shell''s own tokenizer, which runs nothing, reads the line with no error and reads back, after -LiteralPath, the folder''s path as it stands; nothing is written' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and ($t55AposSaid.Count -eq 1) -and $t55AposFound.StartsWith($t55AposWant, [System.StringComparison]::Ordinal) -and [bool]$t55AposLine -and (Test-T55Lines -Run $t55R -Lines @('FACTS: 1 token(s) named; nothing was written')) -and
          (@($t55AposErr).Count -eq 0) -and ($t55AposRead -ceq $t55AposPad) -and ((Get-T55Count -Text $t55AposPad -Needle "'") -ge 1) -and ($t55R.Before -eq $t55R.After)) `
    -Said ('the tokenizer: ' + @($t55AposErr).Count + ' error(s), ' + $t55AposTok.Count + ' token(s), after -LiteralPath it reads [' + $t55AposRead + ']; ' + (Get-T49Short $t55R 400))
$t55HidPad = Join-Path $t55Tmp 'pads\one-hidden'
$t55HidFile = Join-Path $t55HidPad 'unseen.txt'
Write-Utf8 -Path (Join-Path $t55HidPad 'seen.txt') -Text "a file the operator's copy line carries`n"
Write-Utf8 -Path $t55HidFile -Text "a file marked hidden, which his copy line does not carry`n"
$t55HidWas = [System.IO.File]::GetAttributes($t55HidFile)
$t55HidSeen = -1
$t55HidAll = -1
try {
    [System.IO.File]::SetAttributes($t55HidFile, ($t55HidWas -bor [System.IO.FileAttributes]::Hidden))
    $t55HidSeen = @(Get-ChildItem -LiteralPath $t55HidPad -Recurse -File).Count
    $t55HidAll = @(Get-ChildItem -LiteralPath $t55HidPad -Recurse -File -Force).Count
    $t55R = Invoke-T55Variant -Flags @('--prose', $t55Prose, '--scratch', $t55HidPad, '--session', 'fx-session-1', '--seated', $t55Seated)
} finally { [System.IO.File]::SetAttributes($t55HidFile, $t55HidWas) }
$t55HidNow = [System.IO.File]::GetAttributes($t55HidFile)
Add-T55Row -Label '(b) FALSIFIER A HIDDEN FILE OF THE SCRATCHPAD IS REFUSED BY NAME: the composing line over a scratchpad of two files, ONE marked hidden -- this shell''s Get-ChildItem -Recurse -File, the form the operator''s copy line counts by, lists one of them, and two with -Force: REFUSED naming that file HIDDEN -- his copy line, the refusal says, does not carry one; no brief is written counting two, the runtime folder unchanged; and the mark is off again before this row is added' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('the scratch entry ''unseen.txt'' is HIDDEN', 'the operator''s copy line does not carry a hidden file or folder')) -and ($t55HidSeen -eq 1) -and ($t55HidAll -eq 2) -and (($t55HidNow -band [System.IO.FileAttributes]::Hidden) -eq 0) -and (-not $t55R.Put)) `
    -Said ('listed without -Force ' + $t55HidSeen + ', with it ' + $t55HidAll + '; the mark now: ' + $t55HidNow + '; ' + (Get-T49Short $t55R 300) + $t55R.Put)
foreach ($t55Case in @(
        [pscustomobject]@{ what = 'directly inside the runtime folder, in no close folder'; out = (Join-Path $t55Lam2 'head.txt') },
        [pscustomobject]@{ what = 'directly inside close, in no folder of it'; out = (Join-Path $t55Lam2 'close\head.txt') },
        [pscustomobject]@{ what = 'inside a close folder that does not stand'; out = (Join-Path $t55Lam2 'close\fx-none\head.txt') },
        [pscustomobject]@{ what = 'inside a standing folder outside the runtime plane'; out = (Join-Path $t55Root2 'elsewhere\head.txt') })) {
    $t55R = Invoke-T55Second -HeadOut $t55Case.out -Refusal
    Add-T55Row -Label ('(c) FALSIFIER --head-out naming a file ' + $t55Case.what + ': REFUSED, nothing written -- no head file, and no brief either: the runtime folder is unchanged') `
        -Ok ((Test-T41Refused -Run $t55R -Needles @('--head-out ', 'does not lie directly inside one standing folder of')) -and (-not $t55R.Put)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
}
foreach ($t55Leaf in @('halt-x.txt', 'Halt-Y.txt')) {
    $t55R = Invoke-T55Second -HeadOut (Join-Path $t55Close2 $t55Leaf) -Refusal
    Add-T55Row -Label ('(c) FALSIFIER --head-out named ' + $t55Leaf + ' inside the standing close folder: REFUSED by its name, which begins HALT- in some letter case; nothing written, the runtime folder unchanged') `
        -Ok ((Test-T41Refused -Run $t55R -Needles @(('--head-out is named ' + $t55Leaf), 'begins HALT-')) -and (-not $t55R.Put)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
}
# Two names that do NOT begin HALT- and that a volume keeping 8.3 names would list under the evaluator's scan: the scan
# line is run here over the runtime folder BEFORE this member removes what a faulty run wrote.
foreach ($t55Case in @(
        [pscustomobject]@{ leaf = 'H.ALT-x.txt'; what = 'named H.ALT-x.txt inside the standing close folder: REFUSED by its name, which begins HALT- once its dots are dropped'; need = @('--head-out is named H.ALT-x.txt', 'begins HALT- once its dots are dropped') },
        [pscustomobject]@{ leaf = ' HALT-lead.txt'; what = 'named with a LEADING BLANK,  HALT-lead.txt, inside the standing close folder: REFUSED by its name, which is not one token'; need = @('--head-out is named '' HALT-lead.txt''', 'is not one token') })) {
    $t55Out = Join-Path $t55Close2 $t55Case.leaf
    $t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55Prose, '--scratch', $t55Scratch, '--ctx', '77', '--session', 'fx-session-1', '--seated', $t55Seated, '--head-prose', $t55HeadProse, '--head-out', $t55Out) -Target $t55Lam2
    $t55Scan = @(Get-ChildItem -LiteralPath $t55Lam2 -File -Recurse -Filter 'HALT-*')
    $t55Put = Remove-T55Written @($t55Brief2, $t55Out)
    Add-T55Row -Label ('(c) FALSIFIER --head-out ' + $t55Case.what + '; nothing written -- the runtime folder unchanged, and the evaluator''s own scan line over it, Get-ChildItem -File -Recurse -Filter HALT-*, returns 0 files') `
        -Ok ((Test-T41Refused -Run $t55R -Needles $t55Case.need) -and ($t55Scan.Count -eq 0) -and (-not $t55Put)) -Said ((Get-T49Short $t55R 300) + '; the scan line: ' + $t55Scan.Count + ' file(s)' + $(if ($t55Scan.Count -gt 0) { ' -- ' + (@($t55Scan | ForEach-Object { $_.Name }) -join ', ') }) + $t55Put)
}
# A file that ALREADY STANDS at --head-out, and a --head-out inside --scratch. The standing file is this member's own
# bytes, planted in the second root's close folder and taken away again after the two rows; it is also the one file the
# second row's --scratch, that close folder, holds.
$t55Standing = Join-Path $t55Close2 'standing.txt'
$t55StandingText = "bytes this member planted in the close folder: a file that stands, which no run may write over`n"
Write-Utf8 -Path $t55Standing -Text $t55StandingText
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55Prose, '--scratch', $t55Scratch, '--ctx', '77', '--session', 'fx-session-1', '--seated', $t55Seated, '--head-prose', $t55HeadProse, '--head-out', $t55Standing) -Target $t55Lam2
$t55StandingNow = Get-T55Text $t55Standing
$t55Put = Remove-T55Written @($t55Brief2)
if ($t55StandingNow -cne $t55StandingText) { Write-Utf8 -Path $t55Standing -Text $t55StandingText; $t55Put = $t55Put + ' -- THE RUN CHANGED THE PLANTED FILE; this member then put its bytes back' }
Add-T55Row -Label '(c) FALSIFIER A FILE THAT STANDS AT --head-out IS NEVER WRITTEN OVER: the composing line with --head-out naming a file this member planted in the standing close folder: REFUSED in ONE line, whole -- a file already stands at that path -- the planted file BYTE-IDENTICAL after, and no brief written either: the runtime folder is unchanged' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @(('a file already stands at ' + $t55Standing))) -and (Test-T55Lines -Run $t55R -Lines @(('REFUSED: a file already stands at ' + $t55Standing + ' -- nothing was written'))) -and ($t55StandingNow -ceq $t55StandingText) -and (-not $t55Put)) `
    -Said ('the planted file: ' + $t55StandingText.Length + ' B planted, ' + $t55StandingNow.Length + ' B after, sha256 ' + (Get-T30Sha $t55StandingNow) + ' against ' + (Get-T30Sha $t55StandingText) + '; ' + (Get-T49Short $t55R 300) + $t55Put)
$t55Out = Join-Path $t55Close2 'head-in-scratch.txt'
$t55R = Invoke-T55Variant -Flags @('--prose', $t55Prose, '--scratch', $t55Close2, '--session', 'fx-session-1', '--seated', $t55Seated, '--head-prose', $t55HeadProse, '--head-out', $t55Out) -Wrote @($t55Out)
Add-T55Row -Label '(c) FALSIFIER --head-out IS NOT WRITTEN UNDER --scratch: the composing line with --scratch naming the standing close folder ITSELF -- one file in it, the brief''s own path outside it -- and --head-out a new name inside that folder: REFUSED in ONE line, whole -- --head-out lies inside --scratch; nothing written -- no head file beside the one file that folder holds, and no brief either: the runtime folder is unchanged' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('--head-out lies inside --scratch')) -and (Test-T55Lines -Run $t55R -Lines @('REFUSED: --head-out lies inside --scratch -- nothing was written')) -and (@(Get-ChildItem -LiteralPath $t55Close2 -Force).Count -eq 1) -and (-not $t55R.Put)) `
    -Said ((Get-T49Short $t55R 300) + $t55R.Put)
Remove-Item -LiteralPath $t55Standing -Force
# A folder of close that LEADS ELSEWHERE: a junction, made here by cmd's mklink /J inside the second root's close, to
# that root's folder elsewhere -- which stands outside the runtime plane -- and removed by cmd's rmdir, the junction
# ITSELF and never what it leads to, whatever the run between them does and before the row is added.
$t55Led = Join-Path $t55Lam2 'close\led-away'
$t55LedTo = Join-Path $t55Root2 'elsewhere'
$t55Out = Join-Path $t55Led 'head.txt'
$t55LedMade = [pscustomobject]@{ exit = $null; text = '(not run)' }
$t55LedGone = [pscustomobject]@{ exit = $null; text = '(not run)' }
$t55LedStood = $false
$t55Put = ''
try {
    $t55LedMade = Invoke-T55Cmd -Words @('mklink', '/J') -Paths @($t55Led, $t55LedTo)
    $t55LedItem = Get-Item -LiteralPath $t55Led -Force -ErrorAction SilentlyContinue
    $t55LedStood = ($t55LedMade.exit -eq 0) -and ($null -ne $t55LedItem) -and (($t55LedItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) -and (Test-Path -LiteralPath $t55LedTo -PathType Container)
    $t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55Prose, '--scratch', $t55Scratch, '--ctx', '77', '--session', 'fx-session-1', '--seated', $t55Seated, '--head-prose', $t55HeadProse, '--head-out', $t55Out) -Target $t55Lam2
    $t55Put = Remove-T55Written @($t55Brief2, (Join-Path $t55LedTo 'head.txt'))
} finally { if (Test-Path -LiteralPath $t55Led) { $t55LedGone = Invoke-T55Cmd -Words @('rmdir') -Paths @($t55Led) } }
Add-T55Row -Label '(c) FALSIFIER --head-out IS WRITTEN INSIDE A CLOSE FOLDER ITSELF, the folder held as the system opens it: a folder of close that is a JUNCTION to the second root''s folder elsewhere, outside the runtime plane -- a reparse point cmd''s mklink /J made, exit 0, and cmd''s rmdir removed, exit 0, before this row is added -- and --head-out naming a file inside it: REFUSED -- that folder leads elsewhere; nothing written -- no head file in the folder it leads to, and no brief: the runtime folder is unchanged' `
    -Ok ($t55LedStood -and (Test-T41Refused -Run $t55R -Needles @(('--head-out ' + $t55Out + ' lies inside a folder of ' + (Join-Path $t55Lam2 'close') + ' that leads elsewhere ('), '\elsewhere): the head file is written inside a close folder itself')) -and (-not $t55Put) -and
          ($t55LedGone.exit -eq 0) -and (-not (Test-Path -LiteralPath $t55Led)) -and (Test-Path -LiteralPath $t55LedTo -PathType Container)) `
    -Said ('mklink: exit ' + $(if ($null -eq $t55LedMade.exit) { '(none)' } else { [string]$t55LedMade.exit }) + ', a reparse point: ' + $t55LedStood + '; rmdir: exit ' + $(if ($null -eq $t55LedGone.exit) { '(none)' } else { [string]$t55LedGone.exit }) + '; ' + (Get-T49Short $t55R 420) + $t55Put)
foreach ($t55Case in @(
        [pscustomobject]@{ k = 'two'; what = 'of TWO lines'; text = ($t55HeadSecond + "`na third line of the head, which no tool fills`n"); said = 'the head prose is 2 line(s) once filled, not ONE' },
        [pscustomobject]@{ k = 'gap'; what = 'of two lines with an EMPTY line between them'; text = ($t55HeadSecond + "`n`na line after an empty one`n"); said = 'the head prose is 3 line(s) once filled, an empty one among them, not ONE' },
        [pscustomobject]@{ k = 'lead'; what = 'whose FIRST line is empty'; text = ("`n" + $t55HeadSecond + "`n"); said = 'the head prose is 2 line(s) once filled, an empty one among them, not ONE' })) {
    $t55BadHead = Join-Path $t55Base ('prose\head-' + $t55Case.k + '.txt')
    Write-Utf8 -Path $t55BadHead -Text $t55Case.text
    $t55Out = Join-Path $t55Close2 ('head-' + $t55Case.k + '.txt')
    $t55R = Invoke-T55Variant -Flags @('--prose', $t55Prose, '--scratch', $t55Scratch, '--session', 'fx-session-1', '--seated', $t55Seated, '--head-prose', $t55BadHead, '--head-out', $t55Out) -Wrote @($t55Out)
    Add-T55Row -Label ('(c) FALSIFIER THE HEAD FILE IS TWO LINES, the arm line and ONE of the seat''s: the composing line with a head prose ' + $t55Case.what + ': REFUSED, not ONE; nothing written -- no head file, and NO BRIEF either: the runtime folder is unchanged') `
        -Ok ((Test-T41Refused -Run $t55R -Needles @($t55Case.said)) -and (-not $t55R.Put)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
}
$t55Future = Join-Path $t55Base 'fx.future.seated'
Write-Utf8 -Path $t55Future -Text "2099-01-02T03:04:05.678Z`n"
$t55R = Invoke-T55Second -SeatedFile $t55Future -Refusal
$t55NoStamp = Join-Path $t55Base 'fx.no-stamp.seated'
Write-Utf8 -Path $t55NoStamp -Text "2026-01-02T03:04:05Z`n"
$t55R2 = Invoke-T55Second -SeatedFile $t55NoStamp -Refusal
Add-T55Row -Label '(e) FALSIFIER THE STAMP A CALLER HANDS compose IS IN A FILE, the one --seated names, and is held to the clock: a stamp of the year 2099 is REFUSED as later than the clock at the write, and a stamp without its milliseconds is REFUSED as no stamp; nothing written' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('2099-01-02T03:04:05.678Z, is later than the clock at the write')) -and (Test-T41Refused -Run $t55R2 -Needles @('does not hold ONE stamp YYYY-MM-DDTHH:MM:SS.mmmZ'))) -Said ((Get-T49Short $t55R 220) + $t55R.Put + ' ; ' + (Get-T49Short $t55R2 220) + $t55R2.Put)
$t55HeadOut2 = Join-Path $t55Close2 'head.txt'
$t55C2 = Invoke-T55Second -HeadOut $t55HeadOut2
$t55Arm2Lines = @(Get-T49Lines -Run $t55C2 -Head 'HANDOFF AT ')
$t55Arm2 = if ($t55Arm2Lines.Count -eq 1) { [string]$t55Arm2Lines[0] } else { '' }
Add-T55Row -Label '(b), (c) THE SAME LINE, the prose unharmed and --head-out inside the standing close folder, COMPOSES in the second root: exit 0, one arm line, the brief and the head file written -- so each refusal above was of what its row changed' `
    -Ok ((Test-T49Said -Run $t55C2 -Exit 0 -Needles @()) -and ($t55Arm2Lines.Count -eq 1) -and (Test-Path -LiteralPath $t55Brief2 -PathType Leaf) -and (Test-Path -LiteralPath $t55HeadOut2 -PathType Leaf) -and ($t55C2.Before -ne $t55C2.After)) -Said (Get-T49Short $t55C2 300)

# ---- (h): the bases are the --predecessor-brief's, and the arithmetic is whole ------------------------------------------
$t55FixBrief = Join-Path $t55Lines 'fixed-bases.md'
Write-Utf8 -Path $t55FixBrief -Text ("# a predecessor's brief, a fixture: its two bases are fixture stamps`n`nSEAM BASES first $t55FixFirst end $t55FixEnd`n")
$t55Old2 = Get-T55Text $t55Status2
$t55P2 = Invoke-T49Py -Tool $t49Seat -PyArgs @('head', '--root', $t55Root2, '--line-file', $t55HeadOut2, '--place-handoff', '--predecessor-brief', $t55FixBrief) -Target $t55Lam2
$t55New2 = Get-T55Text $t55Status2
$t55Hm2 = [regex]::Match((Get-T55At ($t55New2.Split("`n")) 1), '\ASEAT 3 of ARC-FX-9 hands over at (\S+) \(ctx 77%\); ')
$t55Hs2 = if ($t55Hm2.Success) { $t55Hm2.Groups[1].Value } else { '' }
$t55Fs1 = Get-T55Span -From $t55FixFirst -To $t55Hs2
$t55Fs2 = Get-T55Span -From $t55FixEnd -To $t55Hs2
$t55New2Want = $t55Arm2 + "`n" + $t55HeadFilled.Replace('{CLOCKMS}', $t55Hs2).Replace('{SEAM_FROM_FIRST}', $t55Fs1).Replace('{SEAM_FROM_END}', $t55Fs2) + "`n" + $t55Old2
Add-T55Row -Label '(h) FALSIFIER THE BASES ARE THE --predecessor-brief''s, not the placed brief''s own: the second root''s head file placed against a brief whose bases are the two fixture stamps of January -- both spans are whole minutes and more, each what this member computes from those stamps to the stamp on the line, and STATUS.md is again new == placed + old' `
    -Ok ((Test-T49Said -Run $t55P2 -Exit 0 -Needles @()) -and [bool]$t55Arm2 -and ((Get-T49Clock $t55Hs2) -lt 120) -and ($t55Fs1 -cmatch '\A[1-9][0-9]* min ') -and ($t55Fs2 -cmatch '\A[1-9][0-9]* min ') -and ($t55Fs1 -cne $t55Fs2) -and ($t55New2 -ceq $t55New2Want) -and ($t55Old2 -ceq $t55StatusText)) `
    -Said ('exit ' + $(if ($null -eq $t55P2.Code) { '(none)' } else { [string]$t55P2.Code }) + '; stamp ' + $t55Hs2 + '; computed here [' + $t55Fs1 + '] and [' + $t55Fs2 + ']; line 2 reads [' + (Get-T55At ($t55New2.Split("`n")) 1) + ']' + $(if ($null -eq $t55P2.Code) { ' -- ' + $t55P2.Text }))

# ---- (a): which slot is which -- arm over a planted brief whose two digests differ --------------------------------------
$t55CrBrief = Join-Path $t55Lam2 'HANDOFF-ARC-FX-9-seat-5.md'
Write-T49Bytes -Path $t55CrBrief -Bytes ($t49Utf8.GetBytes("# a planted brief`r`nits lines end in CR LF, so its two digests differ`r`n"))
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('arm', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '5', '--ctx', '100') -Target $t55Lam2
$t55CrLines = @(Get-T49Lines -Run $t55R -Head 'HANDOFF AT ')
$t55CrM = $t55LiftRx.Match($(if ($t55CrLines.Count -eq 1) { [string]$t55CrLines[0] } else { '' }))
$t55CrLf = Get-T37LfSha -Path $t55CrBrief
$t55CrRaw = Get-T41Sha $t55CrBrief
Add-T55Row -Label '(a) FALSIFIER WHICH SLOT IS WHICH: over a planted brief whose lines end CR LF, arm at ctx 100 prints ONE line the lifted pattern matches, its first slot the LF/blob digest (CR LF folded) and its second the working digest -- two different digests, each re-derived here -- and writes nothing' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and $t55LiftOk -and ($t55CrLines.Count -eq 1) -and $t55CrM.Success -and ($t55CrM.Groups['ctx'].Value -ceq '100') -and ($t55CrM.Groups['lf'].Value -ceq $t55CrLf) -and ($t55CrM.Groups['raw'].Value -ceq $t55CrRaw) -and ($t55CrLf -cne $t55CrRaw) -and
          ($t55CrM.Groups['path'].Value -ceq '.mission-runtime/lam/HANDOFF-ARC-FX-9-seat-5.md') -and ($t55R.Before -eq $t55R.After)) `
    -Said ('slots ' + $t55CrM.Groups['lf'].Value + ' ; ' + $t55CrM.Groups['raw'].Value + '; re-derived LF/blob ' + $t55CrLf + ', working ' + $t55CrRaw + '; ' + (Get-T49Short $t55R 160))
# WHICH FIGURE IS WHICH. The row of the brief's own figures reads them over a brief that holds no CR, whose two digests
# are one value. A second brief is planted here, as seat 6, its lines ending CR LF, and arm writes a head file of its own
# for it into the second root's close folder.
$t55CrBrief6 = Join-Path $t55Lam2 'HANDOFF-ARC-FX-9-seat-6.md'
Write-T49Bytes -Path $t55CrBrief6 -Bytes ($t49Utf8.GetBytes("# a second planted brief`r`nits lines end in CR LF too, and a head prose names this brief's own figures`r`n"))
$t55CrFigProse = Join-Path $t55Base 'prose\head.crlf-figures.txt'
Write-Utf8 -Path $t55CrFigProse -Text "the brief {BRIEF_REL}, {BRIEF_BYTES} B, working sha256 {BRIEF_SHA}, LF/blob {BRIEF_LF_SHA}`n"
$t55CrFigOut = Join-Path $t55Close2 'head-crlf-figures.txt'
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('arm', '--root', $t55Root2, '--arc', 'ARC-FX-9', '--seat', '6', '--ctx', '100', '--head-prose', $t55CrFigProse, '--head-out', $t55CrFigOut) -Target $t55Lam2
$t55CrFigArm = @(Get-T49Lines -Run $t55R -Head 'HANDOFF AT ')
$t55CrFigText = Get-T55Text $t55CrFigOut
$t55CrFigLf = Get-T37LfSha -Path $t55CrBrief6
$t55CrFigRaw = Get-T41Sha $t55CrBrief6
$t55CrFigLine = 'the brief .mission-runtime/lam/HANDOFF-ARC-FX-9-seat-6.md, ' + (Get-Item -LiteralPath $t55CrBrief6).Length + ' B, working sha256 ' + $t55CrFigRaw + ', LF/blob ' + $t55CrFigLf
Add-T55Row -Label '(c) FALSIFIER WHICH FIGURE IS WHICH: over a second planted brief whose lines end CR LF, arm with a head prose naming {BRIEF_BYTES}, {BRIEF_SHA} and {BRIEF_LF_SHA} exits 0 and writes a head file of two lines -- the one arm line the run printed, and a second line that holds, whole, the brief''s length, its WORKING digest for {BRIEF_SHA} and its LF/blob digest (CR LF folded) for {BRIEF_LF_SHA}: two different digests, each re-derived here' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and ($t55CrFigArm.Count -eq 1) -and ($t55CrFigLf -cne $t55CrFigRaw) -and ((Get-T55At ($t55CrFigText.Split("`n")) 1) -ceq $t55CrFigLine) -and
          ($t55CrFigText -ceq ((Get-T55At $t55CrFigArm 0) + "`n" + $t55CrFigLine + "`n")) -and ($t55R.Before -ne $t55R.After)) `
    -Said ('line 2 of the head file reads [' + (Get-T55At ($t55CrFigText.Split("`n")) 1) + ']; re-derived here: working ' + $t55CrFigRaw + ', LF/blob ' + $t55CrFigLf + '; ' + (Get-T49Short $t55R 200))

# ---- (e): no flag takes a time -- seat.py copy ----------------------------------------------------------------------------
Write-Utf8 -Path (Join-Path $t55Root2 '.mission\goals\G-T55.verdict.yaml') -Text (New-T49Verdict -Root $t55Root2 -Goal 'G-T55' -At $t55FixFirst -Verdict 'MET')
$t55CopyArgs = @('copy', '--root', $t55Root2, '--goal', 'G-T55', '--close-folder', 'fx-t55')
$t55NowCopy = Invoke-T49Py -Tool $t49Seat -PyArgs ($t55CopyArgs + @('--now', $t55FixFirst)) -Target $t55Rt2
$t55NowCopyPut = Remove-T55Written @(Get-ChildItem -LiteralPath $t55Close2 -File -Filter 'G-T55.verdict.*' | ForEach-Object { $_.FullName })
$t55R = Invoke-T49Py -Tool $t49Seat -PyArgs $t55CopyArgs -Target $t55Rt2
Add-T55Row -Label '(e) FALSIFIER NO FLAG TAKES A TIME, seat.py copy: over a SYNTHETIC verdict in the second root, the line given --now and a stamp besides is argparse''s usage error -- exit 2, unrecognized arguments, no REFUSED line, .mission-runtime unchanged -- and the same line without the flag COPIES, exit 0' `
    -Ok ((Test-T55Usage -Run $t55NowCopy -Prog 'seat.py' -ErrorLine ('seat.py: error: unrecognized arguments: --now ' + $t55FixFirst)) -and (Test-T49Said -Run $t55R -Exit 0 -Needles @('VERDICT MET evaluated_at ' + $t55FixFirst)) -and (@(Get-T49Lines -Run $t55R -Head 'COPIED ').Count -eq 1) -and ($t55R.Before -ne $t55R.After)) `
    -Said ((Get-T49Short $t55NowCopy 240) + $t55NowCopyPut + ' ; without the flag: ' + (Get-T49Short $t55R 160))

# ---- (i), (j), (c): THE THIRD ROOT, inside the second -- the figures, the declared tokens, and arm over a census finding -----
# Its files are this member's own texts, each as small as the figure read from it: a mission file whose completed_at:
# stands empty, two specs, a goal file, an admissions record and a spawn ledger of one line each, ONE live capture.
# The spec pointer, the mirror and the commit ledger are written by the rows that read them.
$t55Root3 = Join-Path $t55Tmp 'r3'
$t55Lam3 = Join-Path $t55Root3 '.mission-runtime\lam'
$t55Close3 = Join-Path $t55Lam3 'close\fx-t55'
$t55Brief3 = Join-Path $t55Lam3 'HANDOFF-ARC-FX-9-seat-3.md'
$t55Adm = Join-Path $t55Lam3 'handoff-admissions.jsonl'
$t55Commits = Join-Path $t55Lam3 'commit-ledger.jsonl'
$t55Spawns = Join-Path $t55Lam3 'spawn-ledger.jsonl'
$t55Capture = Join-Path $t55Lam3 'instrument-runs\G-T55.stub-instrument.stdout.txt'
$t55Mission = Join-Path $t55Root3 '.mission\mission.yaml'
$t55Mirror = Join-Path $t55Root3 '.mission\green-gate\product.json'
$t55Pointer = Join-Path $t55Root3 '.mission\spec\current.txt'
$t55GoalFile = Join-Path $t55Root3 '.mission\goals\G-T55.yaml'
New-Item -ItemType Directory -Path $t55Close3 -Force | Out-Null
Write-Utf8 -Path $t55Adm -Text ('{"fixture": "ONE line of a fixture record, written by this member"}' + "`n")
Write-Utf8 -Path $t55Spawns -Text ('{"seq": 0, "event": "spawn", "dispatch_id": "d-fx-1", "composed_by": "a fixture"}' + "`n")
Write-Utf8 -Path $t55Mission -Text "id: mission-t55`nstate: executing`ncompleted_at:`ncurrent_spec_version: 7`nladder_rung: # none yet`n"
$t55SpecText = "features:`n  - id: F-001`n    status: done`nmilestones:`n  - id: M-1`n    status: sealed`n    contract_assertion_ids: [A-001]`n  - id: M-2`n    status: sealed`n"
Write-Utf8 -Path (Join-Path $t55Root3 '.mission\spec\v-empty.yaml') -Text ($t55SpecText + "    contract_assertion_ids: []`n")
Write-Utf8 -Path (Join-Path $t55Root3 '.mission\spec\v-none.yaml') -Text $t55SpecText
Write-Utf8 -Path $t55GoalFile -Text "id: G-T55`ndetectors:`n  - type: halt_absent`n"
Write-Utf8 -Path $t55Capture -Text ((@('# lam-instrument-run capture', ('head: ' + ('0' * 40)), '--- stdout ---', 'TALLY passed=1 failed=0 skipped=0 deselected=0 runnable=1 stored_floor=1 collection_error=False pytest_exit=0 elapsed_seconds=3', '--- end ---') -join "`n") + "`n")
$t55Third = @(Get-ChildItem -LiteralPath $t55Root3 -Recurse -File -Force | ForEach-Object { $_.FullName.Substring($t55Root3.Length + 1) } | Sort-Object)
Add-T55Row -Label '(fixture) CONTROL the third root stands inside the second, under %TEMP%: seven files of this member''s own text -- a mission file, two specs, a goal file, an admissions record, a spawn ledger, one live capture -- an empty close folder, and no brief' `
    -Ok (($t55Third.Count -eq 7) -and ($t55Root3 + '\').StartsWith(($t55Root2.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase) -and (@(Get-ChildItem -LiteralPath $t55Close3 -Force).Count -eq 0) -and (-not (Test-Path -LiteralPath $t55Brief3)) -and
          (Test-Path -LiteralPath $t55Adm -PathType Leaf) -and (Test-Path -LiteralPath $t55Capture -PathType Leaf) -and (Test-Path -LiteralPath $t55Mission -PathType Leaf)) -Said ($t55Third -join ' ; ')
function Invoke-T55Facts {
    # ONE gen_brief.py facts over the third root: the prose is -Text, written here to a file named by -Key; the flags
    # after --root, --arc, --seat and --prose are the row's. -Target: what is digested before and after the run -- the
    # third root, whole, where no file of it is held; '' where a holder has one.
    param([string]$Key, [string]$Text, [string[]]$Flags, [string]$Target)
    $t55File = Join-Path $t55Base ('prose\facts-' + $Key + '.md')
    Write-Utf8 -Path $t55File -Text $Text
    return (Invoke-T49Py -Tool $t49Gen -PyArgs (@('facts', '--root', $t55Root3, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55File) + @($Flags | Where-Object { $_ })) -Target $Target)
}
$t55Holder = Join-Path $t55Tmp 'hold.ps1'
Write-Utf8 -Path $t55Holder -Text (@('param([string]$Path, [string]$Share, [string]$Ready)',
    '$t55Stream = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::$Share)',
    '[System.IO.File]::WriteAllText($Ready, ''ready'')', 'Start-Sleep -Seconds 30', '$t55Stream.Close()') -join "`n")
function Invoke-T55Held {
    # facts over the third root WHILE A SECOND PROCESS HOLDS ONE FILE OF IT WITH NO SHARING (the holder script above,
    # T-49 (g)'s form): -Runs are the runs made under the one hold, each a key, a text and its flags for
    # Invoke-T55Facts. The root's listing digest is taken BEFORE the holder opens the file and AFTER the holder is
    # gone -- this member's own read asks a sharing the holder does not give -- and each run's own target is none.
    # Returns whether the holder was live, each run with the seconds it took, and the two digests.
    param([string]$Path, [object[]]$Runs)
    $t55Before = Get-T49TreeSha $t55Root3
    $t55Ready = Join-Path $t55Tmp ('ready-' + [guid]::NewGuid().ToString('N').Substring(0, 8) + '.flag')
    $t55Proc = $null
    $t55IsLive = $false
    $t55Got = New-Object System.Collections.Generic.List[object]
    try {
        $t55Proc = Start-Process -FilePath 'powershell' -PassThru -WindowStyle Hidden -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $t55Holder, '-Path', $Path, '-Share', 'None', '-Ready', $t55Ready)
        $t55Waited = 0
        while (-not (Test-Path -LiteralPath $t55Ready) -and $t55Waited -lt 150) { Start-Sleep -Milliseconds 100; $t55Waited++ }
        $t55IsLive = (Test-Path -LiteralPath $t55Ready)
        foreach ($t55One in $Runs) {
            $t55Sw = [System.Diagnostics.Stopwatch]::StartNew()
            $t55Run = Invoke-T55Facts -Key $t55One.key -Text $t55One.text -Flags $t55One.flags -Target ''
            $t55Sw.Stop()
            $t55Got.Add([pscustomobject]@{ Code = $t55Run.Code; Text = $t55Run.Text; Before = $t55Run.Before; After = $t55Run.After; Took = $t55Sw.Elapsed.TotalSeconds })
        }
    } finally { if ($t55Proc) { try { Stop-Process -Id $t55Proc.Id -Force -ErrorAction SilentlyContinue; $t55Proc.WaitForExit(5000) | Out-Null } catch { } } }
    return [pscustomobject]@{ Live = $t55IsLive; Runs = $t55Got; Before = $t55Before; After = (Get-T49TreeSha $t55Root3) }
}

# ---- (i): a figure that is not there is REFUSED, never written as a word; one reader for every file ---------------------------
$t55SpecSource = '.mission/spec/current.txt, the spec it names, the roster''s assertion files'
Write-Utf8 -Path $t55Pointer -Text "v-empty`n"
$t55R = Invoke-T55Facts -Key 'roster' -Text "{ROSTER}|{ASSERTIONS}`n" -Flags @() -Target $t55Root3
Add-T55Row -Label '(i) FALSIFIER AN EMPTY ROSTER IS A VALUE: over a spec whose LAST milestone binds contract_assertion_ids: [], facts over {ROSTER}|{ASSERTIONS} exits 0 and prints the lines ROSTER = with nothing after it and ASSERTIONS = none, each whole with its source; two tokens named, and nothing written -- the third root''s listing digest unchanged' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R -Lines @(('ROSTER =   [' + $t55SpecSource + ']'), ('ASSERTIONS = none  [' + $t55SpecSource + ']'), 'FACTS: 2 token(s) named; nothing was written')) -and ($t55R.Before -eq $t55R.After)) -Said (Get-T49Short $t55R 400)
Write-Utf8 -Path $t55Pointer -Text "v-none`n"
$t55R = Invoke-T55Facts -Key 'assertions' -Text "{ASSERTIONS}`n" -Flags @() -Target $t55Root3
Add-T55Row -Label '(i) CONTROL a spec whose last milestone holds NO contract_assertion_ids line is still REFUSED: {ASSERTIONS} could not be derived -- a roster that is not found is not a roster of none' `
    -Ok (Test-T41Refused -Run $t55R -Needles @(('{ASSERTIONS} could not be derived from ' + $t55SpecSource))) -Said (Get-T49Short $t55R 300)
$t55H = Invoke-T55Held -Path $t55Adm -Runs @([pscustomobject]@{ key = 'adm'; text = "{ADM}`n"; flags = @() })
$t55R = $t55H.Runs[0]
Add-T55Row -Label '(i) FALSIFIER ONE READER: facts naming {ADM} while a second process HOLDS the fixture''s admissions record WITH NO SHARING: REFUSED by name after not less than 0.8 s (five tries 200 ms apart) -- exit 2, ONE REFUSED line, no traceback, it is not read as absent -- and the third root is as it was once the holder is gone' `
    -Ok ($t55H.Live -and (Test-T41Refused -Run $t55R -Needles @(('the admissions record at ' + $t55Adm), 'could not be opened in five tries 200 ms apart', 'it is not read as absent')) -and ($t55R.Took -ge 0.8) -and ($t55H.Before -eq $t55H.After)) `
    -Said ('holder live ' + $t55H.Live + '; ' + [Math]::Round($t55R.Took, 2) + ' s; ' + (Get-T49Short $t55R 300))
$t55R = Invoke-T55Facts -Key 'adm' -Text "{ADM}`n" -Flags @() -Target $t55Root3
Add-T55Row -Label '(i) CONTROL the same line with nothing held: exit 0, ADM = 1 -- the record''s one line -- and nothing written; so the refusal above was the hold''s' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R -Lines @('ADM = 1  [.mission-runtime/lam/handoff-admissions.jsonl]', 'FACTS: 1 token(s) named; nothing was written')) -and ($t55R.Before -eq $t55R.After)) -Said (Get-T49Short $t55R 300)
Write-Utf8 -Path $t55Mirror -Text "[1, 2]`n"
$t55R = Invoke-T55Facts -Key 'floor' -Text "{FLOOR}`n" -Flags @() -Target $t55Root3
Add-T55Row -Label '(i) FALSIFIER a mirror that is JSON and NOT AN OBJECT -- product.json holding the list [1, 2] -- with {FLOOR} named: REFUSED by name, no traceback, nothing written' `
    -Ok (Test-T41Refused -Run $t55R -Needles @('.mission/green-gate/product.json is JSON but not an object')) -Said (Get-T49Short $t55R 300)
$t55ByNeed = '{CL_LAST_BY} could not be derived from .mission-runtime/lam/commit-ledger.jsonl'
$t55ClLine = 'CL = 1  [.mission-runtime/lam/commit-ledger.jsonl]'
Write-Utf8 -Path $t55Commits -Text ('{"sha": "' + ('0' * 40) + '"}' + "`n")
$t55R = Invoke-T55Facts -Key 'by' -Text "{CL}|{CL_LAST_BY}`n" -Flags @() -Target $t55Root3
Write-Utf8 -Path $t55Commits -Text ('{"sha": "' + ('0' * 40) + '", "composed_by": null}' + "`n")
$t55R2 = Invoke-T55Facts -Key 'by' -Text "{CL}|{CL_LAST_BY}`n" -Flags @() -Target $t55Root3
Add-T55Row -Label '(i) FALSIFIER A VALUE THAT IS NOT THERE IS NOT WRITTEN AS A WORD: a commit ledger of ONE line that lacks its composed_by key, and the same line with the key holding JSON null: each time facts reads the ledger -- CL = 1 -- and REFUSES {CL_LAST_BY} as one that could not be derived; nothing written' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @($t55ByNeed)) -and (Test-T55Lines -Run $t55R -Lines @($t55ClLine)) -and (Test-T41Refused -Run $t55R2 -Needles @($t55ByNeed)) -and (Test-T55Lines -Run $t55R2 -Lines @($t55ClLine))) -Said ((Get-T49Short $t55R 220) + ' ; ' + (Get-T49Short $t55R2 220))
$t55R = Invoke-T55Facts -Key 'completed' -Text "{SPEC}|{COMPLETED}`n" -Flags @() -Target $t55Root3
Add-T55Row -Label '(i) FALSIFIER a mission.yaml whose completed_at: stands EMPTY on its line, current_spec_version: 7 on the next: facts reads SPEC = 7 and REFUSES {COMPLETED} as one that could not be derived -- the value is looked for on the key''s own line, and the next line''s key is not taken for it' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('{COMPLETED} could not be derived from .mission/mission.yaml')) -and (Test-T55Lines -Run $t55R -Lines @('SPEC = 7  [.mission/mission.yaml]')) -and (Get-T55Text $t55Mission).Contains("`ncompleted_at:`ncurrent_spec_version: 7`n")) -Said (Get-T49Short $t55R 300)
$t55R = Invoke-T55Facts -Key 'rung' -Text "{SPEC}|{RUNG}`n" -Flags @() -Target $t55Root3
Add-T55Row -Label '(i) FALSIFIER and its ladder_rung: line holds ONLY A COMMENT after the colon -- # none yet: facts reads SPEC = 7 and REFUSES {RUNG} as one that could not be derived -- a comment is not a value' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('{RUNG} could not be derived from .mission/mission.yaml')) -and (Test-T55Lines -Run $t55R -Lines @('SPEC = 7  [.mission/mission.yaml]')) -and (Get-T55Text $t55Mission).Contains("`nladder_rung: # none yet`n")) -Said (Get-T49Short $t55R 300)
Write-Utf8 -Path $t55Mirror -Text ('{"stored_floor": 0, "expected_failure_test_ids": []}' + "`n")
$t55R = Invoke-T55Facts -Key 'falsy' -Text "{SL_LAST_SEQ}|{FLOOR}|{XFAIL_IDS}`n" -Flags @() -Target $t55Root3
Add-T55Row -Label '(i) CONTROL values that are falsy and THERE still fill: a spawn ledger''s last seq of 0, a stored_floor of 0 and an empty list of expected failures read 0, 0 and [], exit 0, nothing written' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R -Lines @('SL_LAST_SEQ = 0  [.mission-runtime/lam/spawn-ledger.jsonl]', 'FLOOR = 0  [.mission/green-gate/product.json]', 'XFAIL_IDS = []  [.mission/green-gate/product.json]', 'FACTS: 3 token(s) named; nothing was written')) -and ($t55R.Before -eq $t55R.After)) -Said (Get-T49Short $t55R 400)
$t55GoalSha = Get-T41Sha $t55GoalFile
$t55H = Invoke-T55Held -Path $t55Capture -Runs @(
    [pscustomobject]@{ key = 'goal'; text = "{GOAL_SHA}`n"; flags = @('--goal', 'G-T55') },
    [pscustomobject]@{ key = 'goal-capture'; text = "{GOAL_SHA}|{CAPTURE_SHA}`n"; flags = @('--goal', 'G-T55') })
$t55R = $t55H.Runs[0]
$t55R2 = $t55H.Runs[1]
Add-T55Row -Label '(i) FALSIFIER THE LIVE CAPTURE IS READ ONLY WHERE NAMED: while a second process holds the goal''s ONE live capture with no sharing, facts with --goal over a prose naming {GOAL_SHA} and NO CAPTURE_ token exits 0 with the goal file''s digest as this member re-derives it -- the capture was not opened -- and writes nothing' `
    -Ok ($t55H.Live -and (Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R -Lines @(('GOAL_SHA = ' + $t55GoalSha + '  [the goal file of --goal]'), 'FACTS: 1 token(s) named; nothing was written')) -and ($t55H.Before -eq $t55H.After)) `
    -Said ('holder live ' + $t55H.Live + '; ' + [Math]::Round($t55R.Took, 2) + ' s; ' + (Get-T49Short $t55R 300))
Add-T55Row -Label '(i) FALSIFIER and under the same hold the same prose with {CAPTURE_SHA} added is REFUSED naming the live capture, after not less than 0.8 s: ONE REFUSED line, no traceback, it is not read as absent; the third root is as it was once the holder is gone' `
    -Ok ($t55H.Live -and (Test-T41Refused -Run $t55R2 -Needles @(('the live capture at ' + $t55Capture), 'could not be opened in five tries 200 ms apart', 'it is not read as absent')) -and ($t55R2.Took -ge 0.8) -and ($t55H.Before -eq $t55H.After)) `
    -Said ('holder live ' + $t55H.Live + '; ' + [Math]::Round($t55R2.Took, 2) + ' s; ' + (Get-T49Short $t55R2 300))

# ---- (i): three figures held to their words -- the acts log by the file's own lines, the goal matched to its end, the arc to the dash after it ----
# The acts log, the settings file and the three HALT files are this member's own texts, written here in the third root,
# under %TEMP%: each line of the log carries the two fields the tool reads of one, its gate and its tool_exit.
$t55Acts = Join-Path $t55Root3 '.mission-runtime\operator-acts.log'
$t55ActLines = @(
    '2026-01-02T03:04:05.678Z kind=gate-act verb=approve gate=dispatch-t55-fixture-a preview_digest=0 tool_exit=0',
    '2026-01-02T03:04:06.678Z kind=gate-act verb=approve gate=push-t55-fixture-b preview_digest=0 tool_exit=0',
    '2026-01-02T03:04:07.678Z kind=gate-act verb=approve gate=push-t55-fixture-c preview_digest=0 tool_exit=0')
$t55ActSource = '  [.mission-runtime/operator-acts.log from the line --acts-from names]'
$t55ActText = "{LOG}|{ACTS_FROM}|{TALLY}|{TALLY_N}`n"
$t55ActNamed = 'FACTS: 4 token(s) named; nothing was written'
Write-Utf8 -Path $t55Acts -Text (($t55ActLines -join "`n") + "`n")
$t55R = Invoke-T55Facts -Key 'acts-beyond' -Text $t55ActText -Flags @('--acts-from', '4') -Target $t55Root3
$t55R2 = Invoke-T55Facts -Key 'acts-last' -Text $t55ActText -Flags @('--acts-from', '3') -Target $t55Root3
Add-T55Row -Label '(i) FALSIFIER A LINE BEYOND THE ACTS LOG''s END IS REFUSED: over a log of THREE lines -- a dispatch, a push, a push, each exited 0, no line empty -- facts with --acts-from 4 is REFUSED in ONE line, whole: it is beyond the log''s 3 line(s), nothing written; and --acts-from 3, the log''s last line, exits 0 with LOG = 3, TALLY = 0/0/0/1/0 and TALLY_N = 1, each line whole with its source -- so the refusal was of the line beyond' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('--acts-from 4 is beyond the acts log''s 3 line(s)')) -and (Test-T55Lines -Run $t55R -Lines @('REFUSED: --acts-from 4 is beyond the acts log''s 3 line(s) -- nothing was written')) -and (Test-T49Said -Run $t55R2 -Exit 0 -Needles @()) -and
          (Test-T55Lines -Run $t55R2 -Lines @(('LOG = 3' + $t55ActSource), ('ACTS_FROM = 3' + $t55ActSource), ('TALLY = 0/0/0/1/0' + $t55ActSource), ('TALLY_N = 1' + $t55ActSource), $t55ActNamed)) -and ($t55R2.Before -eq $t55R2.After)) `
    -Said ((Get-T49Short $t55R 200) + ' ; --acts-from 3: ' + (Get-T49Short $t55R2 400))
Write-Utf8 -Path $t55Acts -Text ((@($t55ActLines[0], '', $t55ActLines[1], $t55ActLines[2]) -join "`n") + "`n")
$t55ActFile = (Get-T55Text $t55Acts).Split("`n")
$t55R = Invoke-T55Facts -Key 'acts-from-3' -Text $t55ActText -Flags @('--acts-from', '3') -Target $t55Root3
$t55R2 = Invoke-T55Facts -Key 'acts-from-4' -Text $t55ActText -Flags @('--acts-from', '4') -Target $t55Root3
Add-T55Row -Label '(i) FALSIFIER --acts-from IS THE FILE''s OWN LINE NUMBER: the same log with an EMPTY line made its line 2 -- file lines 1 a dispatch, 2 empty, 3 a push, 4 a push: facts with --acts-from 3 exits 0 with LOG = 3, the lines that hold an act, TALLY = 0/0/0/2/0 and TALLY_N = 2 -- both pushes, which stand from the file''s line 3; and with --acts-from 4, the file''s last line, exits 0 with ONE push, 0/0/0/1/0 and 1; each line whole with its source, nothing written' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R -Lines @(('LOG = 3' + $t55ActSource), ('ACTS_FROM = 3' + $t55ActSource), ('TALLY = 0/0/0/2/0' + $t55ActSource), ('TALLY_N = 2' + $t55ActSource), $t55ActNamed)) -and ($t55R.Before -eq $t55R.After) -and
          (Test-T49Said -Run $t55R2 -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R2 -Lines @(('LOG = 3' + $t55ActSource), ('ACTS_FROM = 4' + $t55ActSource), ('TALLY = 0/0/0/1/0' + $t55ActSource), ('TALLY_N = 1' + $t55ActSource), $t55ActNamed)) -and ($t55R2.Before -eq $t55R2.After) -and
          ($t55ActFile.Count -eq 5) -and ((Get-T55At $t55ActFile 1) -ceq '') -and ((Get-T55At $t55ActFile 2) -ceq $t55ActLines[1]) -and ((Get-T55At $t55ActFile 3) -ceq $t55ActLines[2])) `
    -Said ('--acts-from 3: ' + (Get-T49Short $t55R 400) + ' ; --acts-from 4: ' + (Get-T49Short $t55R2 400))
# {NFR_LINE} IS THE FILE's OWN LINE NUMBER AS WELL. AN EIGHTH ROOT stands inside the second, under %TEMP%: a mission ledger
# of three entries and nothing else, this member's own text -- no entry of it holds a stamp, and the second states the
# next free row. The ledger is written twice: with ONE EMPTY LINE after its first entry, then with none. The line the
# statement stands on is counted here each time, from the file's own bytes cut at LF.
$t55Root8 = Join-Path $t55Tmp 'r8'
$t55Ledger8 = Join-Path $t55Root8 '.mission\ledger\entries.jsonl'
$t55Entries8 = @('{"id": "E-1", "content": "an entry of this fixture that states nothing of the register"}', '{"id": "E-2", "content": "NEXT FREE ROW 414"}', '{"id": "E-3", "content": "a later entry of this fixture, which states nothing of it either"}')
$t55NfrSource = '  [.mission/ledger/entries.jsonl]'
$t55NfrNamed = 'FACTS: 3 token(s) named; nothing was written'
$t55NfrProse = Join-Path $t55Base 'prose\facts-nfr-line.md'
Write-Utf8 -Path $t55NfrProse -Text "{ML}|{NFR}|{NFR_LINE}`n"
$t55NfrArgs = @('facts', '--root', $t55Root8, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55NfrProse)
Write-Utf8 -Path $t55Ledger8 -Text ((@($t55Entries8[0], '', $t55Entries8[1], $t55Entries8[2]) -join "`n") + "`n")
$t55NfrGapText = Get-T55Text $t55Ledger8
$t55NfrGapAt = [Array]::IndexOf($t55NfrGapText.Split("`n"), $t55Entries8[1]) + 1
$t55NfrGap = Invoke-T49Py -Tool $t49Gen -PyArgs $t55NfrArgs -Target $t55Root8
Write-Utf8 -Path $t55Ledger8 -Text (($t55Entries8 -join "`n") + "`n")
$t55NfrPlainText = Get-T55Text $t55Ledger8
$t55NfrPlainAt = [Array]::IndexOf($t55NfrPlainText.Split("`n"), $t55Entries8[1]) + 1
$t55NfrPlain = Invoke-T49Py -Tool $t49Gen -PyArgs $t55NfrArgs -Target $t55Root8
Add-T55Row -Label '(i) FALSIFIER {NFR_LINE} IS THE FILE''s OWN LINE NUMBER: in an eighth root under %TEMP%, a mission ledger of THREE entries, the second stating NEXT FREE ROW 414, with ONE EMPTY LINE after the first -- four lines by its line ends, the statement on the file''s line 3 as this member counts it: facts over {ML}|{NFR}|{NFR_LINE} exits 0 with ML = 3, the entries, NFR = 414 and NFR_LINE = 3; and the same three entries with no empty line -- three lines, the statement on line 2 -- read ML = 3, NFR = 414 and NFR_LINE = 2, so the 3 was the empty line''s; each line whole with its source, nothing written either time' `
    -Ok ((Test-T49Said -Run $t55NfrGap -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55NfrGap -Lines @(('ML = 3' + $t55NfrSource), ('NFR = 414' + $t55NfrSource), ('NFR_LINE = ' + $t55NfrGapAt + $t55NfrSource), $t55NfrNamed)) -and ($t55NfrGap.Before -eq $t55NfrGap.After) -and
          (Test-T49Said -Run $t55NfrPlain -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55NfrPlain -Lines @(('ML = 3' + $t55NfrSource), ('NFR = 414' + $t55NfrSource), ('NFR_LINE = ' + $t55NfrPlainAt + $t55NfrSource), $t55NfrNamed)) -and ($t55NfrPlain.Before -eq $t55NfrPlain.After) -and
          ((Get-T55Count -Text $t55NfrGapText -Needle "`n") -eq 4) -and $t55NfrGapText.Contains(($t55Entries8[0] + "`n`n" + $t55Entries8[1] + "`n")) -and ($t55NfrGapAt -eq 3) -and ((Get-T55Count -Text $t55NfrPlainText -Needle "`n") -eq 3) -and ($t55NfrPlainAt -eq 2)) `
    -Said ('with the empty line -- ' + (Get-T55Count -Text $t55NfrGapText -Needle "`n") + ' line(s) by the file''s line ends, the statement on its line ' + $t55NfrGapAt + ': ' + (Get-T49Short $t55NfrGap 400) + ' ; with none -- ' + (Get-T55Count -Text $t55NfrPlainText -Needle "`n") + ' line(s), the statement on line ' + $t55NfrPlainAt + ': ' + (Get-T49Short $t55NfrPlain 400))
$t55Settings = Join-Path $t55Root3 '.claude\settings.local.json'
Write-Utf8 -Path $t55Settings -Text ('{"fixture": "a settings file of this member''s own text; it is no session''s", "commands": ["a hook line -Goal G10", "a hook line -Goal G1x", "a hook line -Goal G1"]}' + "`n")
$t55R = Invoke-T55Facts -Key 'hook-count' -Text "{HOOK_COUNT}`n" -Flags @('--goal', 'G1') -Target $t55Root3
Add-T55Row -Label '(i) FALSIFIER THE GOAL IS MATCHED TO ITS END: over a settings file that holds -Goal G10, -Goal G1x and -Goal G1, each once -- the text -Goal G1 three times, as this member counts it -- facts with --goal G1 over {HOOK_COUNT} exits 0 with HOOK_COUNT = 1, the line whole with its source; nothing written' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R -Lines @('HOOK_COUNT = 1  [.claude/settings.local.json]', 'FACTS: 1 token(s) named; nothing was written')) -and ((Get-T55Count -Text (Get-T55Text $t55Settings) -Needle '-Goal G1') -eq 3) -and ($t55R.Before -eq $t55R.After)) `
    -Said ('the text -Goal G1 in the file: ' + (Get-T55Count -Text (Get-T55Text $t55Settings) -Needle '-Goal G1') + ' time(s); ' + (Get-T49Short $t55R 300))
$t55HaltNames = @('HALT-ARC-X-1-01.md', 'HALT-ARC-X-10-01.md', 'HALT-ARC-X-11-02.md')
foreach ($t55N in $t55HaltNames) { Write-Utf8 -Path (Join-Path $t55Root3 ('.mission-runtime\halts\' + $t55N)) -Text "a fixture HALT, this member's own text, in a root under %TEMP%`n" }
$t55HaltProse = Join-Path $t55Base 'prose\facts-halts.md'
Write-Utf8 -Path $t55HaltProse -Text "{HALTS_RAISED}|{HALTS_NAMES}|{HALTS_ANSWERED}|{HALTS_OPEN}`n"
$t55HaltSource = '  [.mission-runtime/halts/HALT-<ARC>-*.md and whether each one''s ruling gate file exists]'
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('facts', '--root', $t55Root3, '--arc', 'ARC-X-1', '--seat', '3', '--prose', $t55HaltProse) -Target $t55Root3
$t55HaltHeld = [string[]]@(Get-ChildItem -LiteralPath (Join-Path $t55Root3 '.mission-runtime\halts') -File -Filter 'HALT-ARC-X-1*.md' | ForEach-Object { $_.Name })
[Array]::Sort($t55HaltHeld, [System.StringComparer]::Ordinal)
Add-T55Row -Label '(i) FALSIFIER THE ARC IS MATCHED TO THE DASH AFTER IT: the third root holding three HALT files -- of ARC-X-1, of ARC-X-10 and of ARC-X-11, all three names beginning HALT-ARC-X-1 -- and no ruling gate: facts with --arc ARC-X-1 exits 0 with HALTS_RAISED = 1, HALTS_NAMES the one file of that arc ALONE, HALTS_ANSWERED = 0 and HALTS_OPEN = 1, each line whole with its source; nothing written' `
    -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R -Lines @(('HALTS_RAISED = 1' + $t55HaltSource), ('HALTS_NAMES = HALT-ARC-X-1-01.md' + $t55HaltSource), ('HALTS_ANSWERED = 0' + $t55HaltSource), ('HALTS_OPEN = 1' + $t55HaltSource), $t55ActNamed)) -and
          (($t55HaltHeld -join ' ') -ceq ($t55HaltNames -join ' ')) -and ($t55R.Before -eq $t55R.After)) `
    -Said ('files beginning HALT-ARC-X-1: ' + ($t55HaltHeld -join ', ') + '; ' + (Get-T49Short $t55R 400))
# THE ARC's HALT FILES WITHOUT REGARD TO LETTER CASE. A NINTH ROOT stands inside the second, under %TEMP%: a halts folder
# holding FOUR fixture HALT files of ARC-H-1, this member's own text, named in four letter cases, and no gate. The order
# the figure names them in is derived here: by the name in small letters, ordinal -- which is NOT the order of the names
# as they are spelled. The scan line is run over that root's runtime folder, as the row of H.ALT-x.txt above runs it.
$t55Root9 = Join-Path $t55Tmp 'r9'
$t55Rt9 = Join-Path $t55Root9 '.mission-runtime'
$t55Halts9 = Join-Path $t55Rt9 'halts'
$t55CaseNames = @('HALT-ARC-H-1-01.md', 'halt-arc-h-1-02.md', 'HALT-arc-h-1-03.md', 'Halt-ARC-H-1-04.md')
foreach ($t55CaseName in $t55CaseNames) { Write-Utf8 -Path (Join-Path $t55Halts9 $t55CaseName) -Text "a fixture HALT, this member's own text, in a root under %TEMP%: its name is in a letter case of its own`n" }
$t55CaseKeys = [string[]]@($t55CaseNames | ForEach-Object { $_.ToLowerInvariant() })
$t55CaseOrder = [string[]]@($t55CaseNames)
[Array]::Sort($t55CaseKeys, $t55CaseOrder, [System.StringComparer]::Ordinal)
$t55CaseSpelled = [string[]]@($t55CaseNames)
[Array]::Sort($t55CaseSpelled, [System.StringComparer]::Ordinal)
$t55CaseHeld = [string[]]@(Get-ChildItem -LiteralPath $t55Halts9 -File -Force | ForEach-Object { $_.Name })
[Array]::Sort($t55CaseHeld, [System.StringComparer]::Ordinal)
$t55CaseScan = @(Get-ChildItem -LiteralPath $t55Rt9 -File -Recurse -Filter 'HALT-*')
$t55CaseProse = Join-Path $t55Base 'prose\facts-halts-letter-case.md'
Write-Utf8 -Path $t55CaseProse -Text "{HALTS_RAISED}|{HALTS_NAMES}|{HALTS_ANSWERED}|{HALTS_OPEN}`n"
$t55CaseSource = '  [.mission-runtime/halts/HALT-<ARC>-*.md and whether each one''s ruling gate file exists]'
$t55CaseRun = Invoke-T49Py -Tool $t49Gen -PyArgs @('facts', '--root', $t55Root9, '--arc', 'ARC-H-1', '--seat', '3', '--prose', $t55CaseProse) -Target $t55Root9
Add-T55Row -Label '(i) FALSIFIER THE ARC''s HALT FILES ARE COUNTED WITHOUT REGARD TO LETTER CASE: in a ninth root under %TEMP%, a halts folder holding FOUR files of ARC-H-1 named in four letter cases -- HALT-ARC-H-1-01.md, halt-arc-h-1-02.md, HALT-arc-h-1-03.md and Halt-ARC-H-1-04.md, every one of which the evaluator''s own scan line, Get-ChildItem -File -Recurse -Filter HALT-*, lists -- and no ruling gate: facts with --arc ARC-H-1 exits 0 with HALTS_RAISED = 4, HALTS_NAMES the four by their names in small letters, HALTS_ANSWERED = 0 and HALTS_OPEN = 4, each line whole with its source; nothing written' `
    -Ok ((Test-T49Said -Run $t55CaseRun -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55CaseRun -Lines @(('HALTS_RAISED = 4' + $t55CaseSource), ('HALTS_NAMES = ' + ($t55CaseOrder -join ', ') + $t55CaseSource), ('HALTS_ANSWERED = 0' + $t55CaseSource), ('HALTS_OPEN = 4' + $t55CaseSource), 'FACTS: 4 token(s) named; nothing was written')) -and
          ($t55CaseRun.Before -eq $t55CaseRun.After) -and (($t55CaseOrder -join ', ') -ceq 'HALT-ARC-H-1-01.md, halt-arc-h-1-02.md, HALT-arc-h-1-03.md, Halt-ARC-H-1-04.md') -and (($t55CaseSpelled -join ', ') -cne ($t55CaseOrder -join ', ')) -and
          (($t55CaseHeld -join ', ') -ceq ($t55CaseSpelled -join ', ')) -and ($t55CaseScan.Count -eq 4) -and (-not (Test-Path -LiteralPath (Join-Path $t55Root9 '.mission'))) -and
          ($t55Root9 + '\').StartsWith(($env:TEMP.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase)) `
    -Said ('the folder holds: ' + ($t55CaseHeld -join ', ') + '; the scan line: ' + $t55CaseScan.Count + ' file(s); by the name in small letters: ' + ($t55CaseOrder -join ', ') + '; ' + (Get-T49Short $t55CaseRun 520))

# ---- (j): the declared tokens -- composed over the third root -----------------------------------------------------------------
function Invoke-T55Third {
    # ONE compose over the third root: the prose is -Text and the declare file the lines of -Declare, each written
    # here to a file named by -Key. Its target is the third root's runtime folder. -Refusal: the row expects REFUSED,
    # and a brief the run wrote regardless is removed afterwards and said as .Put.
    param([string]$Key, [string]$Text, [string[]]$Declare, [switch]$Refusal)
    $t55File = Join-Path $t55Base ('prose\third-' + $Key + '.md')
    $t55DeclareFile = Join-Path $t55Base ('prose\third-' + $Key + '.declare.txt')
    Write-Utf8 -Path $t55File -Text $Text
    Write-Utf8 -Path $t55DeclareFile -Text (($Declare -join "`n") + "`n")
    $t55Run = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t55Root3, '--arc', 'ARC-FX-9', '--seat', '3', '--ctx', '77', '--prose', $t55File, '--declare', $t55DeclareFile) -Target $t55Lam3
    return [pscustomobject]@{ Code = $t55Run.Code; Text = $t55Run.Text; Before = $t55Run.Before; After = $t55Run.After; Put = $(if ($Refusal) { Remove-T55Written @($t55Brief3) } else { '' }) }
}
$t55R = Invoke-T55Third -Key 'absent-glob' -Text "# {ARC}, SEAT {SEAT}: a page of one declared figure`nno ruling gate stands: {GONE}`n" -Declare @('GONE = absent .mission/gates/halt-ruling-*.yaml') -Refusal
Add-T55Row -Label '(j) FALSIFIER absent TAKES ONE EXACT PATH: a declare line GONE = absent .mission/gates/halt-ruling-*.yaml, {GONE} named in the prose: REFUSED by its line -- a name holding * cannot stand, so the figure would read True whatever stood there -- and no brief is written: the third root''s runtime folder is unchanged' `
    -Ok (Test-T41Refused -Run $t55R -Needles @('line 1 of the declare file: `absent` takes ONE exact path', '.mission/gates/halt-ruling-*.yaml holds * or ?')) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
$t55R = Invoke-T55Third -Key 'declare-abs' -Text "# {ARC}, SEAT {SEAT}: a page of one declared figure`na file outside the root: {OUT_ABS}`n" -Declare @(('OUT_ABS = sha256 ' + $t55Seated)) -Refusal
$t55R2 = Invoke-T55Third -Key 'declare-up' -Text "# {ARC}, SEAT {SEAT}: a page of one declared figure`na file outside the root: {OUT_UP}`n" -Declare @('OUT_UP = bytes ..\.mission-runtime\lam\STATUS.md') -Refusal
Add-T55Row -Label '(j) FALSIFIER A DECLARED PATH IS ONE FROM --root AND UNDER IT: a declare line naming a standing file by its ABSOLUTE path, and one naming a standing file by ..\ out of the root, each token named in the prose: each REFUSED by its line as not a path under --root, and no brief is written' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @(('line 1 of the declare file: ' + $t55Seated + ' is not a path under --root'))) -and (Test-T41Refused -Run $t55R2 -Needles @('line 1 of the declare file: ..\.mission-runtime\lam\STATUS.md is not a path under --root')) -and
          (Test-Path -LiteralPath $t55Seated -PathType Leaf) -and (Test-Path -LiteralPath (Join-Path $t55Root3 '..\.mission-runtime\lam\STATUS.md') -PathType Leaf)) -Said ((Get-T49Short $t55R 240) + $t55R.Put + ' ; ' + (Get-T49Short $t55R2 240) + $t55R2.Put)
$t55R = Invoke-T55Third -Key 'declare-abs-under' -Text "# {ARC}, SEAT {SEAT}: a page of one declared figure`na file under the root, named by its absolute path: {IN_ABS}`n" -Declare @(('IN_ABS = bytes ' + $t55Mission)) -Refusal
$t55AbsSaid = 'line 1 of the declare file: ' + $t55Mission + ' is not a path under --root (a declared figure is read under the mission root, by a path from it)'
Add-T55Row -Label '(j) FALSIFIER AN ABSOLUTE PATH IS NO PATH FROM --root, WHEREVER IT LEADS: a declare line naming the third root''s OWN mission file -- a file that stands UNDER --root -- by its ABSOLUTE path, its token named in the prose: REFUSED in ONE line, whole, by its line as not a path under --root, by a path from it; and no brief is written' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @($t55AbsSaid)) -and (Test-T55Lines -Run $t55R -Lines @(('REFUSED: ' + $t55AbsSaid + ' -- nothing was written'))) -and (-not $t55R.Put) -and [System.IO.Path]::IsPathRooted($t55Mission) -and
          $t55Mission.StartsWith(($t55Root3.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $t55Mission -PathType Leaf)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
# A DECLARED PATH WHOSE WILDCARD PART A JUNCTION ANSWERS. A FIFTH ROOT stands inside the second, under %TEMP%: a runtime
# folder and nothing else. Beside it -- outside it, inside this member's %TEMP% root -- a folder holds ONE file of this
# member's own text. The junction lnk1 is made in the fifth root by cmd's mklink /J, to that folder, and removed by cmd's
# rmdir -- the junction ITSELF, never what it leads to -- whatever the run between them does, and before either row is
# added. As a pattern, lnk*/secret.txt lies under the root; the one file that answers it does not. Whether a brief the
# run wrote regardless held that file's digest is read, for the row's face, before this member removes that brief.
$t55Root5 = Join-Path $t55Tmp 'r5'
$t55Rt5 = Join-Path $t55Root5 '.mission-runtime'
$t55Brief5 = Join-Path $t55Rt5 'lam\HANDOFF-ARC-FX-9-seat-3.md'
$t55Beyond = Join-Path $t55Tmp 'beyond-r5'
$t55Secret = Join-Path $t55Beyond 'secret.txt'
$t55SecretText = "a file OUTSIDE the fifth root: no figure of that root is read from it`n"
New-Item -ItemType Directory -Path (Join-Path $t55Rt5 'lam') -Force | Out-Null
Write-Utf8 -Path $t55Secret -Text $t55SecretText
$t55SecretSha = Get-T41Sha $t55Secret
$t55LnkPage = Join-Path $t55Base 'prose\fifth-wildcard.md'
$t55LnkDeclare = Join-Path $t55Base 'prose\fifth-wildcard.declare.txt'
Write-Utf8 -Path $t55LnkPage -Text "# {ARC}, SEAT {SEAT}: a page of one declared figure`na file a wildcard answers: {X}`n"
Write-Utf8 -Path $t55LnkDeclare -Text "X = sha256 lnk*/secret.txt`n"
$t55Lnk = Join-Path $t55Root5 'lnk1'
$t55LnkMade = [pscustomobject]@{ exit = $null; text = '(not run)' }
$t55LnkGone = [pscustomobject]@{ exit = $null; text = '(not run)' }
$t55LnkStood = $false
$t55LnkHeld = $false
$t55LnkMet = -1
$t55Put = ''
try {
    $t55LnkMade = Invoke-T55Cmd -Words @('mklink', '/J') -Paths @($t55Lnk, $t55Beyond)
    $t55LnkItem = Get-Item -LiteralPath $t55Lnk -Force -ErrorAction SilentlyContinue
    $t55LnkStood = ($t55LnkMade.exit -eq 0) -and ($null -ne $t55LnkItem) -and (($t55LnkItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) -and ((Get-T55Text (Join-Path $t55Lnk 'secret.txt')) -ceq $t55SecretText)
    $t55LnkMet = @(Get-ChildItem -LiteralPath $t55Root5 -Force -Filter 'lnk*').Count
    $t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t55Root5, '--arc', 'ARC-FX-9', '--seat', '3', '--ctx', '77', '--prose', $t55LnkPage, '--declare', $t55LnkDeclare) -Target $t55Rt5
    $t55LnkHeld = (Get-T55Text $t55Brief5).Contains($t55SecretSha)
    $t55Put = Remove-T55Written @($t55Brief5)
} finally { if (Test-Path -LiteralPath $t55Lnk) { $t55LnkGone = Invoke-T55Cmd -Words @('rmdir') -Paths @($t55Lnk) } }
Add-T55Row -Label '(j) CONTROL THE JUNCTION STOOD FOR THE ROW BELOW AND IS GONE: in a fifth root under %TEMP%, cmd''s mklink /J made the folder lnk1 a junction to a folder that stands OUTSIDE that root, exit 0 -- a reparse point, through which this member read that folder''s one file byte for byte; and cmd''s rmdir removed the junction ITSELF, exit 0: nothing stands at its path, and the folder it led to and its file stand as they were' `
    -Ok ($t55LnkStood -and ($t55LnkGone.exit -eq 0) -and (-not (Test-Path -LiteralPath $t55Lnk)) -and (Test-Path -LiteralPath $t55Beyond -PathType Container) -and ((Get-T55Text $t55Secret) -ceq $t55SecretText) -and
          ($t55Root5 + '\').StartsWith(($env:TEMP.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase) -and ($t55Beyond + '\').StartsWith(($env:TEMP.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase) -and
          (-not ($t55Beyond + '\').StartsWith(($t55Root5.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase))) `
    -Said ('mklink: exit ' + $(if ($null -eq $t55LnkMade.exit) { '(none)' } else { [string]$t55LnkMade.exit }) + '; it stood, a reparse point the file was read through: ' + $t55LnkStood + '; rmdir: exit ' + $(if ($null -eq $t55LnkGone.exit) { '(none)' } else { [string]$t55LnkGone.exit }) + ' ' + $t55LnkGone.text + '; a thing stands at its path now: ' + (Test-Path -LiteralPath $t55Lnk))
Add-T55Row -Label '(j) FALSIFIER THE FILE A WILDCARD ANSWERS IS HELD TO --root TOO, by the path the system opens: over that fifth root a declare line X = sha256 lnk*/secret.txt -- the one name its wildcard meets is the junction lnk1, and the one file that answers stands outside the root -- with {X} named in the prose: REFUSED by its line, the file named being no path under --root by the path the system opens; no brief is written carrying the digest of a file outside the root -- that root''s .mission-runtime is unchanged' `
    -Ok ($t55LnkStood -and (Test-T41Refused -Run $t55R -Needles @('REFUSED: line 1 of the declare file: lnk*/secret.txt names ', '\beyond-r5\secret.txt, which is not a path under --root by the path the system opens (a declared figure is read under the mission root) -- nothing was written')) -and (-not $t55Put) -and (-not $t55LnkHeld) -and ($t55LnkMet -eq 1)) `
    -Said ((Get-T49Short $t55R 420) + $t55Put + '; names of that root the wildcard lnk* met while the junction stood: ' + $t55LnkMet + '; the file outside the root: sha256 ' + $t55SecretSha + '; a brief the run wrote held that digest: ' + $t55LnkHeld)
$t55R = Invoke-T55Third -Key 'declare-brief' -Text "# {ARC}, SEAT {SEAT}: a page of one declared figure`nthe brief is {BRIEF_BYTES} B, so says the brief itself`n" -Declare @('BRIEF_BYTES = bytes .mission/mission.yaml') -Refusal
Add-T55Row -Label '(j) FALSIFIER THE BRIEF''s OWN FIGURES CANNOT BE DECLARED: a declare line BRIEF_BYTES = bytes and a standing file, the prose naming {BRIEF_BYTES}: REFUSED -- the tool fills that name itself -- and no brief is written carrying another file''s length' `
    -Ok (Test-T41Refused -Run $t55R -Needles @('line 1 of the declare file declares {BRIEF_BYTES}, which this tool fills itself')) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
foreach ($t55Case in @(
        [pscustomobject]@{ k = 'sha'; name = 'BRIEF_SHA'; what = 'its working digest' },
        [pscustomobject]@{ k = 'lf-sha'; name = 'BRIEF_LF_SHA'; what = 'its LF/blob digest' })) {
    $t55R = Invoke-T55Third -Key ('declare-brief-' + $t55Case.k) -Text ("# {ARC}, SEAT {SEAT}: a page of one declared figure`nthe brief's digest is {" + $t55Case.name + "}, so says the brief itself`n") -Declare @(($t55Case.name + ' = sha256 .mission/mission.yaml')) -Refusal
    $t55OwnSaid = 'line 1 of the declare file declares {' + $t55Case.name + '}, which this tool fills itself'
    Add-T55Row -Label ('(j) FALSIFIER AND NEITHER CAN THE BRIEF''s OWN DIGESTS, ' + $t55Case.what + ': a declare line ' + $t55Case.name + ' = sha256 and a standing file, the prose naming {' + $t55Case.name + '}: REFUSED in ONE line, whole -- the tool fills that name itself -- and no brief is written carrying another file''s digest') `
        -Ok ((Test-T41Refused -Run $t55R -Needles @($t55OwnSaid)) -and (Test-T55Lines -Run $t55R -Lines @(('REFUSED: ' + $t55OwnSaid + ' -- nothing was written'))) -and (-not $t55R.Put) -and (Test-Path -LiteralPath $t55Mission -PathType Leaf)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
}
# A declared figure whose VALUE holds a token's form, and a declared glob that TWO files answer. The files the declare
# lines name are this member's own texts, written here under the third root's folder figs.
$t55NoteFile = Join-Path $t55Root3 'figs\note.yaml'
Write-Utf8 -Path $t55NoteFile -Text "note: see {NOW} and {CLOCKMS}`n"
$t55NoteNeed = 'the value of {NOTE} holds {NOW}: a figure that carries a token''s form would be read as a token by what fills this text next'
$t55NoteDeclare = Join-Path $t55Base 'prose\third-note-head.declare.txt'
$t55NotePage = Join-Path $t55Base 'prose\third-note-head.md'
$t55NoteHead = Join-Path $t55Base 'prose\head.note.txt'
$t55NoteOut = Join-Path $t55Close3 'head-note.txt'
Write-Utf8 -Path $t55NoteDeclare -Text "NOTE = key note of figs/note.yaml`n"
Write-Utf8 -Path $t55NotePage -Text "# {ARC}, SEAT {SEAT}: a page that names no declared figure`n"
Write-Utf8 -Path $t55NoteHead -Text "SEAT {SEAT} of {ARC} hands over at {CLOCKMS}; the note: {NOTE}`n"
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t55Root3, '--arc', 'ARC-FX-9', '--seat', '3', '--ctx', '77', '--prose', $t55NotePage, '--declare', $t55NoteDeclare, '--head-prose', $t55NoteHead, '--head-out', $t55NoteOut) -Target $t55Lam3
$t55Put = Remove-T55Written @($t55Brief3, $t55NoteOut)
Add-T55Row -Label '(j) FALSIFIER A VALUE THAT HOLDS A TOKEN''s FORM IS REFUSED, in the head prose: a declare line NOTE = key note of a file whose note reads see {NOW} and {CLOCKMS}, a page that does not name it and a HEAD prose that does: compose is REFUSED naming {NOTE} and the {NOW} its value holds, BEFORE the brief is written -- no brief, and no head file carrying a {CLOCKMS} that is not the seat''s: the third root''s runtime folder is unchanged' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @($t55NoteNeed)) -and (-not $t55Put) -and ((Get-T55Text $t55NoteFile) -ceq "note: see {NOW} and {CLOCKMS}`n")) -Said ((Get-T49Short $t55R 300) + $t55Put)
$t55R = Invoke-T55Third -Key 'note-brief' -Text "# {ARC}, SEAT {SEAT}: a page of one declared figure`nthe note: {NOTE}`n" -Declare @('NOTE = key note of figs/note.yaml') -Refusal
Add-T55Row -Label '(j) FALSIFIER and in the brief''s own prose: the same declare line, the PAGE naming {NOTE}: compose is REFUSED in the same words -- {NOTE}, and the {NOW} its value holds -- and no brief is written' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @($t55NoteNeed)) -and (-not $t55R.Put)) -Said ((Get-T49Short $t55R 300) + $t55R.Put)
# The value above holds {NOW} before its {CLOCKMS}, and is refused for the {NOW}. This one holds {CLOCKMS} ALONE: one of
# the three tokens seat.py head fills, which a head prose may itself name. The second line of a head file the run wrote
# regardless is read, for this row's face, before this member removes that file and the brief.
$t55ClockFile = Join-Path $t55Root3 'figs\clock.yaml'
$t55ClockDeclare = Join-Path $t55Base 'prose\third-clock-head.declare.txt'
$t55ClockPage = Join-Path $t55Base 'prose\third-clock-head.md'
$t55ClockHead = Join-Path $t55Base 'prose\head.clock.txt'
$t55ClockOut = Join-Path $t55Close3 'head-clock.txt'
Write-Utf8 -Path $t55ClockFile -Text "note: at {CLOCKMS}`n"
Write-Utf8 -Path $t55ClockDeclare -Text "STAMPED = key note of figs/clock.yaml`n"
Write-Utf8 -Path $t55ClockPage -Text "# {ARC}, SEAT {SEAT}: a page that names no declared figure`n"
Write-Utf8 -Path $t55ClockHead -Text "SEAT {SEAT} of {ARC} hands over at {CLOCKMS}; the note: {STAMPED}`n"
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t55Root3, '--arc', 'ARC-FX-9', '--seat', '3', '--ctx', '77', '--prose', $t55ClockPage, '--declare', $t55ClockDeclare, '--head-prose', $t55ClockHead, '--head-out', $t55ClockOut) -Target $t55Lam3
$t55ClockWrote = Get-T55At ((Get-T55Text $t55ClockOut).Split("`n")) 1
$t55Put = Remove-T55Written @($t55Brief3, $t55ClockOut)
$t55StampedSaid = 'the value of {STAMPED} holds {CLOCKMS}: a figure that carries a token''s form would be read as a token by what fills this text next'
Add-T55Row -Label '(j) FALSIFIER AND {CLOCKMS} ALONE IS A TOKEN''s FORM AS ANY OTHER, though a head prose may name it: a declare line STAMPED = key note of a file whose note reads at {CLOCKMS} -- that token and no other -- a page that does not name it and a HEAD prose that does: compose is REFUSED in ONE line, whole, naming {STAMPED} and the {CLOCKMS} its value holds, BEFORE the brief is written -- no brief, and no head file carrying a second {CLOCKMS} that is not the seat''s: the third root''s runtime folder is unchanged' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @($t55StampedSaid)) -and (Test-T55Lines -Run $t55R -Lines @(('REFUSED: ' + $t55StampedSaid + ' -- nothing was written'))) -and (-not $t55Put) -and ((Get-T55Text $t55ClockFile) -ceq "note: at {CLOCKMS}`n")) `
    -Said ((Get-T49Short $t55R 300) + $t55Put + $(if ($t55ClockWrote) { ' -- THE HEAD FILE THE RUN WROTE read, on its second line, [' + $t55ClockWrote + ']' } else { '' }))
Write-Utf8 -Path (Join-Path $t55Root3 'figs\two-a.txt') -Text "the first of two files one glob answers`n"
Write-Utf8 -Path (Join-Path $t55Root3 'figs\two-b.txt') -Text "the second of them`n"
$t55R = Invoke-T55Third -Key 'declare-two' -Text "# {ARC}, SEAT {SEAT}: a page of one declared figure`none file of two: {TWO}`n" -Declare @('TWO = name-of-one figs/two-*.txt') -Refusal
$t55OneDeclare = Join-Path $t55Base 'prose\facts-declare-one.declare.txt'
Write-Utf8 -Path $t55OneDeclare -Text "ONE = name-of-one figs/two-a*.txt`n"
$t55R2 = Invoke-T55Facts -Key 'declare-one' -Text "{ONE}`n" -Flags @('--declare', $t55OneDeclare) -Target $t55Root3
Add-T55Row -Label '(j) FALSIFIER A DECLARED GLOB NAMES EXACTLY ONE FILE: a declare line TWO = name-of-one figs/two-*.txt, which TWO files of the third root answer, {TWO} named in the prose: REFUSED by its line -- 2 file(s) match, not one -- and no brief is written with the first of them taken; and facts over a line of the same kind whose glob ONE of the two answers reads that file''s name, exit 0, nothing written -- so the refusal was of the count' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('line 1 of the declare file: 2 file(s) match figs/two-*.txt, not one')) -and (-not $t55R.Put) -and (@(Get-ChildItem -LiteralPath (Join-Path $t55Root3 'figs') -File -Filter 'two-*.txt').Count -eq 2) -and
          (Test-T49Said -Run $t55R2 -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55R2 -Lines @('ONE = two-a.txt  [declared: name-of-one figs/two-a*.txt]', 'FACTS: 1 token(s) named; nothing was written')) -and ($t55R2.Before -eq $t55R2.After)) `
    -Said ((Get-T49Short $t55R 240) + $t55R.Put + ' ; one file: ' + (Get-T49Short $t55R2 200))
# A ROOT WHOSE OWN NAME HOLDS BRACKETS. A TENTH ROOT stands inside the second, under %TEMP%, and is NAMED root[1]: a folder
# figs holding ONE file of this member's own text, and nothing else. Read as a pattern, that root's own path is a
# character class and names no folder that stands. That the folder was made under that very name is read back here, from
# the second root's own listing. The declare file and the prose stand in the sandbox, outside that root.
$t55BrkRoot = Join-Path $t55Tmp 'root[1]'
$t55BrkFile = Join-Path $t55BrkRoot 'figs\one.txt'
Write-Utf8 -Path $t55BrkFile -Text "the one file of a root whose own name holds brackets`n"
$t55BrkSha = Get-T41Sha $t55BrkFile
$t55BrkPage = Join-Path $t55Base 'prose\facts-bracket-root.md'
$t55BrkDeclare = Join-Path $t55Base 'prose\facts-bracket-root.declare.txt'
Write-Utf8 -Path $t55BrkPage -Text "{X}|{Y}`n"
Write-Utf8 -Path $t55BrkDeclare -Text "X = sha256 figs/o*.txt`nY = name-of-one figs/one.txt`n"
$t55BrkRun = Invoke-T49Py -Tool $t49Gen -PyArgs @('facts', '--root', $t55BrkRoot, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55BrkPage, '--declare', $t55BrkDeclare) -Target $t55BrkRoot
$t55BrkHeld = @(Get-ChildItem -LiteralPath $t55Tmp -Force | Where-Object { $_.PSIsContainer -and ($_.Name -ceq 'root[1]') })
$t55BrkFiles = @()
if ($t55BrkHeld.Count -eq 1) { $t55BrkFiles = @(Get-ChildItem -LiteralPath $t55BrkRoot -Recurse -File -Force | ForEach-Object { $_.FullName.Substring($t55BrkRoot.Length + 1) }) }
Add-T55Row -Label '(j) FALSIFIER A ROOT WHOSE OWN NAME HOLDS BRACKETS IS TAKEN AS SPELLED, the wildcards being the declared path''s own: in a tenth root under %TEMP% NAMED root[1], which holds ONE file, figs\one.txt, a declare file of two lines -- X = sha256 figs/o*.txt and Y = name-of-one figs/one.txt -- with the prose {X}|{Y}: facts exits 0 with X that file''s digest, re-derived here, and Y = one.txt, each line whole with its source; nothing written -- that root''s listing digest unchanged' `
    -Ok ((Test-T49Said -Run $t55BrkRun -Exit 0 -Needles @()) -and (Test-T55Lines -Run $t55BrkRun -Lines @(('X = ' + $t55BrkSha + '  [declared: sha256 figs/o*.txt]'), 'Y = one.txt  [declared: name-of-one figs/one.txt]', 'FACTS: 2 token(s) named; nothing was written')) -and ($t55BrkRun.Before -eq $t55BrkRun.After) -and
          ($t55BrkSha -cmatch '\A[0-9a-f]{64}\z') -and ($t55BrkHeld.Count -eq 1) -and ($t55BrkFiles.Count -eq 1) -and ((Get-T55At $t55BrkFiles 0) -ceq 'figs\one.txt') -and
          ($t55BrkRoot + '\').StartsWith(($env:TEMP.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase)) `
    -Said ('folders named root[1] under the second root: ' + $t55BrkHeld.Count + ', holding ' + $t55BrkFiles.Count + ' file(s): ' + ($t55BrkFiles -join ', ') + '; that file re-derived: sha256 ' + $t55BrkSha + '; ' + (Get-T49Short $t55BrkRun 420))
# A BRACKET IN THE DECLARED PATH ITSELF -- the seat's own row, one step beside the row above. AN ELEVENTH ROOT stands
# inside the second, under %TEMP%, its own name plain: a folder NAMED figs[1] holding ONE file of this member's own text.
# Read as a pattern, that folder's name is a character class: it names no folder figs[1], and it names a folder figs1.
# facts is asked TWICE with one command line: first with figs[1] alone under the root, then with a folder figs1 beside
# it that holds a file of the same name and OTHER bytes. The declare file and the prose stand in the sandbox.
$t55DbkRoot = Join-Path $t55Tmp 'r11'
$t55DbkFile = Join-Path $t55DbkRoot 'figs[1]\one.txt'
Write-Utf8 -Path $t55DbkFile -Text "the one file of a folder whose own name holds brackets`n"
$t55DbkSha = Get-T41Sha $t55DbkFile
$t55DbkPage = Join-Path $t55Base 'prose\facts-bracket-declared.md'
$t55DbkDeclare = Join-Path $t55Base 'prose\facts-bracket-declared.declare.txt'
Write-Utf8 -Path $t55DbkPage -Text "{X}|{Y}`n"
Write-Utf8 -Path $t55DbkDeclare -Text "X = sha256 figs[1]/o*.txt`nY = name-of-one figs[1]/one.txt`n"
$t55DbkArgs = @('facts', '--root', $t55DbkRoot, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55DbkPage, '--declare', $t55DbkDeclare)
$t55DbkRun = Invoke-T49Py -Tool $t49Gen -PyArgs $t55DbkArgs -Target $t55DbkRoot
$t55DbkOther = Join-Path $t55DbkRoot 'figs1\one.txt'
