        -Ok ($t55Both -and ($t55Da.Length -gt 0) -and ($t55Dl.Count -ge 3) -and ([string]$t55Dl[-1] -cmatch '\A    \S') -and ($t55Da -ceq $t55Db)) `
        -Said ('seat.py: ' + $t55Dl.Count + ' line(s), ' + $t55Da.Length + ' B, sha256 ' + (Get-T30Sha $t55Da) + ' ; gen_brief.py: ' + $t55Db.Length + ' B, sha256 ' + (Get-T30Sha $t55Db) + $t55Absent)
}
$t55Py = "import os`n`n`ndef clock_now():`n    return 1`n`n`ndef other():`n    return 2`n"
Add-T55Row -Label '(d) CONTROL the same cut over planted twins: it is the def and its body and no line of the next def; ONE byte changed inside the def reads DIFFERENT; one changed in the def after it reads the same' `
    -Ok (((Get-T55Def -Text $t55Py -Head 'def clock_now():') -ceq "def clock_now():`n    return 1") -and ((Get-T55Def -Text $t55Py.Replace('return 1', 'return 7') -Head 'def clock_now():') -cne (Get-T55Def -Text $t55Py -Head 'def clock_now():')) -and ((Get-T55Def -Text $t55Py.Replace('return 2', 'return 3') -Head 'def clock_now():') -ceq (Get-T55Def -Text $t55Py -Head 'def clock_now():'))) `
    -Said ('the cut: [' + (Get-T55Def -Text $t55Py -Head 'def clock_now():') + ']')

# ---- (f): stamp ---------------------------------------------------------------------------------------------------------------
$t55PlantLf = Join-Path $t55Root2 'loose\planted.txt'
Write-T49Bytes -Path $t55PlantLf -Bytes ($t49Utf8.GetBytes("alpha`nbeta`n"))
$t55Git = Invoke-T37Git -Root $t55Root2 -GitArgs @('hash-object', '--no-filters', '--', $t55PlantLf)
$t55GitHex = ([string]$t55Git.text).Trim()
Add-T55Row -Label '(f) CONTROL this member''s own blob id is git''s: over a planted file of two LF lines it equals what git hash-object --no-filters prints for that file, and over the same lines ending CR LF it is the same id -- the fold' `
    -Ok (($t55Git.exit -eq 0) -and ($t55GitHex -cmatch '\A[0-9a-f]{40}\z') -and ((Get-T55BlobId -Bytes ($t49Utf8.GetBytes("alpha`nbeta`n"))) -ceq $t55GitHex) -and ((Get-T55BlobId -Bytes ($t49Utf8.GetBytes("alpha`r`nbeta`r`n"))) -ceq $t55GitHex)) `
    -Said ('git: exit ' + $t55Git.exit + ', ' + $t55GitHex + ' ; here: ' + (Get-T55BlobId -Bytes ($t49Utf8.GetBytes("alpha`nbeta`n"))))
$t55St = Invoke-T49Py -Tool $t49Gen -PyArgs @('stamp')
Add-T55Row -Label '(f) gen_brief.py stamp, exit 0, prints exactly ONE line, composed_by: tools/lam/gen_brief.py@<8 hex>, the eight being the first eight of the blob id this member computes over the file''s bytes with CR LF folded to LF' `
    -Ok ((Test-T49Said -Run $t55St -Exit 0 -Needles @()) -and ($t55Blob8 -cmatch '\A[0-9a-f]{8}\z') -and ([string]$t55St.Text -ceq ('composed_by: tools/lam/gen_brief.py@' + $t55Blob8))) -Said ((Get-T49Short $t55St 200) + ' ; computed here @' + $t55Blob8 + ' over ' + $t55GenBytes.Length + ' B')
$t55LooseA = Join-Path $t55Root2 'loose\lf\gen_brief.py'
$t55LooseB = Join-Path $t55Root2 'loose\crlf\gen_brief.py'
$t55IdA = ''
if ($t55GenBytes.Length -gt 0) {
    $t55Moved = $t55Latin.GetString($t55GenBytes).Replace("`r`n", "`n") + '# a line no commit holds: ' + [guid]::NewGuid().ToString('N') + "`n"
    Write-T49Bytes -Path $t55LooseA -Bytes ($t55Latin.GetBytes($t55Moved))
    Write-T49Bytes -Path $t55LooseB -Bytes ($t55Latin.GetBytes($t55Moved.Replace("`n", "`r`n")))
    $t55IdA = (Get-T55BlobId -Bytes ([System.IO.File]::ReadAllBytes($t55LooseA))).Substring(0, 8)
}
$t55Sa = Invoke-T49Py -Tool $t55LooseA -PyArgs @('stamp')
$t55Sb = Invoke-T49Py -Tool $t55LooseB -PyArgs @('stamp')
Add-T55Row -Label '(f) FALSIFIER THE STAMP IS OF THE BYTES, COMMITTED OR NOT: a copy of the file under %TEMP% with one fresh line added -- bytes no commit holds -- stamps, exit 0 and no refusal, with ANOTHER eight hex, the first eight of the id this member computes over the copy; and that copy with every line end made CR LF stamps the same as it' `
    -Ok ((Test-T49Said -Run $t55Sa -Exit 0 -Needles @()) -and (Test-T49Said -Run $t55Sb -Exit 0 -Needles @()) -and ($t55IdA -cmatch '\A[0-9a-f]{8}\z') -and ($t55IdA -cne $t55Blob8) -and ([string]$t55Sa.Text -ceq ('composed_by: tools/lam/gen_brief.py@' + $t55IdA)) -and ([string]$t55Sb.Text -ceq [string]$t55Sa.Text)) `
    -Said ('the LF copy: ' + (Get-T49Short $t55Sa 160) + ' ; the CR LF copy: ' + (Get-T49Short $t55Sb 160) + ' ; computed here @' + $t55IdA + ' ; the tree''s own @' + $t55Blob8)
# The census is seat.py's, RUN from beside the generator: the LF copy above stands ALONE in its folder.
$t55StopsProse = Join-Path $t55Base 'prose\stops.md'
Write-Utf8 -Path $t55StopsProse -Text "{STOPS}`n"
$t55StopsArgs = @('facts', '--root', $t55Root3, '--arc', 'ARC-FX-9', '--seat', '3', '--prose', $t55StopsProse)
$t55Beside = Join-Path (Split-Path -Parent $t55LooseA) 'seat.py'
$t55R = Invoke-T49Py -Tool $t55LooseA -PyArgs $t55StopsArgs -Target $t55Root3
$t55R2 = Invoke-T49Py -Tool $t49Gen -PyArgs $t55StopsArgs -Target $t55Root3
Add-T55Row -Label '(f) FALSIFIER THE CENSUS IS seat.py''s, RUN FROM BESIDE: that LONE copy -- no seat.py stands beside it -- given facts over the one-line prose {STOPS} is REFUSED naming the seat.py it looked for, nothing written; and the same line given to the tree''s own file, where seat.py stands beside, exits 0 with the census''s count line of the third root''s one REUSED hook stop' `
    -Ok ((Test-T41Refused -Run $t55R -Needles @('the prose names the census and no seat.py stands beside this file', $t55Beside)) -and (-not (Test-Path -LiteralPath $t55Beside)) -and (Test-T49Said -Run $t55R2 -Exit 0 -Needles @()) -and
          (Test-T55Lines -Run $t55R2 -Lines @('STOPS = HOOK STOPS REUSED 1 / FRESH 0 / NOT EVALUATED 0 -- 1 (unread 0); HAND TEES 0  [seat.py census --machine, run from beside this file]', 'FACTS: 1 token(s) named; nothing was written')) -and ($t55R2.Before -eq $t55R2.After)) `
    -Said ('the lone copy: ' + (Get-T49Short $t55R 300) + ' ; the tree''s own: ' + (Get-T49Short $t55R2 240))

# ---- (g): skeleton ------------------------------------------------------------------------------------------------------------
foreach ($t55G in @(@('the full form', @('skeleton'), 1), @('the minimal form', @('skeleton', '--minimal'), 0))) {
    $t55R = Invoke-T49Py -Tool $t49Gen -PyArgs $t55G[1]
    $t55Sk = [string]$t55R.Text
    Add-T55Row -Label ('(g) gen_brief.py ' + ($t55G[1] -join ' ') + ' exits 0 and prints ' + $t55G[0] + ' as ASCII text: it names {KEEP_TABLE} exactly once, {SEAM_BASES} exactly once, and {STOPS_TABLE} ' + $(if ($t55G[2] -eq 1) { 'exactly once' } else { 'NOT AT ALL -- it holds neither thing the --minimal guard refuses, a stops table or a second keep-table' })) `
        -Ok ((Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and ($t55Sk -cnotmatch '[^\x0A\x20-\x7E]') -and ((Get-T55Count -Text $t55Sk -Needle '{KEEP_TABLE}') -eq 1) -and ((Get-T55Count -Text $t55Sk -Needle '{SEAM_BASES}') -eq 1) -and ((Get-T55Count -Text $t55Sk -Needle '{STOPS_TABLE}') -eq $t55G[2])) `
        -Said ('exit ' + $(if ($null -eq $t55R.Code) { '(none)' } else { [string]$t55R.Code }) + '; ' + @($t55Sk.Split("`n")).Count + ' line(s), ' + @([regex]::Matches($t55Sk, '\{[A-Z][A-Z0-9_]*\}')).Count + ' token place(s); {KEEP_TABLE} ' + (Get-T55Count -Text $t55Sk -Needle '{KEEP_TABLE}') + ', {SEAM_BASES} ' + (Get-T55Count -Text $t55Sk -Needle '{SEAM_BASES}') + ', {STOPS_TABLE} ' + (Get-T55Count -Text $t55Sk -Needle '{STOPS_TABLE}') + $(if ($null -eq $t55R.Code) { ' -- ' + $t55Sk }))
}
# The two rows above read skeleton through this shell's capture, which is LINES. THE BYTES are read here.
foreach ($t55G in @(@('the full form', @('skeleton')), @('the minimal form', @('skeleton', '--minimal')))) {
    $t55Raw = Get-T55PyBytes -Tool $t49Gen -PyArgs $t55G[1]
    $t55RawText = $t55Latin.GetString($t55Raw.Bytes)
    $t55R = Invoke-T49Py -Tool $t49Gen -PyArgs $t55G[1]
    Add-T55Row -Label ('(g) FALSIFIER THE BYTES gen_brief.py ' + ($t55G[1] -join ' ') + ' PRINTS, ' + $t55G[0] + ', read from the process''s own stream -- no shell redirect, no text decoding: exit 0, every byte LF or 32 to 126, so NO CR, ending in exactly ONE LF; and they are the lines this shell''s capture reads, each ended by ONE LF') `
        -Ok (($t55Raw.Code -eq 0) -and ($t55Raw.Bytes.Length -gt 2) -and ((Get-T55Count -Text $t55RawText -Needle "`r") -eq 0) -and ($t55RawText -cnotmatch '[^\x0A\x20-\x7E]') -and $t55RawText.EndsWith("`n") -and (-not $t55RawText.EndsWith("`n`n")) -and
              (Test-T49Said -Run $t55R -Exit 0 -Needles @()) -and ($t55RawText -ceq ([string]$t55R.Text + "`n"))) `
        -Said ('exit ' + $(if ($null -eq $t55Raw.Code) { '(none)' } else { [string]$t55Raw.Code }) + '; ' + $t55Raw.Bytes.Length + ' B, ' + (Get-T55Count -Text $t55RawText -Needle "`n") + ' LF, ' + (Get-T55Count -Text $t55RawText -Needle "`r") + ' CR, ' + @([regex]::Matches($t55RawText, '[^\x0A\x0D\x20-\x7E]')).Count + ' other byte(s) outside 32 to 126; the capture''s lines: ' + @(([string]$t55R.Text).Split("`n")).Count + $t55NoGen)
}
# skeleton --out FILE is the seat's own prose file: it is REFUSED under a mission plane and under a HALT- name, and writes nothing.
$t55SkPlane = Join-Path $t55Base 'skeleton-under-a-plane.md'
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('skeleton', '--minimal', '--out', $t55SkPlane) -Target $t55Base
Add-T55Row -Label '(g) FALSIFIER skeleton --out naming a path UNDER A MISSION PLANE -- this member''s own sandbox folder, which stands under .mission-runtime: REFUSED -- a skeleton is the seat''s own prose file, written outside the planes; no file is written and that folder is unchanged' `
    -Ok (($t55SkPlane -match '\\\.mission-runtime\\') -and (Test-T41Refused -Run $t55R -Needles @('--out ', 'lies under a mission plane')) -and (-not (Test-Path -LiteralPath $t55SkPlane))) -Said (Get-T49Short $t55R 300)
# A FOLDER NAMED FOR EITHER OTHER PLANE. The path of the row above holds a part named .mission-runtime. Two plain folders
# this member makes under its %TEMP% root, by their long names -- one named .mission, one named .claude, each inside a
# folder of its own, and no other part of either path named for a plane -- are each named by one skeleton --out.
foreach ($t55PlaneName in @('.mission', '.claude')) {
    $t55PlaneTop = Join-Path $t55Tmp ('plain-' + $t55PlaneName.Substring(1))
    $t55PlaneDir = Join-Path $t55PlaneTop $t55PlaneName
    $t55PlaneOut = Join-Path $t55PlaneDir 'skeleton.md'
    New-Item -ItemType Directory -Path $t55PlaneDir -Force | Out-Null
    $t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('skeleton', '--minimal', '--out', $t55PlaneOut) -Target $t55PlaneTop
    $t55Put = Remove-T55Written @($t55PlaneOut)
    $t55PlaneParts = @($t55PlaneOut.Split('\') | Where-Object { @('.mission', '.mission-runtime', '.claude') -contains $_ })
    $t55PlaneSaid = '--out ' + $t55PlaneOut + ' lies under a mission plane (a folder named .mission, .mission-runtime or .claude): a skeleton is the seat''s own prose file and is written outside them'
    Add-T55Row -Label ('(g) FALSIFIER A FOLDER NAMED ' + $t55PlaneName + ' IS A PLANE AS ONE NAMED .mission-runtime IS: skeleton --minimal --out naming a file inside a plain folder of that name, which this member made under %TEMP% and names by its long name -- the ONE part of the path named for a plane: REFUSED in ONE line, whole, naming the three planes and the path as given; no file is written, and the folder stands empty') `
        -Ok ((Test-T41Refused -Run $t55R -Needles @($t55PlaneSaid)) -and (Test-T55Lines -Run $t55R -Lines @(('REFUSED: ' + $t55PlaneSaid + ' -- nothing was written'))) -and (-not $t55Put) -and
              ($t55PlaneParts.Count -eq 1) -and ((Get-T55At $t55PlaneParts 0) -ceq $t55PlaneName) -and (Test-Path -LiteralPath $t55PlaneDir -PathType Container) -and (@(Get-ChildItem -LiteralPath $t55PlaneDir -Force).Count -eq 0) -and
              ($t55PlaneTop + '\').StartsWith(($env:TEMP.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase)) `
        -Said ((Get-T49Short $t55R 300) + $t55Put)
}
# THE PLANE AS THE SYSTEM OPENS IT. The row above names a plane AS SPELLED. Two more paths lead under one and spell none:
# the first root's runtime folder by the SHORT (8.3) names the system gives its folders, and a JUNCTION. The short
# spelling is asked of the system (Get-T55Short); it DRIVES the row only where it differs from the long one and no
# part of it is named for a plane, and where it does not the row says so and holds the long name's refusal alone.
$t55SkLeaf = 'skeleton-by-short-name.md'
$t55LamShort = Get-T55Short $t55Lam
$t55SkDriven = ($t55LamShort -ine $t55Lam) -and (@($t55LamShort.Split('\') | Where-Object { @('.mission', '.mission-runtime', '.claude') -contains $_ }).Count -eq 0)
$t55SkGiven = Join-Path $t55Lam $t55SkLeaf
$t55SkNeed = @(('--out ' + $t55SkGiven + ' lies under a mission plane (a folder named .mission, .mission-runtime or .claude): a skeleton is the seat''s own prose file'))
if ($t55SkDriven) {
    $t55SkGiven = Join-Path $t55LamShort $t55SkLeaf
    $t55SkNeed = @(('--out ' + $t55SkGiven + ' lies under a mission plane (a folder named .mission, .mission-runtime or .claude; by the path the system opens, '), ('\.mission-runtime\lam\' + $t55SkLeaf + '): a skeleton is the seat''s own prose file'))
}
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('skeleton', '--minimal', '--out', $t55SkGiven) -Target $t55Rt
$t55Put = Remove-T55Written @((Join-Path $t55Lam $t55SkLeaf))
Add-T55Row -Label '(g) FALSIFIER THE PLANE IS HELD AS THE SYSTEM OPENS IT, a short name: skeleton --minimal --out naming a file in the first root''s runtime folder with EVERY FOLDER OF THE PATH SPELLED BY ITS SHORT (8.3) NAME, which the system gives -- no part of the path as spelled is named for a plane: REFUSED naming the plane by the path the system opens; no file is written, and the root''s .mission-runtime is unchanged. WHERE THE VOLUME KEEPS NO SHORT NAME THERE this row cannot drive that: its reading then says NOT DRIVEN ON THIS VOLUME, and it holds the refusal of the long name alone' `
    -Ok ((Test-T41Refused -Run $t55R -Needles $t55SkNeed) -and (-not $t55Put)) `
    -Said ($(if ($t55SkDriven) { 'the short spelling the system gave: --out ' + $t55SkGiven + ' ; ' } else { 'NOT DRIVEN ON THIS VOLUME: this member was given no short spelling of ' + $t55Lam + ' that names no plane (it was given ' + $t55LamShort + '), and the refusal held is the long name''s ; ' }) + (Get-T49Short $t55R 420) + $t55Put)
# THE FOURTH ROOT stands inside the second, under %TEMP%: a runtime folder holding ONE marker file and no STATUS.md.
# The junction is made beside it, inside that root, by cmd's mklink /J; it is removed by cmd's rmdir -- the junction
# ITSELF, never what it leads to -- whatever the run between them does, and before either row is added.
$t55Root4 = Join-Path $t55Tmp 'r4'
$t55Rt4 = Join-Path $t55Root4 '.mission-runtime'
$t55Lam4 = Join-Path $t55Rt4 'lam'
$t55Marker = Join-Path $t55Lam4 'marker.txt'
$t55MarkerText = "the fourth root's one file: a marker this member reads through the junction`n"
Write-Utf8 -Path $t55Marker -Text $t55MarkerText
$t55Junction = Join-Path $t55Root4 'elsewhere'
$t55SkStatus = Join-Path $t55Junction 'lam\STATUS.md'
$t55JMade = [pscustomobject]@{ exit = $null; text = '(not run)' }
$t55JGone = [pscustomobject]@{ exit = $null; text = '(not run)' }
$t55JStood = $false
$t55Put = ''
try {
    $t55JMade = Invoke-T55Cmd -Words @('mklink', '/J') -Paths @($t55Junction, $t55Rt4)
    $t55JItem = Get-Item -LiteralPath $t55Junction -Force -ErrorAction SilentlyContinue
    $t55JStood = ($t55JMade.exit -eq 0) -and ($null -ne $t55JItem) -and (($t55JItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) -and ((Get-T55Text (Join-Path $t55Junction 'lam\marker.txt')) -ceq $t55MarkerText)
    $t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('skeleton', '--out', $t55SkStatus) -Target $t55Rt4
    $t55Put = Remove-T55Written @((Join-Path $t55Lam4 'STATUS.md'))
} finally { if (Test-Path -LiteralPath $t55Junction) { $t55JGone = Invoke-T55Cmd -Words @('rmdir') -Paths @($t55Junction) } }
Add-T55Row -Label '(g) CONTROL THE JUNCTION STOOD FOR THE ROW BELOW AND IS GONE: in a fourth root under %TEMP%, cmd''s mklink /J made the folder elsewhere a junction to that root''s .mission-runtime, exit 0 -- a reparse point, through which this member read its own marker file byte for byte; and cmd''s rmdir removed the junction ITSELF, exit 0: nothing stands at its path, and the folder it led to and the marker stand as they were' `
    -Ok ($t55JStood -and ($t55JGone.exit -eq 0) -and (-not (Test-Path -LiteralPath $t55Junction)) -and (Test-Path -LiteralPath $t55Lam4 -PathType Container) -and ((Get-T55Text $t55Marker) -ceq $t55MarkerText) -and ($t55Root4 + '\').StartsWith(($env:TEMP.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase)) `
    -Said ('mklink: exit ' + $(if ($null -eq $t55JMade.exit) { '(none)' } else { [string]$t55JMade.exit }) + '; it stood, a reparse point the marker was read through: ' + $t55JStood + '; rmdir: exit ' + $(if ($null -eq $t55JGone.exit) { '(none)' } else { [string]$t55JGone.exit }) + ' ' + $t55JGone.text + '; a thing stands at its path now: ' + (Test-Path -LiteralPath $t55Junction))
Add-T55Row -Label '(g) FALSIFIER THE PLANE IS HELD AS THE SYSTEM OPENS IT, a junction: skeleton --out naming elsewhere\lam\STATUS.md in that fourth root -- no part of the path as spelled is named for a plane, and the junction leads into one: REFUSED naming the plane by the path the system opens; no STATUS.md is made under the plane -- that root''s .mission-runtime is unchanged' `
    -Ok ($t55JStood -and (Test-T41Refused -Run $t55R -Needles @(('--out ' + $t55SkStatus + ' lies under a mission plane (a folder named .mission, .mission-runtime or .claude; by the path the system opens, '), '\r4\.mission-runtime\lam\STATUS.md): a skeleton is the seat''s own prose file')) -and (-not $t55Put) -and (-not (Test-Path -LiteralPath (Join-Path $t55Lam4 'STATUS.md')))) `
    -Said ((Get-T49Short $t55R 420) + $t55Put)
$t55SkHalt = Join-Path $t55Tmp 'HA.LT-sk.md'
$t55R = Invoke-T49Py -Tool $t49Gen -PyArgs @('skeleton', '--out', $t55SkHalt) -Target $t55Tmp
Add-T55Row -Label '(g) FALSIFIER skeleton --out named HA.LT-sk.md under %TEMP%, outside every plane: REFUSED by its name, which begins HALT- once its dots are dropped; no file is written and the second root is unchanged' `
    -Ok (($t55SkHalt -notmatch '\\\.mission(-runtime)?\\') -and (Test-T41Refused -Run $t55R -Needles @('--out is named HA.LT-sk.md', 'begins HALT-')) -and (-not (Test-Path -LiteralPath $t55SkHalt))) -Said (Get-T49Short $t55R 300)
}
catch {
    Add-T55Row -Label 'MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED' `
        -Ok $false -Said ("line " + $_.InvocationInfo.ScriptLineNumber + " :: " + $_.Exception.GetType().Name + " :: " + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
# THE SECOND ROOT, the third inside it, IS REMOVED HERE, whatever the rows read (kept with -KeepSandbox); a root that could
# not be removed is NAMED on the face.
if ($t55Tmp -and (-not $KeepSandbox) -and (Test-Path -LiteralPath $t55Tmp)) { try { Remove-Item -LiteralPath $t55Tmp -Recurse -Force -ErrorAction Stop } catch { $t55rows.Add('      NOT REMOVED: ' + $t55Tmp + ' (' + ($_.Exception.Message -replace '[\r\n]+', ' ') + ')') } }
Check -Id 'T-55' -Title 'THE ARM LINE, THE CLOCK, AND WHAT NEITHER TOOL MAY CARRY (BATCH-5 WP-O (a): the arm line "in the evaluator''s own form"): tools/lam/gen_brief.py compose prints ONE arm line, and the pattern lifted at this reading from this tree''s evaluator source matches it -- its ctx, its path and both digests as this member re-derives them, the two slots told apart over a planted CR LF brief -- while tools/lam/seat.py holds that pattern text as one string constant and compiles it after two substitutions; the brief is ASCII, LF only, one final LF, and is the prose with every token filled as this member derives it, the copy line and the compare line read as found; a prose with a CR, a TAB, a byte above 126 or not exactly one final LF is REFUSED with nothing written, and so is one where another table reads as keep rows as the operator''s line reads them -- capital hex too --, {COMPARE_LINE} or a keep-row line with no table placed, a walk of no file, {SEAM_BASES} inside a sentence or twice, an --exclude naming no top-level folder, or a figure whose --session or --scratch is not given; --head-out holds the arm line and the seat''s second line with the three clock tokens standing, and is REFUSED outside a standing close folder or under a name beginning HALT- -- as it stands, or once its dots are dropped -- or not one token, as is a head prose that is not ONE line; seat.py head --place-handoff places those two lines over every prior byte of STATUS.md with a stamp of its own clock and the two spans from the bases of the brief --predecessor-brief names, and REFUSES a fourth token, a span asked of a brief without exactly one SEAM BASES line, and a base later than its clock; arm prints the same line and writes the same head file again, and a second compose is REFUSED; arm prints the census''s finding where its head prose names the sum; the two tools'' clock_now and read_whole are byte-identical; neither file holds either token this member assembles, a session-id shape or an import of its sibling; no flag either declares is named for a time, --now is argparse''s usage error on seat.py copy, seat.py head, gen_brief.py compose and gen_brief.py arm, and the stamp a file hands compose is held to the clock; facts reads an empty roster as none; a file held with no sharing -- the admissions record, and the live capture only where a CAPTURE_ token is named -- is REFUSED by name, never a traceback, never read as absent; a mirror that is JSON and no object, a ledger key absent or null and a mission.yaml key with nothing on its line are REFUSED, not written as a word; a declared path that is absolute or leaves --root, absent over a wildcard and a declared {BRIEF_BYTES} are REFUSED, and a declare line no text names derives nothing; stamp prints the first eight of the blob id of the file''s own bytes, committed or not, and a copy with no seat.py beside it REFUSES a census figure; and skeleton prints its two forms, each naming {KEEP_TABLE} and {SEAM_BASES} once and the minimal one no {STOPS_TABLE}, in bytes that hold no CR' `
      -Ok $t55ok -Detail ("      THE $(@($t55rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t55rows -join "`n") +
          "`n      WHAT THIS MEMBER DOES NOT CLAIM: that the evaluator ADMITS the head placed here -- no evaluator is run in this member; that the two`n" +
          "        slots of the COMPOSED brief's arm line are told apart -- that brief holds no CR, so its two digests are one, and the slots are told`n" +
          "        apart over a planted brief through arm alone; that the copy line and the compare line are right beyond their openings and their`n" +
          "        close; that the census reads Python -- it reads bytes, so a sibling loaded by another spelling than import or from, or a token`n" +
          "        assembled at run time, is not found; that a flag of some name this member did not try could not carry a time -- the flags are read`n" +
          "        by their names, and --now alone is driven; that seat.py's change of \z to \Z is shown by a run -- it is read in the source, and an`n" +
          "        interpreter that takes \z itself would run without it; that the seam's bases cannot be chosen by the caller -- --seated names a`n" +
          "        FILE and --predecessor-brief a brief, whoever writes those writes the stamps, and each tool holds them only to the clock's form and`n" +
          "        to not being later than its own clock; that the evaluator's scan LISTS a head file named H.ALT-x.txt or with a leading blank -- the`n" +
          "        scan line is run over a folder the refused write never reached and returns 0 files there on any volume, one that keeps no 8.3 names`n" +
          "        among them: the refusal is what those two rows hold; that EVERY file the generator opens goes through its one reader -- the`n" +
          "        admissions record and the live capture are held here, the goal file, a kept capture, a scratch file and a declared file are not;`n" +
          "        that every figure of the ledgers and the mirror refuses a value that is not there -- CL_LAST_BY and COMPLETED are driven, the`n" +
          "        others are not; that a hold shorter than the five tries is refused -- the holder keeps its file until it is stopped; that the`n" +
          "        bytes skeleton prints COMPOSE -- they are held to LF, to ASCII and to the lines this shell reads, and no row here composes them;`n" +
          "        that a plane, a scratchpad or a close folder reached by ANOTHER way than the ones driven is refused -- a short (8.3) spelling is`n" +
          "        driven for skeleton's --out and for --scratch, a junction for skeleton's --out and for a folder of close; a symbolic link, a`n" +
          "        mapped drive, --scratch through a junction and --head-out by a short spelling are not, and on a volume that keeps no short names`n" +
          "        the two short-name rows say NOT DRIVEN and hold the long name's refusal alone; that the operator's copy line RUNS over a path`n" +
          "        with an apostrophe -- this shell tokenizes the line and runs nothing; that a hidden FOLDER, or a hidden file under an --exclude`n" +
          "        folder, is refused -- one hidden file of the walk is driven; that a BUILT-IN figure whose value holds a token's form is refused --`n" +
          "        a declared one is driven, in each of the two texts; or that --head-out's create is exclusive AT the write -- a file standing`n" +
          "        before the run is driven, one appearing during it is not.")

# =============================================================================================
# T-59 -- COMPOSE AND ARM TAKE --ctx unknown: THE ARM LINE SAYS SO, AND NO HANDOFF LINE THE EVALUATOR ADMITS COMES FROM IT
#         (as the operator ruled for a meter the seat cannot read)
# =============================================================================================
# THE ROW. The operator's meter is a fact a seat cannot always read, and tools/lam/gen_brief.py's --ctx took a whole
# number from 0 to 100 and nothing else: a seat that could not read the meter could not compose its brief at all.
# THE RULE: --ctx takes the exact word unknown beside 0 to 100, for compose and arm alike (one reading of the flag
# serves both verbs). The arm line then reads HANDOFF AT unknown% <lf>; <raw> <path> -- it says so in its own ctx slot
# -- and {CTX} in the brief reads unknown. That line is in a form NEITHER the evaluator's head pattern nor seat.py's
# constant admits (both take 0 to 100), so seat.py head --place-handoff refuses it; and --head-prose / --head-out with
# unknown are REFUSED before a byte is written, for a head file whose first line no tool would place. Every other
# spelling is refused as before, in the same words. A number composes as it did, byte for byte.
# THE FIXTURE: a root under %TEMP% (a fresh GUID name, removed at the end) holding .mission-runtime\lam and STATUS.md;
# a prose of three tokens, none of them a figure that needs git; and HEAD's generator as it stood, read from the
# installed synthetic base base-700e19e5-s11 and held to its pin, for the CONTROL that a number moves nothing. Every pattern is lifted from its own file at this
# reading, as T-55 lifts it: none is typed here.
$t59ok = $true
$t59rows = New-Object System.Collections.Generic.List[string]
function Add-T59Row {
    param([string]$Label, [bool]$Ok, [string]$Said)
    if (-not $Ok) { $script:t59ok = $false }
    $script:t59rows.Add(('      {0,-104} : {1}{2}' -f $Label, $Ok, $(if ($Said) { '  -- ' + (($Said -replace '\s+', ' ').Trim()) } else { '' })))
}
function Get-T59At {
    # The item of a list at an index, or '' past its end (Set-StrictMode -Version Latest is in force).
    param($List, [int]$At)
    $t59L = @($List)
    if ($At -lt $t59L.Count) { return [string]$t59L[$At] }
    return ''
}
function Get-T59Want {
    # The brief this member expects for one ctx, arc and seat, as bytes, and its arm line, derived HERE. The brief holds
    # no CR, so its LF/blob digest is its sha256: the line's two slots carry one value.
    param([string]$Ctx, [string]$Arc, [string]$Seat)
    $t59WBytes = $t49Utf8.GetBytes("# T-59 brief`n`nctx $Ctx; arc $Arc; seat $Seat`n")
    $t59WSha = Get-T49BytesSha $t59WBytes
    return [pscustomobject]@{ Bytes = $t59WBytes; Sha = $t59WSha
        Arm = ('HANDOFF AT ' + $Ctx + '% ' + $t59WSha + '; ' + $t59WSha + ' .mission-runtime/lam/HANDOFF-' + $Arc + '-seat-' + $Seat + '.md') }
}
function Get-T59BriefSha {
    # The sha256 of the brief compose writes for an arc and a seat under a root, or '(absent)'.
    param([string]$Root, [string]$Arc, [string]$Seat)
    return (Get-T41Sha (Join-Path $Root ('.mission-runtime\lam\HANDOFF-' + $Arc + '-seat-' + $Seat + '.md')))
}
$t59BaseSha   = '700e19e5-s11'
$t59BasePin   = '0250c398506ce80d26ab5bac38ac92c79ba9e2a9843ae8a1fd054c482ab85a26'
$t59Base      = [System.IO.Path]::GetFullPath((Join-Path $env:TEMP ('lam-wp4-t59-' + [Guid]::NewGuid().ToString('N').Substring(0, 10))))
$t59Root      = Join-Path $t59Base 'root'
$t59Lam       = Join-Path $t59Root '.mission-runtime\lam'
$t59Close     = Join-Path $t59Lam 'close\t59'
$t59Status    = Join-Path $t59Lam 'STATUS.md'
$t59Prose     = Join-Path $t59Base 'prose.md'
$t59HeadProse = Join-Path $t59Base 'head-prose.txt'
$t59HeadOut   = Join-Path $t59Close 'head.txt'
$t59HeadOut2  = Join-Path $t59Close 'head-arm.txt'
$t59Lines     = Join-Path $t59Base 'lines'
$t59Refusal   = 'composes no head file'
try {
    New-Item -ItemType Directory -Path $t59Close -Force | Out-Null
    New-Item -ItemType Directory -Path $t59Lines -Force | Out-Null
    Write-Utf8 -Path $t59Status -Text "# T-59 status`n"
    Write-Utf8 -Path $t59Prose -Text "# T-59 brief`n`nctx {CTX}; arc {ARC}; seat {SEAT}`n"
    Write-Utf8 -Path $t59HeadProse -Text "seat {SEAT} of {ARC} hands over (ctx {CTX}%)`n"
    # The base generator through Get-LamBaseBytes -- the installed synthetic base alone, no history.
    $t59BaseRead = Get-LamBaseBytes -Base $t59BaseSha -Path 'tools/lam/gen_brief.py' -Pin $t59BasePin
    $t59BaseBytes = [byte[]]$t59BaseRead.bytes
    $t59BaseGot = Get-T49BytesSha $t59BaseBytes
    $t59BaseTool = Join-Path $t59Base 'base-tool\gen_brief.py'
    Write-T49Bytes -Path $t59BaseTool -Bytes $t59BaseBytes
    Add-T59Row -Label 'FIXTURE a root under %TEMP% (not under this tree) holding .mission-runtime\lam and STATUS.md; the prose of three tokens; HEAD''s generator read at its pin' `
        -Ok ($t59BaseRead.ok -and ($t59BaseGot -ceq $t59BasePin) -and (Test-Path -LiteralPath $t59Status -PathType Leaf) -and
             ($t59Base + '\').StartsWith(($env:TEMP.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase) -and
             (-not ($t59Base + '\').StartsWith(($repoRoot.TrimEnd('\') + '\'), [System.StringComparison]::OrdinalIgnoreCase))) `
        -Said ('root ' + $t59Root + '; base read from ' + $t59BaseRead.from + ', ' + $t59BaseBytes.Length + ' B, sha256 ' + $t59BaseGot)

    # ---- (a), (b): compose and arm take unknown, and the arm line says so ------------------------------------------------
    $t59W1 = Get-T59Want -Ctx 'unknown' -Arc 'ARC-FX-59' -Seat '1'
    $t59C = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t59Root, '--arc', 'ARC-FX-59', '--seat', '1', '--prose', $t59Prose, '--ctx', 'unknown')
    $t59CArm = @(Get-T49Lines -Run $t59C -Head 'HANDOFF AT ')
    Add-T59Row -Label '(a) FALSIFIER compose --ctx unknown: exit 0; the brief written, {CTX} read as unknown, byte for byte as derived here; ONE arm line, HANDOFF AT unknown% with that brief''s digests and path' `
        -Ok ((Test-T49Said -Run $t59C -Exit 0 -Needles @()) -and ($t59CArm.Count -eq 1) -and ((Get-T59At $t59CArm 0) -ceq $t59W1.Arm) -and
             ((Get-T59BriefSha -Root $t59Root -Arc 'ARC-FX-59' -Seat '1') -ceq $t59W1.Sha)) `
        -Said ((Get-T49Short $t59C) + ' | expected arm line: ' + $t59W1.Arm)
    $t59A = Invoke-T49Py -Tool $t49Gen -PyArgs @('arm', '--root', $t59Root, '--arc', 'ARC-FX-59', '--seat', '1', '--ctx', 'unknown')
    $t59AArm = @(Get-T49Lines -Run $t59A -Head 'HANDOFF AT ')
    Add-T59Row -Label '(b) FALSIFIER arm --ctx unknown over that brief: exit 0 and the same ONE arm line' `
        -Ok ((Test-T49Said -Run $t59A -Exit 0 -Needles @()) -and ($t59AArm.Count -eq 1) -and ((Get-T59At $t59AArm 0) -ceq $t59W1.Arm)) `
        -Said (Get-T49Short $t59A)

    # ---- (c): neither pattern admits it; the same line at a number is admitted by both -----------------------------------
    $t59EvalAt = @([regex]::Matches([System.IO.File]::ReadAllText($t49Eval), '(?m)^\$script:HandoffHeadPattern = ''(.*)''\r?$'))
    $t59SeatAt = @([regex]::Matches([System.IO.File]::ReadAllText($t49Seat), '(?m)^HANDOFF_HEAD_PATTERN = r"(.*)"\r?$'))
    $t59EvalRx = $null; $t59SeatRx = $null
    if ($t59EvalAt.Count -eq 1) { try { $t59EvalRx = New-Object System.Text.RegularExpressions.Regex($t59EvalAt[0].Groups[1].Value) } catch { $t59EvalRx = $null } }
    if ($t59SeatAt.Count -eq 1) { try { $t59SeatRx = New-Object System.Text.RegularExpressions.Regex($t59SeatAt[0].Groups[1].Value) } catch { $t59SeatRx = $null } }
    $t59W42 = Get-T59Want -Ctx '42' -Arc 'ARC-FX-59' -Seat '1'
    Add-T59Row -Label '(c) the unknown arm line matches NEITHER the evaluator''s HandoffHeadPattern nor seat.py''s HANDOFF_HEAD_PATTERN (each lifted once from its file); CONTROL the same line at 42 matches both' `
        -Ok (($null -ne $t59EvalRx) -and ($null -ne $t59SeatRx) -and (-not $t59EvalRx.IsMatch($t59W1.Arm)) -and (-not $t59SeatRx.IsMatch($t59W1.Arm)) -and
             $t59EvalRx.IsMatch($t59W42.Arm) -and $t59SeatRx.IsMatch($t59W42.Arm)) `
        -Said ('lifted: evaluator ' + $t59EvalAt.Count + ', seat.py ' + $t59SeatAt.Count + '; unknown matched: ' + $(if ($t59EvalRx) { $t59EvalRx.IsMatch($t59W1.Arm) } else { 'n/a' }) + ' / ' + $(if ($t59SeatRx) { $t59SeatRx.IsMatch($t59W1.Arm) } else { 'n/a' }))

    # ---- (d): --head-prose / --head-out with unknown, REFUSED before a byte, for compose and for arm --------------------
    $t59Hd = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t59Root, '--arc', 'ARC-FX-59', '--seat', '2', '--prose', $t59Prose, '--ctx', 'unknown', '--head-prose', $t59HeadProse, '--head-out', $t59HeadOut) -Target $t59Lam
    Add-T59Row -Label '(d) FALSIFIER compose --ctx unknown with --head-prose / --head-out: REFUSED, one line saying it composes no head file; no brief, no head file, the runtime folder unchanged' `
        -Ok ((Test-T41Refused -Run $t59Hd -Needles @('--ctx unknown', $t59Refusal)) -and (-not (Test-Path -LiteralPath $t59HeadOut)) -and
             ((Get-T59BriefSha -Root $t59Root -Arc 'ARC-FX-59' -Seat '2') -ceq '(absent)')) `
        -Said (Get-T49Short $t59Hd)
    $t59Ha = Invoke-T49Py -Tool $t49Gen -PyArgs @('arm', '--root', $t59Root, '--arc', 'ARC-FX-59', '--seat', '1', '--ctx', 'unknown', '--head-prose', $t59HeadProse, '--head-out', $t59HeadOut2) -Target $t59Lam
    Add-T59Row -Label '(d) FALSIFIER arm --ctx unknown with --head-prose / --head-out over the standing brief: REFUSED the same way; no head file, the runtime folder unchanged' `
        -Ok ((Test-T41Refused -Run $t59Ha -Needles @('--ctx unknown', $t59Refusal)) -and (-not (Test-Path -LiteralPath $t59HeadOut2))) `
        -Said (Get-T49Short $t59Ha)

    # ---- (e): a head file holding the unknown arm line as line 1 is never placed ----------------------------------------
    $t59LineFile = Join-Path $t59Lines 'unknown-head.txt'
    Write-Utf8 -Path $t59LineFile -Text ($t59W1.Arm + "`n" + 'seat 1 of ARC-FX-59 hands over (ctx unknown%)' + "`n")
    $t59StatusBefore = Get-T41Sha $t59Status
    $t59P = Invoke-T49Py -Tool $t49Seat -PyArgs @('head', '--root', $t59Root, '--line-file', $t59LineFile, '--place-handoff') -Target $t59Lam
    Add-T59Row -Label '(e) seat.py head --place-handoff over two lines whose line 1 is the unknown arm line: REFUSED, not in the form; STATUS.md and the runtime folder unchanged' `
        -Ok ((Test-T41Refused -Run $t59P -Needles @('the new line 1 is not in the form')) -and ((Get-T41Sha $t59Status) -ceq $t59StatusBefore)) `
        -Said (Get-T49Short $t59P)

    # ---- (f): every other spelling is refused as before, in the same words ----------------------------------------------
    $t59Seat = 10
    foreach ($t59Bad in @('UNKNOWN', 'Unknown', 'unknown%', ' unknown', 'not-read', '101')) {
        $t59R = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t59Root, '--arc', 'ARC-FX-59', '--seat', [string]$t59Seat, '--prose', $t59Prose, '--ctx', $t59Bad) -Target $t59Lam
        Add-T59Row -Label ('(f) CONTROL compose --ctx [' + $t59Bad + ']: REFUSED as not a whole number from 0 to 100, nothing written') `
            -Ok ((Test-T41Refused -Run $t59R -Needles @('is not a whole number from 0 to 100')) -and ((Get-T59BriefSha -Root $t59Root -Arc 'ARC-FX-59' -Seat ([string]$t59Seat)) -ceq '(absent)')) `
            -Said (Get-T49Short $t59R 240)
        $t59Seat++
    }

    # ---- (g): a number composes as HEAD's generator composes it, byte for byte ------------------------------------------
    $t59TwinA = Join-Path $t59Base 'twin-a'
    $t59TwinB = Join-Path $t59Base 'twin-b'
    New-Item -ItemType Directory -Path (Join-Path $t59TwinA '.mission-runtime\lam') -Force | Out-Null
    New-Item -ItemType Directory -Path (Join-Path $t59TwinB '.mission-runtime\lam') -Force | Out-Null
    $t59Ba = Invoke-T49Py -Tool $t59BaseTool -PyArgs @('compose', '--root', $t59TwinA, '--arc', 'ARC-FX-59', '--seat', '4', '--prose', $t59Prose, '--ctx', '42')
    $t59Tr = Invoke-T49Py -Tool $t49Gen -PyArgs @('compose', '--root', $t59TwinB, '--arc', 'ARC-FX-59', '--seat', '4', '--prose', $t59Prose, '--ctx', '42')
    $t59W4 = Get-T59Want -Ctx '42' -Arc 'ARC-FX-59' -Seat '4'
    $t59BaText = ([string]$t59Ba.Text).Replace($t59TwinA, '<ROOT>')
    $t59TrText = ([string]$t59Tr.Text).Replace($t59TwinB, '<ROOT>')
    Add-T59Row -Label '(g) CONTROL compose --ctx 42 by HEAD''s generator and by this tree''s over twin roots: exit 0 at both; the two briefs byte-equal and as derived here; the two outputs equal but for the root' `
        -Ok (($t59Ba.Code -eq 0) -and ($t59Tr.Code -eq 0) -and ((Get-T59BriefSha -Root $t59TwinA -Arc 'ARC-FX-59' -Seat '4') -ceq $t59W4.Sha) -and
             ((Get-T59BriefSha -Root $t59TwinB -Arc 'ARC-FX-59' -Seat '4') -ceq $t59W4.Sha) -and ($t59BaText -ceq $t59TrText) -and
             (@(Get-T49Lines -Run $t59Tr -Head 'HANDOFF AT ').Count -eq 1) -and ((Get-T59At @(Get-T49Lines -Run $t59Tr -Head 'HANDOFF AT ') 0) -ceq $t59W4.Arm)) `
        -Said ('base: ' + (Get-T49Short $t59Ba 200) + ' | tree: ' + (Get-T49Short $t59Tr 200))
}
catch {
    $t59ok = $false
    $t59rows.Add('      MEMBER ABORTED -- an exception escaped the body; every row after it is UNMEASURED')
    $t59rows.Add('        line ' + $_.InvocationInfo.ScriptLineNumber + ' :: ' + $_.Exception.GetType().Name + ' :: ' + ($_.Exception.Message -replace '[\r\n]+', ' '))
}
finally {
    $t59Gone = $false
    for ($t59Try = 0; $t59Try -lt 5 -and -not $t59Gone; $t59Try++) {
        try { if (Test-Path -LiteralPath $t59Base) { Remove-Item -LiteralPath $t59Base -Recurse -Force -ErrorAction Stop }; $t59Gone = $true } catch { Start-Sleep -Seconds 1 }
    }
}
Add-T59Row -Label 'PLANE the root under %TEMP% removed; nothing of this member under this tree' -Ok ($t59Gone -and (-not (Test-Path -LiteralPath $t59Base))) -Said ('root ' + $t59Base)
Check -Id 'T-59' -Title 'COMPOSE AND ARM TAKE --ctx unknown (BATCH-7 WP-S (b)): tools/lam/gen_brief.py compose and arm accept the exact word unknown -- the brief''s {CTX} reads it and the ONE arm line reads HANDOFF AT unknown% with the brief''s digests --; that line is in a form neither this tree''s evaluator pattern nor seat.py''s constant admits, while the same line at 42 is admitted by both, and seat.py head --place-handoff refuses it with STATUS.md unchanged; --head-prose and --head-out with unknown are REFUSED before a byte, for compose and for arm; UNKNOWN, Unknown, unknown%, a leading blank, not-read and 101 are refused in the words they were; and a number composes as HEAD''s generator (at its pin) composes it, byte for byte' `
      -Ok $t59ok -Detail ("      THE $(@($t59rows | Where-Object { $_ -match ' : (True|False)' }).Count) ROWS:`n" + ($t59rows -join "`n") +
          "`n      WHAT THIS MEMBER DOES NOT CLAIM: that a later arm with a NUMBER over a brief composed with unknown is refused -- it is not: arm`n" +
          "        takes its own --ctx, and its line is then in the form; that rule (a brief composed with unknown is never placed as a head) stays`n" +
          "        the seats'; that the evaluator is run -- its pattern is read from its source, as T-55 reads it.")
if (-not $KeepSandbox) {
    try { Remove-Item -LiteralPath $sandbox -Recurse -Force -ErrorAction Stop } catch { }
    try { Remove-Item -LiteralPath $guardRoot -Recurse -Force -ErrorAction Stop } catch { }
} else {
    Write-Host ""
    Write-Host "kept (-KeepSandbox): $sandbox and the guard root $guardRoot"
}
Write-Host ""
Write-Host "------------------------------------------------------------------------------"
if ($failures -eq 0 -and $skips -eq 0) { Write-Host " WP-4: all $checksRun checks passed." }
elseif ($failures -eq 0) {
    Write-Host " WP-4: $($checksRun - $skips) of $checksRun checks passed, $skips SKIPPED -- a skip is not a pass; see the [SKIP] line(s) above."
}
else { Write-Host (" WP-4: $failures of $checksRun checks FAILED." + $(if ($skips -gt 0) { '  (' + $skips + ' SKIPPED.)' } else { '' })) }
Write-Host "------------------------------------------------------------------------------"
Write-Host "EXIT: $failures"
exit $failures
